def _dbg_report(event, **fields):
    payload = {
        "ts": datetime.now(timezone.utc).replace(tzinfo=None).isoformat() + "Z",
        "sessionId": _DEBUG_SESSION_ID,
        "runId": _DEBUG_RUN_ID,
        "event": event,
        **fields,
    }
    try:
        os.makedirs(_DEBUG_LOG_DIR, exist_ok=True)
        with open(_DEBUG_LOG_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(payload, ensure_ascii=False) + "\n")
    except Exception:
        pass
    if not _DEBUG_SERVER_URL:
        return
    try:
        requests.post(_DEBUG_SERVER_URL, json=payload, timeout=2)
    except Exception:
        pass

def _log_baseexception(context, exc):
    exc_type = type(exc).__name__
    exc_repr = repr(exc)
    tb_text = "".join(traceback.format_exception(type(exc), exc, exc.__traceback__))
    logging.critical(f"{context} | {exc_type}: {exc_repr}\n{tb_text}")
    _dbg_report(
        "process.local.exception",
        context=context,
        exc_type=exc_type,
        exc_repr=exc_repr,
        traceback=tb_text[-12000:],
    )

_SETTINGS_CACHE = TTLCache(maxsize=128, ttl=10)

def _read_setting_value(key):
    cache_key = f"settings:{key}"
    try:
        if cache_key in _SETTINGS_CACHE:
            return _SETTINGS_CACHE[cache_key]
    except Exception:
        pass
    try:
        raw = chat_db.get_setting(key)
    except Exception:
        raw = None
    value = raw
    if isinstance(value, str) and value.strip():
        try:
            value = json.loads(value)
        except Exception:
            value = raw
    try:
        _SETTINGS_CACHE[cache_key] = value
    except Exception:
        pass
    return value

def _channel_key_from_message(source, sender_identifier=None):
    src = str(source or "").strip().lower()
    if src.startswith("whatsapp"):
        return "whatsapp"
    if src in ("tawk.to", "tawkto", "tawk"):
        return "phone"
    if src == "email":
        addr = str(sender_identifier or "").strip().lower()
        if "getyourguide" in addr or "reply.getyourguide.com" in addr or "gyg" in addr:
            return "getyourguide"
        if "viator" in addr:
            return "viator"
        if "headout" in addr:
            return "headout"
        return "email"
    if src:
        return src
    return "email"

