def _build_legacy_meta_whatsapp_accounts():
    config = _load_legacy_app_config()
    whatsapp_cfg = (config.get("whatsapp") or {}) if isinstance(config, dict) else {}
    if not isinstance(whatsapp_cfg, dict):
        return []

    phone_number_ids = whatsapp_cfg.get("phone_number_ids") or {}
    waba_ids = whatsapp_cfg.get("waba_ids") or {}
    phone_id_locations = whatsapp_cfg.get("phone_id_locations") or {}
    access_token = str(whatsapp_cfg.get("access_token") or whatsapp_cfg.get("verify_token") or "").strip()

    if not isinstance(phone_number_ids, dict) or not phone_number_ids:
        return []

    default_phone_id = str(phone_number_ids.get("default") or "").strip()
    default_location = str(phone_id_locations.get(default_phone_id) or "").strip()
    accounts = []
    seen_phone_ids = set()

    for location_key, raw_phone_id in phone_number_ids.items():
        phone_number_id = str(raw_phone_id or "").strip()
        if not phone_number_id or phone_number_id in seen_phone_ids:
            continue
        seen_phone_ids.add(phone_number_id)

        location_name = str(phone_id_locations.get(phone_number_id) or location_key or "").strip()
        if location_name.lower() == "default":
            location_name = default_location or "NeedHelp"

        waba_id = str(
            (waba_ids.get(location_key) if isinstance(waba_ids, dict) else "")
            or (waba_ids.get(location_name) if isinstance(waba_ids, dict) else "")
            or (waba_ids.get("default") if isinstance(waba_ids, dict) else "")
            or ""
        ).strip()

        is_default = bool(default_phone_id and phone_number_id == default_phone_id)
        label_suffix = location_name or ("Default" if is_default else phone_number_id[-6:])
        notes_suffix = location_name or "default routing"

        accounts.append(
            {
                "id": f"legacy_meta_{re.sub(r'[^a-z0-9]+', '_', label_suffix.lower()).strip('_') or 'account'}_{phone_number_id[-6:]}",
                "label": f"Meta {label_suffix}",
                "provider": "meta",
                "usage": "customers",
                "enabled": True,
                "isDefault": is_default,
                "phoneNumber": "",
                "routingLocation": location_name or "NeedHelp",
                "connectionStatus": "connected" if access_token and phone_number_id and waba_id else "ready",
                "businessAccountId": waba_id,
                "phoneNumberId": phone_number_id,
                "accessToken": access_token,
                "providerBaseUrl": "",
                "instanceName": "",
                "apiKey": "",
                "webhookUrl": "",
                "notes": f"Imported from legacy Meta WhatsApp config ({notes_suffix}).",
            }
        )

    if accounts and not any(item.get("isDefault") for item in accounts):
        accounts[0]["isDefault"] = True
    return accounts

def _read_json_setting_value(key, fallback=None):
    try:
        raw = chat_db.get_setting(str(key or "").strip())
    except Exception:
        return fallback
    parsed = raw
    if isinstance(parsed, str) and parsed.strip():
        try:
            parsed = json.loads(parsed)
        except Exception:
            return fallback
    return parsed if parsed is not None else fallback


_INTERNAL_ERROR_ALERT_LOCK = threading.Lock()
_INTERNAL_ERROR_ALERT_LAST_SENT = {}
_INTERNAL_ERROR_ALERT_HANDLER_REGISTERED = False
_INTERNAL_ERROR_ALERT_SUPPRESS_SECONDS = 3600
_INTERNAL_ERROR_ALERT_GUARD = threading.local()


def _internal_notifications_whatsapp_cfg():
    cfg = _read_json_setting_value("internal_whatsapp_notifications_config", {}) or {}
    if not isinstance(cfg, dict):
        return {}
    provider_base_url = str(cfg.get("providerBaseUrl") or "http://127.0.0.1:8080").strip().rstrip("/")
    instance_name = str(cfg.get("instanceName") or "fts_internal_notifications").strip()
    api_key = str(cfg.get("apiKey") or "").strip()
    whatsapp_number = re.sub(r"\D", "", str(cfg.get("whatsappNumber") or "").strip())
    if not provider_base_url or not instance_name or not api_key:
        return {}
    return {
        "providerBaseUrl": provider_base_url,
        "instanceName": instance_name,
        "apiKey": api_key,
        "whatsappNumber": whatsapp_number,
    }


def _send_internal_error_alert_text(text):
    cfg = _internal_notifications_whatsapp_cfg()
    message_text = str(text or "").strip()
    if not cfg or not message_text:
        return False
        
    admin_phones = []
    try:
        import chat_db
        import json
        users_raw = chat_db.get_setting("dashboard_users")
        if users_raw:
            users = json.loads(users_raw)
            for u in users:
                if u.get('role') == 'Admin' and u.get('toolPhone'):
                    phone = re.sub(r"\D", "", str(u.get('toolPhone')))
                    if phone:
                        admin_phones.append(phone)
    except Exception as e:
        pass
        
    if cfg.get("whatsappNumber"):
        admin_phones.append(cfg.get("whatsappNumber"))
        
    if not admin_phones:
        return False
        
    success = False
    for phone in set(admin_phones):
        try:
            resp = requests.post(
                f"{cfg['providerBaseUrl']}/message/sendText/{quote(cfg['instanceName'])}",
                headers={
                    "Content-Type": "application/json",
                    "apikey": cfg["apiKey"],
                },
                json={
                    "number": phone,
                    "text": message_text,
                },
                timeout=20,
            )
            if int(resp.status_code or 0) < 400:
                success = True
        except Exception:
            pass
            
    return success


def _build_internal_error_alert_message(record):
    record = record if isinstance(record, logging.LogRecord) else None
    if not record:
        return ""
    source_file = os.path.basename(str(record.pathname or "").strip()) or str(record.module or "unknown")
    source_func = str(record.funcName or "").strip() or "unknown"
    source_line = int(record.lineno or 0)
    source_label = f"{source_file}:{source_line} in {source_func}"
    reason_text = ""
    try:
        reason_text = str(record.getMessage() or "").strip()
    except Exception:
        reason_text = str(record.msg or "").strip()
    if record.exc_info:
        try:
            exc_only = "".join(traceback.format_exception_only(record.exc_info[0], record.exc_info[1])).strip()
            if exc_only and exc_only not in reason_text:
                reason_text = f"{reason_text}\nException: {exc_only}".strip()
        except Exception:
            pass

    normalized_reason = reason_text.lower()
    normalized_path = str(record.pathname or "").strip().lower()
    normalized_logger = str(record.name or "").strip().lower()
    category = "Backend Runtime"
    if "whatsapp delivery failed via meta status webhook" in normalized_reason or "business eligibility payment issue" in normalized_reason or "meta api" in normalized_reason:
        category = "Meta WhatsApp"
    elif "airtable" in normalized_reason or "airtable" in normalized_path:
        category = "Airtable"
    elif "webhook" in normalized_reason or "webhook" in normalized_path:
        category = "Webhook"
    elif "internal_notifications" in normalized_reason or "internal_notifications" in normalized_path:
        category = "Internal Notifications"
    elif "sqlite" in normalized_reason or "database" in normalized_reason or "chat_db" in normalized_path or "automation_db" in normalized_path:
        category = "Database"
    elif "gmail" in normalized_reason or "email" in normalized_reason:
        category = "Email"
    if len(reason_text) > 1800:
        reason_text = reason_text[:1800] + "..."
    return "\n".join([
        "🚨 Backend Error Alert",
        f"Level: {str(record.levelname or 'ERROR')}",
        f"Category: {category}",
        f"Source: {source_label}",
        f"Logger: {str(record.name or 'root')}",
        f"Reason: {reason_text or 'Unknown error'}",
        f"At: {datetime.now(timezone.utc).astimezone().strftime('%Y-%m-%d %H:%M:%S')}",
    ]).strip()


def _should_suppress_internal_error_alert(record):
    record = record if isinstance(record, logging.LogRecord) else None
    if not record:
        return False
    logger_name = str(record.name or "").strip().lower()
    try:
        message_text = str(record.getMessage() or "").strip().lower()
    except Exception:
        message_text = str(record.msg or "").strip().lower()
    # Internet noise hitting the plain HTTP Flask port should not wake the admin up.
    if logger_name == "werkzeug":
        noisy_http_patterns = (
            "bad http/0.9 request type",
            "bad request version",
            "bad request syntax",
            "invalid http version",
            "code 505",
            "pri * http/2.0",
            "you're speaking plain http to an ssl-enabled server port",
        )
        if any(pattern in message_text for pattern in noisy_http_patterns):
            return True
    # Meta recipient/policy failures are expected business outcomes, not backend crashes.
    if (
        "this person isn't available right now" in message_text
        or "(#551)" in message_text
        or "more than 24 hours have passed" in message_text
    ):
        return True
    if "no module named 'soundfile'" in message_text:
        return True
    # Transient Airtable gateway timeouts are infrastructure, not app crashes.
    if "api.airtable.com" in message_text and (
        "504" in message_text or "gateway time-out" in message_text or "gateway timeout" in message_text
    ):
        return True
    if "database is locked" in message_text or "database is busy" in message_text:
        return True
    return False


class InternalWhatsAppErrorAlertHandler(logging.Handler):
    def emit(self, record):
        if not isinstance(record, logging.LogRecord):
            return
        if int(record.levelno or 0) < int(logging.ERROR):
            return
        if getattr(_INTERNAL_ERROR_ALERT_GUARD, "active", False):
            return
        try:
            message_preview = str(record.getMessage() or "").strip()
        except Exception:
            message_preview = str(record.msg or "").strip()
        if not message_preview:
            return
        if "Real WhatsApp notification sent" in message_preview or "Error alert notification handler" in message_preview:
            return
        if _should_suppress_internal_error_alert(record):
            return
        dedupe_key = f"{str(record.pathname or '')}:{int(record.lineno or 0)}:{message_preview[:240]}"
        now_ts = time.time()
        with _INTERNAL_ERROR_ALERT_LOCK:
            last_sent = float(_INTERNAL_ERROR_ALERT_LAST_SENT.get(dedupe_key) or 0.0)
            if now_ts - last_sent < _INTERNAL_ERROR_ALERT_SUPPRESS_SECONDS:
                return
            _INTERNAL_ERROR_ALERT_LAST_SENT[dedupe_key] = now_ts
        alert_text = _build_internal_error_alert_message(record)
        if not alert_text:
            return
        try:
            _INTERNAL_ERROR_ALERT_GUARD.active = True
            _send_internal_error_alert_text(alert_text)
        except Exception:
            return
        finally:
            _INTERNAL_ERROR_ALERT_GUARD.active = False


def _ensure_internal_error_alert_handler_registered():
    global _INTERNAL_ERROR_ALERT_HANDLER_REGISTERED
    if _INTERNAL_ERROR_ALERT_HANDLER_REGISTERED:
        return
    root_logger = logging.getLogger()
    for handler in root_logger.handlers:
        if isinstance(handler, InternalWhatsAppErrorAlertHandler):
            _INTERNAL_ERROR_ALERT_HANDLER_REGISTERED = True
            return
    root_logger.addHandler(InternalWhatsAppErrorAlertHandler(level=logging.ERROR))
    _INTERNAL_ERROR_ALERT_HANDLER_REGISTERED = True

def _map_legacy_evolution_status(raw_status):
    status = str(raw_status or "").strip().lower()
    if status == "connected":
        return "connected"
    if status in ("pending_qr", "not_connected", "error"):
        return "ready"
    return "draft"

def _build_legacy_evolution_whatsapp_accounts():
    accounts = []
    seen_instance_names = set()

    internal_cfg = _read_json_setting_value("internal_whatsapp_notifications_config", None)
    if isinstance(internal_cfg, dict):
        instance_name = str(internal_cfg.get("instanceName") or "").strip()
        whatsapp_number = str(internal_cfg.get("whatsappNumber") or "").strip()
        if instance_name or whatsapp_number or str(internal_cfg.get("connectionStatus") or "").strip():
            seen_instance_names.add(instance_name)
            notes = str(internal_cfg.get("notes") or "").strip()
            imported_note = "Imported from legacy internal Evolution WhatsApp config."
            if notes:
                imported_note = f"{imported_note} {notes}"
            accounts.append(
                {
                    "id": f"legacy_evolution_internal_{re.sub(r'[^a-z0-9]+', '_', (instance_name or 'internal').lower()).strip('_')}",
                    "label": str(internal_cfg.get("channelName") or "Internal Notifications").strip() or "Internal Notifications",
                    "provider": "evolution",
                    "usage": "internal_notifications",
                    "enabled": bool(internal_cfg.get("enabled", True)),
                    "isDefault": False,
                    "phoneNumber": whatsapp_number,
                    "routingLocation": "Operations",
                    "connectionStatus": _map_legacy_evolution_status(internal_cfg.get("connectionStatus")),
                    "businessAccountId": "",
                    "phoneNumberId": "",
                    "accessToken": "",
                    "providerBaseUrl": str(internal_cfg.get("providerBaseUrl") or "").strip(),
                    "instanceName": instance_name,
                    "apiKey": str(internal_cfg.get("apiKey") or "").strip(),
                    "webhookUrl": str(internal_cfg.get("userWebhookUrl") or internal_cfg.get("webhookUrl") or "").strip(),
                    "notes": imported_note,
                }
            )

    global_base_url = ""
    global_api_key = ""
    global_webhook_url = ""
    if isinstance(internal_cfg, dict):
        global_base_url = str(internal_cfg.get("providerBaseUrl") or "").strip()
        global_api_key = str(internal_cfg.get("apiKey") or "").strip()
        global_webhook_url = str(internal_cfg.get("userWebhookUrl") or internal_cfg.get("webhookUrl") or "").strip()
        if global_webhook_url.endswith("/whatsapp/webhook"):
            global_webhook_url = global_webhook_url.replace("/whatsapp/webhook", "/user_whatsapp/webhook")

    user_connections_map = _read_json_setting_value("dashboard_user_whatsapp_connections", {})
    if isinstance(user_connections_map, dict):
        for username, items in user_connections_map.items():
            username_clean = str(username or "").strip()
            if not isinstance(items, list):
                continue
            for idx, item in enumerate(items):
                if not isinstance(item, dict):
                    continue
                instance_name = str(item.get("instanceName") or "").strip()
                if instance_name and instance_name in seen_instance_names:
                    continue
                connection_label = str(item.get("connectionLabel") or "").strip() or f"{username_clean or 'user'} WhatsApp"
                whatsapp_number = str(item.get("whatsappNumber") or "").strip()
                connection_id = str(item.get("id") or f"{username_clean}_{idx + 1}").strip()
                if not any([instance_name, whatsapp_number, connection_label, username_clean]):
                    continue
                seen_instance_names.add(instance_name)
                notes = str(item.get("notes") or "").strip()
                imported_note = f"Imported from legacy Evolution user connection for {username_clean or 'user'}."
                if notes:
                    imported_note = f"{imported_note} {notes}"
                accounts.append(
                    {
                        "id": f"legacy_evolution_user_{re.sub(r'[^a-z0-9]+', '_', (username_clean or 'user').lower()).strip('_')}_{re.sub(r'[^a-z0-9]+', '_', (instance_name or connection_id).lower()).strip('_')}",
                        "label": connection_label,
                        "provider": "evolution",
                        "usage": "internal_notifications",
                        "enabled": bool(item.get("enabled", True)),
                        "isDefault": False,
                        "phoneNumber": whatsapp_number,
                        "routingLocation": username_clean or "Operations",
                        "connectionStatus": _map_legacy_evolution_status(item.get("connectionStatus")),
                        "businessAccountId": "",
                        "phoneNumberId": "",
                        "accessToken": "",
                        "providerBaseUrl": str(item.get("providerBaseUrl") or global_base_url or "").strip(),
                        "instanceName": instance_name,
                        "apiKey": str(item.get("apiKey") or global_api_key or "").strip(),
                        "webhookUrl": str(item.get("webhookUrl") or global_webhook_url or "").strip(),
                        "notes": imported_note,
                    }
                )

    return accounts

def _merge_channel_settings_with_legacy_whatsapp(raw_settings):
    settings = dict(raw_settings) if isinstance(raw_settings, dict) else {}
    legacy_accounts = _build_legacy_meta_whatsapp_accounts() + _build_legacy_evolution_whatsapp_accounts()
    existing_accounts = settings.get("whatsappAccounts")
    existing_accounts = existing_accounts if isinstance(existing_accounts, list) else []

    if not legacy_accounts:
        return settings

    merged_accounts = []
    legacy_meta_by_phone_id = {
        str(item.get("phoneNumberId") or "").strip(): item
        for item in legacy_accounts
        if isinstance(item, dict)
        and str(item.get("provider") or "").strip().lower() == "meta"
        and str(item.get("phoneNumberId") or "").strip()
    }
    legacy_evolution_by_instance = {
        str(item.get("instanceName") or "").strip(): item
        for item in legacy_accounts
        if isinstance(item, dict)
        and str(item.get("provider") or "").strip().lower() == "evolution"
        and str(item.get("instanceName") or "").strip()
    }
    matched_legacy_phone_ids = set()
    matched_legacy_instances = set()

    for item in existing_accounts:
        if not isinstance(item, dict):
            continue
        merged = dict(item)
        phone_number_id = str(merged.get("phoneNumberId") or "").strip()
        instance_name = str(merged.get("instanceName") or "").strip()
        provider = str(merged.get("provider") or "").strip().lower()
        legacy = None
        if phone_number_id and phone_number_id in legacy_meta_by_phone_id:
            legacy = legacy_meta_by_phone_id.get(phone_number_id)
        elif instance_name and instance_name in legacy_evolution_by_instance:
            legacy = legacy_evolution_by_instance.get(instance_name)
        if legacy:
            if phone_number_id:
                matched_legacy_phone_ids.add(phone_number_id)
            if instance_name:
                matched_legacy_instances.add(instance_name)
            for field in (
                "label",
                "provider",
                "usage",
                "enabled",
                "isDefault",
                "routingLocation",
                "connectionStatus",
                "businessAccountId",
                "phoneNumberId",
                "accessToken",
                "providerBaseUrl",
                "instanceName",
                "apiKey",
                "webhookUrl",
                "notes",
            ):
                value = merged.get(field)
                if value in (None, "", []):
                    merged[field] = legacy.get(field)
            if str(legacy.get("provider") or "").strip().lower() == "meta" and provider != "meta":
                merged["provider"] = "meta"
            if str(legacy.get("provider") or "").strip().lower() == "evolution" and provider != "evolution":
                merged["provider"] = "evolution"
            if str(merged.get("connectionStatus") or "").strip().lower() == "draft":
                merged["connectionStatus"] = legacy.get("connectionStatus") or "ready"
        merged_accounts.append(merged)

    for legacy in legacy_accounts:
        phone_number_id = str(legacy.get("phoneNumberId") or "").strip()
        instance_name = str(legacy.get("instanceName") or "").strip()
        if phone_number_id and phone_number_id in matched_legacy_phone_ids:
            continue
        if instance_name and instance_name in matched_legacy_instances:
            continue
        merged_accounts.append(dict(legacy))

    if merged_accounts:
        settings["whatsappAccounts"] = merged_accounts

    had_existing_customer_account = any(
        isinstance(item, dict) and str(item.get("usage") or "customers").strip() == "customers"
        for item in existing_accounts
    )
    if not had_existing_customer_account:
        current_whatsapp = settings.get("whatsapp")
        current_whatsapp = dict(current_whatsapp) if isinstance(current_whatsapp, dict) else {}
        default_account = next(
            (
                item
                for item in merged_accounts
                if isinstance(item, dict)
                and bool(item.get("enabled", True))
                and str(item.get("usage") or "customers").strip() == "customers"
                and bool(item.get("isDefault"))
            ),
            None,
        ) or next(
            (
                item
                for item in merged_accounts
                if isinstance(item, dict)
                and bool(item.get("enabled", True))
                and str(item.get("usage") or "customers").strip() == "customers"
            ),
            None,
        )
        if default_account:
            current_whatsapp["enabled"] = bool(default_account.get("enabled", True))
            current_whatsapp["mode"] = "api"
            current_whatsapp["identifier"] = str(
                default_account.get("phoneNumber")
                or default_account.get("label")
                or current_whatsapp.get("identifier")
                or ""
            )
            current_whatsapp["routingLocation"] = str(
                default_account.get("routingLocation")
                or current_whatsapp.get("routingLocation")
                or "NeedHelp"
            )
            current_whatsapp["notes"] = str(
                current_whatsapp.get("notes")
                or "Primary customer channel connected via legacy Meta WhatsApp config."
            )
            settings["whatsapp"] = current_whatsapp

    return settings

def _resolve_legacy_config_path(raw_path):
    path_value = str(raw_path or "").strip()
    if not path_value:
        return ""
    try:
        if not os.path.isabs(path_value):
            path_value = os.path.join(SCRIPT_DIR, path_value)
    except Exception:
        pass
    return path_value

def _build_legacy_gmail_accounts():
    config = _load_legacy_app_config()
    email_cfg = (config.get("email") or {}) if isinstance(config, dict) else {}
    if not isinstance(email_cfg, dict):
        return []

    email_settings = email_cfg.get("settings") or {}
    email_settings = email_settings if isinstance(email_settings, dict) else {}
    sales_cfg = email_cfg.get("sales_inbox") or {}
    sales_cfg = sales_cfg if isinstance(sales_cfg, dict) else {}

    candidates = [
        {
            "id": "legacy_gmail_primary",
            "label": "Primary Gmail",
            "emailAddress": str(email_cfg.get("email_address") or "").strip(),
            "enabled": True,
            "isDefaultInbound": True,
            "isDefaultOutbound": True,
            "routingLocation": "All",
            "tokenFile": str(email_settings.get("token_file") or "").strip(),
            "credentialsFile": str(email_settings.get("credentials_file") or "").strip(),
            "notes": "Imported from legacy primary Gmail configuration.",
        }
    ]

    if bool(sales_cfg.get("enabled")) and str(sales_cfg.get("email_address") or "").strip():
        candidates.append(
            {
                "id": "legacy_gmail_sales",
                "label": "Sales Gmail",
                "emailAddress": str(sales_cfg.get("email_address") or "").strip(),
                "enabled": True,
                "isDefaultInbound": False,
                "isDefaultOutbound": False,
                "routingLocation": "Sales",
                "tokenFile": str(sales_cfg.get("token_file") or "").strip(),
                "credentialsFile": str(sales_cfg.get("credentials_file") or "").strip(),
                "notes": "Imported from legacy sales inbox Gmail configuration.",
            }
        )

    accounts = []
    for item in candidates:
        email_address = str(item.get("emailAddress") or "").strip()
        if not email_address:
            continue
        token_file = str(item.get("tokenFile") or "").strip()
        credentials_file = str(item.get("credentialsFile") or "").strip()
        token_path = _resolve_legacy_config_path(token_file)
        credentials_path = _resolve_legacy_config_path(credentials_file)

        has_token_reference = bool(token_file)
        has_credentials_reference = bool(credentials_file)
        token_exists = bool(token_path and os.path.exists(token_path))
        credentials_exists = bool(credentials_path and os.path.exists(credentials_path))
        connection_status = "connected" if (has_token_reference or token_exists) else ("ready" if has_credentials_reference or credentials_exists else "draft")

        accounts.append(
            {
                "id": str(item.get("id") or ""),
                "label": str(item.get("label") or email_address),
                "provider": "gmail",
                "enabled": bool(item.get("enabled", True)),
                "isDefaultInbound": bool(item.get("isDefaultInbound")),
                "isDefaultOutbound": bool(item.get("isDefaultOutbound")),
                "emailAddress": email_address,
                "routingLocation": str(item.get("routingLocation") or "Sales"),
                "connectionStatus": connection_status,
                "clientIdHint": os.path.basename(credentials_file or credentials_path or ""),
                "refreshTokenHint": os.path.basename(token_file or token_path or ""),
                "signature": "",
                "notes": str(item.get("notes") or ""),
            }
        )

    if accounts and not any(item.get("isDefaultInbound") for item in accounts):
        accounts[0]["isDefaultInbound"] = True
    if accounts and not any(item.get("isDefaultOutbound") for item in accounts):
        accounts[0]["isDefaultOutbound"] = True
    return accounts

def _merge_channel_settings_with_legacy_email(raw_settings):
    settings = dict(raw_settings) if isinstance(raw_settings, dict) else {}
    legacy_accounts = _build_legacy_gmail_accounts()
    existing_accounts = settings.get("emailAccounts")
    existing_accounts = existing_accounts if isinstance(existing_accounts, list) else []

    if not legacy_accounts:
        return settings

    merged_accounts = []
    legacy_by_email = {
        str(item.get("emailAddress") or "").strip().lower(): item
        for item in legacy_accounts
        if isinstance(item, dict) and str(item.get("emailAddress") or "").strip()
    }
    matched_legacy_emails = set()

    for item in existing_accounts:
        if not isinstance(item, dict):
            continue
        merged = dict(item)
        email_key = str(merged.get("emailAddress") or "").strip().lower()
        legacy = legacy_by_email.get(email_key)
        if legacy:
            matched_legacy_emails.add(email_key)
            for field in (
                "label",
                "provider",
                "enabled",
                "isDefaultInbound",
                "isDefaultOutbound",
                "routingLocation",
                "connectionStatus",
                "clientIdHint",
                "refreshTokenHint",
                "signature",
                "notes",
            ):
                value = merged.get(field)
                if value in (None, "", []):
                    merged[field] = legacy.get(field)
            if str(merged.get("provider") or "").strip().lower() != "gmail":
                merged["provider"] = "gmail"
            if str(merged.get("connectionStatus") or "").strip().lower() == "draft":
                merged["connectionStatus"] = legacy.get("connectionStatus") or "ready"
        merged_accounts.append(merged)

    for legacy in legacy_accounts:
        email_key = str(legacy.get("emailAddress") or "").strip().lower()
        if email_key and email_key in matched_legacy_emails:
            continue
        merged_accounts.append(dict(legacy))

    if merged_accounts:
        seen_default_inbound = False
        seen_default_outbound = False
        for item in merged_accounts:
            if not isinstance(item, dict):
                continue
            if bool(item.get("isDefaultInbound")) and not seen_default_inbound:
                seen_default_inbound = True
            else:
                item["isDefaultInbound"] = False
            if bool(item.get("isDefaultOutbound")) and not seen_default_outbound:
                seen_default_outbound = True
            else:
                item["isDefaultOutbound"] = False
        if not seen_default_inbound:
            for item in merged_accounts:
                if isinstance(item, dict) and bool(item.get("enabled", True)):
                    item["isDefaultInbound"] = True
                    seen_default_inbound = True
                    break
        if not seen_default_outbound:
            for item in merged_accounts:
                if isinstance(item, dict) and bool(item.get("enabled", True)):
                    item["isDefaultOutbound"] = True
                    break
        settings["emailAccounts"] = merged_accounts

    had_existing_email_accounts = any(isinstance(item, dict) for item in existing_accounts)
    if not had_existing_email_accounts:
        current_email = settings.get("email")
        current_email = dict(current_email) if isinstance(current_email, dict) else {}
        default_account = next(
            (
                item
                for item in merged_accounts
                if isinstance(item, dict)
                and bool(item.get("enabled", True))
                and bool(item.get("isDefaultOutbound"))
            ),
            None,
        ) or next(
            (
                item
                for item in merged_accounts
                if isinstance(item, dict)
                and bool(item.get("enabled", True))
                and bool(item.get("isDefaultInbound"))
            ),
            None,
        ) or next(
            (
                item
                for item in merged_accounts
                if isinstance(item, dict) and bool(item.get("enabled", True))
            ),
            None,
        )
        if default_account:
            current_email["enabled"] = bool(default_account.get("enabled", True))
            current_email["mode"] = "email"
            current_email["identifier"] = str(
                default_account.get("emailAddress")
                or default_account.get("label")
                or current_email.get("identifier")
                or ""
            )
            current_email["routingLocation"] = str(
                default_account.get("routingLocation")
                or current_email.get("routingLocation")
                or "All"
            )
            current_email["notes"] = str(
                current_email.get("notes")
                or "Default account imported from legacy Gmail configuration."
            )
            settings["email"] = current_email

    return settings

def _get_channel_settings():
    raw = _read_setting_value("dashboard_channel_settings")
    if not isinstance(raw, dict):
        raw = {}
    merged = _merge_channel_settings_with_legacy_whatsapp(raw)
    merged = _merge_channel_settings_with_legacy_email(merged)
    return merged

def _write_setting_value(key, value):
    raw_value = value
    if isinstance(raw_value, (dict, list)):
        raw_value = json.dumps(raw_value, ensure_ascii=False)
    chat_db.set_setting(key, str(raw_value) if raw_value is not None else "")
    try:
        _SETTINGS_CACHE[f"settings:{key}"] = value
    except Exception:
        pass

def _get_dashboard_email_oauth_tokens():
    raw = _read_setting_value("dashboard_email_oauth_tokens")
    return raw if isinstance(raw, dict) else {}

def _save_dashboard_email_oauth_tokens(tokens_map):
    normalized = tokens_map if isinstance(tokens_map, dict) else {}
    _write_setting_value("dashboard_email_oauth_tokens", normalized)
    return normalized

def _get_dashboard_email_oauth_states():
    raw = _read_setting_value("dashboard_email_oauth_states")
    return raw if isinstance(raw, dict) else {}

def _save_dashboard_email_oauth_states(states_map):
    normalized = states_map if isinstance(states_map, dict) else {}
    _write_setting_value("dashboard_email_oauth_states", normalized)
    return normalized

def _get_dashboard_email_accounts():
    settings = _get_channel_settings()
    accounts = settings.get("emailAccounts") if isinstance(settings, dict) else None
    return accounts if isinstance(accounts, list) else []

def _update_dashboard_email_account(account_id, updater):
    settings = _get_channel_settings()
    if not isinstance(settings, dict):
        settings = {}
    accounts = settings.get("emailAccounts")
    if not isinstance(accounts, list):
        accounts = []
    changed = False
    next_accounts = []
    for item in accounts:
        if not isinstance(item, dict):
            next_accounts.append(item)
            continue
        if str(item.get("id") or "").strip() != str(account_id or "").strip():
            next_accounts.append(item)
            continue
        updated = updater(dict(item))
        next_accounts.append(updated if isinstance(updated, dict) else dict(item))
        changed = True
    if changed:
        settings["emailAccounts"] = next_accounts
        _write_setting_value("dashboard_channel_settings", settings)
    return changed, settings

def _get_channel_config(channel_key):
    settings = _get_channel_settings()
    cfg = settings.get(str(channel_key or "").strip().lower()) if isinstance(settings, dict) else None
    if not isinstance(cfg, dict):
        cfg = {}
    enabled = cfg.get("enabled")
    if not isinstance(enabled, bool):
        enabled = True
    routing = str(cfg.get("routingLocation") or "").strip()
    return enabled, routing, cfg

def _channel_policy_for_message(source, sender_identifier=None):
    channel_key = _channel_key_from_message(source, sender_identifier)
    enabled, routing, cfg = _get_channel_config(channel_key)
    return channel_key, enabled, routing, cfg

def _default_facebook_routing_location():
    config = _load_legacy_app_config()
    facebook_cfg = (config.get("facebook") or {}) if isinstance(config, dict) else {}
    if not isinstance(facebook_cfg, dict):
        facebook_cfg = {}
        
    # Check if there is an explicit routing_location
    explicit_routing = str(facebook_cfg.get("routing_location") or "").strip()
    if explicit_routing and explicit_routing != "All":
        return explicit_routing
        
    page_name = str(facebook_cfg.get("page_name") or "").strip().lower()
    religious_keywords = (
        "religious",
        "hajj",
        "umrah",
        "الحج",
        "العمرة",
        "حج",
        "عمر",
    )
    if any(keyword in page_name for keyword in religious_keywords):
        return "Religious"
    return "Hurghada/Cairo"

def _friendly_template_title(template_name):
    name = str(template_name or "").strip().lower()
    mapping = {
        "ftstravels_confirm_payment": "Payment Template Sent",
        "whatsapp_pickup_time": "Pickup Template Sent",
        "pickup_time_new1": "Pickup Template Sent",
        "attachment_pickup": "Attachment Template Sent",
        "new_qr_ticket": "Ticket Template Sent",
        "qr_tickets_with_pickup": "Ticket Template Sent",
        "fts_ticket": "Attachment Template Sent",
        "audio_guide_app": "Audio Guide Template Sent",
        "feedbackk": "Review Template Sent",
        "photographers__sent_link": "Photographer Template Sent",
        "collect_info": "Collection Template Sent",
        "new_collect": "Collection Template Sent",
        "welcome_plane": "Welcome Plane Template Sent",
        "3omra": "Umrah Campaign Template Sent",
    }
    return mapping.get(name, f"{str(template_name or 'Template').strip()} Sent")

def _format_template_chat_text(template_name, shown="", fallback_text="", extra_link=""):
    parts = [f"[Sent WhatsApp] {_friendly_template_title(template_name)}"]
    shown_s = str(shown or "").strip()
    fallback_s = str(fallback_text or "").strip()
    link_s = str(extra_link or "").strip()
    if shown_s:
        parts.append(shown_s)
    elif fallback_s:
        parts.append(fallback_s)
    if link_s:
        parts.append(link_s)
    return "\n".join([p for p in parts if p])

def _dbg_install_hooks():
    _dbg_report("process.hooks.install.start")

    def _excepthook(exc_type, exc, tb):
        _dbg_report(
            "process.sys.excepthook",
            exc_type=getattr(exc_type, "__name__", str(exc_type)),
            exc_repr=repr(exc),
        )
        try:
            sys.__excepthook__(exc_type, exc, tb)
        except Exception:
            pass

    sys.excepthook = _excepthook

    if hasattr(threading, "excepthook") and hasattr(threading, "__excepthook__"):
        def _thread_excepthook(args):
            _dbg_report(
                "process.thread.excepthook",
                thread_name=getattr(getattr(args, "thread", None), "name", None),
                exc_type=getattr(getattr(args, "exc_type", None), "__name__", None),
                exc_repr=repr(getattr(args, "exc_value", None)),
            )
            try:
                threading.__excepthook__(args)
            except Exception:
                pass

        threading.excepthook = _thread_excepthook

    atexit.register(lambda: _dbg_report("process.atexit"))

    for sig in ("SIGTERM", "SIGINT", "SIGBREAK"):
        s = getattr(signal, sig, None)
        if s is None:
            continue
        try:
            prev = signal.getsignal(s)
            def _handler(*_args, _sig=sig, _prev=prev):
                try:
                    _dbg_report("process.signal", signal=_sig)
                except Exception:
                    pass
                try:
                    if callable(_prev):
                        return _prev(*_args)
                except Exception:
                    pass
            signal.signal(s, _handler)
        except Exception:
            pass

    _dbg_report("process.hooks.install.done")

_dbg_install_hooks()
_dbg_report("process.import.done")

def _dbg_start_heartbeat():
    if not _DEBUG_SERVER_URL:
        return
    def _hb():
        while True:
            try:
                _dbg_report("process.heartbeat", pid=os.getpid())
            except Exception:
                pass
            time.sleep(30)
    try:
        threading.Thread(target=_hb, daemon=True, name="dbg-heartbeat").start()
    except Exception:
        pass

_dbg_start_heartbeat()
#endregion

