    def _refresh_dynamic_email_services(self, force=False):
        now_ts = time.time()
        if not force and (now_ts - float(getattr(self, "_dynamic_email_services_loaded_at", 0.0) or 0.0) < 5.0):
            return

        email_accounts = _get_dashboard_email_accounts()
        oauth_tokens = _get_dashboard_email_oauth_tokens()
        credentials_path = self._get_dashboard_oauth_email_credentials_path()
        next_services = {}
        next_accounts = {}

        for item in email_accounts:
            if not isinstance(item, dict):
                continue
            account_id = str(item.get('id') or "").strip()
            if not account_id:
                continue
            token_payload = oauth_tokens.get(account_id)
            account = dict(item)
            account['id'] = account_id
            next_accounts[account_id] = account
            if not bool(account.get('enabled', True)):
                continue
            if not token_payload:
                continue
            try:
                gmail_svc = GmailService(credentials_file=credentials_path, token_json=token_payload)
                if not gmail_svc.service:
                    continue
                if not str(account.get('emailAddress') or "").strip():
                    discovered_email = gmail_svc.get_profile_email()
                    if discovered_email:
                        account['emailAddress'] = discovered_email
                next_services[account_id] = gmail_svc
            except Exception as e:
                logging.error(f"Failed to initialize dynamic Gmail account {account_id}: {e}")

        self.dynamic_gmail_services = next_services
        self.dynamic_email_accounts = next_accounts
        self._dynamic_email_services_loaded_at = now_ts

    def _get_dynamic_email_account(self, account_id):
        self._refresh_dynamic_email_services()
        return self.dynamic_email_accounts.get(str(account_id or "").strip())

    def _get_default_dynamic_email_account_id(self, direction="outbound"):
        self._refresh_dynamic_email_services()
        for account_id, account in (self.dynamic_email_accounts or {}).items():
            if account_id not in self.dynamic_gmail_services:
                continue
            if direction == "inbound" and bool(account.get('isDefaultInbound')):
                return account_id
            if direction == "outbound" and bool(account.get('isDefaultOutbound')):
                return account_id
        for account_id, account in (self.dynamic_email_accounts or {}).items():
            if account_id in self.dynamic_gmail_services and bool(account.get('enabled', True)):
                return account_id
        return None

    def _select_gmail_service(self, mailbox=None, direction="outbound", sales_fallback=False):
        self._refresh_dynamic_email_services()
        mailbox_key = str(mailbox or "").strip()
        if mailbox_key and mailbox_key in self.dynamic_gmail_services:
            return self.dynamic_gmail_services[mailbox_key], mailbox_key

        normalized_mailbox_key = mailbox_key.lower()
        if normalized_mailbox_key == "sales":
            if getattr(self, "sales_gmail_service", None):
                return self.sales_gmail_service, "sales"
            return self.gmail_service, "booking"
        if normalized_mailbox_key == "booking":
            return self.gmail_service, "booking"

        default_dynamic_id = self._get_default_dynamic_email_account_id(direction=direction)
        if default_dynamic_id and default_dynamic_id in self.dynamic_gmail_services:
            return self.dynamic_gmail_services[default_dynamic_id], default_dynamic_id

        if sales_fallback and getattr(self, "sales_gmail_service", None):
            return self.sales_gmail_service, "sales"
        return self.gmail_service, "booking"

    def setup_connections(self):
        try:
            self.airtable_api = Api(self.config['airtable']['api_key'])
            self.base_id = self.config['airtable']['base_id']
            # ENABLE FIELD IDs for Robustness
            # pyairtable uses 'return_fields_by_field_id' ONLY in methods like all(), not in table constructor.
            # But wait, pyairtable 2.x+ supports this in Api.table? No, it's usually per-request.
            # Let's check docs logic: 
            # Actually, to use field IDs in responses, we should pass it to the 'all()' method, NOT the constructor.
            self.table = self.airtable_api.table(
                self.base_id, 
                self.config['airtable']['tables']['main_list']
            )
            
            # Initialize Leads Table
            try:
                self.leads_table = self.airtable_api.table(self.base_id, LEADS_TABLE_NAME)
                logging.info(f"Connected to Leads Table: {LEADS_TABLE_NAME}")
            except Exception:
                logging.warning(f"Leads Table '{LEADS_TABLE_NAME}' not found or connection failed.")
                self.leads_table = None

            # Religious Tourism Base
            if 'religious_base_id' in self.config['airtable']:
                self.religious_base_id = self.config['airtable']['religious_base_id']
                try:
                    rel_leads_name = self.config['airtable']['tables'].get('religious_leads', 'استفسارات جديدة')
                    self.religious_leads_table = self.airtable_api.table(self.religious_base_id, rel_leads_name)
                    
                    self.religious_tables = {
                        t_name: self.airtable_api.table(self.religious_base_id, t_name)
                        for t_name in self.config['airtable']['tables'].get('religious_tables', [])
                    }
                    logging.info(f"Connected to Religious Tourism Airtable. Loaded {len(self.religious_tables)} tables.")
                except Exception as e:
                    logging.error(f"Failed to connect to Religious Base tables: {e}")
                    self.religious_leads_table = None
                    self.religious_tables = {}
            else:
                self.religious_base_id = None
                self.religious_leads_table = None
                self.religious_tables = {}

            try:
                drivers_table_name = ((self.config.get('airtable', {}) or {}).get('tables', {}) or {}).get('drivers') or "Add Driver Name & Phone copy"
                self.drivers_table = self.airtable_api.table(self.base_id, drivers_table_name)
                logging.info(f"Connected to Drivers Table: {drivers_table_name}")
            except Exception:
                logging.warning("Drivers Table not found or connection failed.")
                self.drivers_table = None
            self._drivers_cache = {"ts": None, "keys": set(), "name_by_key": {}}

            try:
                guides_table_name = ((self.config.get('airtable', {}) or {}).get('tables', {}) or {}).get('guides') or "Add Guide Name & Phone"
                self.guides_table = self.airtable_api.table(self.base_id, guides_table_name)
                logging.info(f"Connected to Guides Table: {guides_table_name}")
            except Exception:
                logging.warning("Guides Table not found or connection failed.")
                self.guides_table = None
            self._guides_cache = {"ts": None, "keys": set(), "name_by_key": {}}
            
            # Initialize Trips Catalog Table
            self.trips_table = None
            if 'trips_base_id' in self.config['airtable']:
                self.trips_base_id = self.config['airtable']['trips_base_id']
                # Trips catalog can still use names if we want, or switch to IDs if we mapped it.
                # For now, let's keep Trips Catalog as is (Names) to avoid breaking search logic unless we mapped it too.
                # Assuming 'Trips' table structure is stable or less critical for this specific refactor.
                self.trips_table = self.airtable_api.table(self.trips_base_id, self.config['airtable']['tables']['trips_catalog'])
                logging.info("Connected to Trips Catalog Airtable.")
            else:
                logging.warning("Trips Base ID not found in config.")

            # Initialize Hotel Transfer Table
            try:
                self.hotel_transfer_table = self.airtable_api.table(self.base_id, HOTEL_TRANSFER_TABLE_NAME)
                logging.info(f"Connected to Hotel Transfer Table: {HOTEL_TRANSFER_TABLE_NAME}")
            except Exception:
                logging.warning(f"Hotel Transfer Table '{HOTEL_TRANSFER_TABLE_NAME}' not found.")
                self.hotel_transfer_table = None

            # Initialize MPC Table (Master Product Catalog)
            try:
                self.mpc_table = self.airtable_api.table(self.base_id, "MPC")
                logging.info("Connected to MPC Table.")
            except Exception:
                logging.warning("MPC Table not found.")
                self.mpc_table = None

            self.kb = KnowledgeBase()
            # Sync Knowledge Base with Trips if available
            if self.trips_table:
                logging.info("Syncing Trips DB to Knowledge Base...")
                # Fetch with cell_format='string' to get readable names for Linked Records (like Inclusions)
                try:
                    all_trips = self.trips_table.all(cell_format='string', time_zone='Africa/Cairo', user_locale='en-US')
                except Exception as e:
                    logging.warning(f"Failed to fetch trips with string format, falling back to default: {e}")
                    all_trips = self.trips_table.all()
                    
                self.kb.sync_trips_from_airtable(all_trips)
            
            self.kb.build_if_needed()
            
            # --- DYNAMIC SCHEMA DISCOVERY ---
            logging.info("Analyzing Table Schemas for Context...")
            self.trips_schema_context = self._analyze_table_schema(self.trips_table)
            # We can also analyze the Booking table schema if needed, but usually Trips is more opaque
            
            logging.info("Connected to Airtable and Knowledge Base ready.")
        except Exception as e:
            logging.error(f"Airtable connection failed: {e}")

    def _analyze_table_schema(self, table, sample_size=3):
        """
        Dynamically inspects a table to create a schema reference for the AI.
        Returns a string describing fields, types, and examples.
        """
        if not table:
            return "Table not available."
            
        try:
            # Use cell_format='string' to get readable examples
            try:
                records = table.all(max_records=sample_size, cell_format='string', time_zone='Africa/Cairo', user_locale='en-US')
            except Exception:
                records = table.all(max_records=sample_size)
                
            if not records:
                return "Table is empty."
                
            schema_map = {}
            
            for rec in records:
                fields = rec.get('fields', {})
                for key, val in fields.items():
                    if key not in schema_map:
                        # Determine readable name
                        readable = ID_TO_READABLE_NAME.get(key, key)
                        # Infer simple type
                        val_type = type(val).__name__
                        if isinstance(val, list):
                            val_type = "List"
                        
                        schema_map[key] = {
                            "name": readable,
                            "type": val_type,
                            "examples": set()
                        }
                    
                    # Add unique examples (up to 2)
                    if val and len(schema_map[key]["examples"]) < 2:
                        s_val = str(val)
                        if len(s_val) > 50: s_val = s_val[:47] + "..."
                        schema_map[key]["examples"].add(s_val)
            
            # Format output
            lines = []
            for key, info in schema_map.items():
                examples = ", ".join([f'"{ex}"' for ex in info["examples"]])
                lines.append(f'- Field: "{info["name"]}" | Type: {info["type"]} | Examples: {examples}')
                
            return "\n".join(lines)
        except Exception as e:
            logging.error(f"Schema analysis failed: {e}")
            return "Schema analysis failed."

    def _get_manual_cairo_offset(self, dt_utc):
        """
        Manually calculate Cairo Offset (UTC+2 Winter, UTC+3 Summer)
        Egypt DST: Last Friday of April to Last Thursday of October.
        Approximation: May to September is definitely Summer (+3).
        April and October are transitional.
        Jan, Feb, Mar, Nov, Dec are Winter (+2).
        """
        # Simple approximation for fallback
        month = dt_utc.month
        if 5 <= month <= 9: # May to Sept -> Summer
            return timedelta(hours=3)
        elif month in [1, 2, 3, 11, 12]: # Winter
            return timedelta(hours=2)
        else:
            if month == 10:
                return timedelta(hours=3)
            return timedelta(hours=2)

    def get_field_value(self, fields, field_id):
        """
        Robustly get field value using ID or Mapped Name.
        """
        # Safety Check
        if not fields:
            return None
            
        # 1. Try ID directly (if fetch used IDs)
        val = fields.get(field_id)
        if val is not None:
            return val
            
        # 2. Try Mapped Name (if fetch used Names)
        name = ID_TO_READABLE_NAME.get(field_id)
        if name:
            val = fields.get(name)
            if val is not None:
                return val
            try:
                want = str(name).strip().lower()
                for k in fields.keys():
                    kk = str(k).strip().lower()
                    if kk == want:
                        return fields.get(k)
            except Exception:
                pass
                
        return None

    def get_corrected_trip_date(self, date_trip_str):
        """
        Parses trip date from Airtable string and converts to EET (Cairo Time).
        Handles ISO format, space-separated format, and simple date.
        """
        try:
            if not date_trip_str:
                return None, "Unknown Date"
            
            # Normalize format: Replace space with T to handle "2026-01-22 00:00:00"
            clean_date_str = date_trip_str.strip()
            if ' ' in clean_date_str and 'T' not in clean_date_str:
                clean_date_str = clean_date_str.replace(' ', 'T')
            
            # Handle ISO format
            if 'T' in clean_date_str:
                # Handle Z for UTC
                if clean_date_str.endswith('Z'):
                    clean_date_str = clean_date_str.replace('Z', '+00:00')
                
                try:
                    trip_dt = datetime.fromisoformat(clean_date_str)
                except ValueError:
                     trip_dt = datetime.fromisoformat(clean_date_str.split('.')[0])

                # If naive (no timezone), ASSUME UTC to avoid system local time interference
                if trip_dt.tzinfo is None:
                    trip_dt = trip_dt.replace(tzinfo=pytz.utc)
                
                # Convert to Cairo Time
                if self.cairo_tz:
                    trip_dt_cairo = trip_dt.astimezone(self.cairo_tz)
                else:
                    offset = self._get_manual_cairo_offset(trip_dt)
                    trip_dt_cairo = trip_dt + offset
                    
                return trip_dt_cairo.date(), trip_dt_cairo.strftime("%A, %d %B %Y")
            else:
                # Handle simple YYYY-MM-DD
                trip_date = datetime.strptime(clean_date_str, "%Y-%m-%d").date()
                return trip_date, trip_date.strftime("%A, %d %B %Y")
        except Exception as e:
            logging.warning(f"Date parsing failed for '{date_trip_str}': {e}")
            try:
                match = re.search(r'(\d{4}-\d{2}-\d{2})', str(date_trip_str))
                if match:
                     d_str = match.group(1)
                     d_obj = datetime.strptime(d_str, "%Y-%m-%d").date()
                     return d_obj, d_obj.strftime("%A, %d %B %Y")
            except:
                pass
            return None, str(date_trip_str)


    def search_trips_db(self, query):
        """
        Search the Trips Airtable for trip details.
        Matches against Title, TripCode, or keywords in Description.
        """
        if not self.trips_table:
            return ""
            
        try:
            all_trips = self.trips_table.all()
            
            query_lower = query.lower()
            matches = []
            
            for trip in all_trips:
                fields = trip['fields']
                title = fields.get('Title', '').lower()
                code = fields.get('TripCode', '').lower()
                
                # Score match
                score = 0
                if code and code in query_lower:
                    score += 100 # Exact code match is strong
                
                # Check for Title Match
                if title:
                    # Exact phrase match (Strong)
                    if query_lower in title:
                        score += 50
                    
                    # Keyword match (Flexible)
                    query_words = set(query_lower.split())
                    # Clean title words (remove punctuation)
                    title_clean = re.sub(r'[^\w\s]', '', title).lower()
                    title_words = set(title_clean.split())
                    
                    overlap = len(query_words.intersection(title_words))
                    if overlap > 0:
                        score += 10 * overlap
                        
                if score > 0:
                    matches.append((score, fields))
            
            matches.sort(key=lambda x: x[0], reverse=True)
            
            if not matches:
                return ""
                
            best_match = matches[0][1]
            
            context = f"""
            **Trip Details Found in Database:**
            - **Title:** {best_match.get('Title')}
            - **Code:** {best_match.get('TripCode')}
            - **Duration:** {best_match.get('Duration_Hours')} {best_match.get('Duration_Unit')}
            - **Price From:** {best_match.get('Price_From')} {best_match.get('Currency')}
            - **Highlights:** {best_match.get('TripHighlights')}
            - **Description:** {best_match.get('Trip_Description', '')[:800]}...
            - **Inclusions:** {best_match.get('TripIncludes')}
            - **Exclusions:** {best_match.get('TripExcludes')}
            - **Itinerary Steps:** {best_match.get('ItinerarySteps')}
            - **Itinerary Description:** {best_match.get('Itinerary_Description', '')[:500]}...
            - **FAQs:** {best_match.get('TripFAQs')}
            - **Important Notes:** {best_match.get('FTS_Notice')}
            """
            return context

        except Exception as e:
            logging.error(f"Error searching Trips DB: {e}")
            return ""

    def get_kb_context(self, query_text, department=None, religious_product_family=None):
        """
        Retrieves relevant context from the Knowledge Base (Trips & Past Emails & Uploaded Docs).
        For Religious department, ALWAYS injects core guidelines + safety rules.
        religious_product_family: optional 'hajj' / 'umrah' to avoid injecting the wrong program family.
        """
        try:
            if not query_text:
                return ""
            
            ctx = ""
            family = str(religious_product_family or "").strip().lower()
            
            # --- RELIGIOUS DEPARTMENT: Always inject core context ---
            if department and str(department).lower() == "religious":
                religious_ctx = self.kb.get_religious_core_context()
                if religious_ctx:
                    ctx += religious_ctx + "\n\n"
                    logging.info("Injected religious core context into KB response")
                
                # Inject only the matching product family when known from Facebook Ad routing.
                if family == "umrah" and hasattr(self.kb, "get_umrah_programs_context"):
                    programs_ctx = self.kb.get_umrah_programs_context()
                    if programs_ctx:
                        ctx += programs_ctx + "\n\n"
                        logging.info("Injected Umrah programs context into KB response (ad-routed)")
                elif family != "umrah":
                    programs_ctx = self.kb.get_hajj_programs_context()
                    if programs_ctx:
                        ctx += programs_ctx + "\n\n"
                        logging.info("Injected Hajj programs context into KB response")
            
            # Search KB (Trips + Emails + Docs)
            # The KB now has smart fallback (Strict -> Keywords) to find "similar meaning"
            results = self.kb.search(query_text, department=department, top_k=4)
            
            for r in results:
                # Format clearly for the LLM to understand this is PAST DATA
                source_label = r.get('source', 'Unknown Source')
                content = r.get('content', '')
                
                if source_label == "Email Archive":
                    ctx += f"--- [PAST SIMILAR TICKET] ---\n{content}\n"
                else:
                    ctx += f"--- [INTERNAL DATA: {source_label}] ---\n{content}\n"
            
            if not ctx:
                return ""
            return ctx
        except Exception as e:
            logging.error(f"KB search error: {e}")
            return ""

    def _religious_leads_table_name(self):
        try:
            return str(
                self.config.get("airtable", {}).get("tables", {}).get("religious_leads", "استفسارات جديدة") or "استفسارات جديدة"
            ).strip()
        except Exception:
            return "استفسارات جديدة"

    def _is_religious_leads_table(self, table_name):
        return bool(str(table_name or "").strip() == self._religious_leads_table_name())

    def _is_lead_like_table(self, table_name):
        table_name = str(table_name or "").strip()
        return bool(table_name == LEADS_TABLE_NAME or self._is_religious_leads_table(table_name))

    def _classify_airtable_record_table(self, rec):
        """
        Infer the real owning table from record fields.

        Airtable's Records API can return a record by ID even when the URL table
        name is wrong. Relying on which .get() succeeded therefore mis-labels
        Leads CRM rows as List and then List-only fields (Inquiry Type, Remarks)
        fail with UNKNOWN_FIELD_NAME.
        """
        if not isinstance(rec, dict):
            return None
        fields = rec.get("fields") or {}
        if not isinstance(fields, dict):
            fields = {}

        if LeadFieldIds.LEAD_STATUS in fields:
            return LEADS_TABLE_NAME

        religious_markers = (
            ReligiousLeadFieldIds.CUSTOMER_NAME,  # "الاسم"
            ReligiousLeadFieldIds.GENDER_OR_TYPE,
            ReligiousLeadFieldIds.INQUIRY_DETAILS,
            ReligiousLeadFieldIds.INQUIRY_DATE,
        )
        if any(marker in fields for marker in religious_markers):
            return self._religious_leads_table_name()

        existing = str(rec.get("table_name") or "").strip()
        if self._is_lead_like_table(existing):
            return existing

        main_list = self.config.get("airtable", {}).get("tables", {}).get("main_list") or "List"
        list_markers = (
            "Booking Nr.",
            "Date Trip",
            "Inquiry Type",
            "Remarks",
            "des",
            "trip Name",
        )
        if any(marker in fields for marker in list_markers):
            return main_list
        if self.get_field_value(fields, FieldIds.BOOKING_NR):
            return main_list

        return existing or main_list

    def _is_lead_like_record(self, record):
        if not isinstance(record, dict):
            return False
        if self._is_lead_like_table(record.get("table_name")):
            return True
        classified = self._classify_airtable_record_table(record)
        return self._is_lead_like_table(classified)

    def _contact_field_keys_for_table(self, table_name):
        table_name = str(table_name or "").strip()
        if table_name == LEADS_TABLE_NAME:
            return {
                "name": LeadFieldIds.CUSTOMER_NAME,
                "phone": LeadFieldIds.CUSTOMER_PHONE,
                "email": LeadFieldIds.CUSTOMER_EMAIL,
                "personal_email": LeadFieldIds.CUSTOMER_EMAIL,
            }
        if self._is_religious_leads_table(table_name):
            return {
                "name": ReligiousLeadFieldIds.CUSTOMER_NAME,
                "phone": ReligiousLeadFieldIds.CUSTOMER_PHONE,
                "email": ReligiousLeadFieldIds.CUSTOMER_EMAIL,
                "personal_email": ReligiousLeadFieldIds.CUSTOMER_EMAIL,
            }
        return {
            "name": FieldIds.CUSTOMER_NAME,
            "phone": FieldIds.CUSTOMER_PHONE,
            "email": FieldIds.CUSTOMER_EMAIL,
            "personal_email": FieldIds.CUSTOMER_PERSONAL_EMAIL,
        }

    def _extracted_json_key_to_field_key(self, json_key, table_name):
        table_name = str(table_name or "").strip()
        if self._is_religious_leads_table(table_name):
            religious_map = {
                "Customer Name": ReligiousLeadFieldIds.CUSTOMER_NAME,
                "Customer personal email": ReligiousLeadFieldIds.CUSTOMER_EMAIL,
                "Customer Email": ReligiousLeadFieldIds.CUSTOMER_EMAIL,
                "Customer Phone": ReligiousLeadFieldIds.CUSTOMER_PHONE,
                "Note": ReligiousLeadFieldIds.NOTES,
            }
            return religious_map.get(json_key)
        # Leads CRM has a small schema — never map List-only fields like Traveler name.
        if table_name == LEADS_TABLE_NAME:
            leads_map = {
                "Customer Name": LeadFieldIds.CUSTOMER_NAME,
                "Customer personal email": LeadFieldIds.CUSTOMER_EMAIL,
                "Customer Email": LeadFieldIds.CUSTOMER_EMAIL,
                "Customer Phone": LeadFieldIds.CUSTOMER_PHONE,
                "Note": LeadFieldIds.FOLLOW_UP_NOTES,
            }
            return leads_map.get(json_key)
        return JSON_KEY_TO_ID.get(json_key)

    def _get_contact_field_value(self, fields, table_name, field_kind):
        if not fields:
            return None
        field_key = self._contact_field_keys_for_table(table_name).get(field_kind)
        if not field_key:
            return None
        if isinstance(field_key, str):
            val = fields.get(field_key)
            if val is not None:
                return val
        return self.get_field_value(fields, field_key)

    def _coerce_single_line_text_value(self, value):
        """Coerce AI/API values into a single-line text Airtable value, or None to skip."""
        if value is None:
            return None
        if isinstance(value, bool):
            return None
        if isinstance(value, (int, float)):
            try:
                if isinstance(value, float) and value.is_integer():
                    return str(int(value))
                return str(value)
            except Exception:
                return None
        if isinstance(value, list):
            parts = []
            for item in value:
                coerced = self._coerce_single_line_text_value(item)
                if coerced:
                    parts.append(coerced)
            return ", ".join(parts) if parts else None
        if isinstance(value, dict):
            return None
        text = str(value).strip()
        if not text:
            return None
        # Common extraction leftovers that are not real ages.
        if text.lower() in {"years", "year", "age", "ages", "n/a", "na", "none", "null", "unknown", "-", "--"}:
            return None
        return text

    def _sanitize_booking_field_updates(self, updates):
        """
        Normalize field values that Airtable rejects when the type is wrong.
        CHD Age is singleLineText — numbers/lists from AI extraction must become strings.
        pickup time is singleSelect (HH:MM) — empty/date-like values must be cleaned.
        """
        if not isinstance(updates, dict) or not updates:
            return updates

        chd_age_keys = {FieldIds.CHD_AGE, "CHD Age", "chd age", "Child Age", "child age"}
        pickup_keys = {
            FieldIds.PICKUP_TIME,
            "pickup time",
            "Pickup Time",
            "Pickup time",
        }

        def _normalize_pickup_time_value(value):
            # Clear select
            if value is None:
                return None
            if isinstance(value, (list, tuple)):
                if not value:
                    return None
                value = value[0]
            if isinstance(value, dict):
                value = value.get("name") or value.get("value") or value.get("id")
            s = str(value or "").strip()
            if not s:
                return None
            # Reject ISO dates / datetimes accidentally sent as pickup time
            if re.match(r"^\d{4}-\d{2}-\d{2}", s):
                logging.warning("Rejecting date-like pickup time value=%r", value)
                return "__SKIP__"
            # Normalize H:MM / HH:MM / HH:MM:SS → HH:MM
            m = re.match(r"^(\d{1,2}):(\d{2})(?::\d{2})?\s*([AaPp][Mm])?$", s)
            if m:
                hh = int(m.group(1))
                mm = int(m.group(2))
                ampm = m.group(3)
                if ampm:
                    ap = ampm.upper()
                    if ap == "AM":
                        if hh == 12:
                            hh = 0
                    else:
                        if hh != 12:
                            hh += 12
                if (0 <= hh <= 23 and 0 <= mm <= 59):
                    # Snap to nearest 5 minutes (Airtable choices are :00/:05/…)
                    snapped = int(round(mm / 5.0) * 5)
                    if snapped == 60:
                        hh = (hh + 1) % 24
                        snapped = 0
                    return f"{hh:02d}:{snapped:02d}"
            # Keep known free-text legacy options that already exist in Airtable
            return s

        sanitized = {}
        for key, value in updates.items():
            key_str = str(key or "").strip()
            is_chd_age = (
                key == FieldIds.CHD_AGE
                or key_str in chd_age_keys
                or key_str.lower() in {"chd age", "child age"}
                or ID_TO_READABLE_NAME.get(key_str) == "CHD Age"
            )
            is_pickup = (
                key in pickup_keys
                or key_str in pickup_keys
                or key_str.lower() == "pickup time"
                or ID_TO_READABLE_NAME.get(key_str) in {"pickup time", "Pickup Time"}
            )
            if is_chd_age:
                coerced = self._coerce_single_line_text_value(value)
                if coerced is None:
                    logging.warning(
                        "Skipping invalid CHD Age update value=%r (must be single-line text)",
                        value,
                    )
                    continue
                sanitized[key] = coerced
            elif is_pickup:
                coerced = _normalize_pickup_time_value(value)
                if coerced == "__SKIP__":
                    continue
                # Airtable singleSelect clear must be null, not ""
                sanitized[key] = coerced
            else:
                sanitized[key] = value
        return sanitized

    def _normalize_airtable_update_keys(self, updates):
        """Convert internal field IDs to Airtable field names before update()."""
        if not isinstance(updates, dict):
            return updates

        normalized_updates = {}
        for key, value in updates.items():
            normalized_key = key
            if isinstance(key, str) and key.startswith("fld"):
                readable_name = ID_TO_READABLE_NAME.get(key)
                if not readable_name or str(readable_name).startswith("fld"):
                    raise KeyError(f"Missing Airtable readable-name mapping for field id '{key}'")
                normalized_key = readable_name
            normalized_updates[normalized_key] = value

        return normalized_updates

    def _create_airtable_table_record(self, table, fields, typecast=False):
        """Apply a normalized Airtable create against any table handle."""
        normalized_fields = self._normalize_airtable_update_keys(fields)
        return table.create(normalized_fields, typecast=typecast)

    def _update_airtable_table_record(self, table, record_id, updates, typecast=False):
        """Apply a normalized Airtable update against any table handle."""
        normalized_updates = self._normalize_airtable_update_keys(updates)
        result = table.update(record_id, normalized_updates, typecast=typecast)
        des_value = None
        for key in (FieldIds.DES, "des", "DES"):
            if key in (normalized_updates or {}):
                des_value = normalized_updates.get(key)
                break
        if des_value is not None:
            try:
                import chat_db
                chat_db.sync_conversation_locations_from_des(record_id, des_value)
            except Exception as sync_err:
                logging.warning(
                    "Failed to sync chat location after Airtable des update for %s: %s",
                    record_id,
                    sync_err,
                )
        return result

    def _filter_updates_for_leads_crm(self, updates):
        """Keep only fields that exist on Leads CRM; drop List-only keys."""
        if not isinstance(updates, dict) or not updates:
            return updates
        allowed = {
            LeadFieldIds.LEAD_STATUS,
            LeadFieldIds.CUSTOMER_NAME,
            LeadFieldIds.CUSTOMER_EMAIL,
            LeadFieldIds.CUSTOMER_PHONE,
            LeadFieldIds.AI_CHAT_LOG,
            LeadFieldIds.LAST_INTERACTION,
            LeadFieldIds.SOURCE,
            LeadFieldIds.INTERESTED_TRIP,
            LeadFieldIds.FOLLOW_UP_NOTES,
            LeadFieldIds.TRAVEL_DATE,
            LeadFieldIds.PAX_COUNT,
            LeadFieldIds.BUDGET,
            "AI Lead Quality Score",
            "Owner",
            "AI Arabic Translation",
        }
        # Remap common List field IDs/names that AI extraction may still emit.
        remap = {
            FieldIds.CUSTOMER_NAME: LeadFieldIds.CUSTOMER_NAME,
            FieldIds.CUSTOMER_PHONE: LeadFieldIds.CUSTOMER_PHONE,
            FieldIds.CUSTOMER_EMAIL: LeadFieldIds.CUSTOMER_EMAIL,
            FieldIds.CUSTOMER_PERSONAL_EMAIL: LeadFieldIds.CUSTOMER_EMAIL,
            FieldIds.NOTE: LeadFieldIds.FOLLOW_UP_NOTES,
            "Note": LeadFieldIds.FOLLOW_UP_NOTES,
            FieldIds.AI_CHAT_LOG: LeadFieldIds.AI_CHAT_LOG,
            "AI Chat Log": LeadFieldIds.AI_CHAT_LOG,
        }
        filtered = {}
        dropped = []
        for key, value in updates.items():
            mapped = remap.get(key, key)
            if mapped in allowed:
                # Prefer first value; do not overwrite with empty.
                if mapped not in filtered or (value and not filtered.get(mapped)):
                    filtered[mapped] = value
            else:
                dropped.append(str(key))
        if dropped:
            logging.info(
                "Dropped Leads-CRM-unsupported Airtable fields from update: %s",
                sorted(set(dropped)),
            )
        return filtered

    def update_booking_record(self, record_id, updates, table_name=None):
        """Update a record in the correct table (Main or Leads)."""
        try:
            target_table = self.table # Default
            effective_table_name = table_name
            if updates and isinstance(updates, dict):
                updates = self._sanitize_booking_field_updates(updates)
                if not updates:
                    logging.info(
                        "No valid fields left to update for record %s after sanitization; skipping.",
                        record_id,
                    )
                    return None

            # Correct mislabeled Leads that were resolved via the List endpoint.
            if updates and isinstance(updates, dict):
                list_only_keys = {
                    FieldIds.INQUIRY_TYPE,
                    "Inquiry Type",
                    FieldIds.REMARKS,
                    "Remarks",
                    FieldIds.AI_CHAT_STATUS,
                    "AI Chat Status",
                    FieldIds.TRAVELER_NAME,
                    "Traveler name",
                    FieldIds.HOTEL_NAME,
                    "Hotel Name",
                    FieldIds.ROOM_NUMBER,
                    "Room number",
                    "Room Number",
                    FieldIds.CHD_AGE,
                    "CHD Age",
                    FieldIds.BOOKING_NR,
                    "Booking Nr.",
                }
                touches_list_only = any(k in list_only_keys for k in updates.keys())
                if touches_list_only and not self._is_lead_like_table(effective_table_name):
                    try:
                        existing = self._get_record_from_any_table(record_id)
                    except Exception:
                        existing = None
                    if self._is_lead_like_record(existing):
                        classified = (
                            (existing or {}).get("table_name")
                            or self._classify_airtable_record_table(existing)
                        )
                        if classified == LEADS_TABLE_NAME:
                            # Re-route to Leads CRM; unsupported List fields are filtered below.
                            effective_table_name = LEADS_TABLE_NAME
                        else:
                            logging.info(
                                "Skipping List-only field update on lead-like record %s (table=%s, fields=%s)",
                                record_id,
                                classified,
                                sorted(str(k) for k in updates.keys()),
                            )
                            return None
                    elif isinstance(existing, dict) and existing.get("table_name"):
                        effective_table_name = existing.get("table_name")
            
            if effective_table_name == LEADS_TABLE_NAME and self.leads_table:
                target_table = self.leads_table
            elif self._is_religious_leads_table(effective_table_name) and self.religious_leads_table:
                target_table = self.religious_leads_table

            if effective_table_name == LEADS_TABLE_NAME or target_table is self.leads_table:
                updates = self._filter_updates_for_leads_crm(updates)
                if not updates:
                    logging.info(
                        "No Leads-CRM-compatible fields left to update for record %s; skipping.",
                        record_id,
                    )
                    return None
            
            # Use typecast=True to allow creating new Select options if needed
            self._update_airtable_table_record(target_table, record_id, updates, typecast=True)
            logging.info(f"Updated record {record_id} in {effective_table_name or 'Main List'}")
        except Exception as e:
            logging.error(f"Failed to update record {record_id} in {table_name}: {e}")
            raise e

    def _booking_nr_search_variants(self, booking_nr):
        raw = str(booking_nr or "").strip()
        if not raw:
            return []
        variants = [raw]
        upper = raw.upper()
        if upper.startswith("BR-") and len(raw) > 3:
            stripped = raw[3:].strip()
            if stripped and stripped not in variants:
                variants.append(stripped)
        elif raw.isdigit():
            prefixed = f"BR-{raw}"
            if prefixed not in variants:
                variants.append(prefixed)
        return variants

    def find_booking_by_number(self, booking_nr):
        """Find a booking record by Booking Nr. using ID query"""
        booking_nr = str(booking_nr or "").strip()
        if not booking_nr or self._is_placeholder_booking_number(booking_nr):
            logging.info(f"Skipping placeholder/invalid booking lookup: {booking_nr}")
            return None
        last_error = None
        for variant in self._booking_nr_search_variants(booking_nr):
            try:
                rec = self._find_booking_by_number_exact(variant)
                if rec:
                    if variant != booking_nr:
                        logging.info(f"Found booking using variant '{variant}' for input '{booking_nr}'")
                    return rec
            except Exception as e:
                last_error = e
                logging.error(f"Error finding booking {variant}: {e}")
        if last_error:
            return None
        return None

    def _find_booking_by_number_exact(self, booking_nr):
        """Find a booking record by exact Booking Nr. value."""
        try:
            # Formula still uses Field Names usually! 
            # PyAirtable 'formula' parameter sends string to Airtable API.
            # Airtable API formulas use Field Names, NOT IDs.
            # So we MUST keep using Names in the formula string.
            
            formula = f"{{Booking Nr.}}='{booking_nr}'"
            logging.info(f"DEBUG: Searching Table with formula: {formula}")
            
            records = self.table.all(formula=formula)
            logging.info(f"DEBUG: Search result count: {len(records)}")
            
            if records:
                rec = records[0]
                rec['table_name'] = self.config['airtable']['tables']['main_list']
                return rec
            
            # Check Leads Table
            # SKIP: Leads Table usually does not have "Booking Nr." field. 
            # Searching it causes API errors and confusion.
            # if self.leads_table:
            #    try:
            #        # Leads table might not have "Booking Nr." field.
            #        # Only search if we are sure, or catch the error.
            #        logging.info(f"DEBUG: Searching Leads Table with formula: {formula}")
            #        lead_records = self.leads_table.all(formula=formula)
            #        if lead_records:
            #            rec = lead_records[0]
            #            rec['table_name'] = LEADS_TABLE_NAME
            #            return rec
            #    except Exception as e:
            #        # Ignore error if field doesn't exist in Leads
            #        logging.warning(f"Skipping Leads lookup for Booking Nr {booking_nr} (Field might be missing): {e}")
            
            return None
        except Exception as e:
            logging.error(f"Error finding booking {booking_nr}: {e}")
            return None

    def _is_placeholder_booking_number(self, value):
        booking_nr = str(value or "").strip().lower()
        if not booking_nr:
            return True
        placeholders = {
            "received",
            "receive",
            "done",
            "pending",
            "unknown",
            "none",
            "null",
            "n/a",
            "-",
            "try again",
            "try-again",
            "draft",
        }
        if booking_nr in placeholders:
            return True
        return booking_nr.startswith("lead-")



    def create_lead_record(self, email, name="Guest", initial_message="", phone=None, department="general"):
        """
        Create a new 'Lead' record for an unknown user.
        If 'Leads' table exists, create there. Otherwise, create in Main Table as 'Inquiry'.
        """
        try:
            timestamp = datetime.now().strftime("%Y%m%d%H%M")
            fake_booking_nr = f"LEAD-{timestamp}"
            
            # Clean phone if provided
            clean_phone = self.clean_phone_for_whatsapp(phone) if phone else None
            clean_email = str(email or "").strip() or None
            
            if department == "religious" and getattr(self, "religious_leads_table", None):
                inquiry_message = str(initial_message or "").strip()
                fields = {
                    ReligiousLeadFieldIds.CUSTOMER_NAME: name or "Guest",
                    ReligiousLeadFieldIds.GENDER_OR_TYPE: "جديد",
                    ReligiousLeadFieldIds.INQUIRY_DATE: datetime.now().isoformat(),
                    ReligiousLeadFieldIds.CREATED_BY: "AI Agent",
                }
                if clean_email:
                    fields[ReligiousLeadFieldIds.CUSTOMER_EMAIL] = clean_email
                if clean_phone:
                    fields[ReligiousLeadFieldIds.CUSTOMER_PHONE] = clean_phone
                if inquiry_message:
                    fields[ReligiousLeadFieldIds.INQUIRY_DETAILS] = inquiry_message
                    fields[ReligiousLeadFieldIds.AI_CHAT_LOG] = f"[SYSTEM]: New Religious Inquiry Created. Initial Message: {inquiry_message}"
                    fields[ReligiousLeadFieldIds.NOTES] = inquiry_message
                record = self._create_airtable_table_record(self.religious_leads_table, fields, typecast=True)
                record['table_name'] = self._religious_leads_table_name()
                logging.info(f"Created new Religious Lead record: {clean_email} / {clean_phone} / {name}")
                return record

            if self.leads_table:
                # Use Leads Table Fields
                fields = {
                    LeadFieldIds.CUSTOMER_NAME: name,
                    LeadFieldIds.LEAD_STATUS: "New (جديد)", 
                    LeadFieldIds.AI_CHAT_LOG: f"[SYSTEM]: New Lead Created. Initial Message: {initial_message}",
                    LeadFieldIds.LAST_INTERACTION: datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                }
                if clean_email:
                    fields[LeadFieldIds.CUSTOMER_EMAIL] = clean_email
                if clean_phone:
                    fields[LeadFieldIds.CUSTOMER_PHONE] = clean_phone
                    
                record = self._create_airtable_table_record(self.leads_table, fields, typecast=True)
                record['table_name'] = LEADS_TABLE_NAME
                logging.info(f"Created new Lead record in Leads Table: {clean_email}")
                return record
            else:
                # Fallback to Main Table
                fields = {
                    FieldIds.BOOKING_NR: fake_booking_nr,
                    FieldIds.CUSTOMER_NAME: name,
                    FieldIds.BOOKING_STATUS: "Inquiry", 
                    FieldIds.AI_CHAT_LOG: f"[SYSTEM]: New Lead Created. Initial Message: {initial_message}"
                }
                if clean_email:
                    fields[FieldIds.CUSTOMER_EMAIL] = clean_email
                if clean_phone:
                     fields[FieldIds.CUSTOMER_PHONE] = clean_phone
                     
                record = self._create_airtable_table_record(self.table, fields, typecast=True)
                record['table_name'] = self.config['airtable']['tables']['main_list']
                logging.info(f"Created new Lead record in Main Table: {fake_booking_nr}")
                return record

        except Exception as e:
            logging.error(f"Failed to create lead record for {email}: {e}")
            return None

    def send_email(self, to_email, subject, html_content, thread_id=None, in_reply_to_message_id=None, attachments=None, record_id=None, mailbox=None):
        """
        Send HTML email using Gmail OAuth Service
        Respects 'draft_mode' setting in config.
        """
        gmail_svc, selected_mailbox = self._select_gmail_service(mailbox=mailbox, direction="outbound")
        if not gmail_svc or not getattr(gmail_svc, "service", None):
            logging.error("Gmail Service not authenticated. Cannot send email.")
            return False
        
        # Check Draft Mode
        email_settings = self.config.get('email', {}).get('settings', {})
        draft_mode = email_settings.get('draft_mode', False)
        
        # In draft mode, we create a draft and log it for human review/learning
        # BUT: For automated system responses/agent replies generated via backend, we NEVER create a draft
        # to prevent duplicate/spam drafts on the frontend.
        if draft_mode and "System Log" not in html_content and "[System Log]" not in html_content and "Replying via System" not in str(html_content):
            logging.info(f"DRAFT MODE ON: Creating draft instead of sending to {to_email}")
            result = gmail_svc.create_draft(
                to_email, 
                subject, 
                html_content, 
                sender_name=self.config['company_info']['name'],
                thread_id=thread_id,
                in_reply_to_message_id=in_reply_to_message_id,
                attachments=attachments
            )
            
            if result and record_id:
                # Log draft for future audit/learning
                audit_utils.log_draft(result['id'], thread_id, record_id, html_content, mailbox=selected_mailbox)
                
            return result is not None
            
        return gmail_svc.send_email(
            to_email, 
            subject, 
            html_content, 
            sender_name=self.config['company_info']['name'],
            thread_id=thread_id,
            in_reply_to_message_id=in_reply_to_message_id,
            attachments=attachments
        )

    def learn_from_human_edits(self):
        """
        SELF-LEARNING: Scan drafts that were sent by humans (not by AI directly)
        to see if the human changed the AI's suggested draft.
        """
        logging.info("Checking for human-edited drafts to learn...")
        pending = audit_utils.get_pending_drafts()
        
        if not pending:
            return

        for draft in pending:
            draft_id = draft['draft_id']
            thread_id = draft['thread_id']
            record_id = draft['record_id']
            original_body = draft['original_body']
            mailbox = str(draft.get('mailbox') or 'booking').strip() or 'booking'
            gmail_svc, _selected_mailbox = self._select_gmail_service(
                mailbox=mailbox,
                direction="outbound",
                sales_fallback=str(mailbox).lower() == "sales"
            )
            
            # Check if draft still exists
            try:
                gmail_svc.service.users().drafts().get(userId='me', id=draft_id).execute()
                # Draft exists -> Still pending review
                continue
            except:
                # Draft gone -> Likely sent (or deleted)
                pass
            
            # Get thread history
            history = gmail_svc.get_thread_history(thread_id)
            if not history:
                audit_utils.mark_draft_processed(draft_id, 'missing_history')
                continue
                
            # Assume last message is the sent one
            last_message = history[-1]
            
            sent_body = last_message['body']
            
            # Compare
            # Simple clean HTML
            clean_orig = re.sub('<[^<]+?>', '', original_body).strip()
            clean_sent = re.sub('<[^<]+?>', '', sent_body).strip()
            
            similarity = difflib.SequenceMatcher(None, clean_orig, clean_sent).ratio()
            
            if similarity < 0.99: # If changed
                logging.info(f"Draft {draft_id} was edited (Sim: {similarity:.2f})")
                
                # Log to Airtable
                log_msg = f"[HUMAN_CORRECTION]: Draft edited before sending.\nSimilarity: {similarity*100:.1f}%\nFinal Sent: {clean_sent}..."
                self.append_to_chat_log(record_id, log_msg, sender="System", source="Audit")
                
                # Save for learning
                audit_utils.save_correction(clean_orig, clean_sent, trigger_context="Draft Edit")
            else:
                logging.info(f"Draft {draft_id} sent without changes.")
                
            audit_utils.mark_draft_processed(draft_id, 'checked')

    def log_proposed_reply_for_learning(self, record_id, proposed_text, table_name=None):
        """
        Log the AI's proposed reply to a special field or log for later comparison.
        This helps in self-learning by comparing what AI proposed vs what Human actually sent.
        """
        try:
            if "System Log" in str(proposed_text) or "[System Log]" in str(proposed_text) or "Replying via System" in str(getattr(self, '_current_chat_id', "")):
                return
            # We will append this to the AI Chat Log with a special tag [PROPOSED_DRAFT]
            self.append_to_chat_log(
                record_id, 
                f"[PROPOSED_DRAFT]\n{proposed_text}", 
                sender="System", 
                source="AI_Learning", 
                table_name=table_name
            )
        except Exception as e:
            logging.warning(f"Failed to log proposed reply for learning: {e}")

    def _get_record_from_any_table(self, record_id):
        """Fetch a record by ID from any of the known tables (Main, Religious, Leads)."""
        if not record_id:
            return None

        # Airtable may return the same record ID from the wrong table URL.
        # Fetch from the first endpoint that responds, then classify by fields.
        fetchers = [lambda: self.table.get(record_id)]
        if getattr(self, "leads_table", None):
            fetchers.append(lambda: self.leads_table.get(record_id))
        if getattr(self, "religious_leads_table", None):
            fetchers.append(lambda: self.religious_leads_table.get(record_id))

        rec = None
        for fetch in fetchers:
            try:
                candidate = fetch()
                if isinstance(candidate, dict) and candidate.get("id"):
                    rec = candidate
                    break
            except Exception:
                continue

        if not isinstance(rec, dict):
            return None

        classified = self._classify_airtable_record_table(rec)
        if classified:
            rec["table_name"] = classified
        elif not rec.get("table_name"):
            rec["table_name"] = self.config["airtable"]["tables"]["main_list"]
        return rec

    def _get_record_table_name(self, record_id):
        """Resolve which Airtable table owns this record ID."""
        if not record_id:
            return None

        rec = self._get_record_from_any_table(record_id)
        if isinstance(rec, dict) and rec.get("table_name"):
            return rec.get("table_name")

        return None

    def _derive_chat_location_from_fields(self, fields, fallback_location="Unknown", receiving_phone_id=None, is_leads_table=False):
        """Normalize dashboard chat routing with inbox pinning before Airtable fallbacks."""
        raw_fields = fields or {}

        phone_id_locations = (self.config.get('whatsapp', {}) or {}).get('phone_id_locations', {}) or {}
        if receiving_phone_id is not None:
            pinned_loc = str(phone_id_locations.get(str(receiving_phone_id)) or "").strip()
            if pinned_loc in {"Sharm", "Hurghada/Cairo", "Sales", "Quality", "Religious"}:
                return pinned_loc

        from chat_location import derive_chat_location_from_des

        destination = self.get_field_value(raw_fields, FieldIds.DES) or ""
        derived = derive_chat_location_from_des(destination, fallback_location)
        if destination and str(destination).strip():
            return derived
        if fallback_lower := str(fallback_location or "").strip().lower():
            if fallback_lower == "sales" and not is_leads_table:
                return "Hurghada/Cairo"
        return derived

    def append_to_chat_log(self, record_id, message, sender="AI", source="System", table_name=None, skip_local_sync=False):
        """
        Unified helper to append messages to Airtable Chat Log and Session Cache.
        Format: [YYYY-MM-DD HH:MM:SS] [Source - Sender]: Message
        THREAD-SAFE: Uses Keyed Mutex to allow parallel processing of DIFFERENT records.
        """
        if getattr(self, "_suppress_chat_log_sync", False):
            logging.info("append_to_chat_log suppressed for record %s (%s)", record_id, source)
            return
        with self.mutex.lock(record_id):
            try:
                timestamp = (datetime.now(timezone.utc).replace(tzinfo=None) + CAIRO_OFFSET).strftime("%Y-%m-%d %H:%M:%S")
                log_entry = f"\n[{timestamp}] [{source} - {sender}]: {message}"
                
                # 1. Update Airtable
                table = self.table
                effective_table_name = table_name
                is_religious_leads = bool(
                    self._is_religious_leads_table(effective_table_name) and getattr(self, "religious_leads_table", None)
                )
                if table_name == LEADS_TABLE_NAME and self.leads_table:
                    table = self.leads_table
                elif is_religious_leads:
                    table = self.religious_leads_table
                
                # Fetch current log
                rec = None
                try:
                    rec = table.get(record_id)
                except Exception:
                    if effective_table_name is None:
                        if hasattr(self, 'religious_leads_table') and self.religious_leads_table:
                            try:
                                rec = self.religious_leads_table.get(record_id)
                                table = self.religious_leads_table
                                effective_table_name = self._religious_leads_table_name()
                                is_religious_leads = True
                            except Exception:
                                pass
                        
                        if rec is None and hasattr(self, 'leads_table') and self.leads_table:
                            try:
                                rec = self.leads_table.get(record_id)
                                table = self.leads_table
                                effective_table_name = LEADS_TABLE_NAME
                            except Exception:
                                pass
                        
                        if rec is None:
                            raise Exception(f"Record {record_id} not found or accessible in any known table.")
                    else:
                        raise
                current_log = self.get_field_value(rec['fields'], FieldIds.AI_CHAT_LOG) or ""
                
                # Use Lead ID if Main ID missing
                if not current_log and effective_table_name == LEADS_TABLE_NAME:
                     current_log = self.get_field_value(rec['fields'], LeadFieldIds.AI_CHAT_LOG) or ""
                elif not current_log and is_religious_leads:
                     current_log = (
                         rec['fields'].get(ReligiousLeadFieldIds.AI_CHAT_LOG)
                         or rec['fields'].get("AI Chat log")
                         or rec['fields'].get(ReligiousLeadFieldIds.NOTES)
                         or ""
                     )

                new_log = current_log + "\n" + log_entry
                
                update_data = {FieldIds.AI_CHAT_LOG: new_log}
                # For Leads, map to Lead Field ID if needed
                if effective_table_name == LEADS_TABLE_NAME:
                     # FORCE using the Lead Field ID directly if we are in Leads Table
                     update_data = {LeadFieldIds.AI_CHAT_LOG: new_log}
                elif is_religious_leads:
                     religious_log_field = next(
                         (
                             field_name
                             for field_name in (
                                 ReligiousLeadFieldIds.AI_CHAT_LOG,
                                 "AI Chat log",
                                 ReligiousLeadFieldIds.NOTES,
                             )
                             if field_name in rec['fields']
                         ),
                         None
                     )
                     update_data = {religious_log_field: new_log} if religious_log_field else None
                
                if update_data:
                    update_ok = False
                    last_update_error = None
                    for attempt in range(1, 4):
                        try:
                            self._update_airtable_table_record(table, record_id, update_data, typecast=True)
                            update_ok = True
                            break
                        except Exception as update_err:
                            last_update_error = update_err
                            err_text = str(update_err or "").lower()
                            is_retriable = (
                                "retriable_error" in err_text
                                or "503" in err_text
                                or "service unavailable" in err_text
                            )
                            if attempt >= 3 or not is_retriable:
                                raise
                            time.sleep(0.8 * attempt)
                    if not update_ok and last_update_error:
                        raise last_update_error
                    logging.info(f"Appended to Chat Log for {record_id} ({source})")
                else:
                    logging.warning(f"Skipped Airtable chat log append for religious lead {record_id}: no supported log field found")
                
                if not skip_local_sync:
                    try:
                        import chat_db
                        chat_row = chat_db.get_chat_by_record_id(record_id)
                        
                        if not chat_row:
                            # Try to create a conversation if we have the record data
                            if effective_table_name == LEADS_TABLE_NAME:
                                contact_name = self.get_field_value(rec['fields'], LeadFieldIds.CUSTOMER_NAME) or "Guest"
                                customer_phone = self.get_field_value(rec['fields'], LeadFieldIds.CUSTOMER_PHONE)
                                customer_email = self.get_field_value(rec['fields'], LeadFieldIds.CUSTOMER_EMAIL)
                            elif is_religious_leads:
                                contact_name = rec['fields'].get(ReligiousLeadFieldIds.CUSTOMER_NAME) or "Guest"
                                customer_phone = rec['fields'].get(ReligiousLeadFieldIds.CUSTOMER_PHONE)
                                customer_email = rec['fields'].get(ReligiousLeadFieldIds.CUSTOMER_EMAIL)
                            else:
                                contact_name = self.get_field_value(rec['fields'], FieldIds.CUSTOMER_NAME) or "Guest"
                                customer_phone = self.get_field_value(rec['fields'], FieldIds.CUSTOMER_PHONE)
                                customer_email = self.get_field_value(rec['fields'], FieldIds.CUSTOMER_EMAIL)
                            
                            raw_phone = str(customer_phone or "").strip()
                            raw_email = str(customer_email or "").strip()
                            if raw_phone:
                                sender_identifier = raw_phone
                                source_type = "WhatsApp"
                            elif raw_email.isdigit():
                                sender_identifier = raw_email
                                source_type = "Facebook"
                            elif raw_email and "@" in raw_email:
                                sender_identifier = raw_email
                                source_type = "Email"
                            else:
                                # Skip if it is a phantom chat (no email, no phone, not already in DB)
                                if not chat_db.get_chat_by_record_id(record_id):
                                    return # Prevent crash, safely skip phantom
                                sender_identifier = f"Record-{record_id}"
                                source_type = "Email"
                            if is_religious_leads:
                                derived_location = "Religious"
                            else:
                                derived_location = self._derive_chat_location_from_fields(
                                    rec.get('fields', {}),
                                    fallback_location="Unknown",
                                    is_leads_table=(effective_table_name == LEADS_TABLE_NAME),
                                )
                            
                            chat_row = chat_db.get_or_create_conversation(
                                source=source_type,
                                sender_identifier=sender_identifier,
                                contact_name=contact_name,
                                airtable_record_id=record_id,
                                location=derived_location
                            )

                        if chat_row:
                            # Only sync if it's NOT a direct user message from WhatsApp/Email
                            # because those are already synced locally beforehand to ensure quick UI response.
                            if source not in ["WhatsApp", "Email"] or sender != "User":
                                # Prevent HUMAN_CORRECTION from showing up as an agent chat bubble in UI
                                if "[HUMAN_CORRECTION]" not in message:
                                    # Map sender to sender_type
                                    if sender == "User":
                                        s_type = "customer"
                                    elif sender.startswith("AI"):
                                        s_type = "ai"
                                    else:
                                        s_type = "agent" # Or system
                                    
                                    # Fix: Don't duplicate customer messages from Airtable if they already exist
                                    if s_type == "customer" and source == "Airtable":
                                        with chat_db.sqlite3.connect(chat_db.DB_FILE, timeout=15.0) as conn:
                                            c = conn.cursor()
                                            c.execute("SELECT 1 FROM messages WHERE chat_id=? AND sender_type='customer' AND text LIKE ? LIMIT 1", (chat_row['chat_id'], f"%{message.strip()}%"))
                                            if c.fetchone():
                                                pass # Already exists
                                            else:
                                                chat_db.add_message(chat_row['chat_id'], s_type, message, status='received')
                                    else:
                                        chat_db.add_message(chat_row['chat_id'], s_type, message, status='sent')
                    except Exception as db_err:
                        logging.error(f"Failed to sync chat_log to local dashboard db: {db_err}")
                # -----------------------------------------
                
                return True
            except Exception as e:
                logging.error(f"Failed to append to chat log: {e}")
                return False

    def process_new_bookings(self):
        """
        Check Airtable for new bookings based on specific views
        """
        logging.info("Checking for new bookings...")
        try:
            # Fetch records from the 'Ahmady' view (or Main View)
            # Use NAMES directly to avoid issues with ID support in this environment
            records = self.table.all(view=self.config['airtable']['views']['ahmady_view'], max_records=10)
            
            for record in records:
                self.handle_booking(record)
                
        except Exception as e:
            logging.error(f"Error checking bookings: {e}")

    def handle_booking(self, record):
        """
        Process a single booking record (Using IDs)
        """
        record_id = record['id']
        fields = record['fields']
        
        logging.info(f"Processing booking: {record_id}")
        
        # 1. Handle Pickup Details (Priority 1)
        # We assume the config 'update_status' maps to 'pickup time' -> FieldIds.PICKUP_TIME
        pickup_time = self.get_field_value(fields, FieldIds.PICKUP_TIME)
        
        if pickup_time and pickup_time != 'Done':
            self.process_pickup_details(record_id, fields, pickup_time)

        # 2. Handle Customer Inquiries (Priority 2)
        customer_message = self.get_field_value(fields, FieldIds.CUSTOMER_LAST_MESSAGE) 
        ai_chat_log = self.get_field_value(fields, FieldIds.AI_CHAT_LOG) or ''
        
        if customer_message and customer_message not in ai_chat_log:
             self.handle_customer_inquiry(record_id, fields, customer_message)


    def _download_file_content(self, url):
        """Download file content from URL."""
        try:
            response = requests.get(url)
            response.raise_for_status()
            return response.content
        except Exception as e:
            logging.error(f"Failed to download file from {url}: {e}")
            return None

    def _get_valid_attachments(self, fields, pdf_only=False):
        """
        Download and filter attachments from Airtable fields.
        Checks both 'Attachments' and 'Tickets Files' fields.
        Returns a list of dicts suitable for send_email.
        If pdf_only=True, keeps PDF files only and skips everything else.
        If pdf_only=False, filters out images (png, jpg) and keeps documents.
        """
        processed_attachments = []
        
        # Helper to process a list of attachments
        def process_list(att_list):
            if not att_list:
                return
            
            # Safety Fix for AttributeError
            if isinstance(att_list, str):
                att_list = [{'url': att_list, 'filename': 'document'}]
            elif isinstance(att_list, dict):
                att_list = [att_list]
            elif not isinstance(att_list, list):
                return

            for att in att_list:
                if not isinstance(att, dict): continue
                
                filename_original = att.get('filename', 'document')
                filename = str(filename_original).lower()
                url = att.get('url')
                mime_type = att.get('type', 'application/octet-stream')
                
                url_no_qs = str(url).split('?', 1)[0].lower() if url else ""
                is_pdf = (
                    filename.endswith('.pdf') or
                    str(mime_type).lower().startswith('application/pdf') or
                    url_no_qs.endswith('.pdf')
                )
                
                if pdf_only:
                    if not is_pdf:
                        continue
                else:
                    if filename.endswith(('.png', '.jpg', '.jpeg')):
                        continue
                
                content = self._download_file_content(url)
                if content:
                    processed_attachments.append({
                        'filename': filename_original,
                        'content': content,
                        'mime_type': 'application/pdf' if is_pdf else mime_type,
                        'url': url
                    })

        # 1. Check 'Attachments' field
        process_list(self.get_field_value(fields, FieldIds.ATTACHMENTS))
        
        # 2. Check 'Tickets Files' field (Common for ticket-only trips)
        process_list(self.get_field_value(fields, FieldIds.TICKETS))
        
        return processed_attachments

