    def send_whatsapp_reaction(self, recipient_phone, reacted_message_id, emoji, location="Unknown", receiving_phone_id=None):
        try:
            import json
            phone_number_id = self._resolve_phone_number_id(location, receiving_phone_id)
            if not phone_number_id:
                return False, {"status_code": 500, "body": "PHONE_NUMBER_ID_NOT_RESOLVED"}

            access_token = self._get_whatsapp_access_token()
            if not access_token:
                return False, {"status_code": 500, "body": "MISSING_WHATSAPP_TOKEN"}

            url = f"https://graph.facebook.com/v18.0/{phone_number_id}/messages"
            headers = {
                "Authorization": f"Bearer {access_token}",
                "Content-Type": "application/json"
            }

            payload = {
                "messaging_product": "whatsapp",
                "recipient_type": "individual",
                "to": recipient_phone,
                "type": "reaction",
                "reaction": {
                    "message_id": str(reacted_message_id),
                    "emoji": str(emoji)
                }
            }

            import requests
            response = requests.post(url, headers=headers, json=payload, timeout=10)
            if response.status_code in [200, 201]:
                try:
                    return True, response.json()
                except Exception:
                    return True, {"status_code": response.status_code, "body": response.text}
            parsed = None
            try:
                parsed = response.json()
            except Exception:
                parsed = None
            return False, {
                "status_code": response.status_code,
                "body": response.text,
                "json": parsed,
                "phone_number_id": phone_number_id,
            }
        except Exception as e:
            return False, {"status_code": 500, "body": str(e)}

    def send_facebook_message(self, recipient_psid, text=None, media_url=None, media_type=None, media_bytes=None, media_mime=None, media_filename=None):
        """Send a Facebook Messenger message using the connected page access token."""
        try:
            facebook_cfg = (self.config.get('facebook') or {}) if isinstance(self.config, dict) else {}
            if not isinstance(facebook_cfg, dict):
                facebook_cfg = {}

            page_id = str(facebook_cfg.get('page_id') or '').strip()
            access_token = str(facebook_cfg.get('page_access_token') or '').strip()
            if not page_id or not access_token:
                return False, {
                    "status_code": 500,
                    "body": "MISSING_FACEBOOK_CONFIG",
                    "json": {
                        "error": {
                            "message": "Missing Facebook page configuration",
                            "type": "LocalConfigurationError",
                            "code": "MISSING_FACEBOOK_CONFIG"
                        }
                    }
                }

            recipient_id = str(recipient_psid or '').strip()
            if not recipient_id:
                return False, {"status_code": 400, "body": "MISSING_FACEBOOK_RECIPIENT"}

            payload = {
                "recipient": {"id": recipient_id},
                "messaging_type": "RESPONSE",
            }

            has_media = bool(media_url or media_bytes)
            if has_media:
                mt = str(media_type or '').strip().lower()
                if mt == "image":
                    attachment_type = "image"
                elif mt == "audio":
                    attachment_type = "audio"
                elif mt == "video":
                    attachment_type = "video"
                else:
                    attachment_type = "file"
                source_url = str(media_url or "").strip()
                name = str(media_filename or "").strip() or self._filename_from_media_url(source_url, attachment_type)
                mime = self._mime_for_outbound_media(attachment_type, media_mime, name, source_url)
                data = media_bytes
                if not data and source_url:
                    data, got_mime, used = self._download_media_bytes(source_url)
                    if got_mime:
                        mime = self._mime_for_outbound_media(attachment_type, got_mime, name, used or source_url)
                    if used:
                        source_url = used
                attachment_id = None
                if data:
                    attachment_id = self._upload_facebook_attachment_bytes(
                        access_token, attachment_type, data, mime, name
                    )
                if attachment_id:
                    logging.info(f"Using Facebook attachment_id={attachment_id} instead of Cloudinary weblink")
                    payload["message"] = {
                        "attachment": {
                            "type": attachment_type,
                            "payload": {"attachment_id": attachment_id},
                        }
                    }
                else:
                    link = source_url or str(media_url or "").strip()
                    cands = self._cloudinary_url_candidates(link)
                    if len(cands) > 1:
                        link = cands[-1]
                    payload["message"] = {
                        "attachment": {
                            "type": attachment_type,
                            "payload": {
                                "url": link,
                                "is_reusable": True,
                            }
                        }
                    }
            else:
                clean_text = str(text or '').strip()
                if not clean_text:
                    return False, {"status_code": 400, "body": "EMPTY_FACEBOOK_MESSAGE"}
                payload["message"] = {"text": clean_text}

            url = f"https://graph.facebook.com/{META_GRAPH_VERSION}/me/messages"
            headers = {
                "Content-Type": "application/json"
            }
            timeout_s = 60 if has_media else 15
            last_error = None
            parsed = None
            response = None
            for attempt in range(1, 4):
                try:
                    response = requests.post(
                        url,
                        headers=headers,
                        params={"access_token": access_token},
                        json=payload,
                        timeout=timeout_s,
                    )
                    last_error = None
                    break
                except (requests.exceptions.Timeout, requests.exceptions.ConnectionError) as e:
                    last_error = e
                    logging.warning(
                        f"Facebook send attempt {attempt}/3 timed out for {recipient_id}: {e}"
                    )
                    if attempt < 3:
                        time.sleep(1.5 * attempt)
            if last_error is not None:
                logging.error(f"Exception sending Facebook message: {last_error}")
                return False, {"status_code": 500, "body": str(last_error)}

            try:
                parsed = response.json()
            except Exception:
                parsed = None

            if response.status_code in [200, 201]:
                logging.info(f"Successfully sent Facebook message to {recipient_id}")
                return True, parsed or {"status_code": response.status_code, "body": response.text}

            err = (parsed or {}).get("error") if isinstance(parsed, dict) else {}
            err_code = str((err or {}).get("code") or "").strip()
            # 551 = recipient blocked/deleted/unavailable; 10 = 24h messaging window closed.
            log_fn = logging.warning if err_code in {"551", "10"} else logging.error
            log_fn(f"Failed to send Facebook message. Meta API Error: {response.text}")
            return False, {
                "status_code": response.status_code,
                "body": response.text,
                "json": parsed,
                "page_id": page_id,
            }
        except Exception as e:
            logging.error(f"Exception sending Facebook message: {e}")
            return False, {"status_code": 500, "body": str(e)}

    def _is_placeholder_facebook_name(self, name):
        value = str(name or "").strip()
        if not value:
            return True
        lowered = value.lower()
        return lowered == "facebook user" or lowered.startswith("facebook user ")

    def _compose_facebook_profile_name(self, profile_data):
        if not isinstance(profile_data, dict):
            return ""
        full_name = str(profile_data.get("name") or "").strip()
        if full_name:
            return full_name
        first_name = str(profile_data.get("first_name") or "").strip()
        last_name = str(profile_data.get("last_name") or "").strip()
        combined = " ".join(part for part in [first_name, last_name] if part).strip()
        return combined

    def _normalize_customer_name(self, name):
        cleaned_name = str(name or "").strip()
        if not cleaned_name:
            return "Guest"
        cleaned_name = re.sub(r"\s+", " ", cleaned_name).strip()
        lowered_name = cleaned_name.lower()
        invalid_name_keywords = [
            "viator", "expedia", "getyourguide", "gyg", "tripadvisor", "booking.com",
            "tours", "travels", "travel", "agency", "limited", "ltd", "inc", "corp",
            "service", "support", "team", "reservation", "guest", "customer", "client",
            "unknown", "not provided", "n/a", "sir", "madam", "get started"
        ]
        for keyword in invalid_name_keywords:
            if keyword in lowered_name:
                return "Guest"
        return cleaned_name

    def _sanitize_table_name_list(self, value, max_items=200):
        if not isinstance(value, list):
            return None
        out = []
        seen = set()
        for item in value:
            name = str(item or "").strip()
            if not name or len(name) > 160:
                continue
            key = name.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(name)
            if len(out) >= max_items:
                break
        return out or None

    def _sanitize_religious_operation_acl(self, value):
        if not isinstance(value, dict):
            return None
        out = {}
        allowed = self._sanitize_table_name_list(value.get("allowedTables"))
        denied = self._sanitize_table_name_list(value.get("deniedTables"))
        if allowed:
            out["allowedTables"] = allowed
        if denied:
            out["deniedTables"] = denied
        return out or None

    def _user_can_access_airtable_table(self, user_obj, table_name, scope="main"):
        """Admin = all tables. Else apply allowedTables / deniedTables ACL."""
        if not isinstance(user_obj, dict):
            return False
        role = str(user_obj.get("role") or "").strip().lower()
        if role == "admin":
            return True
        name = str(table_name or "").strip()
        if not name:
            return False
        scope_l = str(scope or "main").strip().lower()
        if scope_l in ("religious", "religion", "rel", "hajj"):
            acl = user_obj.get("religiousOperationAcl") if isinstance(user_obj.get("religiousOperationAcl"), dict) else {}
        else:
            acl = user_obj.get("aiOperationAcl") if isinstance(user_obj.get("aiOperationAcl"), dict) else {}
        denied = acl.get("deniedTables") if isinstance(acl.get("deniedTables"), list) else []
        for item in denied:
            if str(item or "").strip().lower() == name.lower():
                return False
        allowed = acl.get("allowedTables") if isinstance(acl.get("allowedTables"), list) else []
        if allowed:
            return any(str(item or "").strip().lower() == name.lower() for item in allowed)
        return True

    def _sanitize_ai_operation_acl(self, value):
        if not isinstance(value, dict):
            return None
        out = {}
        if "canCreateRecord" in value:
            out["canCreateRecord"] = bool(value.get("canCreateRecord"))
        if "canExport" in value:
            out["canExport"] = bool(value.get("canExport"))
        if "canDismissForcedRecordFilters" in value:
            out["canDismissForcedRecordFilters"] = bool(value.get("canDismissForcedRecordFilters"))
        if "recordFiltersVersion" in value:
            ver = value.get("recordFiltersVersion")
            if isinstance(ver, (int, float)) and not isinstance(ver, bool):
                out["recordFiltersVersion"] = int(ver) if float(ver).is_integer() else ver
            elif isinstance(ver, str) and ver.strip():
                out["recordFiltersVersion"] = ver.strip()[:64]
        raw_fields = value.get("fields")
        fields = {}
        if isinstance(raw_fields, dict):
            for key, caps in raw_fields.items():
                field_name = str(key or "").strip()
                if not field_name or len(field_name) > 120:
                    continue
                if not isinstance(caps, dict):
                    continue
                view = bool(caps["view"]) if "view" in caps else True
                edit = bool(caps["edit"]) if "edit" in caps else True
                create = bool(caps["create"]) if "create" in caps else True
                if not view:
                    edit = False
                    create = False
                if view and edit and create:
                    continue
                entry = {}
                if not view:
                    entry["view"] = False
                if not edit:
                    entry["edit"] = False
                if not create:
                    entry["create"] = False
                fields[field_name] = entry
                if len(fields) >= 400:
                    break
        if fields:
            out["fields"] = fields
        raw_filters = value.get("recordFilters")
        cleaned_filters = self._sanitize_ai_operation_record_filters(raw_filters)
        if cleaned_filters:
            out["recordFilters"] = cleaned_filters
        else:
            # Legacy simple scope only when Filter builder conditions are absent.
            raw_scope = value.get("recordScope")
            if isinstance(raw_scope, dict):
                scope = {}
                def _clean_date(v):
                    s = str(v or "").strip()
                    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
                        return None
                    try:
                        datetime.fromisoformat(s)
                        return s
                    except Exception:
                        return None

                def _clean_list(v, max_items=80, max_len=160):
                    if not isinstance(v, list):
                        return None
                    seen = set()
                    out_list = []
                    for item in v:
                        s = str(item or "").strip()
                        if not s or len(s) > max_len:
                            continue
                        key = s.lower()
                        if key in seen:
                            continue
                        seen.add(key)
                        out_list.append(s)
                        if len(out_list) >= max_items:
                            break
                    return out_list or None

                d_from = _clean_date(raw_scope.get("dateTripFrom"))
                d_to = _clean_date(raw_scope.get("dateTripTo"))
                if d_from:
                    scope["dateTripFrom"] = d_from
                if d_to:
                    scope["dateTripTo"] = d_to
                for key in ("tripNames", "agencies", "destinations", "bookingStatuses"):
                    cleaned = _clean_list(raw_scope.get(key))
                    if cleaned:
                        scope[key] = cleaned
                if scope:
                    out["recordScope"] = scope
        allowed_tables = self._sanitize_table_name_list(value.get("allowedTables"))
        if allowed_tables:
            out["allowedTables"] = allowed_tables
        denied_tables = self._sanitize_table_name_list(value.get("deniedTables"))
        if denied_tables:
            out["deniedTables"] = denied_tables
        fixed_ids = {
            "All Booking",
            "Operation Today",
            "Operation Tomorrow",
            "Operation Weekly",
        }
        denied_fixed = self._sanitize_table_name_list(value.get("deniedFixedViews"), max_items=20)
        if denied_fixed:
            cleaned_fixed = [x for x in denied_fixed if x in fixed_ids]
            if cleaned_fixed:
                out["deniedFixedViews"] = cleaned_fixed
        if out.get("canCreateRecord") is True:
            out.pop("canCreateRecord", None)
        if out.get("canExport") is True:
            out.pop("canExport", None)
        if out.get("canDismissForcedRecordFilters") is False:
            out.pop("canDismissForcedRecordFilters", None)
        if not out.get("recordFilters") and not out.get("recordScope"):
            out.pop("recordFiltersVersion", None)
        if not out:
            return None
        return out

    def _sanitize_ai_operation_record_filters(self, value, depth=0):
        """Sanitize Filter-builder conditions (same shape as AI Operation tab)."""
        if not isinstance(value, list) or depth > 2:
            return None
        allowed_ops = {
            "contains", "does not contain", "is", "is not", "is empty", "is not empty",
            "is before", "is after", "is today", "is tomorrow", "is yesterday",
            "greater than", "less than", "greater or equal", "less or equal",
        }
        out = []
        for item in value:
            if not isinstance(item, dict):
                continue
            node_id = str(item.get("id") or "").strip() or f"f_{len(out)+1}"
            connector = "or" if str(item.get("connector") or "").strip().lower() == "or" else "and"
            is_group = bool(item.get("isGroup")) or isinstance(item.get("conditions"), list)
            if is_group:
                children_raw = item.get("conditions") if isinstance(item.get("conditions"), list) else []
                children = self._sanitize_ai_operation_record_filters(children_raw, depth + 1) or []
                if not children:
                    continue
                out.append({
                    "id": node_id[:80],
                    "connector": connector,
                    "isGroup": True,
                    "groupLogic": "and" if str(item.get("groupLogic") or "").strip().lower() == "and" else "or",
                    "conditions": children[:20],
                })
            else:
                field = str(item.get("field") or "").strip()
                operator = str(item.get("operator") or "").strip()
                if not field or len(field) > 120 or operator not in allowed_ops:
                    continue
                val = str(item.get("value") or "").strip()
                if len(val) > 500:
                    val = val[:500]
                out.append({
                    "id": node_id[:80],
                    "connector": connector,
                    "field": field,
                    "operator": operator,
                    "value": val,
                })
            if len(out) >= 40:
                break
        return out or None

    def _ai_operation_record_scope_to_filters(self, scope):
        """Convert admin recordScope into AND filter nodes for mirror query."""
        if not isinstance(scope, dict) or not scope:
            return []
        filters = []
        uid = 0

        def _nid():
            nonlocal uid
            uid += 1
            return f"scope_{uid}"

        def _shift_iso(iso_day, days):
            try:
                d = datetime.fromisoformat(str(iso_day)).date()
                return (d + timedelta(days=int(days))).isoformat()
            except Exception:
                return None

        d_from = str(scope.get("dateTripFrom") or "").strip()
        d_to = str(scope.get("dateTripTo") or "").strip()
        if d_from:
            before = _shift_iso(d_from, -1)
            if before:
                filters.append({
                    "id": _nid(),
                    "field": "Date Trip",
                    "operator": "is after",
                    "value": before,
                    "connector": "and",
                })
        if d_to:
            after = _shift_iso(d_to, 1)
            if after:
                filters.append({
                    "id": _nid(),
                    "field": "Date Trip",
                    "operator": "is before",
                    "value": after,
                    "connector": "and",
                })

        trip_names = [str(x).strip() for x in (scope.get("tripNames") or []) if str(x).strip()]
        if trip_names:
            trip_groups = []
            for name in trip_names:
                trip_groups.append({
                    "id": _nid(),
                    "isGroup": True,
                    "groupLogic": "or",
                    "connector": "or",
                    "conditions": [
                        {"id": _nid(), "field": "trip Name", "operator": "contains", "value": name, "connector": "or"},
                        {"id": _nid(), "field": "Real Product Name", "operator": "contains", "value": name, "connector": "or"},
                    ],
                })
            filters.append({
                "id": _nid(),
                "isGroup": True,
                "groupLogic": "or",
                "connector": "and",
                "conditions": trip_groups,
            })

        def _or_field(field_name, values):
            vals = [str(x).strip() for x in (values or []) if str(x).strip()]
            if not vals:
                return None
            if len(vals) == 1:
                return {
                    "id": _nid(),
                    "field": field_name,
                    "operator": "is",
                    "value": vals[0],
                    "connector": "and",
                }
            return {
                "id": _nid(),
                "isGroup": True,
                "groupLogic": "or",
                "connector": "and",
                "conditions": [
                    {"id": _nid(), "field": field_name, "operator": "is", "value": v, "connector": "or"}
                    for v in vals
                ],
            }

        for field_name, key in (
            ("Agency", "agencies"),
            ("des", "destinations"),
            ("Booking Status", "bookingStatuses"),
        ):
            node = _or_field(field_name, scope.get(key))
            if node:
                filters.append(node)
        return filters

    def _merge_ai_operation_record_scope_filters(
        self,
        filters,
        actor_username=None,
        actor=None,
        skip_forced_record_filters=False,
        dismissed_forced_filters_version=None,
    ):
        actor_obj = actor if isinstance(actor, dict) else {}
        if actor_username and not actor_obj.get("username"):
            actor_obj = {**actor_obj, "username": str(actor_username).strip()}
        user_obj = self._load_dashboard_user_by_actor(actor_obj)
        if self._ai_operation_actor_is_admin(user_obj, actor=actor_obj):
            return filters if isinstance(filters, list) else []
        acl = (user_obj or {}).get("aiOperationAcl") if isinstance(user_obj, dict) else None
        base = filters if isinstance(filters, list) else []
        # User may dismiss forced scope only when ACL grants it.
        if skip_forced_record_filters and isinstance(acl, dict) and bool(acl.get("canDismissForcedRecordFilters")):
            current_version = acl.get("recordFiltersVersion")
            if current_version is None:
                # Legacy ACL without version: honor dismiss when client sends any skip.
                return base
            client_ver = str(dismissed_forced_filters_version or "").strip()
            server_ver = str(current_version).strip()
            if client_ver and server_ver and client_ver == server_ver:
                return base
            # Version mismatch → admin re-applied filters; keep merging.
        scope_filters = []
        if isinstance(acl, dict):
            cleaned = self._sanitize_ai_operation_record_filters(acl.get("recordFilters"))
            if cleaned:
                scope_filters = cleaned
            else:
                scope_filters = self._ai_operation_record_scope_to_filters(acl.get("recordScope"))
        if not scope_filters:
            return base
        merged = list(base)
        for node in scope_filters:
            item = dict(node)
            item["connector"] = "and"
            merged.append(item)
        return merged

    def _load_dashboard_user_by_actor(self, actor=None):
        try:
            import chat_db
            username = ""
            role_hint = ""
            if isinstance(actor, dict):
                username = str(
                    actor.get("username")
                    or actor.get("user_id")
                    or actor.get("id")
                    or ""
                ).strip()
                role_hint = str(actor.get("role") or "").strip()
            if not username:
                return None
            raw = chat_db.get_setting("dashboard_users")
            parsed = json.loads(raw) if isinstance(raw, str) and raw.strip() else raw
            if not isinstance(parsed, list):
                return None
            uname_l = username.lower()
            for item in parsed:
                if not isinstance(item, dict):
                    continue
                item_username = str(item.get("username") or item.get("id") or "").strip()
                if item_username.lower() == uname_l:
                    if role_hint and not item.get("role"):
                        item = dict(item)
                        item["role"] = role_hint
                    return item
            return {
                "username": username,
                "role": role_hint or "Agent",
                "aiOperationAcl": None,
            }
        except Exception:
            return None

    def _ai_operation_actor_is_admin(self, user_obj, actor=None):
        role = ""
        username = ""
        if isinstance(user_obj, dict):
            role = str(user_obj.get("role") or "").strip().lower()
            username = str(user_obj.get("username") or "").strip().lower()
        if isinstance(actor, dict):
            if not role:
                role = str(actor.get("role") or "").strip().lower()
            if not username:
                username = str(
                    actor.get("username") or actor.get("user_id") or actor.get("id") or ""
                ).strip().lower()
        return role == "admin"

    def _ai_operation_field_allowed(self, user_obj, field_name, action="edit", actor=None):
        """Allow-by-default field ACL. action: view|edit|create"""
        if self._ai_operation_actor_is_admin(user_obj, actor=actor):
            return True
        name = str(field_name or "").strip()
        if not name:
            return True
        acl = None
        if isinstance(user_obj, dict):
            acl = user_obj.get("aiOperationAcl")
        if not isinstance(acl, dict):
            return True
        fields = acl.get("fields")
        if not isinstance(fields, dict):
            return True
        caps = fields.get(name)
        if not isinstance(caps, dict):
            # Case-insensitive / trim fallback for UI field labels vs ACL keys.
            name_l = name.lower()
            for k, v in fields.items():
                if str(k or "").strip().lower() == name_l and isinstance(v, dict):
                    caps = v
                    break
        if not isinstance(caps, dict):
            return True
        view = caps.get("view", True) is not False
        if not view:
            return False
        if action == "view":
            return True
        if action == "edit":
            return caps.get("edit", True) is not False
        if action == "create":
            return caps.get("create", True) is not False
        return True

    def _ai_operation_can_create_record(self, user_obj, actor=None):
        if self._ai_operation_actor_is_admin(user_obj, actor=actor):
            return True
        acl = None
        if isinstance(user_obj, dict):
            acl = user_obj.get("aiOperationAcl")
        if not isinstance(acl, dict):
            return True
        if "canCreateRecord" not in acl:
            return True
        return bool(acl.get("canCreateRecord"))

    def _filter_ai_operation_fields_by_acl(self, fields, user_obj, action="edit", actor=None):
        """Returns (allowed_fields, denied_field_names)."""
        if not isinstance(fields, dict):
            return {}, []
        if self._ai_operation_actor_is_admin(user_obj, actor=actor):
            return dict(fields), []
        allowed = {}
        denied = []
        for key, value in fields.items():
            name = str(key or "").strip()
            if not name:
                continue
            if self._ai_operation_field_allowed(user_obj, name, action=action, actor=actor):
                allowed[name] = value
            else:
                denied.append(name)
        return allowed, denied

    def _get_dashboard_user_name_candidates(self):
        cached = getattr(self, "_dashboard_user_name_candidates_cache", None)
        if isinstance(cached, set):
            return cached

        candidates = set()
        try:
            import chat_db
            raw = chat_db.get_setting("dashboard_users")
            parsed = json.loads(raw) if isinstance(raw, str) and raw.strip() else raw
            items = []
            if isinstance(parsed, list):
                items = parsed
            elif isinstance(parsed, dict):
                items = list(parsed.values())
            for item in items:
                if not isinstance(item, dict):
                    continue
                for value in (item.get("name"), item.get("username"), item.get("id")):
                    text = str(value or "").strip()
                    if not text:
                        continue
                    normalized = re.sub(r"[_\-]+", " ", text)
                    normalized = re.sub(r"\s+", " ", normalized).strip().lower()
                    if not normalized:
                        continue
                    candidates.add(normalized)
                    first_token = normalized.split()[0].strip()
                    if first_token:
                        candidates.add(first_token)
        except Exception:
            candidates = set()

        self._dashboard_user_name_candidates_cache = candidates
        return candidates

    def _is_safe_facebook_fallback_customer_name(self, name):
        candidate = self._normalize_customer_name(name)
        if candidate == "Guest":
            return False

        lowered = candidate.lower()
        compact = re.sub(r"\s+", " ", lowered).strip()
        words = [w for w in re.split(r"\s+", candidate) if w]
        if not words:
            return False

        invalid_exact_values = {
            "get started",
            "السلام عليكم",
            "وعليكم السلام",
            "بكم",
            "اه تمام",
            "أه تمام",
            "تمام",
            "تحسين",
            "بري",
            "اقتصادي",
            "الاقتصادي",
            "طيران",
            "الحج",
            "عمرة",
            "العمرة",
            "البرنامج",
            "تفاصيل",
            "السعر",
            "الاسعار",
            "الأسعار",
        }
        if compact in invalid_exact_values:
            return False

        invalid_prefixes = (
            "مع حضرتك",
            "معك",
            "انا ",
            "أنا ",
            "اسمي ",
            "إسمي ",
        )
        if any(compact.startswith(prefix) for prefix in invalid_prefixes):
            return False

        # Fallback names for Facebook are too risky when they are just one token
        # because they often come from intent words like "تحسين" or agent signatures.
        if len(words) == 1:
            return False

        dashboard_user_names = self._get_dashboard_user_name_candidates()
        if compact in dashboard_user_names:
            return False

        return True

    def _get_verified_explicit_booking_number(self, text, matched_record=None, existing_booking_nr=None):
        candidates = self.extract_booking_numbers_regex(text or "")
        existing_booking_clean = str(existing_booking_nr or "").strip().lower()
        for cand, confidence in candidates:
            candidate_clean = str(cand or "").strip()
            if not candidate_clean or confidence != "STRONG":
                continue
            if self._is_placeholder_booking_number(candidate_clean):
                continue
            if existing_booking_clean and candidate_clean.lower() == existing_booking_clean:
                continue
            if matched_record and str(matched_record.get('id') or '').strip():
                return candidate_clean
        return None

    def _extract_facebook_referral_info(self, event=None, message=None, postback=None, hop_context=None):
        event = event or {}
        message = message or {}
        postback = postback or {}
        hop_context = hop_context or {}

        referral_sources = [
            ("message", message.get("referral")),
            ("postback", postback.get("referral")),
            ("event", event.get("referral")),
        ]
        for referral_origin, referral_payload in referral_sources:
            if not isinstance(referral_payload, dict) or not referral_payload:
                continue
            ads_context_data = referral_payload.get("ads_context_data") or {}
            if not isinstance(ads_context_data, dict):
                ads_context_data = {}
            info = {
                "origin": referral_origin,
                "ref": str(referral_payload.get("ref") or "").strip(),
                "source": str(referral_payload.get("source") or "").strip(),
                "type": str(referral_payload.get("type") or "").strip(),
                "ad_id": str(referral_payload.get("ad_id") or "").strip(),
                "referer_uri": str(referral_payload.get("referer_uri") or "").strip(),
                "ad_title": str(ads_context_data.get("ad_title") or "").strip(),
                "post_id": str(ads_context_data.get("post_id") or "").strip(),
                "media_url": str(ads_context_data.get("video_url") or ads_context_data.get("photo_url") or "").strip(),
            }
            if isinstance(hop_context, dict):
                info["hop_app_id"] = str(hop_context.get("app_id") or "").strip()
                info["hop_metadata"] = str(hop_context.get("metadata") or "").strip()
            if any(info.get(key) for key in ("ref", "source", "type", "ad_id", "referer_uri", "hop_metadata", "ad_title", "post_id", "media_url")):
                return info

        if isinstance(hop_context, dict):
            hop_metadata = str(hop_context.get("metadata") or "").strip()
            if hop_metadata:
                return {
                    "origin": "hop_context",
                    "ref": "",
                    "source": "",
                    "type": "",
                    "ad_id": "",
                    "referer_uri": "",
                    "hop_app_id": str(hop_context.get("app_id") or "").strip(),
                    "hop_metadata": hop_metadata,
                }
        return None

    def _format_facebook_referral_notice(self, referral_info):
        if not isinstance(referral_info, dict) or not referral_info:
            return ""
        label = "[Facebook Referral]"
        if str(referral_info.get("source") or "").strip().upper() == "ADS":
            label = "[Facebook Ad Referral]"
        parts = [label]
        for key in ("source", "type", "ad_id", "ad_title", "post_id", "ref", "referer_uri", "hop_metadata"):
            value = str(referral_info.get(key) or "").strip()
            if value:
                parts.append(f"{key}={value}")
        return " ".join(parts).strip()

    def _facebook_graph_version(self):
        fb_cfg = (self.config.get('facebook') or {}) if isinstance(self.config, dict) else {}
        version = str(fb_cfg.get('graph_version') or META_GRAPH_VERSION or 'v21.0').strip()
        return version or 'v21.0'

    def _lookup_facebook_profile_via_user_api(self, customer_psid, page_token):
        graph_version = self._facebook_graph_version()
        psid = str(customer_psid or '').strip()
        url = f"https://graph.facebook.com/{graph_version}/{psid}"
        resp = requests.get(
            url,
            params={"fields": "first_name,last_name,name", "access_token": page_token},
            timeout=6,
        )
        try:
            data = resp.json() if resp.content else {}
        except Exception:
            data = {}
        if not isinstance(data, dict):
            data = {}
        name = self._compose_facebook_profile_name(data)
        if resp.status_code == 200 and name:
            return name
        err = data.get("error") if isinstance(data.get("error"), dict) else {}
        err_code = err.get("code")
        err_sub = err.get("error_subcode")
        err_msg = str(err.get("message") or resp.text or "").strip()
        logging.warning(
            "Facebook User Profile API did not return a name for %s: status=%s code=%s subcode=%s body=%s",
            psid,
            resp.status_code,
            err_code,
            err_sub,
            (err_msg or "{}")[:500],
        )
        return ""

    def _lookup_facebook_profile_via_conversations(self, customer_psid, page_token, page_id):
        graph_version = self._facebook_graph_version()
        psid = str(customer_psid or '').strip()
        page_id = str(page_id or '').strip()
        if not psid or not page_id or not page_token:
            return ""
        url = f"https://graph.facebook.com/{graph_version}/{page_id}/conversations"
        resp = requests.get(
            url,
            params={
                "platform": "messenger",
                "user_id": psid,
                "fields": "participants",
                "limit": 1,
                "access_token": page_token,
            },
            timeout=6,
        )
        try:
            data = resp.json() if resp.content else {}
        except Exception:
            data = {}
        if resp.status_code != 200 or not isinstance(data, dict):
            logging.warning(
                "Facebook conversations name lookup failed for %s: status=%s body=%s",
                psid,
                resp.status_code,
                str(resp.text or "")[:500],
            )
            return ""
        rows = data.get("data") if isinstance(data.get("data"), list) else []
        for row in rows:
            participants = ((row or {}).get("participants") or {}).get("data") or []
            if not isinstance(participants, list):
                continue
            for person in participants:
                if not isinstance(person, dict):
                    continue
                person_id = str(person.get("id") or "").strip()
                if person_id != psid:
                    continue
                person_name = str(person.get("name") or "").strip()
                if person_name and not self._is_placeholder_facebook_name(person_name):
                    return person_name
        return ""

    def _resolve_facebook_sender_name(self, customer_psid, fallback_name=None, allow_lookup=True):
        sender_name = str(fallback_name or "").strip()
        if sender_name and not self._is_placeholder_facebook_name(sender_name):
            return sender_name
        try:
            fb_cfg = (self.config.get('facebook') or {}) if isinstance(self.config, dict) else {}
            fb_page_token = str(fb_cfg.get('page_access_token') or '').strip()
            fb_page_id = str(fb_cfg.get('page_id') or '').strip()
            if allow_lookup and fb_page_token and customer_psid:
                fb_name = self._lookup_facebook_profile_via_user_api(customer_psid, fb_page_token)
                if fb_name:
                    return fb_name
                conv_name = self._lookup_facebook_profile_via_conversations(
                    customer_psid, fb_page_token, fb_page_id
                )
                if conv_name:
                    return conv_name
        except Exception as e:
            logging.warning(f"Facebook profile lookup exception for {customer_psid}: {e}")

        if sender_name:
            return sender_name
        customer_psid = str(customer_psid or "").strip()
        return f"Facebook User {customer_psid[-6:]}" if len(customer_psid) > 6 else "Facebook User"

    def process_facebook_message_async(self, sender_psid, message_body, sender_name, page_psid, location, chat_conv):
        try:
            import chat_db
            facebook_auto_reply_enabled = bool(self.config.get("facebook_auto_reply_enabled", True))
            if not facebook_auto_reply_enabled:
                logging.info("Facebook auto-reply disabled by configuration.")
                return
            
            auto_locations = set(self.config.get("auto_reply_locations", ["Hurghada/Cairo", "Sharm"]))
            draft_locations = set(self.config.get("auto_reply_draft_locations", []))
            is_auto_location = location in auto_locations
            is_draft_location = location in draft_locations

            if not is_auto_location and not is_draft_location:
                return

            if chat_conv:
                # For Facebook: Pause auto-reply if human is helping, but DO NOT pause if we are in draft mode
                needs_help_paused = bool(is_auto_location and chat_conv and int(chat_conv.get("needs_help") or 0) == 1)
                if needs_help_paused:
                    logging.info(f"Facebook auto-reply paused (needs_help=1) for chat {chat_conv.get('chat_id')}")
                    return
                # Never draft/reply to Facebook Ad Referral metadata alone.
                try:
                    if hasattr(chat_db, "is_facebook_referral_metadata_text") and chat_db.is_facebook_referral_metadata_text(message_body):
                        logging.info(
                            "Skipping Facebook AI/draft for chat %s — message is Ad Referral metadata only.",
                            chat_conv.get("chat_id"),
                        )
                        return
                except Exception:
                    pass
                # If a workflow already replied to this customer turn, never generate a late draft.
                try:
                    fb_chat_id = chat_conv.get("chat_id")
                    if fb_chat_id and self._should_skip_ai_draft_for_chat(fb_chat_id):
                        logging.info(
                            "Skipping Facebook AI/draft for chat %s because system/workflow already replied.",
                            fb_chat_id,
                        )
                        self._reconcile_stale_proposed_draft(fb_chat_id)
                        # Only mark read when a live reply truly covers this customer turn.
                        # Never mark read just because a stale in-memory workflow flag existed.
                        try:
                            self._mark_read_only_if_turn_covered(fb_chat_id)
                        except Exception:
                            pass
                        return
                except Exception:
                    pass
                    
            history_list = chat_db.get_messages(chat_conv['chat_id']) if chat_conv else []
            history_text = "\n".join([
                f"{'User' if m['sender_type'] == 'customer' else 'AI'}: {m['text']}" 
                for m in history_list[-10:]
            ])

            result = self.process_unified_message(
                sender_identifier=sender_psid,
                message_body=message_body,
                history_text=history_text,
                source="Facebook",
                subject=f"Facebook Message ({location})",
                location=location,
                receiving_phone_id=page_psid,
                skip_db_save=True
            )
            
            if result:
                reply_text = str(result.get("response_text") or "").strip()
                if not reply_text:
                    return
                    
                assistant_name, assistant_signature = self._assistant_identity_for_text(message_body)
                reply_text = self._ensure_signature_once(reply_text, assistant_signature, chat_id=chat_conv.get("chat_id") if chat_conv else None, location=location)
                
                if is_draft_location:
                    if chat_conv and chat_conv.get("chat_id") and (
                        chat_db.check_if_system_replied_recently(chat_conv["chat_id"])
                        or self._should_skip_ai_draft_for_chat(chat_conv["chat_id"])
                    ):
                        logging.info("Skipping draft generation for Facebook because system/workflow already replied.")
                        try:
                            self._reconcile_stale_proposed_draft(chat_conv["chat_id"])
                        except Exception:
                            pass
                        try:
                            self._mark_read_only_if_turn_covered(chat_conv["chat_id"])
                        except Exception:
                            pass
                        return
                    reply_text = "[PROPOSED_DRAFT] " + reply_text
                    ok = True
                    err = None
                else:
                    ok, err = self.send_facebook_message(sender_psid, text=reply_text)
                    if not ok:
                        logging.error(f"Failed Facebook auto-reply send. Error: {err}")
                        try:
                            if chat_conv and chat_conv.get("chat_id"):
                                chat_db.update_conversation_info(chat_conv["chat_id"], needs_help=True)
                        except Exception:
                            pass
                        return
                    
                if ok and chat_conv:
                    if is_draft_location:
                        # Final race guard: workflow live reply may have landed while AI was generating.
                        if self._should_skip_ai_draft_for_chat(chat_conv["chat_id"]):
                            logging.info(
                                "Aborting Facebook PROPOSED_DRAFT insert for chat %s — workflow already replied.",
                                chat_conv["chat_id"],
                            )
                            try:
                                self._reconcile_stale_proposed_draft(chat_conv["chat_id"])
                            except Exception:
                                pass
                            try:
                                self._mark_read_only_if_turn_covered(chat_conv["chat_id"])
                            except Exception:
                                pass
                            return
                        chat_db.delete_proposed_drafts(chat_conv["chat_id"])
                    inserted_id = chat_db.add_message(
                        chat_id=chat_conv["chat_id"],
                        sender_type="agent",
                        text=reply_text,
                        status="sent",
                        increment_unread=False,
                        source="Facebook"
                    )
                    if is_draft_location:
                        # TOCTOU: workflow may have recorded its live reply between the
                        # pre-check and this insert — remove the stale draft immediately.
                        self._reconcile_stale_proposed_draft(chat_conv["chat_id"])
                        # PROPOSED_DRAFT is for human review — must stay UNREAD.
                        # Never call mark_conversation_read here (that caused force_read_at
                        # right after the draft and hid customer messages from the inbox).
                        if inserted_id:
                            try:
                                if hasattr(chat_db, "ensure_unread_for_pending_draft"):
                                    chat_db.ensure_unread_for_pending_draft(chat_conv["chat_id"])
                            except Exception:
                                pass
                        else:
                            logging.info(
                                "Facebook PROPOSED_DRAFT was not inserted for chat %s (live reply guard).",
                                chat_conv["chat_id"],
                            )
                    if not is_draft_location:
                        chat_db.mark_conversation_read(chat_conv["chat_id"])
                        
        except Exception as e:
            logging.error(f"Error in process_facebook_message_async: {e}")

    def check_and_send_sales_report_reminders(self):
        """
        Runs on day 8 of every month to check if sales employees have submitted their reports
        for the previous month. If not, sends a WhatsApp alert to the manager.
        """
        try:
            from datetime import datetime, timedelta
            import pytz
            import json
            import os
            
            cairo_tz = pytz.timezone('Africa/Cairo')
            now = datetime.now(cairo_tz)
            
            # Check if today is the 8th day of the month
            if now.day != 8:
                return
                
            # To avoid sending multiple times on the same day, check a local state file
            state_file = os.path.join(os.path.dirname(__file__), 'sales_reminder_state.json')
            last_sent_month = None
            if os.path.exists(state_file):
                try:
                    with open(state_file, 'r') as f:
                        state = json.load(f)
                        last_sent_month = state.get('last_sent_month')
                except:
                    pass
            
            current_month_str = now.strftime('%Y-%m')
            if last_sent_month == current_month_str:
                return # Already sent for this month
                
            # We are checking reports for the PREVIOUS month
            first_day_this_month = now.replace(day=1)
            last_month_date = first_day_this_month - timedelta(days=1)
            target_month = last_month_date.strftime('%Y-%m')
            
            logging.info(f"Checking sales reports for {target_month} on {now.date()}")
            
            sales_users = [
                {"name": "Bassant Khalled", "airtableUsername": "bassant"},
                {"name": "Nadeen Hossam", "airtableUsername": "nadeen"},
                {"name": "Ahmed Saad", "airtableUsername": "ahmedsaad"}
            ]
            
            try:
                reviews_table = self.airtable_api.table(self.config['airtable']['base_id'], "Sales_Performance_Reviews")
                all_reviews = reviews_table.all(formula=f"{{Month}} = '{target_month}'")
            except Exception as e:
                logging.error(f"Could not fetch Sales_Performance_Reviews for reminder: {e}")
                return
                
            review_status_map = {}
            for r in all_reviews:
                fields = r.get('fields', {})
                email_or_user = fields.get('Employee Email', '')
                status = fields.get('Report Status', 'Draft')
                review_status_map[email_or_user] = status
                
            missing_or_draft = []
            for user in sales_users:
                username = user['airtableUsername']
                status = review_status_map.get(username)
                
                if not status:
                    missing_or_draft.append(f"- {user['name']} (لم يتم التقديم)")
                elif status == 'Draft':
                    missing_or_draft.append(f"- {user['name']} (مسودة - Draft)")
                    
            if missing_or_draft:
                alert_message = (
                    f"🔴 *تنبيه نظام إدارة المبيعات (FTS Manager)*\n\n"
                    f"تم إغلاق نافذة تقديم التقارير الشهرية (لشهر {target_month}).\n"
                    f"الموظفون التاليون لم يقوموا باعتماد تقاريرهم النهائية:\n"
                    f"{chr(10).join(missing_or_draft)}\n\n"
                    f"يرجى التوجيه أو إعادة فتح النافذة لهم من النظام."
                )
                
                manager_phone = "+201068177086"
                
                try:
                    import re
                    clean_phone = re.sub(r'\D', '', manager_phone)
                    self.send_whatsapp_message(clean_phone, text=alert_message, location="Religious")
                    logging.info(f"Sales report reminder sent successfully to {manager_phone}")
                    
                    with open(state_file, 'w') as f:
                        json.dump({'last_sent_month': current_month_str}, f)
                        
                except Exception as e:
                    logging.error(f"Failed to send Sales report reminder via WhatsApp: {e}")

        except Exception as e:
            logging.error(f"Error in check_and_send_sales_report_reminders: {e}", exc_info=True)

    def _background_scheduler_loop(self):
        import time
        while True:
            try:
                self.check_and_send_sales_report_reminders()
            except Exception as e:
                logging.error(f"Error in background scheduler loop: {e}")
            time.sleep(3600)

    def start_background_scheduler(self):
        import threading
        t = threading.Thread(target=self._background_scheduler_loop, daemon=True)
        t.start()
        logging.info("Background scheduler thread started.")

    def _internal_cairo_now(self):
        try:
            tz = getattr(self, "cairo_tz", None)
            if tz:
                return datetime.now(tz)
        except Exception:
            pass
        try:
            return datetime.utcnow() + timedelta(hours=2)
        except Exception:
            return datetime.now()

    def _parse_iso_datetime(self, value):
        raw = str(value or "").strip()
        if not raw:
            return None
        try:
            if raw.endswith("Z"):
                raw = raw[:-1] + "+00:00"
            return datetime.fromisoformat(raw)
        except Exception:
            return None

    def _load_json_setting_value(self, key, fallback=None):
        import chat_db
        try:
            raw = chat_db.get_setting(str(key or "").strip())
            if isinstance(raw, str) and raw.strip():
                try:
                    parsed = json.loads(raw)
                except Exception:
                    parsed = None
            else:
                parsed = raw
            return parsed if parsed is not None else fallback
        except Exception:
            return fallback

    def _save_json_setting_value(self, key, value):
        import chat_db
        try:
            chat_db.set_setting(str(key or "").strip(), json.dumps(value, ensure_ascii=False))
            return True
        except Exception:
            return False

    def _internal_workspace_actor_key(self, actor):
        if isinstance(actor, dict):
            pass
        elif isinstance(actor, str):
            actor = {"username": actor}
        else:
            actor = {}
        username = str(actor.get("username") or "").strip().lower()
        phone = re.sub(r"\D", "", str(actor.get("phone") or ""))
        if username:
            return f"u:{username}"
        if phone:
            return f"p:{phone}"
        return ""

    def _sanitize_allowed_base_ids(self, value, max_items=40):
        if not isinstance(value, list):
            return None
        out = []
        seen = set()
        for item in value:
            base_id = str(item or "").strip().replace(" ", "")
            if not base_id or len(base_id) < 3 or len(base_id) > 64:
                continue
            key = base_id.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(base_id)
            if len(out) >= max_items:
                break
        return out or None

    def _configured_airtable_bases(self):
        airtable_cfg = (self.config.get("airtable", {}) or {})
        bases = []
        for label, name_en, name_ar, key in (
            ("main", "Main / External", "الرئيسي / الخارجي", "base_id"),
            ("religious", "Religious", "الديني", "religious_base_id"),
            ("trips", "Trips / Website", "الرحلات / الموقع", "trips_base_id"),
        ):
            base_id = str(airtable_cfg.get(key) or "").strip()
            if not base_id:
                continue
            bases.append({
                "label": label,
                "nameEn": name_en,
                "nameAr": name_ar,
                "baseId": base_id,
            })
        return bases

    def _user_allowed_base_ids(self, user_obj):
        """Return explicit list, or None for unrestricted (admin). Empty list = none."""
        if not isinstance(user_obj, dict):
            return []
        role = str(user_obj.get("role") or "").strip().lower()
        if role == "admin":
            return None
        configured = self._configured_airtable_bases()
        known_ids = {
            str(b.get("baseId") or "").strip().lower()
            for b in configured
            if str(b.get("baseId") or "").strip()
        }

        def _inherit_from_locations():
            locs = [str(x or "").strip().lower() for x in (user_obj.get("allowedLocations") or []) if str(x or "").strip()]
            by_label = {str(b.get("label") or "").lower(): str(b.get("baseId") or "").strip() for b in configured}
            if (not locs) or ("all" in locs):
                return [b["baseId"] for b in configured if b.get("baseId")]
            out = []
            def _push(label):
                bid = by_label.get(label)
                if bid and bid.lower() not in {x.lower() for x in out}:
                    out.append(bid)
            if "religious" in locs:
                _push("religious")
            if any(l not in ("religious", "needhelp") for l in locs):
                _push("main")
                _push("trips")
            return out

        explicit = self._sanitize_allowed_base_ids(user_obj.get("allowedBaseIds"))
        if explicit:
            has_known = any(str(x or "").strip().lower() in known_ids for x in explicit)
            # Custom-only allowlist: keep extras + inherit known bases from Locations
            # so adding a typed app… does not strip Main and hide FTS AI Operation.
            if (not has_known) and known_ids:
                merged = list(_inherit_from_locations())
                seen = {x.lower() for x in merged}
                for bid in explicit:
                    key = str(bid or "").strip().lower()
                    if key and key not in seen:
                        merged.append(bid)
                        seen.add(key)
                return merged
            return explicit
        return _inherit_from_locations()

    def _user_can_access_base_id(self, user_obj, base_id):
        allowed = self._user_allowed_base_ids(user_obj)
        if allowed is None:
            return True
        bid = str(base_id or "").strip()
        if not bid:
            return False
        return any(str(x or "").strip().lower() == bid.lower() for x in allowed)

    def _user_can_access_base_scope(self, user_obj, scope="main"):
        scope_l = str(scope or "main").strip().lower()
        if scope_l in ("religious", "religion", "rel", "hajj"):
            label = "religious"
        elif scope_l in ("trips", "trip", "website"):
            label = "trips"
        else:
            label = "main"
        configured = self._configured_airtable_bases()
        match = next((b for b in configured if str(b.get("label") or "").lower() == label), None)
        if match and self._user_can_access_base_id(user_obj, match.get("baseId")):
            return True
        # Custom Base IDs unlock main/operations scope (same intent as checking Main).
        if label == "main" and isinstance(user_obj, dict):
            explicit = self._sanitize_allowed_base_ids(user_obj.get("allowedBaseIds")) or []
            known_ids = {
                str(b.get("baseId") or "").strip().lower()
                for b in configured
                if str(b.get("baseId") or "").strip()
            }
            if any(str(x or "").strip().lower() not in known_ids for x in explicit):
                return True
        if not match:
            return True
        return False

    def _actor_allowed_base_labels(self, actor):
        actor = actor or {}
        # Prefer dashboard user record when username present
        try:
            user_obj = self._load_dashboard_user_by_actor(actor) if isinstance(actor, dict) else None
        except Exception:
            user_obj = None
        if isinstance(user_obj, dict):
            allowed_ids = self._user_allowed_base_ids(user_obj)
            if allowed_ids is None:
                return ["general", "religious"]
            configured = self._configured_airtable_bases()
            labels = []
            for b in configured:
                bid = str(b.get("baseId") or "").strip()
                label = str(b.get("label") or "").strip().lower()
                if not bid or not any(str(x).strip().lower() == bid.lower() for x in allowed_ids):
                    continue
                if label == "religious":
                    labels.append("religious")
                elif label in ("main", "trips"):
                    if "general" not in labels:
                        labels.append("general")
            return labels or []

        allowed_locations = [str(x).strip() for x in (actor.get("allowed_locations") or actor.get("allowedLocations") or []) if str(x).strip()]
        lowered = [item.lower() for item in allowed_locations]
        if "all" in lowered:
            return ["general", "religious"]
        labels = []
        if any(item == "religious" for item in lowered):
            labels.append("religious")
        if any(item != "religious" for item in lowered):
            labels.append("general")
        return labels

    def _pi_brain_root(self):
        root = os.path.join(SCRIPT_DIR, "runtime", "pi_brain", "users")
        os.makedirs(root, exist_ok=True)
        return root

    def _pi_brain_actor_slug(self, actor):
        actor_key = self._internal_workspace_actor_key(actor)
        if not actor_key:
            return ""
        return re.sub(r"[^a-z0-9._-]+", "_", actor_key.lower()).strip("._-")

    def _pi_brain_paths(self, actor, case_id=None):
        if isinstance(actor, dict):
            pass
        elif isinstance(actor, str):
            actor = {"username": actor}
        else:
            actor = {}
        actor_slug = self._pi_brain_actor_slug(actor)
        if not actor_slug:
            return {}
        user_dir = os.path.join(self._pi_brain_root(), actor_slug)
        memory_dir = os.path.join(user_dir, "memory")
        active_dir = os.path.join(user_dir, "active")
        cases_dir = os.path.join(user_dir, "cases")
        bridge_dir = os.path.join(user_dir, "bridge")
        inbox_dir = os.path.join(bridge_dir, "inbox")
        outbox_dir = os.path.join(bridge_dir, "outbox")
        management_dir = os.path.join(user_dir, "management")
        watchers_dir = os.path.join(management_dir, "watchers")
        scheduled_tasks_dir = os.path.join(management_dir, "scheduled_tasks")
        projects_dir = os.path.join(management_dir, "projects")
        case_dir = os.path.join(cases_dir, str(case_id or "").strip()) if str(case_id or "").strip() else ""
        paths = {
            "user_dir": user_dir,
            "memory_dir": memory_dir,
            "active_dir": active_dir,
            "cases_dir": cases_dir,
            "bridge_dir": bridge_dir,
            "inbox_dir": inbox_dir,
            "outbox_dir": outbox_dir,
            "management_dir": management_dir,
            "watchers_dir": watchers_dir,
            "scheduled_tasks_dir": scheduled_tasks_dir,
            "projects_dir": projects_dir,
            "workspace_file": os.path.join(user_dir, "workspace.json"),
            "profile_file": os.path.join(user_dir, "profile.json"),
            "permissions_file": os.path.join(user_dir, "permissions_cache.json"),
            "roadmap_file": os.path.join(user_dir, "roadmap.json"),
            "current_context_file": os.path.join(active_dir, "current_context.json"),
        }
        if case_dir:
            paths["case_dir"] = case_dir
            paths["case_status_file"] = os.path.join(case_dir, "status.json")
        return paths

    def _pi_brain_safe_json(self, value, max_depth=4):
        if max_depth <= 0:
            return str(value)[:4000]
        if value is None:
            return None
        if isinstance(value, (bool, int, float)):
            return value
        if isinstance(value, str):
            return value[:4000]
        if isinstance(value, dict):
            normalized = {}
            for key, nested_value in value.items():
                normalized[str(key)[:120]] = self._pi_brain_safe_json(nested_value, max_depth=max_depth - 1)
            return normalized
        if isinstance(value, list):
            return [self._pi_brain_safe_json(item, max_depth=max_depth - 1) for item in value[:100]]
        return str(value)[:4000]

    def _pi_brain_write_json(self, file_path, payload):
        if not file_path:
            return False
        try:
            os.makedirs(os.path.dirname(file_path), exist_ok=True)
            safe_payload = self._pi_brain_safe_json(payload)
            with open(file_path, "w", encoding="utf-8") as fh:
                json.dump(safe_payload, fh, ensure_ascii=False, indent=2)
            return True
        except Exception as e:
            logging.warning(f"Failed to write PI brain json {file_path}: {e}")
            return False

    def _pi_brain_read_json(self, file_path, fallback=None):
        if not file_path or not os.path.exists(file_path):
            return {} if fallback is None else fallback
        try:
            with open(file_path, "r", encoding="utf-8") as fh:
                payload = json.load(fh)
            if isinstance(payload, dict):
                return payload
            return {} if fallback is None else fallback
        except Exception:
            return {} if fallback is None else fallback

    def _pi_brain_append_jsonl(self, file_path, record):
        if not file_path:
            return False
        try:
            os.makedirs(os.path.dirname(file_path), exist_ok=True)
            safe_record = self._pi_brain_safe_json(record)
            with open(file_path, "a", encoding="utf-8") as fh:
                fh.write(json.dumps(safe_record, ensure_ascii=False) + "\n")
            return True
        except Exception as e:
            logging.warning(f"Failed to append PI brain jsonl {file_path}: {e}")
            return False

    def _pi_brain_conversation_file(self, actor, conversation_id="internal_assistant"):
        conversation_id = str(conversation_id or "").strip() or "internal_assistant"
        actor_paths = self._pi_brain_paths(actor)
        user_dir = actor_paths.get("user_dir") if isinstance(actor_paths, dict) else ""
        if not user_dir:
            return ""
        safe_id = re.sub(r"[^a-z0-9._-]+", "_", conversation_id.lower()).strip("._-") or "internal_assistant"
        return os.path.join(user_dir, "conversations", f"{safe_id}.jsonl")

    def _pi_brain_read_recent_conversation_turns(self, actor, conversation_id="internal_assistant", limit=20):
        file_path = self._pi_brain_conversation_file(actor, conversation_id=conversation_id)
        if not file_path or not os.path.exists(file_path):
            return []
        try:
            with open(file_path, "r", encoding="utf-8") as fh:
                lines = fh.read().splitlines()
            turns = []
            for raw_line in lines[-max(int(limit or 0), 1):]:
                raw_line = str(raw_line or "").strip()
                if not raw_line:
                    continue
                try:
                    payload = json.loads(raw_line)
                except Exception:
                    continue
                if isinstance(payload, dict):
                    turns.append(payload)
            return turns
        except Exception:
            return []

    def _pi_brain_user_activity_file(self, actor, kind):
        kind = re.sub(r"[^a-z0-9._-]+", "_", str(kind or "").strip().lower()).strip("._-")
        if not kind:
            return ""
        actor_paths = self._pi_brain_paths(actor)
        user_dir = actor_paths.get("user_dir") if isinstance(actor_paths, dict) else ""
        if not user_dir:
            return ""
        return os.path.join(user_dir, "activity", f"{kind}.jsonl")

    def _pi_brain_ensure_jsonl(self, file_path):
        if not file_path:
            return False
        try:
            os.makedirs(os.path.dirname(file_path), exist_ok=True)
            if not os.path.exists(file_path):
                with open(file_path, "w", encoding="utf-8") as fh:
                    fh.write("")
            return True
        except Exception:
            return False

    def _pi_brain_behavior_summary_file(self, actor):
        actor_paths = self._pi_brain_paths(actor)
        user_dir = actor_paths.get("user_dir") if isinstance(actor_paths, dict) else ""
        if not user_dir:
            return ""
        return os.path.join(user_dir, "behavior_summary.json")

    def _pi_brain_dynamic_schedule_file(self, actor):
        actor_paths = self._pi_brain_paths(actor)
        management_dir = actor_paths.get("management_dir") if isinstance(actor_paths, dict) else ""
        if not management_dir:
            return ""
        return os.path.join(management_dir, "daily_command_schedule.json")

    def _pi_brain_dynamic_schedule_task_file(self, actor, schedule_id):
        schedule_id = re.sub(r"[^a-z0-9._-]+", "_", str(schedule_id or "").strip().lower()).strip("._-")
        if not schedule_id:
            return ""
        actor_paths = self._pi_brain_paths(actor)
        tasks_dir = actor_paths.get("scheduled_tasks_dir") if isinstance(actor_paths, dict) else ""
        if not tasks_dir:
            return ""
        return os.path.join(tasks_dir, f"dynamic_schedule_{schedule_id}.json")

    def _normalize_internal_behavior_signature(self, request_text, intent_name=None, pending_action=None):
        action_key = str(
            ((pending_action or {}) if isinstance(pending_action, dict) else {}).get("type")
            or intent_name
            or "general_qa"
        ).strip().lower() or "general_qa"
        text = " ".join(str(request_text or "").strip().lower().split())
        if not text:
            return f"{action_key}:empty"
        text = re.sub(r"\b20\d{2}-\d{2}-\d{2}\b", "{date}", text)
        text = re.sub(r"\b[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}\b", "{email}", text, flags=re.IGNORECASE)
        text = re.sub(r"(?<!\w)\+?\d[\d\s().\-]{7,}\d", "{phone}", text)
        text = re.sub(r"\b[a-z]{2,8}[0-9._-]{3,}[a-z0-9._-]*\b", "{booking}", text, flags=re.IGNORECASE)
        text = re.sub(r"\b\d{5,}\b", "{number}", text)
        text = re.sub(r"\s+", " ", text).strip()
        words = text.split()
        if len(words) > 14:
            text = " ".join(words[:14])
        return f"{action_key}:{text}"

    def _internal_behavior_label(self, intent_name=None, pending_action=None):
        action_key = str(
            ((pending_action or {}) if isinstance(pending_action, dict) else {}).get("type")
            or intent_name
            or "general_qa"
        ).strip()
        labels = {
            "general_qa": "Guided Assistance",
            "booking_summary": "Booking Summary",
            "draft_reply": "Draft Reply",
            "next_step": "Next Step",
            "update_airtable": "Airtable Update",
            "send_customer_message": "Customer Send",
            "create_invoice": "Invoice Creation",
            "booking_field_watch": "Booking Field Watch",
            "trip_booking_alert": "Trip Booking Alert",
            "dynamic_report": "Dynamic Report",
            "problems_diagnostics": "Diagnostics",
            "airtable_live_query": "Live Query",
            "agentic_orchestrator": "PI Orchestration",
        }
        return labels.get(action_key, action_key or "Guided Assistance")

    def _sync_internal_dynamic_schedule_tasks(self, actor, schedule_payload):
        actor = actor or {}
        schedule_payload = schedule_payload if isinstance(schedule_payload, dict) else {}
        items = schedule_payload.get("items") if isinstance(schedule_payload.get("items"), list) else []
        for item in items:
            if not isinstance(item, dict):
                continue
            schedule_id = str(item.get("schedule_id") or "").strip()
            task_file = self._pi_brain_dynamic_schedule_task_file(actor, schedule_id)
            if not task_file:
                continue
            status = str(item.get("status") or "suggested").strip().lower()
            if status != "active":
                try:
                    if os.path.exists(task_file):
                        os.remove(task_file)
                except Exception:
                    pass
                continue
            preferred_time = str(item.get("preferred_time") or "09:00").strip()
            m = re.fullmatch(r"(\d{1,2}):(\d{2})", preferred_time)
            if not m:
                preferred_time = "09:00"
                m = re.fullmatch(r"(\d{1,2}):(\d{2})", preferred_time)
            hour = max(0, min(23, int(m.group(1)) if m else 9))
            minute = max(0, min(59, int(m.group(2)) if m else 0))
            try:
                if ZoneInfo is not None:
                    now_local = datetime.now(ZoneInfo("Africa/Cairo"))
                else:
                    now_local = datetime.utcnow() + timedelta(hours=2)
            except Exception:
                now_local = datetime.utcnow() + timedelta(hours=2)
            if getattr(now_local, "tzinfo", None) is None:
                target_dt = datetime(now_local.year, now_local.month, now_local.day, hour, minute)
            else:
                target_dt = now_local.replace(hour=hour, minute=minute, second=0, microsecond=0)
            if target_dt <= now_local:
                target_dt = target_dt + timedelta(days=1)
            execute_timestamp = float(target_dt.timestamp())
            existing = self._pi_brain_read_json(task_file, {})
            if isinstance(existing, dict):
                existing_time = str(existing.get("time_of_day") or "").strip()
                existing_ts = existing.get("execute_timestamp")
                try:
                    existing_ts = float(existing_ts)
                except Exception:
                    existing_ts = 0.0
                if existing_time == preferred_time and existing_ts and existing_ts > time.time():
                    execute_timestamp = existing_ts
            pre_alert_minutes = item.get("pre_alert_minutes")
            try:
                pre_alert_minutes = max(1, int(pre_alert_minutes))
            except Exception:
                pre_alert_minutes = 10
            action_message = (
                f"حان الآن موعد الأمر المجدول: {str(item.get('title') or item.get('label') or schedule_id).strip()}\n"
                f"- التوقيت: {preferred_time}\n"
                f"- الأمر الأصلي: {str(item.get('sample_request') or '').strip()}\n\n"
                f"إذا أردت تشغيله الآن أرسل: نفذ الجدول {schedule_id}\n"
                f"ولإيقافه أرسل: تعطيل الجدول {schedule_id}"
            ).strip()
            pre_alert_message = (
                f"تنبيه مسبق: سيتاح بعد {pre_alert_minutes} دقيقة تنفيذ الأمر المجدول التالي:\n"
                f"- {str(item.get('title') or item.get('label') or schedule_id).strip()}\n"
                f"- التوقيت: {preferred_time}\n"
                f"- الأمر: {str(item.get('sample_request') or '').strip()}\n\n"
                f"لتعديل الوقت أرسل: عدل الجدول {schedule_id} 14:30"
            ).strip()
            task_payload = dict(existing or {})
            task_payload.update({
                "schema_version": "1.0",
                "task_type": "dynamic_daily_schedule",
                "task_id": str(task_payload.get("task_id") or f"dynamic_schedule_{schedule_id}").strip(),
                "schedule_id": schedule_id,
                "schedule_label": str(item.get("title") or item.get("label") or "").strip(),
                "time_of_day": preferred_time,
                "repeat": "daily",
                "status": "active",
                "execute_timestamp": execute_timestamp,
                "notify_phone": re.sub(r"\D", "", str(actor.get("phone") or "")),
                "pre_alert_seconds": int(pre_alert_minutes) * 60,
                "pre_alert_message": pre_alert_message,
                "action_to_execute": {
                    "type": "send_internal_notification",
                    "phone": re.sub(r"\D", "", str(actor.get("phone") or "")),
                    "payload": {
                        "message": action_message,
                    },
                },
                "updated_at": datetime.now(timezone.utc).isoformat(),
            })
            if "pre_alert_sent" not in task_payload:
                task_payload["pre_alert_sent"] = False
            self._pi_brain_write_json(task_file, task_payload)
        return True

    def _register_internal_behavior_signal(self, actor, request_text, intent_name=None, case_context=None, pending_action=None):
        actor = actor or {}
        case_context = case_context if isinstance(case_context, dict) else {}
        pending_action = pending_action if isinstance(pending_action, dict) else {}
        request_text = str(request_text or "").strip()
        if not request_text:
            return {}
        paths = self._ensure_pi_brain_workspace(actor)
        if not paths:
            return {}
        try:
            if ZoneInfo is not None:
                now_local = datetime.now(ZoneInfo("Africa/Cairo"))
            else:
                now_local = datetime.utcnow() + timedelta(hours=2)
        except Exception:
            now_local = datetime.utcnow() + timedelta(hours=2)
        action_type = str(pending_action.get("type") or intent_name or "general_qa").strip() or "general_qa"
        signature = self._normalize_internal_behavior_signature(
            request_text,
            intent_name=intent_name,
            pending_action=pending_action,
        )
        behavior_file = self._pi_brain_behavior_summary_file(actor)
        schedule_file = self._pi_brain_dynamic_schedule_file(actor)
        activity_file = self._pi_brain_user_activity_file(actor, "mediator_usage")
        self._pi_brain_append_jsonl(activity_file, {
            "schema_version": "1.0",
            "ts": datetime.now(timezone.utc).isoformat(),
            "actor_key": self._internal_workspace_actor_key(actor),
            "username": str(actor.get("username") or "").strip(),
            "phone": re.sub(r"\D", "", str(actor.get("phone") or "")),
            "intent": str(intent_name or "").strip(),
            "action_type": action_type,
            "request_text": request_text[:1200],
            "signature": signature,
            "case_reference": str(
                case_context.get("booking_number")
                or case_context.get("record_id")
                or case_context.get("phone")
                or case_context.get("email")
                or case_context.get("customer_name")
                or ""
            ).strip(),
            "hour_local": int(getattr(now_local, "hour", 0)),
        })
        summary = self._pi_brain_read_json(behavior_file, {
            "schema_version": "1.0",
            "intent_totals": {},
            "patterns": [],
            "updated_at": "",
        })
        patterns = summary.get("patterns") if isinstance(summary.get("patterns"), list) else []
        intent_totals = summary.get("intent_totals") if isinstance(summary.get("intent_totals"), dict) else {}
        intent_key = str(intent_name or action_type or "general_qa").strip() or "general_qa"
        intent_totals[intent_key] = int(intent_totals.get(intent_key) or 0) + 1
        matched = None
        for item in patterns:
            if isinstance(item, dict) and str(item.get("signature") or "").strip() == signature:
                matched = item
                break
        if not matched:
            matched = {
                "signature": signature,
                "intent": intent_key,
                "action_type": action_type,
                "label": self._internal_behavior_label(intent_name=intent_name, pending_action=pending_action),
                "sample_request": request_text[:300],
                "count": 0,
                "hour_counts": {},
                "first_seen": datetime.now(timezone.utc).isoformat(),
            }
            patterns.append(matched)
        hour_counts = matched.get("hour_counts") if isinstance(matched.get("hour_counts"), dict) else {}
        hour_key = str(int(getattr(now_local, "hour", 0)))
        hour_counts[hour_key] = int(hour_counts.get(hour_key) or 0) + 1
        dominant_hour = 9
        if hour_counts:
            dominant_hour = sorted(
                ((int(k), int(v)) for k, v in hour_counts.items() if str(k).isdigit()),
                key=lambda pair: (-pair[1], pair[0]),
            )[0][0]
        matched.update({
            "intent": intent_key,
            "action_type": action_type,
            "label": self._internal_behavior_label(intent_name=intent_name, pending_action=pending_action),
            "sample_request": str(matched.get("sample_request") or request_text[:300]).strip() or request_text[:300],
            "last_request": request_text[:500],
            "count": int(matched.get("count") or 0) + 1,
            "hour_counts": hour_counts,
            "dominant_hour": int(dominant_hour),
            "preferred_time": f"{int(dominant_hour):02d}:00",
            "last_case_reference": str(
                case_context.get("booking_number")
                or case_context.get("record_id")
                or case_context.get("phone")
                or case_context.get("email")
                or case_context.get("customer_name")
                or ""
            ).strip(),
            "last_seen": datetime.now(timezone.utc).isoformat(),
        })
        patterns = [
            item for item in patterns
            if isinstance(item, dict) and str(item.get("signature") or "").strip()
        ]
        patterns.sort(key=lambda item: (-int(item.get("count") or 0), str(item.get("label") or "")))
        summary["intent_totals"] = intent_totals
        summary["patterns"] = patterns[:80]
        summary["updated_at"] = datetime.now(timezone.utc).isoformat()
        self._pi_brain_write_json(behavior_file, summary)
        schedule_payload = self._pi_brain_read_json(schedule_file, {
            "schema_version": "1.0",
            "items": [],
            "updated_at": "",
        })
        existing_items = schedule_payload.get("items") if isinstance(schedule_payload.get("items"), list) else []
        existing_by_signature = {}
        for item in existing_items:
            if not isinstance(item, dict):
                continue
            item_signature = str(item.get("signature") or "").strip()
            if item_signature:
                existing_by_signature[item_signature] = dict(item)
        new_items = []
        for item in patterns[:20]:
            if not isinstance(item, dict):
                continue
            item_intent = str(item.get("intent") or "").strip() or "general_qa"
            item_count = int(item.get("count") or 0)
            if item_intent in {"general_qa", "agentic_orchestrator"} and item_count < 3:
                continue
            if item_count < 2:
                continue
            allowed_intents = actor.get("allowIntents")
            permission_allowed = True
            actor_role = str(actor.get("role") or "").strip().lower()
            if actor_role != "admin":
                if isinstance(allowed_intents, list) and allowed_intents:
                    permission_allowed = item_intent in {str(x).strip() for x in allowed_intents if str(x).strip()}
                else:
                    permission_allowed = item_intent in {"general_qa", "booking_summary", "draft_reply", "next_step"}
            existing_item = existing_by_signature.get(str(item.get("signature") or "").strip(), {})
            schedule_id = str(existing_item.get("schedule_id") or f"sch_{hashlib.sha1(str(item.get('signature') or '').encode('utf-8')).hexdigest()[:10]}").strip()
            schedule_status = str(existing_item.get("status") or "suggested").strip() or "suggested"
            preferred_time = str(existing_item.get("preferred_time") or item.get("preferred_time") or f"{int(item.get('dominant_hour') or 9):02d}:00").strip()
            new_items.append({
                "schedule_id": schedule_id,
                "signature": str(item.get("signature") or "").strip(),
                "intent": item_intent,
                "action_type": str(item.get("action_type") or item_intent).strip(),
                "title": str(existing_item.get("title") or item.get("label") or self._internal_behavior_label(intent_name=item_intent)).strip(),
                "label": str(item.get("label") or existing_item.get("label") or "").strip(),
                "sample_request": str(existing_item.get("sample_request") or item.get("sample_request") or "").strip(),
                "status": schedule_status,
                "preferred_time": preferred_time,
                "pre_alert_minutes": int(existing_item.get("pre_alert_minutes") or 10),
                "source_count": item_count,
                "dominant_hour": int(item.get("dominant_hour") or 9),
                "permission_allowed": bool(permission_allowed),
                "repeat": "daily",
                "mode": "reminder_only",
                "last_seen": str(item.get("last_seen") or "").strip(),
                "updated_at": datetime.now(timezone.utc).isoformat(),
            })
        schedule_payload["items"] = new_items[:12]
        schedule_payload["updated_at"] = datetime.now(timezone.utc).isoformat()
        self._pi_brain_write_json(schedule_file, schedule_payload)
        self._sync_internal_dynamic_schedule_tasks(actor, schedule_payload)
        return {
            "behavior_summary": summary,
            "schedule": schedule_payload,
        }

    def _build_pi_brain_workspace_payload(self, actor):
        actor = actor or {}
        now_iso = datetime.now(timezone.utc).isoformat()
        actor_key = self._internal_workspace_actor_key(actor)
        actor_slug = self._pi_brain_actor_slug(actor)
        existing = self._pi_brain_read_json(self._pi_brain_paths(actor).get("workspace_file", ""), {})
        created_at = str(existing.get("created_at") or now_iso).strip()
        return {
            "schema_version": "1.0",
            "workspace_id": str(existing.get("workspace_id") or f"pi-ws-{actor_slug or 'unknown'}").strip(),
            "actor_key": actor_key,
            "owner": {
                "name": str(actor.get("name") or "").strip(),
                "role": str(actor.get("role") or "").strip(),
                "phone": re.sub(r"\D", "", str(actor.get("phone") or "")),
                "username": str(actor.get("username") or "").strip(),
            },
            "allowed_bases": self._actor_allowed_base_labels(actor),
            "status": "active",
            "created_at": created_at,
            "updated_at": now_iso,
        }

