    def _build_pi_brain_behavior_model_payload(self, actor, session_state=None):
        actor = actor or {}
        session_state = session_state if isinstance(session_state, dict) else {}
        recent_turns = session_state.get("recent_turns") if isinstance(session_state.get("recent_turns"), list) else []
        example_turns = []
        for item in recent_turns[-5:]:
            if not isinstance(item, dict):
                continue
            txt = str(item.get("text") or "").strip()
            role = str(item.get("role") or "").strip()
            if txt:
                example_turns.append({
                    "role": role[:32],
                    "text": txt[:300],
                })
        return {
            "schema_version": "1.0",
            "user_key": self._internal_workspace_actor_key(actor),
            "communication_style": "mixed_ar_en",
            "detail_level": "medium",
            "decision_style": "approval_first",
            "prefers_examples": True,
            "prefers_direct_execution_for_safe_ops": True,
            "risk_tolerance": "medium_low",
            "common_sequences": [
                ["booking_summary", "next_step", "draft_reply"],
                ["lookup_case", "update_airtable", "approval"],
            ],
            "rejected_patterns": [
                "implicit_note_update",
                "send_without_preview",
            ],
            "recent_signal_examples": example_turns,
            "confidence": 0.6,
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }

