    def _get_pi_capability_registry(self):
        return self._build_pi_capability_registry_payload()

    def _match_pi_capabilities(self, text, intent_name=None):
        txt = " ".join(str(text or "").strip().lower().split())
        intent_name = str(intent_name or "").strip().lower()
        registry = self._get_pi_capability_registry()
        matched = []
        for item in (registry.get("capabilities") or []):
            if not isinstance(item, dict):
                continue
            key = str(item.get("key") or "").strip().lower()
            aliases = [str(x).strip().lower() for x in (item.get("aliases") or []) if str(x).strip()]
            if intent_name and key == intent_name:
                matched.append(item)
                continue
            if txt and any(alias in txt for alias in aliases):
                matched.append(item)
        return matched[:5]

    def _get_payment_record_context(self, record_id, amount_in=None, currency_in=None, selected_add_ons=None):
        record_id = str(record_id or "").strip()
        if not record_id:
            raise ValueError("Missing record_id")
        rec = self.table.get(record_id)
        if not isinstance(rec, dict):
            raise ValueError("Booking record not found")
        fields = (rec.get("fields") or {}) if isinstance(rec.get("fields"), dict) else {}
        amount = amount_in if amount_in is not None else fields.get("Amount")
        currency = currency_in if currency_in is not None else fields.get("Currency")
        try:
            amount_val = float(str(amount).strip())
        except Exception:
            amount_val = None
        currency_val = ""
        try:
            if isinstance(currency, list) and currency:
                currency_val = str(currency[0] or "").strip()
            else:
                currency_val = str(currency or "").strip()
        except Exception:
            currency_val = str(currency or "").strip()
        if not currency_val:
            net_rate_str = str(fields.get("Net Rate") or "")
            agency_str = str(fields.get("Agency") or "").strip().lower()
            if "€" in net_rate_str or "eur" in net_rate_str.upper() or "ägypten" in agency_str:
                currency_val = "EUR"
            elif "$" in net_rate_str or "USD" in net_rate_str.upper():
                currency_val = "USD"
            elif "EGP" in net_rate_str.upper():
                currency_val = "EGP"
            else:
                currency_val = "EUR"
        add_ons_text = ""
        if isinstance(selected_add_ons, list):
            add_ons_text = " | ".join([str(x or "").strip() for x in selected_add_ons if str(x or "").strip()])
        if not add_ons_text:
            raw_multi = fields.get("Add-Ons ((MultiSelect))")
            if isinstance(raw_multi, list):
                add_ons_text = " | ".join([str(x or "").strip() for x in raw_multi if str(x or "").strip()])
        if not add_ons_text:
            add_ons_text = str(fields.get("Add - Ons") or "").strip()
        return {
            "record_id": record_id,
            "fields": fields,
            "amount": amount_val,
            "currency": str(currency_val or "").strip(),
            "customer_name": str(fields.get("Customer Name") or "").strip(),
            "customer_email": str(fields.get("Customer personal email") or fields.get("Customer Email") or "").strip(),
            "customer_phone": str(fields.get("Customer Phone") or "").strip(),
            "trip_name": str(fields.get("trip Name") or fields.get("Trip Name") or "").strip(),
            "booking_number": str(fields.get("Booking Nr.") or "").strip(),
            "trip_date": fields.get("Date Trip") or fields.get("Date") or "",
            "add_ons_text": add_ons_text,
            "existing_payment_url": str(fields.get("Stripe invoice") or "").strip(),
            "existing_payment_id": str(fields.get("Trip UUID") or "").strip(),
            "invoice_status": str(fields.get("Invoice Status") or "").strip(),
        }

    def _infer_booking_communication_profile(self, booking_fields):
        fields = booking_fields if isinstance(booking_fields, dict) else {}
        trip_name = str(fields.get("trip Name") or fields.get("Trip Name") or "").strip()
        option_name = str(fields.get("Option") or "").strip()
        trip_lower = trip_name.lower()
        option_lower = option_name.lower()
        is_ticket = ("qr" in trip_lower) or ("sound" in trip_lower)
        is_flight = ("plane" in trip_lower) or ("flight" in trip_lower)
        is_audio_guide = "audio guide" in option_lower
        booking_type = "standard"
        if is_ticket:
            booking_type = "ticket"
        elif is_flight:
            booking_type = "flight"
        elif is_audio_guide:
            booking_type = "audio_guide"
        return {
            "trip_name": trip_name,
            "option": option_name,
            "booking_type": booking_type,
            "is_ticket": bool(is_ticket),
            "is_flight": bool(is_flight),
            "is_audio_guide": bool(is_audio_guide),
            "payment_template_strategy": "payment_template_default",
        }

    def _resolve_current_invoice_template_name(self, location=None):
        _ = location
        return "ftstravels_confirm_payment"

    def _build_current_invoice_template_variables(self, booking_fields, payment_url):
        fields = booking_fields if isinstance(booking_fields, dict) else {}
        customer_name = str(fields.get("Customer Name") or "").strip() or "Guest"
        booking_nr = str(fields.get("Booking Nr.") or "").strip() or "-"
        trip_name = str(fields.get("trip Name") or fields.get("Trip Name") or "").strip() or booking_nr
        add_ons = str(fields.get("Add - Ons") or "").strip() or "add ons"
        return [
            customer_name,
            booking_nr,
            trip_name,
            str(payment_url or "").strip(),
            trip_name,
            add_ons,
        ]

    def _stringify_template_field(self, value):
        if value is None:
            return ""
        if isinstance(value, list):
            return " | ".join([self._stringify_template_field(x) for x in value if self._stringify_template_field(x)])
        if isinstance(value, dict):
            return str(value.get("name") or value.get("url") or "").strip()
        s = str(value).strip()
        m = re.match(r"^(\d{4})-(\d{2})-(\d{2})(?:[T\s]|$)", s)
        if m and ("T" in s or "00:00:00" in s):
            return f"{m.group(3)}/{m.group(2)}/{m.group(1)}"
        return s

    def _booking_field_for_template(self, booking_data, *keys):
        data = booking_data if isinstance(booking_data, dict) else {}
        wanted = {str(k).strip().lower() for k in keys if str(k).strip()}
        for ek, ev in data.items():
            if str(ek).strip().lower() in wanted:
                s = self._stringify_template_field(ev)
                if s:
                    return s
        return ""

    def _map_whatsapp_template_variables(self, template_text, booking_data=None, template_name="", agent_name="", contact_name=""):
        text = str(template_text or "")
        nums = []
        for inner in re.findall(r"\{\{([^}]+)\}\}", text):
            for d in re.findall(r"\d+", str(inner)):
                try:
                    nums.append(int(d))
                except Exception:
                    pass
        expected = max(nums) if nums else 0
        if expected <= 0:
            return []

        agent_first = str(agent_name or "").strip().split()[0] if str(agent_name or "").strip() else ""
        catalog = {
            "customer_name": self._booking_field_for_template(booking_data, "Customer Name", "Traveler name") or str(contact_name or "").strip(),
            "agent_name": agent_first,
            "booking_nr": self._booking_field_for_template(booking_data, "Booking Nr.", "Booking Number", "Booking Nr"),
            "trip_name": self._booking_field_for_template(booking_data, "trip Name", "Trip Name", "Real Product Name"),
            "hotel": self._booking_field_for_template(booking_data, "Hotel Name"),
            "pickup": self._booking_field_for_template(booking_data, "pickup time", "Pickup Time"),
            "room": self._booking_field_for_template(booking_data, "Room number", "Room Number"),
            "date": self._booking_field_for_template(booking_data, "Date Trip", "Date"),
            "phone": self._booking_field_for_template(booking_data, "Customer Phone"),
            "invoice": self._booking_field_for_template(booking_data, "Stripe invoice", "Strip Invoice", "Payment Link", "Invoice URL"),
            "addons": self._booking_field_for_template(booking_data, "Add-Ons ((MultiSelect))", "Add - Ons"),
            "option": self._booking_field_for_template(booking_data, "Option"),
        }
        keywords = {
            "customer_name": ("hello", "dear", "hi ", "guest", "customer name", "passenger"),
            "agent_name": ("this is", "i am", "from fts", "my name", "agent"),
            "booking_nr": ("booking", "reference", "ref", "nr.", "#"),
            "trip_name": ("trip", "tour", "excursion", "activity", "product"),
            "hotel": ("hotel",),
            "pickup": ("pickup", "pick up", "pick-up"),
            "room": ("room",),
            "date": ("date", "day of"),
            "phone": ("phone", "whatsapp", "mobile"),
            "invoice": ("invoice", "payment", "stripe", "pay now", "pay here"),
            "addons": ("addon", "add-on", "add on", "extra"),
            "option": ("option",),
        }
        known_layouts = {
            "opening": ["customer_name", "agent_name", "booking_nr", "trip_name"],
            "welcome_booking": ["customer_name", "trip_name", "booking_nr", "date"],
            "ftstravels_confirm_payment": ["customer_name", "booking_nr", "trip_name", "invoice", "addons", "trip_name"],
        }
        name_lower = str(template_name or "").strip().lower()
        known = None
        for key, layout in known_layouts.items():
            if name_lower == key or key in name_lower:
                known = layout
                break

        parts = re.split(r"\{\{\s*\d+\s*\}\}", text)
        matches = re.findall(r"\{\{\s*(\d+)\s*\}\}", text)
        used = set()
        values = []
        leftover_skip = {"invoice", "phone", "agent_name"}

        for i in range(1, expected + 1):
            picked = ""
            if known and i - 1 < len(known):
                picked = known[i - 1]
            else:
                ctx = ""
                for idx, num_s in enumerate(matches):
                    try:
                        n = int(num_s)
                    except Exception:
                        continue
                    if n != i:
                        continue
                    before = parts[idx] if idx < len(parts) else ""
                    after = parts[idx + 1] if idx + 1 < len(parts) else ""
                    ctx = f"{before[-48:]} {after[:14]}".lower()
                    break
                best_key = ""
                best_score = 0
                for key, kws in keywords.items():
                    if key in used and key != "trip_name":
                        continue
                    score = 0
                    for kw in kws:
                        if kw in ctx:
                            score += max(3, len(kw))
                    if score > best_score:
                        best_score = score
                        best_key = key
                if best_score > 0:
                    picked = best_key
            if not picked:
                for key, val in catalog.items():
                    if key in used or key in leftover_skip or not val:
                        continue
                    picked = key
                    break
            if picked:
                used.add(picked)
            values.append(str(catalog.get(picked) or "") if picked else "")
        return values

    def _fetch_whatsapp_templates_from_meta(self, location=None, statuses=None, max_pages=25):
        """
        Fetch WhatsApp message templates for the WABA linked to `location`.
        Follows Meta pagination cursors (important: accounts often have >100 templates).
        `statuses`: None = return all statuses; or iterable like {"APPROVED"}.
        """
        location = str(location or "default").strip() or "default"
        token = self._get_whatsapp_access_token()
        waba_ids = self.config.get('whatsapp', {}).get('waba_ids', {}) or {}
        waba_id = waba_ids.get(location, waba_ids.get('default'))
        if not token or not waba_id:
            return {
                "templates": [],
                "waba_id": waba_id,
                "location": location,
                "pages_fetched": 0,
                "error": "missing_token_or_waba_id",
            }

        status_filter = None
        if statuses is not None:
            status_filter = {str(s or "").strip().upper() for s in statuses if str(s or "").strip()}

        collected = []
        pages_fetched = 0
        after = None
        last_error = None
        try:
            while pages_fetched < max(1, int(max_pages or 25)):
                params = {
                    "access_token": token,
                    "limit": 100,
                    "fields": "name,status,category,language,components,id",
                }
                if after:
                    params["after"] = after
                url = f"https://graph.facebook.com/{META_GRAPH_VERSION}/{waba_id}/message_templates"
                res = requests.get(url, params=params, timeout=20)
                pages_fetched += 1
                if res.status_code != 200:
                    last_error = res.text
                    logging.warning(
                        "Failed to fetch WhatsApp templates page %s for %s (WABA %s): %s",
                        pages_fetched,
                        location,
                        waba_id,
                        res.text,
                    )
                    break
                payload = res.json() or {}
                batch = payload.get("data") or []
                if isinstance(batch, list):
                    for t in batch:
                        if not isinstance(t, dict):
                            continue
                        st = str(t.get("status") or "").strip().upper()
                        if status_filter is not None and st not in status_filter:
                            continue
                        collected.append(t)
                paging = payload.get("paging") if isinstance(payload.get("paging"), dict) else {}
                cursors = paging.get("cursors") if isinstance(paging.get("cursors"), dict) else {}
                next_after = str(cursors.get("after") or "").strip()
                has_next = bool(paging.get("next")) and bool(next_after)
                if not has_next:
                    break
                after = next_after
        except Exception as e:
            last_error = str(e)
            logging.warning(f"Error fetching WhatsApp templates for {location}: {e}", exc_info=True)

        return {
            "templates": collected,
            "waba_id": waba_id,
            "location": location,
            "pages_fetched": pages_fetched,
            "error": last_error,
        }

    def _fetch_approved_whatsapp_templates(self, location=None):
        result = self._fetch_whatsapp_templates_from_meta(location=location, statuses={"APPROVED"})
        return list(result.get("templates") or [])

    def _extract_whatsapp_template_body_preview(self, template_obj):
        template_obj = template_obj if isinstance(template_obj, dict) else {}
        for comp in (template_obj.get("components") or []):
            if not isinstance(comp, dict):
                continue
            if str(comp.get("type") or "").strip().upper() != "BODY":
                continue
            txt = str(comp.get("text") or "").strip()
            if txt:
                return txt[:120]
        return ""

    def _describe_whatsapp_template_candidate(self, template_obj):
        template_obj = template_obj if isinstance(template_obj, dict) else {}
        name = str(template_obj.get("name") or "").strip()
        language = str(template_obj.get("language") or "en").strip() or "en"
        body_preview = self._extract_whatsapp_template_body_preview(template_obj)
        name_lower = name.lower()
        if "opening" in name_lower:
            base = "Opening / conversation reopening template"
        elif any(token in name_lower for token in ("payment", "invoice", "confirm")):
            base = "Payment or invoice link template"
        elif "collect" in name_lower:
            base = "Information collection template"
        elif "feedback" in name_lower:
            base = "Feedback follow-up template"
        else:
            base = "Approved WhatsApp template"
        if body_preview:
            return f"{base}. Lang: {language}. Preview: {body_preview}"
        return f"{base}. Lang: {language}."

    def _suggest_invoice_template_candidates(self, location=None, preferred_template_name="", booking_fields=None, limit=5):
        templates = self._fetch_approved_whatsapp_templates(location)
        preferred = str(preferred_template_name or "").strip().lower()
        fields = booking_fields if isinstance(booking_fields, dict) else {}
        trip_name = str(fields.get("trip Name") or fields.get("Trip Name") or "").strip().lower()

        def _score(template_obj):
            name = str(template_obj.get("name") or "").strip().lower()
            language = str(template_obj.get("language") or "en").strip().lower()
            body = self._extract_whatsapp_template_body_preview(template_obj).lower()
            score = 0
            if preferred:
                if name == preferred:
                    score += 1000
                elif preferred in name:
                    score += 700
            if any(token in name for token in ("payment", "invoice", "confirm")):
                score += 140
            if any(token in body for token in ("payment", "invoice", "pay now", "secure payment")):
                score += 90
            if "opening" in name:
                score += 120
            if "collect" in name:
                score += 40
            if trip_name and trip_name in body:
                score += 10
            if language == "en":
                score += 10
            return score

        ranked = []
        seen = set()
        for template_obj in templates:
            name = str(template_obj.get("name") or "").strip()
            language = str(template_obj.get("language") or "en").strip() or "en"
            key = (name.lower(), language.lower())
            if not name or key in seen:
                continue
            seen.add(key)
            ranked.append({
                "name": name,
                "language": language,
                "label": f"{name} ({language})",
                "description": self._describe_whatsapp_template_candidate(template_obj),
                "score": _score(template_obj),
            })
        ranked.sort(key=lambda item: (-int(item.get("score") or 0), str(item.get("name") or "")))
        filtered = [item for item in ranked if int(item.get("score") or 0) > 0]
        final_items = filtered or ranked[:max(1, int(limit or 5))]
        return final_items[:max(1, int(limit or 5))]

    def _preview_invoice_capability(self, record_id, amount_in=None, currency_in=None, selected_add_ons=None, allow_existing_invoice=False):
        ctx = self._get_payment_record_context(record_id, amount_in=amount_in, currency_in=currency_in, selected_add_ons=selected_add_ons)
        warnings = []
        blocked_reasons = []
        if ctx.get("amount") in (None, 0) or float(ctx.get("amount") or 0) <= 0:
            blocked_reasons.append("missing_or_invalid_amount")
        if not str(ctx.get("currency") or "").strip():
            blocked_reasons.append("missing_currency")
        if not str(ctx.get("customer_name") or "").strip():
            warnings.append("missing_customer_name")
        communication_profile = self._infer_booking_communication_profile(ctx.get("fields") or {})
        existing_invoice_present = bool(str(ctx.get("existing_payment_url") or "").strip() or str(ctx.get("existing_payment_id") or "").strip())
        if existing_invoice_present and not allow_existing_invoice:
            blocked_reasons.append("invoice_already_exists")
        if existing_invoice_present and allow_existing_invoice:
            warnings.append("existing_invoice_will_be_replaced")
        provider = "stripe" if "USD" in str(ctx.get("currency") or "").upper() else "wetravel"
        return {
            "capability_key": "create_invoice",
            "simulate_only": True,
            "record_id": str(ctx.get("record_id") or "").strip(),
            "booking_number": str(ctx.get("booking_number") or "").strip(),
            "customer_name": str(ctx.get("customer_name") or "").strip(),
            "amount": ctx.get("amount"),
            "currency": str(ctx.get("currency") or "").strip(),
            "provider": provider,
            "invoice_status": str(ctx.get("invoice_status") or "").strip(),
            "existing_payment_url": str(ctx.get("existing_payment_url") or "").strip(),
            "existing_payment_id": str(ctx.get("existing_payment_id") or "").strip(),
            "existing_invoice_present": existing_invoice_present,
            "force_new_invoice": bool(allow_existing_invoice),
            "booking_type": str(communication_profile.get("booking_type") or "standard"),
            "communication_profile": communication_profile,
            "ready_to_execute": not blocked_reasons,
            "warnings": warnings,
            "blocked_reasons": blocked_reasons,
            "dry_run_supported": True,
        }

    def _execute_invoice_capability(self, record_id, amount_in=None, currency_in=None, selected_add_ons=None, allow_existing=False):
        preview = self._preview_invoice_capability(
            record_id,
            amount_in=amount_in,
            currency_in=currency_in,
            selected_add_ons=selected_add_ons,
            allow_existing_invoice=allow_existing,
        )
        blocked_reasons = list(preview.get("blocked_reasons") or [])
        if blocked_reasons and not (allow_existing and blocked_reasons == ["invoice_already_exists"]):
            raise ValueError("Invoice execution blocked: " + ", ".join(blocked_reasons))
        ctx = self._get_payment_record_context(record_id, amount_in=amount_in, currency_in=currency_in, selected_add_ons=selected_add_ons)
        amount_val = float(ctx.get("amount"))
        currency_val = str(ctx.get("currency") or "").strip()
        customer_name = str(ctx.get("customer_name") or "").strip() or None
        customer_email = str(ctx.get("customer_email") or "").strip() or None
        customer_phone = str(ctx.get("customer_phone") or "").strip() or None
        trip_name = str(ctx.get("trip_name") or "").strip() or None
        booking_nr = str(ctx.get("booking_number") or "").strip() or None
        date_trip = ctx.get("trip_date")
        add_ons_text = str(ctx.get("add_ons_text") or "").strip()

        def _stripe_secret_key():
            k = os.environ.get("STRIPE_SECRET_KEY")
            if k:
                return k.strip()
            cfg = (self.config.get("stripe", {}) or {})
            k = cfg.get("secret_key")
            return str(k).strip() if k else None

        def _wetravel_refresh_token():
            k = os.environ.get("WETRAVEL_REFRESH_TOKEN")
            if k:
                return k.strip()
            cfg = (self.config.get("wetravel", {}) or {})
            k = cfg.get("refresh_token")
            return str(k).strip() if k else None

        def _stripe_request(method, path, data=None):
            import requests
            key = _stripe_secret_key()
            if not key:
                raise ValueError("Stripe secret key missing")
            url = f"https://api.stripe.com{path}"
            headers = {"Authorization": f"Bearer {key}"}
            res = requests.request(method, url, headers=headers, data=data, timeout=20)
            try:
                body = res.json()
            except Exception:
                body = {"raw": res.text}
            if res.status_code not in (200, 201):
                raise ValueError(f"Stripe error ({res.status_code}): {body}")
            return body

        def _create_stripe_invoice():
            import time
            name = customer_name or "Guest"
            cust = _stripe_request("POST", "/v1/customers", {
                "name": name,
                "email": customer_email or "",
                "phone": customer_phone or "",
            })
            cents = int(round(float(amount_val) * 100))
            if cents <= 0:
                raise ValueError("Stripe amount is too small after converting to cents")
            desc_parts = []
            if add_ons_text:
                desc_parts.append(add_ons_text)
            if trip_name:
                desc_parts.append(trip_name)
            if booking_nr:
                desc_parts.append(f"({booking_nr})")
            description = " ".join(desc_parts) if desc_parts else "Booking Payment"
            inv = _stripe_request("POST", "/v1/invoices", {
                "customer": cust.get("id"),
                "auto_advance": "false",
                "collection_method": "send_invoice",
                "days_until_due": "7",
            })
            ii = _stripe_request("POST", "/v1/invoiceitems", {
                "customer": cust.get("id"),
                "invoice": inv.get("id"),
                "amount": cents,
                "currency": currency_val.strip().lower(),
                "description": description,
            })
            _ = ii
            inv_check = None
            for attempt in range(5):
                if attempt:
                    time.sleep(1.0)
                inv_check = _stripe_request("GET", f"/v1/invoices/{inv.get('id')}")
                try:
                    if int(inv_check.get("total") or 0) > 0 or int(inv_check.get("amount_due") or 0) > 0:
                        break
                except Exception:
                    pass
            if not inv_check or (int(inv_check.get("total") or 0) <= 0 and int(inv_check.get("amount_due") or 0) <= 0):
                raise ValueError("Stripe invoice total is 0 after attaching invoice item.")
            fin = _stripe_request("POST", f"/v1/invoices/{inv.get('id')}/finalize")
            if int(fin.get("total") or 0) <= 0 and int(fin.get("amount_due") or 0) <= 0:
                raise ValueError("Stripe invoice finalized with total=0.")
            return {
                "payment_method": "stripe",
                "payment_id": fin.get("id") or inv.get("id"),
                "payment_url": fin.get("hosted_invoice_url") or inv.get("hosted_invoice_url"),
                "invoice_pdf": fin.get("invoice_pdf") or inv.get("invoice_pdf"),
            }

        def _create_wetravel_link():
            import requests
            refresh_token = _wetravel_refresh_token()
            if not refresh_token:
                raise ValueError("WeTravel refresh token missing")
            token_res = requests.post(
                "https://api.wetravel.com/v2/auth/tokens/access",
                headers={"accept": "application/json", "authorization": f"Bearer {refresh_token}"},
                timeout=20,
            )
            try:
                token_json = token_res.json()
            except Exception:
                token_json = None
            if token_res.status_code not in (200, 201) or not token_json:
                raise ValueError(f"WeTravel token error ({token_res.status_code}): {token_res.text}")
            access_token = ((token_json.get("data") or {}).get("access_token") if isinstance(token_json, dict) else None) or (token_json.get("access_token") if isinstance(token_json, dict) else None)
            if not access_token:
                raise ValueError("WeTravel access_token missing")
            body = {
                "data": {
                    "trip": {
                        "participant_fees": "all",
                        "title": (trip_name or "").strip() or "Trip",
                        "start_date": str(date_trip).strip() if date_trip is not None else "",
                        "end_date": str(date_trip).strip() if date_trip is not None else "",
                        "currency": currency_val,
                    },
                    "pricing": {"price": float(amount_val)},
                    "payer": {
                        "name": customer_name or "Guest",
                        "email": (customer_email or "").replace("\n", "").replace("\r", "").strip(),
                    },
                    "metadata": {
                        "booking_nr": booking_nr or "",
                        "airtable_record_id": str(record_id),
                        "selected_add_ons": add_ons_text,
                    },
                }
            }
            link_res = requests.post(
                "https://api.wetravel.com/v2/payment_links?publish_immediately=true",
                headers={
                    "accept": "application/json",
                    "content-type": "application/json",
                    "authorization": f"Bearer {access_token}",
                },
                json=body,
                timeout=20,
            )
            try:
                link_json = link_res.json()
            except Exception:
                link_json = None
            if link_res.status_code not in (200, 201) or not link_json:
                raise ValueError(f"WeTravel payment_link error ({link_res.status_code}): {link_res.text}")
            data_root = link_json.get("data") if isinstance(link_json, dict) else None
            if isinstance(data_root, list):
                data_root = data_root[0] if data_root else None
            if not isinstance(data_root, dict):
                data_root = {}
            trip = data_root.get("trip")
            if not trip and isinstance((data_root.get("data") or {}), dict):
                trip = (data_root.get("data") or {}).get("trip")
            if isinstance(trip, list):
                trip = trip[0] if trip else None
            if not isinstance(trip, dict):
                trip = {}
            w_uuid = trip.get("uuid")
            w_url = trip.get("url")
            if (not w_uuid) or (not w_url):
                raise ValueError(f"WeTravel response missing uuid/url: {link_json}")
            return {
                "payment_method": "wetravel",
                "payment_id": w_uuid,
                "payment_url": w_url,
            }

        if "USD" in currency_val.upper():
            created = _create_stripe_invoice()
        else:
            created = _create_wetravel_link()
        updates = {
            "Trip UUID": created.get("payment_id"),
            "Stripe invoice": created.get("payment_url"),
            "Invoice Status": "pending",
        }
        if amount_in is not None:
            updates["Amount"] = amount_val
        if str(currency_in or "").strip():
            updates["Currency"] = currency_val
        try:
            self._update_airtable_table_record(self.table, str(record_id), updates, typecast=True)
        except Exception:
            fallback_updates = {
                "Trip UUID": created.get("payment_id"),
                "Stripe invoice": created.get("payment_url"),
                "Invoice Status": "pending",
            }
            self._update_airtable_table_record(self.table, str(record_id), fallback_updates, typecast=True)
        return {
            "record_id": str(record_id),
            **created,
            "airtable_updates": updates,
        }

    def _build_pi_brain_current_context_payload(self, actor, session_state=None, case_id=None, intent_name=None, case_context=None):
        actor = actor or {}
        session_state = session_state if isinstance(session_state, dict) else {}
        recent_turns = session_state.get("recent_turns") if isinstance(session_state.get("recent_turns"), list) else []
        pending_action = session_state.get("pending_action") if isinstance(session_state.get("pending_action"), dict) else {}
        workflow_state = session_state.get("workflow_state") if isinstance(session_state.get("workflow_state"), dict) else {}
        pi_case_state = session_state.get("pi_case_state") if isinstance(session_state.get("pi_case_state"), dict) else {}
        return {
            "schema_version": "1.0",
            "user_key": self._internal_workspace_actor_key(actor),
            "case_id": str(case_id or pi_case_state.get("case_id") or "").strip(),
            "intent": str(intent_name or workflow_state.get("intent") or pi_case_state.get("intent") or "").strip(),
            "case_context": self._pi_brain_safe_json(case_context if isinstance(case_context, dict) and case_context else workflow_state.get("case_context") or session_state.get("last_case_context") or {}),
            "workflow_state": self._pi_brain_safe_json(workflow_state),
            "pending_action": self._pi_brain_safe_json(pending_action),
            "recent_turns": self._pi_brain_safe_json(recent_turns[-20:]),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }

    def _build_pi_brain_action_manifest_payload(self, actor, case_id, stage_name, payload, intent_name=None, case_context=None, session_state=None):
        actor = actor or {}
        payload = payload if isinstance(payload, dict) else {}
        session_state = session_state if isinstance(session_state, dict) else {}
        pending_action = session_state.get("pending_action") if isinstance(session_state.get("pending_action"), dict) else {}
        workflow_state = session_state.get("workflow_state") if isinstance(session_state.get("workflow_state"), dict) else {}
        case_context = case_context if isinstance(case_context, dict) else {}
        payload_preview = payload.get("payload_preview") if isinstance(payload.get("payload_preview"), dict) else {}
        pi_guidance = payload.get("pi_guidance") if isinstance(payload.get("pi_guidance"), dict) else {}
        pending_action_type = str(payload.get("pending_action_type") or pending_action.get("type") or intent_name or "").strip()
        target = str(
            case_context.get("record_id")
            or case_context.get("booking_number")
            or case_context.get("email")
            or case_context.get("phone")
            or ""
        ).strip()
        actions = []
        if stage_name in {"execution_bridge", "approval_preparation"} and pending_action_type:
            actions.append({
                "action_id": f"{case_id}-pending-01",
                "type": pending_action_type,
                "target": target,
                "requires_approval": bool(payload.get("requires_approval", True)),
                "status": str(payload.get("bridge_status") or workflow_state.get("phase") or "proposed").strip() or "proposed",
                "source_stage": stage_name,
                "payload": self._pi_brain_safe_json(dict(pending_action) if pending_action else payload_preview),
                "reason": str((pi_guidance or {}).get("recommended_next_step") or f"Generated from {stage_name}").strip(),
                "confidence": pi_guidance.get("confidence"),
            })
        if stage_name == "pi_delegation":
            structured = payload.get("pi_analysis") if isinstance(payload.get("pi_analysis"), dict) else {}
            structured_result = structured.get("structured_result") if isinstance(structured.get("structured_result"), dict) else {}
            execution_guidance = str(structured_result.get("execution_guidance") or "").strip()
            
            # Extract PI's generated action manifest
            pi_manifest = structured_result.get("action_manifest", [])
            if isinstance(pi_manifest, list) and pi_manifest:
                for idx, act in enumerate(pi_manifest):
                    actions.append({
                        "action_id": f"{case_id}-pi-manifest-{idx}",
                        "type": str(act.get("type") or "unknown").strip(),
                        "target": str(act.get("target_record") or act.get("target") or target).strip(),
                        "requires_approval": bool(act.get("requires_approval", True)),
                        "status": "proposed",
                        "source_stage": stage_name,
                        "payload": self._pi_brain_safe_json(act.get("payload", {})),
                        "reason": "Explicitly requested by PI via Knowledge Engine schema.",
                        "confidence": structured_result.get("confidence"),
                    })
            elif execution_guidance or str(structured_result.get("recommended_next_step") or "").strip():
                actions.append({
                    "action_id": f"{case_id}-pi-guidance-01",
                    "type": "pi_guidance",
                    "target": target,
                    "requires_approval": bool(structured_result.get("approval_required")),
                    "status": str((structured or {}).get("status") or "advisory").strip() or "advisory",
                    "source_stage": stage_name,
                    "payload": {
                        "execution_guidance": execution_guidance,
                        "recommended_next_step": str(structured_result.get("recommended_next_step") or "").strip(),
                        "clarifying_question": str(structured_result.get("clarifying_question") or "").strip(),
                        "risk_flags": [str(x).strip() for x in (structured_result.get("risk_flags") or []) if str(x).strip()][:10],
                    },
                    "reason": "Structured PI analysis is available for the local bridge.",
                    "confidence": structured_result.get("confidence"),
                })
        if stage_name == "validation" and payload.get("status") == "blocked":
            actions.append({
                "action_id": f"{case_id}-validation-block-01",
                "type": "ask_clarifying_question",
                "target": target,
                "requires_approval": False,
                "status": "blocked",
                "source_stage": stage_name,
                "payload": {
                    "blocked_reasons": [str(x).strip() for x in (payload.get("blocked_reasons") or []) if str(x).strip()][:10],
                },
                "reason": "Validation blocked the path and requires clarification.",
                "confidence": 1.0,
            })
        return {
            "schema_version": "1.0",
            "workspace_actor": self._internal_workspace_actor_key(actor),
            "case_id": str(case_id or "").strip(),
            "intent": str(intent_name or workflow_state.get("intent") or "").strip(),
            "stage": str(stage_name or "").strip(),
            "actions": actions,
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }

    def _write_pi_manifest_to_outbox(self, actor, manifest_payload, case_id=None):
        import uuid
        import hashlib
        paths = self._ensure_pi_brain_workspace(actor, case_id=case_id)
        if not paths or not paths.get("outbox_dir"):
            return None
        outbox_dir = paths["outbox_dir"]
        actions = manifest_payload.get("actions") if isinstance(manifest_payload.get("actions"), list) else []
        manifest_fingerprint_payload = {
            "intent": str(manifest_payload.get("intent") or "").strip(),
            "stage": str(manifest_payload.get("stage") or "").strip(),
            "actions": actions,
        }
        try:
            manifest_fingerprint = hashlib.sha1(
                json.dumps(manifest_fingerprint_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
            ).hexdigest()
        except Exception:
            manifest_fingerprint = ""
        if manifest_fingerprint:
            try:
                for filename in os.listdir(outbox_dir):
                    if not filename.endswith(".json"):
                        continue
                    existing_path = os.path.join(outbox_dir, filename)
                    try:
                        with open(existing_path, "r", encoding="utf-8") as existing_file:
                            existing_manifest = json.load(existing_file)
                    except Exception:
                        continue
                    if not isinstance(existing_manifest, dict):
                        continue
                    if str(existing_manifest.get("status") or "").strip().lower() != "pending":
                        continue
                    existing_fingerprint = str(existing_manifest.get("fingerprint") or "").strip()
                    if not existing_fingerprint:
                        existing_payload = {
                            "intent": str(existing_manifest.get("intent") or "").strip(),
                            "stage": str(existing_manifest.get("stage") or "").strip(),
                            "actions": existing_manifest.get("actions") if isinstance(existing_manifest.get("actions"), list) else [],
                        }
                        try:
                            existing_fingerprint = hashlib.sha1(
                                json.dumps(existing_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
                            ).hexdigest()
                        except Exception:
                            existing_fingerprint = ""
                    if existing_fingerprint and existing_fingerprint == manifest_fingerprint:
                        return str(existing_manifest.get("manifest_id") or os.path.splitext(filename)[0]).strip() or None
            except Exception:
                pass
        manifest_id = str(manifest_payload.get("manifest_id") or f"man_{uuid.uuid4().hex[:8]}")
        manifest_payload["manifest_id"] = manifest_id
        manifest_payload["status"] = "pending"
        manifest_payload["created_at"] = datetime.now(timezone.utc).isoformat()
        if manifest_fingerprint:
            manifest_payload["fingerprint"] = manifest_fingerprint
        file_path = os.path.join(outbox_dir, f"{manifest_id}.json")
        try:
            os.makedirs(os.path.dirname(file_path), exist_ok=True)
            with open(file_path, "w", encoding="utf-8") as fh:
                json.dump(manifest_payload, fh, ensure_ascii=False, indent=2)
        except TypeError:
            self._pi_brain_write_json(file_path, manifest_payload)
        # #region debug-point internal-latency.manifest-outbox-write
        try:
            import json as _dbg_json, urllib.request as _dbg_urllib_request, time as _dbg_time
            _dbg_urllib_request.urlopen(
                _dbg_urllib_request.Request(
                    'http://127.0.0.1:7778/event',
                    data=_dbg_json.dumps({
                        'sessionId': 'internal-latency',
                        'runId': 'pre',
                        'hypothesisId': 'H2',
                        'location': 'ai_agent.py:_write_pi_manifest_to_outbox',
                        'msg': '[DEBUG] manifest written to outbox',
                        'data': {
                            'manifest_id': str(manifest_id or ''),
                            'intent': str(manifest_payload.get('intent') or ''),
                            'stage': str(manifest_payload.get('stage') or ''),
                            'actions_count': len(actions),
                            'created_at': str(manifest_payload.get('created_at') or ''),
                            'case_id': str(case_id or ''),
                            'actor_username': str((actor or {}).get('username') or ''),
                        },
                        'ts': int(_dbg_time.time() * 1000)
                    }).encode(),
                    headers={'Content-Type': 'application/json'}
                ),
                timeout=2
            ).read()
        except Exception:
            pass
        # #endregion
        try:
            self._emit_pi_trace_event(
                "manifest.outbox.write",
                {
                    "manifest_id": manifest_id,
                    "intent": str(manifest_payload.get("intent") or "").strip(),
                    "stage": str(manifest_payload.get("stage") or "").strip(),
                    "action_count": len(actions),
                    "actions": [
                        {
                            "type": str((action or {}).get("type") or "").strip(),
                            "requires_approval": bool((action or {}).get("requires_approval")),
                        }
                        for action in actions[:10]
                        if isinstance(action, dict)
                    ],
                    "file_path": file_path,
                    "outbox_dir": outbox_dir,
                    "actor": str((actor or {}).get("username") or (actor or {}).get("name") or "").strip(),
                    "case_id": str(case_id or "").strip(),
                },
            )
        except Exception:
            pass
        return manifest_id

    def _emit_pi_trace_event(self, event_name, payload=None, run_id="e2e"):
        try:
            url = str(os.environ.get("DEBUG_SERVER_URL") or "").strip() or "http://127.0.0.1:7777/event"
            session_id = str(os.environ.get("DEBUG_SESSION_ID") or "").strip() or "pi-workflow-e2e-tests"
            if not url:
                return
            safe_payload = payload if isinstance(payload, dict) else {"value": payload}
            body = {
                "sessionId": session_id,
                "runId": str(run_id or "e2e"),
                "hypothesisId": "e2e",
                "event": str(event_name or "event"),
                "payload": safe_payload,
            }
            requests.post(url, json=body, timeout=2)
        except Exception:
            return

    def _read_pi_outbox_manifests(self, actor):
        paths = self._pi_brain_paths(actor)
        if not paths or not paths.get("outbox_dir"):
            return []
        outbox_dir = paths["outbox_dir"]
        if not os.path.isdir(outbox_dir):
            return []
        manifests = []
        for filename in os.listdir(outbox_dir):
            if not filename.endswith(".json"):
                continue
            file_path = os.path.join(outbox_dir, filename)
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    manifest = json.load(f)
                    if isinstance(manifest, dict) and manifest.get("status") == "pending":
                        manifests.append(manifest)
            except Exception:
                continue
        manifests.sort(key=lambda x: str(x.get("created_at") or ""))
        return manifests

    def _airtable_schema_context_file(self, actor=None):
        try:
            paths = self._pi_brain_paths(actor or {})
            user_dir = str((paths or {}).get("user_dir") or "").strip()
            if user_dir:
                return os.path.join(user_dir, "airtable_schema_context.json")
        except Exception:
            pass
        return os.path.join(self._pi_brain_root(), "airtable_schema_context_cache.json")

    def _airtable_schema_base_targets(self):
        airtable_cfg = (self.config.get("airtable", {}) or {})
        targets = []
        seen = set()
        for base_label, base_id in (
            ("main", airtable_cfg.get("base_id")),
            ("trips", airtable_cfg.get("trips_base_id")),
            ("religious", airtable_cfg.get("religious_base_id")),
        ):
            base_id = str(base_id or "").strip()
            if not base_id or base_id in seen:
                continue
            seen.add(base_id)
            targets.append({"base_label": base_label, "base_id": base_id})
        return targets

    def _fetch_airtable_schema_context_live(self, include_field_options=True, base_labels=None, target_table=None):
        airtable_cfg = (self.config.get("airtable", {}) or {})
        api_key = str(airtable_cfg.get("api_key") or "").strip()
        if not api_key:
            return {"status": "error", "message": "Missing Airtable API key.", "bases": [], "updated_at": datetime.now(timezone.utc).isoformat()}
        requested_labels = {str(item or "").strip().lower() for item in (base_labels or []) if str(item or "").strip()}
        target_table_normalized = str(target_table or "").strip().lower()
        blocked_update_types = {
            "formula", "rollup", "count", "createdTime", "lastModifiedTime", "multipleLookupValues",
            "lookup", "button", "autoNumber", "multipleRecordLinks", "createdBy", "lastModifiedBy"
        }
        out = {
            "status": "success",
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "bases": [],
            "summary": {"base_count": 0, "table_count": 0, "field_count": 0},
        }
        headers = {"Authorization": f"Bearer {api_key}"}
        for target in self._airtable_schema_base_targets():
            base_label = str(target.get("base_label") or "").strip().lower()
            if requested_labels and base_label not in requested_labels:
                continue
            base_id = str(target.get("base_id") or "").strip()
            meta_url = f"https://api.airtable.com/v0/meta/bases/{base_id}/tables"
            try:
                resp = requests.get(meta_url, headers=headers, timeout=30)
                if resp.status_code != 200:
                    out["bases"].append({
                        "base_label": base_label,
                        "base_id": base_id,
                        "status": "error",
                        "message": resp.text[:500],
                        "tables": [],
                    })
                    continue
                payload = resp.json() or {}
                base_entry = {
                    "base_label": base_label,
                    "base_id": base_id,
                    "status": "success",
                    "tables": [],
                }
                for table in (payload.get("tables") or []):
                    table_name = str(table.get("name") or "").strip()
                    if target_table_normalized and table_name.lower() != target_table_normalized:
                        continue
                    table_entry = {
                        "table_id": str(table.get("id") or "").strip(),
                        "table_name": table_name,
                        "primary_field_id": str(table.get("primaryFieldId") or "").strip(),
                        "field_count": 0,
                        "fields": [],
                    }
                    for field in (table.get("fields") or []):
                        field_type = str(field.get("type") or "").strip()
                        options = field.get("options") if isinstance(field.get("options"), dict) else {}
                        field_entry = {
                            "field_id": str(field.get("id") or "").strip(),
                            "field_name": str(field.get("name") or "").strip(),
                            "field_type": field_type,
                            "is_updatable": field_type not in blocked_update_types,
                        }
                        if include_field_options:
                            choices = [str(choice.get("name") or "").strip() for choice in (options.get("choices") or []) if str(choice.get("name") or "").strip()]
                            if choices:
                                field_entry["choices"] = choices[:50]
                        linked_table_id = str(options.get("linkedTableId") or "").strip()
                        if linked_table_id:
                            field_entry["linked_table_id"] = linked_table_id
                        table_entry["fields"].append(field_entry)
                    table_entry["field_count"] = len(table_entry["fields"])
                    base_entry["tables"].append(table_entry)
                out["bases"].append(base_entry)
            except Exception as exc:
                out["bases"].append({
                    "base_label": base_label,
                    "base_id": base_id,
                    "status": "error",
                    "message": str(exc)[:500],
                    "tables": [],
                })
        out["summary"]["base_count"] = len(out["bases"])
        out["summary"]["table_count"] = sum(len(base.get("tables") or []) for base in out["bases"])
        out["summary"]["field_count"] = sum(len(table.get("fields") or []) for base in out["bases"] for table in (base.get("tables") or []))
        return out

    def resolve_airtable_list_view_layout(self, view_ref, base_scope="main", table_name=None):
        """
        Import field visibility + order from an Airtable grid view (by name or view id).
        Filter conditions are NOT available via Airtable Metadata API.

        base_scope: "main" | "religious" — which Base ID to use
        table_name: optional preferred table hint (defaults to List for main)

        Resolution rules:
        - By view ID (viw…): always load from the owning table (correct table).
        - By view name: if the same name exists on multiple tables, prefer List (main)
          or the religious default table; otherwise use the first match found.
        """
        import requests

        view_ref = str(view_ref or "").strip()
        if not view_ref:
            return {"status": "error", "message": "Missing view name or id"}

        airtable_cfg = (self.config.get("airtable", {}) or {})
        api_key = str(airtable_cfg.get("api_key") or "").strip()
        scope = str(base_scope or "main").strip().lower()
        if scope in ("religious", "religion"):
            base_id = str(airtable_cfg.get("religious_base_id") or "").strip()
            default_table = "استفسارات جديدة"
        else:
            scope = "main"
            base_id = str(airtable_cfg.get("base_id") or "").strip()
            default_table = str(((airtable_cfg.get("tables") or {}) or {}).get("main_list") or "List").strip() or "List"
        table_name = str(table_name or "").strip() or default_table
        if not api_key or not base_id:
            return {
                "status": "error",
                "message": (
                    "Airtable API key / religious_base_id not configured"
                    if scope == "religious"
                    else "Airtable API key / base_id not configured"
                ),
            }

        headers = {"Authorization": f"Bearer {api_key}"}
        try:
            # include=visibleFieldIds so nested table.views carry ordered visible fields (grid views).
            tables_resp = requests.get(
                f"https://api.airtable.com/v0/meta/bases/{base_id}/tables",
                headers=headers,
                params=[("include", "visibleFieldIds")],
                timeout=30,
            )
            if tables_resp.status_code != 200:
                # Retry without include for older tokens / plans.
                tables_resp = requests.get(
                    f"https://api.airtable.com/v0/meta/bases/{base_id}/tables",
                    headers=headers,
                    timeout=30,
                )
            if tables_resp.status_code != 200:
                return {
                    "status": "error",
                    "message": f"Failed to load Airtable schema ({tables_resp.status_code})",
                    "detail": (tables_resp.text or "")[:400],
                }
            tables = (tables_resp.json() or {}).get("tables") or []
        except Exception as exc:
            return {"status": "error", "message": f"Airtable schema request failed: {exc}"}

        list_table = None
        for table in tables:
            if str(table.get("name") or "").strip() == table_name:
                list_table = table
                break
        if not list_table:
            # fallback: case-insensitive
            for table in tables:
                if str(table.get("name") or "").strip().lower() == table_name.lower():
                    list_table = table
                    break
        if not list_table:
            available = [str(t.get("name") or "").strip() for t in tables if str(t.get("name") or "").strip()]
            return {
                "status": "error",
                "message": f"Table '{table_name}' not found in Airtable base",
                "available_tables_sample": available[:20],
            }

        tables_by_id = {}
        for table in tables:
            tid = str(table.get("id") or "").strip()
            if tid:
                tables_by_id[tid] = table

        def _field_map_for_table(table_obj):
            mapping = {}
            for field in ((table_obj or {}).get("fields") or []):
                fid = str(field.get("id") or "").strip()
                fname = str(field.get("name") or "").strip()
                if fid and fname:
                    mapping[fid] = fname
            return mapping

        list_table_id = str(list_table.get("id") or "").strip()

        # Primary candidates: views nested under tables (often include ordered visibleFieldIds).
        candidates = []
        nested_by_id = {}
        for table in tables:
            tid = str(table.get("id") or "").strip()
            for view in (table.get("views") or []):
                if not isinstance(view, dict):
                    continue
                stamped = dict(view)
                if tid and not stamped.get("tableId"):
                    stamped["tableId"] = tid
                candidates.append(stamped)
                vid = str(stamped.get("id") or "").strip()
                if vid:
                    nested_by_id[vid] = stamped

        views_resp = None
        try:
            # Also query dedicated views endpoint (Enterprise) and merge richer payloads.
            views_resp = requests.get(
                f"https://api.airtable.com/v0/meta/bases/{base_id}/views",
                headers=headers,
                params=[("include", "visibleFieldIds")],
                timeout=30,
            )
        except Exception:
            views_resp = None

        if views_resp is not None and views_resp.status_code == 200:
            for view in ((views_resp.json() or {}).get("views") or []):
                if not isinstance(view, dict):
                    continue
                vid = str(view.get("id") or "").strip()
                existing = nested_by_id.get(vid)
                if existing:
                    # Prefer whichever payload has visibleFieldIds; keep tableId from nested.
                    merged = {**existing, **view}
                    if existing.get("tableId") and not merged.get("tableId"):
                        merged["tableId"] = existing.get("tableId")
                    if not isinstance(merged.get("visibleFieldIds"), list) and isinstance(existing.get("visibleFieldIds"), list):
                        merged["visibleFieldIds"] = existing.get("visibleFieldIds")
                    # Replace candidate entry
                    for i, c in enumerate(candidates):
                        if str(c.get("id") or "").strip() == vid:
                            candidates[i] = merged
                            break
                    nested_by_id[vid] = merged
                else:
                    candidates.append(view)
                    if vid:
                        nested_by_id[vid] = view

        # Prefer matches on the requested table first (do not silently pick another table).
        def _view_table_id(view_obj):
            return str((view_obj or {}).get("tableId") or (view_obj or {}).get("table_id") or "").strip()

        # Canonical "List" (main) / default religious table — preferred when resolving by NAME.
        priority_table_name = default_table
        if scope == "main":
            priority_table_name = "List"
        priority_table = None
        for table in tables:
            if str(table.get("name") or "").strip() == priority_table_name:
                priority_table = table
                break
        if not priority_table:
            for table in tables:
                if str(table.get("name") or "").strip().lower() == priority_table_name.lower():
                    priority_table = table
                    break
        priority_table_id = str((priority_table or {}).get("id") or "").strip()

        list_candidates = [v for v in candidates if (not list_table_id) or _view_table_id(v) in ("", list_table_id)]
        priority_candidates = [
            v for v in candidates
            if priority_table_id and _view_table_id(v) == priority_table_id
        ]
        other_candidates = [v for v in candidates if v not in list_candidates]

        ref_l = view_ref.lower()
        is_view_id = view_ref.startswith("viw")
        matched = None

        if is_view_id:
            # ID → always resolve to the owning table (ignore selected-table collisions).
            for view in candidates:
                if str(view.get("id") or "").strip() == view_ref:
                    matched = view
                    break
            if not matched:
                try:
                    one = requests.get(
                        f"https://api.airtable.com/v0/meta/bases/{base_id}/views/{view_ref}",
                        headers=headers,
                        params=[("include", "visibleFieldIds")],
                        timeout=30,
                    )
                    if one.status_code == 200 and isinstance(one.json(), dict):
                        matched = one.json()
                        nested = nested_by_id.get(str(matched.get("id") or view_ref).strip())
                        if nested:
                            matched = {**nested, **matched}
                            if not isinstance(matched.get("visibleFieldIds"), list) and isinstance(nested.get("visibleFieldIds"), list):
                                matched["visibleFieldIds"] = nested.get("visibleFieldIds")
                    elif one.status_code != 200:
                        matched = nested_by_id.get(view_ref)
                        if matched is None:
                            return {
                                "status": "error",
                                "message": f"Airtable view lookup failed ({one.status_code})",
                                "detail": (one.text or "")[:400],
                            }
                except Exception as exc:
                    matched = nested_by_id.get(view_ref)
                    if matched is None:
                        return {"status": "error", "message": f"Airtable view lookup failed: {exc}"}
        else:
            # NAME → if the same name exists on multiple tables, prefer List (main) / default table.
            def _name_matches(view_obj):
                vname = str((view_obj or {}).get("name") or "").strip()
                return vname == view_ref or vname.lower() == ref_l

            for view in priority_candidates:
                if _name_matches(view):
                    matched = view
                    break
            if not matched:
                for view in list_candidates:
                    if _name_matches(view):
                        matched = view
                        break
            if not matched:
                for view in other_candidates:
                    if _name_matches(view):
                        matched = view
                        break

        if not matched:
            sample_src = priority_candidates or list_candidates
            sample = [str(v.get("name") or "").strip() for v in sample_src[:12] if str(v.get("name") or "").strip()]
            return {
                "status": "error",
                "message": (
                    f"View not found: {view_ref}"
                    if is_view_id
                    else f"View not found (searched '{priority_table_name}' first): {view_ref}"
                ),
                "available_views_sample": sample,
            }

        # Resolve owning table from the matched view.
        # - By ID: always retarget to the correct owning table.
        # - By name: List (main) / default table wins when the same name exists elsewhere.
        matched_table_id = _view_table_id(matched) or list_table_id or priority_table_id

        visible_ids = matched.get("visibleFieldIds")
        if not isinstance(visible_ids, list) or not visible_ids:
            # Some tokens/scopes omit visibleFieldIds — try one more fetch by id.
            vid = str(matched.get("id") or "").strip()
            if vid:
                nested = nested_by_id.get(vid)
                if nested and isinstance(nested.get("visibleFieldIds"), list) and nested.get("visibleFieldIds"):
                    visible_ids = nested.get("visibleFieldIds")
                    matched = {**matched, **nested}
                else:
                    try:
                        one = requests.get(
                            f"https://api.airtable.com/v0/meta/bases/{base_id}/views/{vid}",
                            headers=headers,
                            params=[("include", "visibleFieldIds")],
                            timeout=30,
                        )
                        if one.status_code == 200:
                            payload = one.json() or {}
                            if isinstance(payload.get("visibleFieldIds"), list):
                                visible_ids = payload.get("visibleFieldIds")
                                matched = {**matched, **payload}
                    except Exception:
                        pass

        matched_table_id = _view_table_id(matched) or list_table_id or priority_table_id
        matched_table = tables_by_id.get(matched_table_id) or list_table or priority_table or {}
        field_id_to_name = _field_map_for_table(matched_table)
        # Soft fallback: if field id not on matched table, search all tables (rare cross-map).
        if len(field_id_to_name) < 5:
            for table in tables:
                field_id_to_name.update(_field_map_for_table(table))
        resolved_table_name = str(matched_table.get("name") or table_name).strip() or table_name

        if not isinstance(visible_ids, list) or not visible_ids:
            # Fallback: import all fields from the view's table (order = schema order).
            # Non-grid views / limited tokens often omit visibleFieldIds.
            visible_fields = [
                str(f.get("name") or "").strip()
                for f in (matched_table.get("fields") or [])
                if str(f.get("name") or "").strip()
            ]
            if not visible_fields:
                return {
                    "status": "error",
                    "message": (
                        "Airtable did not return visible fields for this view. "
                        "Ensure the API token has workspacesAndBases:read and the view is a Grid view."
                    ),
                    "view": {
                        "id": str(matched.get("id") or ""),
                        "name": str(matched.get("name") or ""),
                        "type": str(matched.get("type") or ""),
                        "table": resolved_table_name,
                    },
                }
            return {
                "status": "success",
                "data": {
                    "airtableViewId": str(matched.get("id") or ""),
                    "airtableViewName": str(matched.get("name") or view_ref),
                    "viewType": str(matched.get("type") or ""),
                    "baseScope": scope,
                    "tableName": resolved_table_name,
                    "visibleFields": visible_fields,
                    "columnOrder": list(visible_fields),
                    "unknownFieldIds": [],
                    "filters": [],
                    "sorts": [],
                    "linkAirtableView": True,
                    "note": (
                        "visibleFieldIds unavailable; imported all table fields. "
                        "Airtable filter/sort still apply via linked view name."
                    ),
                },
            }

        visible_fields = []
        unknown_ids = []
        for fid in visible_ids:
            fid_s = str(fid or "").strip()
            if not fid_s:
                continue
            name = field_id_to_name.get(fid_s)
            if not name:
                # Search other tables if List map missed the id.
                for table in tables:
                    name = _field_map_for_table(table).get(fid_s)
                    if name:
                        break
            if name:
                if name not in visible_fields:
                    visible_fields.append(name)
            else:
                unknown_ids.append(fid_s)

        if not visible_fields:
            return {
                "status": "error",
                "message": (
                    f"No mappable visible fields found for this view on table '{resolved_table_name}'."
                ),
                "view": {
                    "id": str(matched.get("id") or ""),
                    "name": str(matched.get("name") or ""),
                    "type": str(matched.get("type") or ""),
                    "table": resolved_table_name,
                },
            }

        return {
            "status": "success",
            "data": {
                "airtableViewId": str(matched.get("id") or ""),
                "airtableViewName": str(matched.get("name") or view_ref),
                "viewType": str(matched.get("type") or ""),
                "baseScope": scope,
                "tableName": resolved_table_name,
                "visibleFields": visible_fields,
                "columnOrder": list(visible_fields),
                "unknownFieldIds": unknown_ids[:40],
                # Official Metadata API does not expose filter/sort AST.
                # Linking baseView keeps Airtable filter+sort applied on fetch;
                # app filters remain empty so the user can rebuild editable copies.
                "filters": [],
                "sorts": [],
                "linkAirtableView": True,
                "note": (
                    "Airtable does not expose filter/sort rules via API. "
                    "This import links the Airtable view (so records arrive filtered/sorted like Airtable) "
                    "and copies visible fields/order. Rebuild filters once in-app if you need to edit them."
                ),
            },
        }

    def _get_airtable_schema_context(self, actor=None, refresh=False, max_age_seconds=3600):
        cache_file = self._airtable_schema_context_file(actor=actor)
        cached_payload = self._pi_brain_read_json(cache_file, {})
        if isinstance(cached_payload, dict) and cached_payload and not refresh:
            updated_at = str(cached_payload.get("updated_at") or "").strip()
            if updated_at:
                try:
                    updated_dt = datetime.fromisoformat(updated_at.replace("Z", "+00:00"))
                    age_seconds = (datetime.now(timezone.utc) - updated_dt).total_seconds()
                    if age_seconds <= max(int(max_age_seconds or 0), 60):
                        return cached_payload
                except Exception:
                    pass
        live_payload = self._fetch_airtable_schema_context_live()
        if isinstance(live_payload, dict) and live_payload:
            self._pi_brain_write_json(cache_file, live_payload)
            return live_payload
        return cached_payload if isinstance(cached_payload, dict) else {}

    def _format_airtable_schema_context_summary(self, actor=None, target_table=None, max_tables=8, max_fields_per_table=8):
        schema_context = self._get_airtable_schema_context(actor=actor, refresh=False)
        if not isinstance(schema_context, dict) or not (schema_context.get("bases") or []):
            return "No Airtable schema snapshot is currently available."
        target_table_normalized = str(target_table or "").strip().lower()
        lines = []
        summary = schema_context.get("summary") if isinstance(schema_context.get("summary"), dict) else {}
        lines.append(
            f"Schema snapshot updated at: {str(schema_context.get('updated_at') or '').strip() or 'unknown'} | "
            f"Bases: {int(summary.get('base_count') or 0)} | "
            f"Tables: {int(summary.get('table_count') or 0)} | "
            f"Fields: {int(summary.get('field_count') or 0)}"
        )
        emitted_tables = 0
        table_limit = max(int(max_tables or 0), 1)
        field_limit = max(int(max_fields_per_table or 0), 1)
        for base in (schema_context.get("bases") or []):
            base_tables = []
            for table in (base.get("tables") or []):
                table_name = str(table.get("table_name") or "").strip()
                if target_table_normalized and table_name.lower() != target_table_normalized:
                    continue
                base_tables.append(table)
            if not base_tables:
                continue
            lines.append(f"Base: {str(base.get('base_label') or '').strip()} ({str(base.get('base_id') or '').strip()})")
            for table in base_tables:
                if emitted_tables >= table_limit:
                    break
                emitted_tables += 1
                lines.append(f"- Table: {str(table.get('table_name') or '').strip()} | Fields: {int(table.get('field_count') or 0)}")
                for field in (table.get("fields") or [])[:field_limit]:
                    field_line = f"  * {str(field.get('field_name') or '').strip()} [{str(field.get('field_type') or '').strip()}]"
                    choices = [str(x).strip() for x in (field.get("choices") or []) if str(x).strip()]
                    if choices:
                        field_line += f" options: {', '.join(choices[:5])}"
                    if field.get("linked_table_id"):
                        field_line += f" linked_to: {str(field.get('linked_table_id') or '').strip()}"
                    lines.append(field_line)
                remaining_fields = len(table.get("fields") or []) - field_limit
                if remaining_fields > 0:
                    lines.append(f"  * ... {remaining_fields} more field(s)")
            if emitted_tables >= table_limit:
                break
        return "\n".join(lines).strip()

    def _write_pi_result_to_inbox(self, actor, manifest_id, result_payload, case_id=None):
        paths = self._ensure_pi_brain_workspace(actor, case_id=case_id)
        if not paths or not paths.get("inbox_dir") or not paths.get("outbox_dir"):
            return False
        result_payload["manifest_id"] = manifest_id
        result_payload["processed_at"] = datetime.now(timezone.utc).isoformat()
        inbox_file = os.path.join(paths["inbox_dir"], f"{manifest_id}_result.json")
        self._pi_brain_write_json(inbox_file, result_payload)
        
        # Mark outbox manifest as processed
        outbox_file = os.path.join(paths["outbox_dir"], f"{manifest_id}.json")
        manifest = {}
        if os.path.isfile(outbox_file):
            try:
                with open(outbox_file, "r", encoding="utf-8") as f:
                    manifest = json.load(f)
                manifest["status"] = "processed"
                manifest["processed_at"] = result_payload["processed_at"]
                self._pi_brain_write_json(outbox_file, manifest)
            except Exception:
                pass
        # #region debug-point internal-latency.manifest-inbox-write
        try:
            import json as _dbg_json, urllib.request as _dbg_urllib_request, time as _dbg_time
            created_at = str((manifest or {}).get('created_at') or '').strip() if isinstance(manifest, dict) else ''
            elapsed_ms = None
            if created_at:
                try:
                    created_dt = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                    processed_dt = datetime.fromisoformat(str(result_payload.get("processed_at") or "").replace("Z", "+00:00"))
                    elapsed_ms = int((processed_dt - created_dt).total_seconds() * 1000)
                except Exception:
                    elapsed_ms = None
            _dbg_urllib_request.urlopen(
                _dbg_urllib_request.Request(
                    'http://127.0.0.1:7778/event',
                    data=_dbg_json.dumps({
                        'sessionId': 'internal-latency',
                        'runId': 'pre',
                        'hypothesisId': 'H4',
                        'location': 'ai_agent.py:_write_pi_result_to_inbox',
                        'msg': '[DEBUG] manifest result written to inbox',
                        'data': {
                            'manifest_id': str(manifest_id or ''),
                            'status': str(result_payload.get('status') or ''),
                            'created_at': created_at,
                            'processed_at': str(result_payload.get('processed_at') or ''),
                            'elapsed_ms': elapsed_ms,
                            'case_id': str(case_id or ''),
                        },
                        'ts': int(_dbg_time.time() * 1000)
                    }).encode(),
                    headers={'Content-Type': 'application/json'}
                ),
                timeout=2
            ).read()
        except Exception:
            pass
        # #endregion
        try:
            actor_phone = re.sub(r"\D", "", str((actor or {}).get("phone") or ""))
            status_label = str(result_payload.get("status") or "").strip().lower() or "unknown"
            result_text = str(
                result_payload.get("internal_reply")
                or result_payload.get("result_preview")
                or result_payload.get("message")
                or result_payload.get("error")
                or ""
            ).strip()
            if actor_phone:
                if status_label == "success":
                    notification_text = (
                        f"اكتمل تنفيذ الطلب.\nExecution ID: {manifest_id}\n"
                        f"{result_text or 'تم تنفيذ الطلب بنجاح.'}"
                    ).strip()
                elif status_label == "error":
                    notification_text = (
                        f"فشل تنفيذ الطلب.\nExecution ID: {manifest_id}\n"
                        f"{result_text or 'حدث خطأ أثناء التنفيذ.'}"
                    ).strip()
                else:
                    notification_text = (
                        f"تحديث على الطلب.\nExecution ID: {manifest_id}\n"
                        f"{result_text or f'Status: {status_label}'}"
                    ).strip()
                send_ok = self.send_internal_notifications_whatsapp_text(actor_phone, notification_text)
                self._emit_pi_trace_event(
                    "manifest.result.notify_internal",
                    {
                        "manifest_id": str(manifest_id or ""),
                        "actor_phone": actor_phone,
                        "status": status_label,
                        "send_ok": bool(send_ok),
                        "text_preview": notification_text[:300],
                    },
                )
        except Exception:
            pass
        return True

    def _process_pi_background_tasks(self):
        """Background worker loop to process pending PI manifests."""
        try:
            internal_users = [u for u in (self.config.get("internalAssistant", {}).get("adminUsers", []) or [])]
            for actor in internal_users:
                manifests = self._read_pi_outbox_manifests(actor)
                for manifest in manifests:
                    manifest_id = manifest.get("manifest_id")
                    intent = manifest.get("intent")
                    actions = manifest.get("actions", [])
                    
                    if not actions:
                        self._write_pi_result_to_inbox(actor, manifest_id, {"status": "error", "error": "No actions in manifest"})
                        continue
                        
                    # Here we would evaluate the manifest actions and decide to execute or request approval
                    # For now, we simulate processing by sending a WhatsApp message asking for approval
                    actor_phone = str(actor.get("phone") or "")
                    if actor_phone:
                        message_body = f"PI Brain Request ({manifest_id}):\nIntent: {intent}\n"
                        for action in actions:
                            message_body += f"- Action: {action.get('type')}\n"
                        message_body += "\nReply with 'approve' to execute."
                        
                        # In a real implementation, we would store this as a pending_action
                        # and send a message. For this scaffold, we just mark it processed.
                        
                    self._write_pi_result_to_inbox(actor, manifest_id, {"status": "success", "message": "Manifest processed and approval requested."})
        except Exception as e:
            pass # Silent fail for background thread

    def _sync_pi_brain_stage(self, actor, case_id, stage_name, payload, intent_name=None, case_context=None, session_state=None, stage_status=None, status=None, next_stage=None):
        actor = actor or {}
        payload = payload if isinstance(payload, dict) else {"value": payload}
        case_context = case_context if isinstance(case_context, dict) else {}
        paths = self._ensure_pi_brain_workspace(actor, case_id=case_id)
        if not paths:
            return {}
        case_dir = paths.get("case_dir")
        if not case_dir:
            return paths
        self._pi_brain_write_json(
            paths.get("current_context_file"),
            self._build_pi_brain_current_context_payload(
                actor,
                session_state=session_state,
                case_id=case_id,
                intent_name=intent_name,
                case_context=case_context,
            ),
        )
        self._pi_brain_write_json(os.path.join(case_dir, "request.json"), {
            "schema_version": "1.0",
            "case_id": str(case_id or "").strip(),
            "intent": str(intent_name or "").strip(),
            "request_source": "internal_whatsapp_assistant",
            "captured_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(os.path.join(case_dir, "context_snapshot.json"), {
            "schema_version": "1.0",
            "case_id": str(case_id or "").strip(),
            "case_context": self._pi_brain_safe_json(case_context),
            "session_state": self._pi_brain_safe_json(session_state if isinstance(session_state, dict) else {}),
            "captured_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(os.path.join(case_dir, f"{stage_name}.json"), payload)
        case_status = self._pi_brain_read_json(paths.get("case_status_file"), {})
        case_status.update({
            "schema_version": "1.0",
            "case_id": str(case_id or "").strip(),
            "intent": str(intent_name or "").strip(),
            "current_stage": str(stage_name or "").strip(),
            "stage_status": str(stage_status or "").strip(),
            "status": str(status or case_status.get("status") or "active").strip(),
            "next_stage": str(next_stage or "").strip(),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(paths.get("case_status_file"), case_status)
        manifest = self._build_pi_brain_action_manifest_payload(
            actor,
            case_id,
            stage_name,
            payload,
            intent_name=intent_name,
            case_context=case_context,
            session_state=session_state,
        )
        if manifest.get("actions"):
            self._pi_brain_write_json(os.path.join(case_dir, "proposed_actions.json"), manifest)
            # Write to outbox so the Background Task Engine can pick it up
            self._write_pi_manifest_to_outbox(actor, manifest, case_id=case_id)
            self._pi_brain_write_json(os.path.join(paths.get("user_dir"), "action_manifest.json"), manifest)
        if stage_name == "memory":
            self._update_pi_brain_memory_files(
                actor,
                case_id,
                payload,
                intent_name=intent_name,
                case_context=case_context,
                paths=paths,
            )
        self._refresh_pi_brain_roadmap_status(paths, case_id=case_id)
        return paths

    def _refresh_pi_brain_roadmap_status(self, paths, case_id=None):
        paths = paths if isinstance(paths, dict) else {}
        roadmap_file = paths.get("roadmap_file")
        if not roadmap_file:
            return False
        roadmap = self._pi_brain_read_json(roadmap_file, {})
        phases = roadmap.get("phases") if isinstance(roadmap.get("phases"), list) else []
        user_dir = paths.get("user_dir") or ""
        memory_dir = paths.get("memory_dir") or ""
        case_dir = paths.get("case_dir") or (os.path.join(paths.get("cases_dir") or "", str(case_id or "").strip()) if case_id else "")
        has_workspace = bool(user_dir and os.path.exists(os.path.join(user_dir, "workspace.json")))
        has_memory_model = bool(user_dir and os.path.exists(os.path.join(user_dir, "behavior_model.json")) and os.path.exists(os.path.join(user_dir, "goals.json")))
        has_manifest = bool(user_dir and os.path.exists(os.path.join(user_dir, "action_manifest.json")))
        has_assistant_result = bool(case_dir and os.path.exists(os.path.join(case_dir, "result.json")) and os.path.exists(os.path.join(case_dir, "verification.json")))
        for item in phases:
            if not isinstance(item, dict):
                continue
            phase_num = int(item.get("phase") or 0)
            if phase_num == 1:
                item["status"] = "completed" if has_workspace else "active"
            elif phase_num == 2:
                item["status"] = "completed" if has_memory_model and os.path.exists(os.path.join(memory_dir, "episodic_memory.jsonl")) else "planned"
            elif phase_num == 3:
                item["status"] = "completed" if has_manifest else "planned"
            elif phase_num == 4:
                item["status"] = "active" if has_assistant_result else "planned"
        roadmap["updated_at"] = datetime.now(timezone.utc).isoformat()
        return self._pi_brain_write_json(roadmap_file, roadmap)

    def _update_pi_brain_memory_files(self, actor, case_id, memory_payload, intent_name=None, case_context=None, paths=None):
        actor = actor or {}
        memory_payload = memory_payload if isinstance(memory_payload, dict) else {}
        case_context = case_context if isinstance(case_context, dict) else {}
        paths = paths if isinstance(paths, dict) and paths else self._ensure_pi_brain_workspace(actor, case_id=case_id)
        if not paths:
            return False
        case_dir = paths.get("case_dir") or ""
        memory_dir = paths.get("memory_dir") or ""
        if not memory_payload.get("memory_eligible"):
            self._pi_brain_write_json(os.path.join(case_dir, "verification.json"), {
                "schema_version": "1.0",
                "case_id": str(case_id or "").strip(),
                "status": "skipped",
                "reason": "memory_not_eligible",
                "checked_at": datetime.now(timezone.utc).isoformat(),
            })
            return False
        episodic_record = {
            "case_id": str(case_id or "").strip(),
            "intent": str(intent_name or memory_payload.get("resolved_action") or "").strip(),
            "pattern": str(memory_payload.get("pattern") or "").strip(),
            "outcome": str(memory_payload.get("execution_outcome") or "").strip(),
            "pi_used": bool(memory_payload.get("pi_used")),
            "lesson": str(memory_payload.get("lesson_learned") or "").strip(),
            "case_reference": str(
                case_context.get("booking_number")
                or case_context.get("record_id")
                or case_context.get("email")
                or case_context.get("phone")
                or ""
            ).strip(),
            "ts": datetime.now(timezone.utc).isoformat(),
        }
        decision_record = {
            "case_id": str(case_id or "").strip(),
            "intent": str(intent_name or memory_payload.get("resolved_action") or "").strip(),
            "root_cause": [str(x).strip() for x in (memory_payload.get("root_cause") or []) if str(x).strip()][:10],
            "outcome": str(memory_payload.get("execution_outcome") or "").strip(),
            "recommended_next_step": str(((memory_payload.get("pi_summary") or {}).get("recommended_next_step") or "")).strip(),
            "approval_required": bool(((memory_payload.get("pi_summary") or {}).get("approval_required"))),
            "ts": datetime.now(timezone.utc).isoformat(),
        }
        self._pi_brain_append_jsonl(os.path.join(memory_dir, "episodic_memory.jsonl"), episodic_record)
        self._pi_brain_append_jsonl(os.path.join(memory_dir, "decisions.jsonl"), decision_record)

        patterns_file = os.path.join(memory_dir, "patterns.json")
        patterns_payload = self._pi_brain_read_json(patterns_file, {"schema_version": "1.0", "patterns": []})
        patterns_list = patterns_payload.get("patterns") if isinstance(patterns_payload.get("patterns"), list) else []
        pattern_name = str(memory_payload.get("pattern") or "general_contextual_case").strip()
        matched = False
        for item in patterns_list:
            if not isinstance(item, dict):
                continue
            if str(item.get("name") or "").strip() == pattern_name:
                item["count"] = int(item.get("count") or 0) + 1
                item["last_case_id"] = str(case_id or "").strip()
                item["last_outcome"] = str(memory_payload.get("execution_outcome") or "").strip()
                matched = True
                break
        if not matched:
            patterns_list.append({
                "name": pattern_name,
                "count": 1,
                "last_case_id": str(case_id or "").strip(),
                "last_outcome": str(memory_payload.get("execution_outcome") or "").strip(),
            })
        patterns_payload["patterns"] = patterns_list[-50:]
        patterns_payload["updated_at"] = datetime.now(timezone.utc).isoformat()
        self._pi_brain_write_json(patterns_file, patterns_payload)

        root_causes = [str(x).strip() for x in (memory_payload.get("root_cause") or []) if str(x).strip()]
        if len(root_causes) >= 2 or "ambiguous_lookup_case" == pattern_name:
            rare_file = os.path.join(memory_dir, "rare_cases.json")
            rare_payload = self._pi_brain_read_json(rare_file, {"schema_version": "1.0", "cases": []})
            cases = rare_payload.get("cases") if isinstance(rare_payload.get("cases"), list) else []
            cases.append({
                "case_id": str(case_id or "").strip(),
                "pattern": pattern_name,
                "root_cause": root_causes[:10],
                "lesson_learned": str(memory_payload.get("lesson_learned") or "").strip(),
                "captured_at": datetime.now(timezone.utc).isoformat(),
            })
            rare_payload["cases"] = cases[-30:]
            rare_payload["updated_at"] = datetime.now(timezone.utc).isoformat()
            self._pi_brain_write_json(rare_file, rare_payload)

        goals_file = os.path.join(paths.get("user_dir") or "", "goals.json")
        goals_payload = self._pi_brain_read_json(goals_file, {})
        active_goals = goals_payload.get("active_goals") if isinstance(goals_payload.get("active_goals"), list) else []
        for item in active_goals:
            if not isinstance(item, dict):
                continue
            item["last_case_id"] = str(case_id or "").strip()
            item["last_outcome"] = str(memory_payload.get("execution_outcome") or "").strip()
            item["updated_at"] = datetime.now(timezone.utc).isoformat()
        goals_payload["active_goals"] = active_goals
        goals_payload["updated_at"] = datetime.now(timezone.utc).isoformat()
        self._pi_brain_write_json(goals_file, goals_payload)

        self._pi_brain_write_json(os.path.join(case_dir, "result.json"), {
            "schema_version": "1.0",
            "case_id": str(case_id or "").strip(),
            "intent": str(intent_name or "").strip(),
            "execution_outcome": str(memory_payload.get("execution_outcome") or "").strip(),
            "resolved_action": str(memory_payload.get("resolved_action") or "").strip(),
            "lesson_learned": str(memory_payload.get("lesson_learned") or "").strip(),
            "pi_summary": self._pi_brain_safe_json(memory_payload.get("pi_summary") or {}),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(os.path.join(case_dir, "verification.json"), {
            "schema_version": "1.0",
            "case_id": str(case_id or "").strip(),
            "status": "recorded",
            "memory_eligible": True,
            "checks": [
                "episodic_memory_appended",
                "decisions_memory_appended",
                "patterns_updated",
                "goals_updated",
            ],
            "checked_at": datetime.now(timezone.utc).isoformat(),
        })
        return True

    def _ensure_pi_brain_workspace(self, actor, case_id=None):
        actor = actor or {}
        paths = self._pi_brain_paths(actor, case_id=case_id)
        if not paths:
            return {}
        for dir_key in ("user_dir", "memory_dir", "active_dir", "cases_dir", "bridge_dir", "inbox_dir", "outbox_dir", "management_dir", "watchers_dir", "scheduled_tasks_dir", "projects_dir"):
            dir_path = paths.get(dir_key)
            if dir_path:
                os.makedirs(dir_path, exist_ok=True)
        if paths.get("case_dir"):
            os.makedirs(paths["case_dir"], exist_ok=True)
        self._pi_brain_write_json(paths.get("workspace_file"), self._build_pi_brain_workspace_payload(actor))
        self._pi_brain_write_json(paths.get("profile_file"), self._build_pi_brain_profile_payload(actor))
        self._pi_brain_write_json(paths.get("permissions_file"), self._build_pi_brain_permissions_payload(actor))
        self._pi_brain_write_json(paths.get("roadmap_file"), self._build_pi_brain_roadmap_payload())
        self._pi_brain_write_json(os.path.join(paths.get("user_dir"), "capability_registry.json"), self._build_pi_capability_registry_payload())
        self._pi_brain_write_json(os.path.join(paths.get("user_dir"), "behavior_model.json"), self._build_pi_brain_behavior_model_payload(actor))
        self._pi_brain_write_json(os.path.join(paths.get("user_dir"), "goals.json"), self._build_pi_brain_goals_payload(actor))
        self._pi_brain_write_json(os.path.join(paths.get("memory_dir"), "memory_catalog.json"), self._build_pi_brain_memory_catalog_payload())
        self._pi_brain_write_json(os.path.join(paths.get("memory_dir"), "semantic_memory.json"), {
            "schema_version": "1.0",
            "facts": [],
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(os.path.join(paths.get("memory_dir"), "patterns.json"), {
            "schema_version": "1.0",
            "patterns": [],
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(os.path.join(paths.get("memory_dir"), "rare_cases.json"), {
            "schema_version": "1.0",
            "cases": [],
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_ensure_jsonl(os.path.join(paths.get("memory_dir"), "episodic_memory.jsonl"))
        self._pi_brain_ensure_jsonl(os.path.join(paths.get("memory_dir"), "decisions.jsonl"))
        self._pi_brain_write_json(paths.get("current_context_file"), {
            "schema_version": "1.0",
            "status": "initialized",
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(os.path.join(paths.get("active_dir"), "open_goals.json"), {
            "schema_version": "1.0",
            "goal_ids": [item.get("goal_id") for item in self._build_pi_brain_goals_payload(actor).get("active_goals", []) if isinstance(item, dict)],
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        self._pi_brain_write_json(os.path.join(paths.get("active_dir"), "active_watchers.json"), {
            "schema_version": "1.0",
            "watchers": [],
            "updated_at": datetime.now(timezone.utc).isoformat(),
        })
        if paths.get("case_status_file"):
            self._pi_brain_write_json(paths.get("case_status_file"), {
                "schema_version": "1.0",
                "case_id": str(case_id or "").strip(),
                "status": "initialized",
                "updated_at": datetime.now(timezone.utc).isoformat(),
            })
        return paths

    def _get_or_create_internal_workspace(self, actor):
        actor = actor or {}
        actor_key = self._internal_workspace_actor_key(actor)
        if not actor_key:
            return None
        index_key = "internal_workspace_index"
        ws_key = f"internal_workspace:{actor_key}"
        index = self._load_json_setting_value(index_key, []) or []
        if not isinstance(index, list):
            index = []
        existing = self._load_json_setting_value(ws_key, None)
        if not isinstance(existing, dict):
            existing = {}
        if not existing.get("workspace_id"):
            existing = {
                "workspace_id": secrets.token_hex(8),
                "actor_key": actor_key,
                "created_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                "updated_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                "actor": {
                    "name": str(actor.get("name") or "").strip(),
                    "role": str(actor.get("role") or "").strip(),
                    "phone": re.sub(r"\D", "", str(actor.get("phone") or "")),
                    "username": str(actor.get("username") or "").strip(),
                    "allowed_locations": list(actor.get("allowed_locations") or []),
                },
                "preferences": {},
                "watchers": [],
            }
            if actor_key not in index:
                index.append(actor_key)
                self._save_json_setting_value(index_key, index)
            self._save_json_setting_value(ws_key, existing)
        else:
            existing["updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            if isinstance(existing.get("actor"), dict):
                existing["actor"]["role"] = str(actor.get("role") or existing["actor"].get("role") or "").strip()
                existing["actor"]["allowed_locations"] = list(actor.get("allowed_locations") or existing["actor"].get("allowed_locations") or [])
            self._save_json_setting_value(ws_key, existing)
            if actor_key not in index:
                index.append(actor_key)
                self._save_json_setting_value(index_key, index)
        return existing

    def _actor_allows_base_label(self, actor, base_label):
        actor = actor or {}
        base_label = str(base_label or "").strip().lower() or "general"
        allowed = [str(x).strip() for x in (actor.get("allowed_locations") or []) if str(x).strip()]
        if "All" in allowed or "all" in [x.lower() for x in allowed]:
            return True
        if base_label == "religious":
            return any(str(x).strip().lower() == "religious" for x in allowed)
        return any(str(x).strip().lower() != "religious" for x in allowed)

    def create_trip_booking_alert_watcher(self, actor, trip_contains="", trip_names=None, date_mode="today", target_dates=None, match_mode="contains", base_label="general", table_name="", interval_sec=300, max_per_poll=10):
        actor = actor or {}
        trip_contains = str(trip_contains or "").strip()
        trip_names = [str(x).strip() for x in (trip_names or []) if str(x).strip()]
        date_mode = str(date_mode or "today").strip().lower() or "today"
        target_dates = [str(x).strip() for x in (target_dates or []) if str(x).strip()]
        match_mode = str(match_mode or "contains").strip().lower() or "contains"
        base_label = str(base_label or "general").strip().lower() or "general"
        table_name = str(table_name or "").strip()
        interval_sec = int(interval_sec or 300)
        max_per_poll = int(max_per_poll or 10)
        if not trip_contains and not trip_names:
            return None, "missing_trip"
        if not self._actor_allows_base_label(actor, base_label):
            return None, "unauthorized_base"
        if base_label == "religious" and not table_name:
            return None, "missing_religious_table"
        ws = self._get_or_create_internal_workspace(actor)
        if not isinstance(ws, dict):
            return None, "workspace_missing"
        watcher = {
            "id": secrets.token_hex(6),
            "type": "trip_booking_alert",
            "enabled": True,
            "base_label": base_label,
            "table_name": table_name,
            "trip_contains": trip_contains,
            "trip_names": trip_names,
            "date_mode": date_mode,
            "target_dates": target_dates,
            "match_mode": match_mode,
            "interval_sec": max(60, interval_sec),
            "max_per_poll": max(1, min(25, max_per_poll)),
            "start_created_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            "last_run_at": "",
            "notified_record_ids": [],
            "notify_phone": re.sub(r"\D", "", str(actor.get("phone") or "")),
            "created_by": self._internal_workspace_actor_key(actor),
            "created_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        }
        watchers = ws.get("watchers") or []
        if not isinstance(watchers, list):
            watchers = []
        watchers.append(watcher)
        ws["watchers"] = watchers[-50:]
        ws["updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        ws_key = f"internal_workspace:{str(ws.get('actor_key') or '').strip()}"
        self._save_json_setting_value(ws_key, ws)
        return watcher, ""

    def _list_mpc_trip_name_correction_options(self, limit=120):
        if not getattr(self, "mpc_table", None):
            return []
        try:
            try:
                records = self.mpc_table.all(max_records=max(50, int(limit or 120) * 3))
            except TypeError:
                records = self.mpc_table.all()
        except Exception as e:
            logging.warning(f"Failed to load MPC trip options from Trip name correction: {e}")
            return []
        seen = set()
        options = []
        for rec in (records or []):
            fields = rec.get("fields", {}) if isinstance(rec, dict) else {}
            corrected = str(fields.get("Trip name correction") or "").strip()
            if not corrected:
                continue
            key = self._normalize_internal_watcher_text(corrected)
            if not key or key in seen:
                continue
            seen.add(key)
            options.append(corrected)
        options.sort(key=lambda item: self._normalize_internal_watcher_text(item))
        return options[:max(1, int(limit or 120))]

    def _parse_trip_watch_date_request(self, text):
        raw = str(text or "").strip()
        normalized = self._normalize_internal_watcher_text(raw)
        if any(
            term in normalized
            for term in [
                "الاثنين معا", "الاثنين", "اليوم والغد", "اليوم و الغد", "اليوم وغدا", "اليوم و غدا",
                "today and tomorrow", "today tomorrow", "both",
            ]
        ):
            return {"date_mode": "both", "target_dates": sorted(self._watcher_date_targets("both"))}
        if any(term in normalized for term in ["غدا", "بكره", "بكرا", "tomorrow"]):
            return {"date_mode": "tomorrow", "target_dates": sorted(self._watcher_date_targets("tomorrow"))}
        if any(term in normalized for term in ["اليوم", "today"]):
            return {"date_mode": "today", "target_dates": sorted(self._watcher_date_targets("today"))}
        custom_match = re.search(r"\b(20\d{2}-\d{2}-\d{2})\b", raw)
        if custom_match:
            date_value = str(custom_match.group(1) or "").strip()
            return {"date_mode": "custom", "target_dates": [date_value]}
        return {}

    def disable_trip_booking_alert_watcher(self, actor, watcher_id):
        actor = actor or {}
        watcher_id = str(watcher_id or "").strip()
        if not watcher_id:
            return False
        ws = self._get_or_create_internal_workspace(actor)
        if not isinstance(ws, dict):
            return False
        watchers = ws.get("watchers") or []
        if not isinstance(watchers, list) or not watchers:
            return False
        changed = False
        for item in watchers:
            if not isinstance(item, dict):
                continue
            if str(item.get("id") or "").strip() == watcher_id:
                item["enabled"] = False
                item["updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
                changed = True
        if changed:
            ws["watchers"] = watchers
            ws["updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            ws_key = f"internal_workspace:{str(ws.get('actor_key') or '').strip()}"
            self._save_json_setting_value(ws_key, ws)
        return changed

    def _normalize_internal_watcher_text(self, value):
        text = str(value or "").strip().lower()
        text = text.replace("أ", "ا").replace("إ", "ا").replace("آ", "ا")
        text = text.replace("ة", "ه")
        text = re.sub(r"\s+", " ", text)
        return text

    def _stringify_internal_watcher_value(self, value):
        if value is None:
            return ""
        if isinstance(value, list):
            return ", ".join(str(item).strip() for item in value if str(item).strip())
        if isinstance(value, dict):
            try:
                return json.dumps(value, ensure_ascii=False, sort_keys=True)
            except Exception:
                return str(value).strip()
        return str(value).strip()

    def _extract_field_value_by_name(self, fields, field_name):
        fields = fields if isinstance(fields, dict) else {}
        wanted = str(field_name or "").strip()
        if not wanted:
            return None
        if wanted in fields:
            return fields.get(wanted)
        wanted_norm = self._normalize_internal_watcher_text(wanted)
        for key, value in fields.items():
            if self._normalize_internal_watcher_text(key) == wanted_norm:
                return value
        return None

    def _monitorable_main_fields_catalog(self, actor=None):
        from airtable_fields import ID_TO_READABLE_NAME
        catalog = {}

        def _add_field(field_name, field_type="", choices=None):
            name = str(field_name or "").strip()
            if not name:
                return
            key = self._normalize_internal_watcher_text(name)
            if key not in catalog:
                catalog[key] = {
                    "field_name": name,
                    "field_type": str(field_type or "").strip(),
                    "choices": [str(x).strip() for x in (choices or []) if str(x).strip()],
                }

        for readable_name in (ID_TO_READABLE_NAME or {}).values():
            _add_field(readable_name)

        schema_context = self._get_airtable_schema_context(actor=actor, refresh=False)
        for base in (schema_context.get("bases") or []):
            if not isinstance(base, dict):
                continue
            base_label = str(base.get("base_label") or "").strip().lower()
            if base_label != "main":
                continue
            tables = base.get("tables") or []
            if isinstance(tables, dict):
                tables = list(tables.values())
            for table in tables:
                if not isinstance(table, dict):
                    continue
                table_name = str(table.get("table_name") or "").strip().lower()
                if table_name != "list":
                    continue
                fields = table.get("fields") or []
                if isinstance(fields, dict):
                    fields = list(fields.values())
                for field in fields:
                    if not isinstance(field, dict):
                        continue
                    _add_field(
                        field.get("field_name"),
                        field_type=field.get("field_type"),
                        choices=field.get("choices") or [],
                    )
        return catalog

    def _resolve_monitorable_field_name(self, raw_field_name, actor=None):
        target = self._normalize_internal_watcher_text(raw_field_name)
        if not target:
            return ""
        aliases = {
            "booking status": "Booking Status",
            "حاله الحجز": "Booking Status",
            "حالة الحجز": "Booking Status",
            "invoice status": "Invoice Status",
            "حاله الفاتوره": "Invoice Status",
            "حالة الفاتورة": "Invoice Status",
            "payment status": "Invoice Status",
            "حاله الدفع": "Invoice Status",
            "حالة الدفع": "Invoice Status",
            "payment method": "Payment Method",
            "طريقه الدفع": "Payment Method",
            "طريقة الدفع": "Payment Method",
            "customer name": "Customer Name",
            "اسم العميل": "Customer Name",
            "trip name": "trip Name",
            "اسم الرحله": "trip Name",
            "اسم الرحلة": "trip Name",
            "date trip": "Date Trip",
            "trip date": "Date Trip",
            "تاريخ الرحله": "Date Trip",
            "تاريخ الرحلة": "Date Trip",
            "hotel name": "Hotel Name",
            "اسم الفندق": "Hotel Name",
            "room number": "Room number",
            "رقم الغرفه": "Room number",
            "رقم الغرفة": "Room number",
            "reason": "Reason ",
            "السبب": "Reason ",
            "note": "Note",
            "ملاحظه": "Note",
            "ملاحظة": "Note",
            "no show": "No show & refund",
            "نوشو": "No show & refund",
            "نو شو": "No show & refund",
        }
        catalog = self._monitorable_main_fields_catalog(actor=actor)
        alias_value = aliases.get(target)
        if alias_value:
            resolved = catalog.get(self._normalize_internal_watcher_text(alias_value))
            return str((resolved or {}).get("field_name") or alias_value).strip()
        direct = catalog.get(target)
        if direct:
            return str(direct.get("field_name") or "").strip()
        for key, meta in catalog.items():
            if key == target or target == key:
                return str(meta.get("field_name") or "").strip()
        return ""

    def _monitorable_field_alias_pairs(self, actor=None):
        alias_pairs = []
        catalog = self._monitorable_main_fields_catalog(actor=actor)
        for key, meta in catalog.items():
            name = str(meta.get("field_name") or "").strip()
            if key and name:
                alias_pairs.append((key, name))
        custom_aliases = {
            "حالة الحجز": "Booking Status",
            "حاله الحجز": "Booking Status",
            "booking status": "Booking Status",
            "حالة الفاتورة": "Invoice Status",
            "حاله الفاتوره": "Invoice Status",
            "payment status": "Invoice Status",
            "invoice status": "Invoice Status",
            "حالة الدفع": "Invoice Status",
            "حاله الدفع": "Invoice Status",
            "طريقة الدفع": "Payment Method",
            "طريقه الدفع": "Payment Method",
            "payment method": "Payment Method",
            "اسم العميل": "Customer Name",
            "customer name": "Customer Name",
            "اسم الرحلة": "trip Name",
            "اسم الرحله": "trip Name",
            "trip name": "trip Name",
            "تاريخ الرحلة": "Date Trip",
            "تاريخ الرحله": "Date Trip",
            "trip date": "Date Trip",
            "date trip": "Date Trip",
            "السبب": "Reason ",
            "reason": "Reason ",
            "ملاحظة": "Note",
            "ملاحظه": "Note",
            "note": "Note",
        }
        for alias, canonical in custom_aliases.items():
            resolved = self._resolve_monitorable_field_name(canonical, actor=actor) or canonical
            alias_pairs.append((self._normalize_internal_watcher_text(alias), resolved))
        alias_pairs.sort(key=lambda item: len(item[0]), reverse=True)
        return alias_pairs

    def _booking_field_watch_suggested_fields(self, actor=None, limit=10):
        catalog = self._monitorable_main_fields_catalog(actor=actor)
        preferred = [
            "Invoice Status",
            "Booking Status",
            "Payment Method",
            "Date Trip",
            "Hotel Name",
            "Room number",
            "Customer Name",
            "trip Name",
            "Reason ",
            "Note",
        ]
        out = []
        seen = set()
        for field_name in preferred:
            resolved = self._resolve_monitorable_field_name(field_name, actor=actor)
            key = self._normalize_internal_watcher_text(resolved)
            if resolved and key not in seen:
                out.append(resolved)
                seen.add(key)
        for meta in catalog.values():
            resolved = str(meta.get("field_name") or "").strip()
            key = self._normalize_internal_watcher_text(resolved)
            if resolved and key not in seen:
                out.append(resolved)
                seen.add(key)
            if limit and len(out) >= limit:
                break
        return out[:max(int(limit or 0), 1)]

    def _normalize_booking_field_watch_expected_value(self, field_name, expected_value):
        normalized_field = self._normalize_internal_watcher_text(field_name)
        raw_value = str(expected_value or "").strip().strip("\"'“”`")
        if not raw_value:
            return ""
        normalized_value = self._normalize_internal_watcher_text(raw_value)
        if normalized_field == self._normalize_internal_watcher_text("Invoice Status"):
            invoice_map = {
                "paid": "Succeeded",
                "succeeded": "Succeeded",
                "success": "Succeeded",
                "done": "Succeeded",
                "pending": "pending",
                "failed": "failed",
                "open": "open",
                "unpaid": "open",
            }
            return invoice_map.get(normalized_value, raw_value)
        if normalized_field == self._normalize_internal_watcher_text("Booking Status"):
            booking_map = {
                "active": "Active",
                "confirmed": "Confirmed",
                "pending": "Pending",
                "canceled": "Cancelled",
                "cancelled": "Cancelled",
                "no show": "No show",
                "no-show": "No show",
                "نوشو": "No show",
                "نو شو": "No show",
            }
            return booking_map.get(normalized_value, raw_value)
        return raw_value

    def _parse_booking_field_watch_request(self, message_text, actor=None):
        text = str(message_text or "").strip()
        if not text:
            return {"booking_number": "", "field_name": "", "expected_value": ""}
        booking_number = ""
        for cand, _confidence in (self.extract_booking_numbers_regex(text) or []):
            normalized_booking = str(cand or "").strip()
            if normalized_booking and not self._is_placeholder_booking_number(normalized_booking):
                booking_number = normalized_booking
                break

        field_name = ""
        explicit_field_match = re.search(
            r"(?:حقل|field)\s*[:\-]?\s*([^\n\r,]{2,80})",
            text,
            flags=re.IGNORECASE,
        )
        if explicit_field_match:
            field_name = self._resolve_monitorable_field_name(explicit_field_match.group(1), actor=actor)
        if not field_name:
            normalized_text = self._normalize_internal_watcher_text(text)
            for alias_key, canonical in self._monitorable_field_alias_pairs(actor=actor):
                if alias_key and alias_key in normalized_text:
                    field_name = canonical
                    break

        expected_value = ""
        for pattern in [
            r"(?:يب(?:قى|قي)|يصبح|يصير|تكون|يساوي|equals?|equal to|=|to|الى|إلى)\s*([^\n\r]+?)\s*$",
            r"(?:لو|if|when)\s+.+?(?:يب(?:قى|قي)|يصبح|يصير|يساوي|equals?|=|to|الى|إلى)\s*([^\n\r]+?)\s*$",
        ]:
            match = re.search(pattern, text, flags=re.IGNORECASE)
            if match:
                expected_value = str(match.group(1) or "").strip().strip("\"'“”`.,،:;")
                break

        normalized_expected = self._normalize_internal_watcher_text(expected_value)
        if field_name and normalized_expected == self._normalize_internal_watcher_text(field_name):
            expected_value = ""
        if booking_number and normalized_expected == self._normalize_internal_watcher_text(booking_number):
            expected_value = ""
        return {
            "booking_number": booking_number,
            "field_name": field_name,
            "expected_value": expected_value,
        }

    def create_booking_field_watcher(self, actor, booking_number, field_name, expected_value="", interval_sec=120):
        actor = actor or {}
        booking_number = str(booking_number or "").strip()
        field_name = self._resolve_monitorable_field_name(field_name, actor=actor)
        expected_value = self._normalize_booking_field_watch_expected_value(field_name, expected_value)
        interval_sec = int(interval_sec or 120)
        if not booking_number:
            return None, "missing_booking"
        if not field_name:
            return None, "field_not_found"
        if not self._actor_allows_base_label(actor, "general"):
            return None, "unauthorized_base"
        booking_record = self.find_booking_by_number(booking_number)
        if not isinstance(booking_record, dict):
            return None, "booking_not_found"
        ws = self._get_or_create_internal_workspace(actor)
        if not isinstance(ws, dict):
            return None, "workspace_missing"
        current_raw_value = self._extract_field_value_by_name(booking_record.get("fields", {}) or {}, field_name)
        current_value = self._stringify_internal_watcher_value(current_raw_value)
        watcher = {
            "id": secrets.token_hex(6),
            "type": "booking_field_watch",
            "enabled": True,
            "booking_number": booking_number,
            "target_record_id": str(booking_record.get("id") or "").strip(),
            "field_name": field_name,
            "expected_value": expected_value,
            "initial_value": current_value,
            "last_seen_value": current_value,
            "last_notified_value": "",
            "interval_sec": max(30, interval_sec),
            "notify_phone": re.sub(r"\D", "", str(actor.get("phone") or "")),
            "created_by": self._internal_workspace_actor_key(actor),
            "created_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            "updated_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            "last_run_at": "",
        }
        watchers = ws.get("watchers") or []
        if not isinstance(watchers, list):
            watchers = []
        watchers.append(watcher)
        ws["watchers"] = watchers[-50:]
        ws["updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        ws_key = f"internal_workspace:{str(ws.get('actor_key') or '').strip()}"
        self._save_json_setting_value(ws_key, ws)
        return watcher, ""

    def _build_booking_field_watch_message(self, watcher, booking_record, previous_value, current_value):
        from airtable_fields import FieldIds
        watcher = watcher or {}
        booking_record = booking_record or {}
        fields = booking_record.get("fields", {}) or {}
        booking_nr = self.get_field_value(fields, FieldIds.BOOKING_NR) or watcher.get("booking_number") or ""
        customer_name = self.get_field_value(fields, FieldIds.CUSTOMER_NAME) or ""
        trip_name = self.get_field_value(fields, FieldIds.TRIP_NAME) or ""
        field_name = str(watcher.get("field_name") or "").strip()
        expected_value = str(watcher.get("expected_value") or "").strip()
        if expected_value:
            lines = [
                "🔔 Booking Field Watch Triggered",
                "",
                f"🧾 Booking: [{booking_nr}]",
                f"👤 Customer: [{customer_name}]",
                f"🌊 Trip: [{trip_name}]",
                f"🧩 Field: [{field_name}]",
                f"🎯 Target: [{expected_value}]",
                f"✅ Current Value: [{current_value}]",
            ]
        else:
            lines = [
                "🔔 Booking Field Changed",
                "",
                f"🧾 Booking: [{booking_nr}]",
                f"👤 Customer: [{customer_name}]",
                f"🌊 Trip: [{trip_name}]",
                f"🧩 Field: [{field_name}]",
                f"🕘 Previous: [{previous_value}]",
                f"✅ Current: [{current_value}]",
            ]
        return "\n".join(lines).strip()

    def _poll_single_booking_field_watcher(self, watcher):
        watcher = watcher or {}
        if not bool(watcher.get("enabled", True)):
            return watcher
        booking_number = str(watcher.get("booking_number") or "").strip()
        field_name = str(watcher.get("field_name") or "").strip()
        owner_phone = re.sub(r"\D", "", str(watcher.get("notify_phone") or ""))
        if not booking_number or not field_name or not owner_phone:
            return watcher
        booking_record = self.find_booking_by_number(booking_number)
        if not isinstance(booking_record, dict):
            return watcher
        fields = booking_record.get("fields", {}) or {}
        current_value = self._stringify_internal_watcher_value(
            self._extract_field_value_by_name(fields, field_name)
        )
        previous_value = str(watcher.get("last_seen_value") or "")
        expected_value = str(watcher.get("expected_value") or "").strip()
        should_notify = False
        disable_after_notify = False
        if expected_value:
            if self._normalize_internal_watcher_text(current_value) == self._normalize_internal_watcher_text(expected_value):
                if self._normalize_internal_watcher_text(str(watcher.get("last_notified_value") or "")) != self._normalize_internal_watcher_text(current_value):
                    should_notify = True
                    disable_after_notify = True
        else:
            if current_value != previous_value:
                should_notify = True
        if should_notify:
            msg = self._build_booking_field_watch_message(watcher, booking_record, previous_value, current_value)
            ok = self.send_internal_notifications_whatsapp_text(owner_phone, msg)
            if ok:
                watcher["last_notified_value"] = current_value
                if disable_after_notify:
                    watcher["enabled"] = False
                    watcher["completed_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        watcher["target_record_id"] = str(booking_record.get("id") or "").strip()
        watcher["last_seen_value"] = current_value
        watcher["last_run_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        watcher["updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        return watcher

    def _internal_evolution_cfg_for_notifications(self):
        cfg = self._load_json_setting_value("internal_whatsapp_notifications_config", {}) or {}
        if not isinstance(cfg, dict):
            cfg = {}
        instance_name = str(cfg.get("instanceName") or "fts_internal_notifications").strip()
        provider_base_url = str(cfg.get("providerBaseUrl") or "").strip().rstrip("/")
        api_key = str(cfg.get("apiKey") or "").strip()
        if not provider_base_url:
            provider_base_url = "http://127.0.0.1:8080"
        if not instance_name or not api_key:
            return None
        return {
            "instanceName": instance_name,
            "providerBaseUrl": provider_base_url,
            "apiKey": api_key,
        }

    def send_internal_notifications_whatsapp_text(self, recipient_phone, text):
        """
        Staff/ops alerts MUST send only via the dedicated Internal Notifications
        Evolution instance. No load-balancing / fallback to other user numbers.

        Returns True/False for backward compatibility.
        Detailed result is also stored on self._last_internal_notify_send_meta.
        """
        ok, meta = self.send_internal_notifications_whatsapp_text_detailed(recipient_phone, text)
        self._last_internal_notify_send_meta = meta
        return ok

    def send_internal_notifications_whatsapp_text_detailed(self, recipient_phone, text):
        """
        Same as send_internal_notifications_whatsapp_text but returns (ok, meta_dict).
        """
        cfg = self._internal_evolution_cfg_for_notifications()
        raw_recipient = str(recipient_phone or "").strip()
        is_group = "@g.us" in raw_recipient.lower()
        if is_group:
            to_phone = raw_recipient
        else:
            to_phone = re.sub(r"\D", "", raw_recipient)
        message_text = str(text or "").strip()
        # Strip ASCII control chars (except \\n \\r \\t) — Make payloads sometimes embed them
        message_text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", message_text)
        if not cfg or not to_phone or not message_text:
            meta = {
                "ok": False,
                "error": "missing_cfg_phone_or_text",
                "has_cfg": bool(cfg),
                "phone": to_phone,
                "is_group": is_group,
            }
            return False, meta

        import requests
        url = f"{cfg['providerBaseUrl']}/message/sendText/{quote(cfg['instanceName'])}"
        try:
            resp = requests.post(
                url,
                headers={
                    "Content-Type": "application/json",
                    "apikey": cfg["apiKey"],
                },
                json={
                    "number": to_phone,
                    "text": message_text,
                },
                timeout=25,
            )
            status_code = int(resp.status_code or 0)
            body_text = (resp.text or "")[:800]
            body_json = None
            try:
                body_json = resp.json() if resp.content else None
            except Exception:
                body_json = None
            ok = status_code < 400
            meta = {
                "ok": ok,
                "status_code": status_code,
                "instance_name": cfg.get("instanceName"),
                "phone": to_phone,
                "is_group": is_group,
                "body": body_text,
                "json": body_json,
            }
            if not ok:
                # Evolution often returns message:["[object Object]"] for group/membership failures
                hint = None
                if is_group:
                    hint = (
                        "Target is a WhatsApp GROUP. Ensure the Internal Notifications number "
                        f"({cfg.get('instanceName')}) is still a member of this group, and that "
                        "the group JID is current (old phone-timestamp@g.us IDs often break after WhatsApp migrates groups)."
                    )
                else:
                    hint = (
                        "Evolution rejected the send. Check that the Internal Notifications "
                        "WhatsApp session is open and the recipient number is valid."
                    )
                meta["hint"] = hint
                logging.warning(
                    "Internal notifications send failed via %s (%s) to %s: %s",
                    cfg.get("instanceName"),
                    status_code,
                    to_phone,
                    body_text[:400],
                )
            return ok, meta
        except Exception as e:
            logging.warning("Internal notifications send exception via %s: %s", cfg.get("instanceName"), e)
            return False, {
                "ok": False,
                "error": "exception",
                "message": str(e),
                "phone": to_phone,
                "is_group": is_group,
                "instance_name": (cfg or {}).get("instanceName"),
            }

    def resolve_user_evolution_connection(self, username, connection_id=None):
        """Return the first enabled+connected Evolution WhatsApp for a dashboard user."""
        uname = str(username or "").strip()
        if not uname:
            return None
        try:
            import chat_db
            raw = chat_db.get_setting("dashboard_user_whatsapp_connections")
            data = json.loads(raw) if raw else {}
        except Exception:
            data = {}
        if not isinstance(data, dict):
            return None
        items = data.get(uname) or []
        if not isinstance(items, list):
            return None
        want_id = str(connection_id or "").strip()
        connected = []
        for item in items:
            if not isinstance(item, dict):
                continue
            if not bool(item.get("enabled", True)):
                continue
            status = str(item.get("connectionStatus") or "").strip().lower()
            if status not in {"connected", "open"}:
                continue
            instance_name = str(item.get("instanceName") or "").strip()
            if not instance_name:
                continue
            if want_id and str(item.get("id") or "").strip() != want_id:
                continue
            connected.append(item)
        if not connected:
            return None
        return connected[0]

    def send_user_evolution_whatsapp(
        self,
        username,
        recipient_phone,
        text=None,
        media_url=None,
        media_type=None,
        connection_id=None,
    ):
        """
        Send a customer message using the logged-in user's personal Evolution WhatsApp.
        Used when reply_channel=whatsapp_internal (hard Meta / ignored-customer cases).
        """
        conn = self.resolve_user_evolution_connection(username, connection_id=connection_id)
        if not conn:
            return False, {
                "error": "no_connected_user_whatsapp",
                "message": "No connected personal WhatsApp number found for this user.",
            }

        to_phone = re.sub(r"\D", "", str(recipient_phone or ""))
        message_text = str(text or "").strip()
        media_url_s = str(media_url or "").strip()
        if not to_phone:
            return False, {"error": "missing_phone", "message": "Missing recipient phone."}
        if not message_text and not media_url_s:
            return False, {"error": "missing_text", "message": "Message text is required."}

        base_cfg = self._internal_evolution_cfg_for_notifications() or {}
        provider_base_url = str(base_cfg.get("providerBaseUrl") or "http://127.0.0.1:8080").rstrip("/")
        api_key = str(base_cfg.get("apiKey") or "").strip()
        instance_name = str(conn.get("instanceName") or "").strip()
        if not api_key or not instance_name:
            return False, {
                "error": "missing_evolution_config",
                "message": "Evolution API config missing for personal WhatsApp send.",
            }

        import requests
        headers = {"Content-Type": "application/json", "apikey": api_key}
        try:
            if media_url_s:
                mt = str(media_type or "document").strip().lower()
                if mt.startswith("image"):
                    evo_type = "image"
                elif mt.startswith("audio"):
                    evo_type = "audio"
                elif mt.startswith("video"):
                    evo_type = "video"
                else:
                    evo_type = "document"
                url = f"{provider_base_url}/message/sendMedia/{quote(instance_name)}"
                body = {
                    "number": to_phone,
                    "mediatype": evo_type,
                    "media": media_url_s,
                    "caption": message_text or "",
                }
            else:
                url = f"{provider_base_url}/message/sendText/{quote(instance_name)}"
                body = {"number": to_phone, "text": message_text}
            resp = requests.post(url, headers=headers, json=body, timeout=30)
            if int(resp.status_code or 0) >= 400:
                return False, {
                    "error": "evolution_send_failed",
                    "status_code": int(resp.status_code or 0),
                    "body": (resp.text or "")[:800],
                    "instance_name": instance_name,
                }
            payload = {}
            try:
                payload = resp.json() if resp.content else {}
            except Exception:
                payload = {}
            return True, {
                "instance_name": instance_name,
                "whatsapp_number": str(conn.get("whatsappNumber") or ""),
                "connection_label": str(conn.get("connectionLabel") or ""),
                "connection_id": str(conn.get("id") or ""),
                "evolution_response": payload,
                "text": message_text,
            }
        except Exception as e:
            logging.error("User Evolution WhatsApp send failed: %s", e, exc_info=True)
            return False, {"error": "exception", "message": str(e)}

    def _build_trip_booking_alert_message(self, record):
        from airtable_fields import FieldIds
        rec = record or {}
        fields = rec.get("fields", {}) or {}
        booking_nr = self.get_field_value(fields, FieldIds.BOOKING_NR) or ""
        trip_name = self.get_field_value(fields, FieldIds.TRIP_NAME) or ""
        option = self.get_field_value(fields, FieldIds.OPTION) or ""
        date_trip_raw = self.get_field_value(fields, FieldIds.DATE_TRIP) or ""
        try:
            _, date_trip = self.get_corrected_trip_date(str(date_trip_raw or ""))
            if not date_trip or str(date_trip).strip().lower() == "unknown date":
                date_trip = str(date_trip_raw or "")
        except Exception:
            date_trip = str(date_trip_raw or "")
        adt = self.get_field_value(fields, FieldIds.ADT) or ""
        chd = self.get_field_value(fields, FieldIds.CHD) or ""
        std = self.get_field_value(fields, FieldIds.STD) or ""
        inf = self.get_field_value(fields, FieldIds.INF) or ""
        guide = self.get_field_value(fields, FieldIds.GUIDE) or ""
        customer_name = self.get_field_value(fields, FieldIds.CUSTOMER_NAME) or ""
        customer_phone = self.get_field_value(fields, FieldIds.CUSTOMER_PHONE) or ""
        hotel = self.get_field_value(fields, FieldIds.HOTEL_NAME) or ""
        lines = [
            "🚨 Last-Minute Booking Alert!",
            "",
            f"🧾 Ref: [{booking_nr}]",
            f"🌊 Trip: [{trip_name}]",
            f"🔘 Option:[{option}]",
            f"🕗 Date: [{date_trip}]",
            "👥 Pax: [ADT:{adt}\nCHD:{chd}\nSTD:{std}\nInf:{inf}]".format(
                adt=str(adt or "").strip(),
                chd=str(chd or "").strip(),
                std=str(std or "").strip(),
                inf=str(inf or "").strip(),
            ),
            f"🗣 Guide: [{guide}]",
            f"👥 Customer Name: [{customer_name}]",
            f"📞 Customer Phone:  [{customer_phone}]",
            f"🏨 Pickup Hotel: [{hotel}]",
        ]
        return "\n".join(lines).strip()

    def _watcher_date_targets(self, mode):
        mode = str(mode or "").strip().lower() or "today"
        now = self._internal_cairo_now()
        today = now.date()
        tomorrow = (now + timedelta(days=1)).date()
        if mode in {"both", "today_tomorrow", "today+tomorrow"}:
            return {today.isoformat(), tomorrow.isoformat()}
        if mode in {"tomorrow", "tmr"}:
            return {tomorrow.isoformat()}
        return {today.isoformat()}

    def _poll_single_trip_alert_watcher(self, watcher):
        from airtable_fields import FieldIds, ID_TO_READABLE_NAME, TABLE_NAME
        watcher = watcher or {}
        if not bool(watcher.get("enabled", True)):
            return watcher
        base_label = str(watcher.get("base_label") or "general").strip().lower() or "general"
        table_name = str(watcher.get("table_name") or "").strip()
        trip_contains = str(watcher.get("trip_contains") or "").strip()
        trip_names = [str(x).strip() for x in (watcher.get("trip_names") or []) if str(x).strip()]
        date_mode = str(watcher.get("date_mode") or "today").strip().lower() or "today"
        target_dates = [str(x).strip() for x in (watcher.get("target_dates") or []) if str(x).strip()]
        match_mode = str(watcher.get("match_mode") or "contains").strip().lower() or "contains"
        max_per_poll = int(watcher.get("max_per_poll") or 10)
        start_created_at = self._parse_iso_datetime(watcher.get("start_created_at")) or datetime.now(timezone.utc)
        notified_ids = watcher.get("notified_record_ids") or []
        if not isinstance(notified_ids, list):
            notified_ids = []
        notified_set = set(str(x) for x in notified_ids if str(x).strip())
        owner_phone = re.sub(r"\D", "", str(watcher.get("notify_phone") or ""))
        if (not trip_contains and not trip_names) or not owner_phone:
            return watcher

        table = None
        if base_label == "religious":
            if not table_name:
                return watcher
            table = (getattr(self, "religious_tables", {}) or {}).get(table_name)
            if not table and getattr(self, "religious_leads_table", None):
                leads_name = str(self.config.get("airtable", {}).get("tables", {}).get("religious_leads", "استفسارات جديدة") or "").strip()
                if leads_name and table_name == leads_name:
                    table = getattr(self, "religious_leads_table", None)
        else:
            table_name = table_name or TABLE_NAME
            table = getattr(self, "table", None)

        if not table:
            return watcher

        trip_field_name = str(ID_TO_READABLE_NAME.get(FieldIds.TRIP_NAME, "Trip Name") or "Trip Name").strip()
        date_field_name = str(ID_TO_READABLE_NAME.get(FieldIds.DATE_TRIP, "Date Trip") or "Date Trip").strip()
        safe_query = trip_contains.replace("'", "''")
        targets = set(target_dates) if target_dates else self._watcher_date_targets(date_mode)
        date_parts = [f"DATETIME_FORMAT({{{date_field_name}}}, 'YYYY-MM-DD') = '{d}'" for d in sorted(targets)]
        date_expr = f"OR({', '.join(date_parts)})" if len(date_parts) > 1 else date_parts[0]
        if trip_names:
            name_parts = []
            for item in trip_names[:20]:
                safe_name = str(item or "").replace("'", "''")
                name_parts.append(f"LOWER({{{trip_field_name}}}) = LOWER('{safe_name}')")
            trip_expr = f"OR({', '.join(name_parts)})" if len(name_parts) > 1 else (name_parts[0] if name_parts else "")
        else:
            contains_expr = f"FIND(LOWER('{safe_query}'), LOWER({{{trip_field_name}}}))"
            trip_expr = contains_expr
        formula = f"AND({trip_expr}, {date_expr})" if trip_expr else date_expr

        records = []
        try:
            try:
                records = table.all(formula=formula, max_records=max(50, max_per_poll * 4))
            except TypeError:
                records = table.all(formula=formula)
        except Exception:
            records = []

        candidates = []
        normalized_trip_names = {self._normalize_internal_watcher_text(x) for x in trip_names if str(x).strip()}
        for rec in (records or []):
            rec_id = str((rec or {}).get("id") or "").strip()
            if not rec_id or rec_id in notified_set:
                continue
            fields = (rec or {}).get("fields", {}) if isinstance(rec, dict) else {}
            live_trip_name = str(self.get_field_value(fields, FieldIds.TRIP_NAME) or "").strip()
            live_trip_norm = self._normalize_internal_watcher_text(live_trip_name)
            if normalized_trip_names:
                if match_mode == "exact":
                    if live_trip_norm not in normalized_trip_names:
                        continue
                elif not any(item in live_trip_norm for item in normalized_trip_names):
                    continue
            created_time = self._parse_iso_datetime((rec or {}).get("createdTime"))
            if created_time and created_time.tzinfo:
                created_time = created_time.astimezone(timezone.utc).replace(tzinfo=None)
            if created_time and created_time < start_created_at.replace(tzinfo=None):
                continue
            candidates.append(rec)

        candidates.sort(key=lambda x: str((x or {}).get("createdTime") or ""))
        to_send = candidates[: max(0, max_per_poll)]
        sent_any = False
        for rec in to_send:
            msg = self._build_trip_booking_alert_message(rec)
            ok = self.send_internal_notifications_whatsapp_text(owner_phone, msg)
            if ok:
                sent_any = True
                rec_id = str((rec or {}).get("id") or "").strip()
                if rec_id:
                    notified_set.add(rec_id)
        if sent_any:
            watcher["notified_record_ids"] = list(notified_set)[-800:]
            watcher["last_run_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        return watcher

    def _poll_trip_booking_alert_watchers_once(self):
        index = self._load_json_setting_value("internal_workspace_index", []) or []
        if not isinstance(index, list) or not index:
            return
        for actor_key in list(index):
            ws_key = f"internal_workspace:{str(actor_key).strip()}"
            workspace = self._load_json_setting_value(ws_key, None)
            if not isinstance(workspace, dict):
                continue
            watchers = workspace.get("watchers") or []
            if not isinstance(watchers, list) or not watchers:
                continue
            updated = False
            new_watchers = []
            for watcher in watchers:
                if not isinstance(watcher, dict):
                    continue
                interval_sec = int(watcher.get("interval_sec") or 300)
                last_run = self._parse_iso_datetime(watcher.get("last_run_at"))
                if last_run and (datetime.now(timezone.utc) - last_run.replace(tzinfo=timezone.utc)).total_seconds() < max(30, interval_sec):
                    new_watchers.append(watcher)
                    continue
                watcher_type = str(watcher.get("type") or "").strip().lower()
                if watcher_type == "booking_field_watch":
                    new_watchers.append(self._poll_single_booking_field_watcher(watcher))
                else:
                    new_watchers.append(self._poll_single_trip_alert_watcher(watcher))
                updated = True
            if updated:
                workspace["watchers"] = new_watchers
                workspace["updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
                self._save_json_setting_value(ws_key, workspace)

    def _trip_booking_alert_watchers_loop(self):
        import time
        while True:
            try:
                self._poll_trip_booking_alert_watchers_once()
            except Exception:
                pass
            time.sleep(300)

    def start_trip_booking_alert_watchers(self):
        try:
            if getattr(self, "_trip_booking_alert_watchers_started", False):
                return
            self._trip_booking_alert_watchers_started = True
            import threading
            t = threading.Thread(target=self._trip_booking_alert_watchers_loop, daemon=True)
            t.start()
        except Exception:
            return

