        def _save_dashboard_user_whatsapp_connections(data):
            normalized = {}
            if isinstance(data, dict):
                for username, items in data.items():
                    uname = str(username or "").strip()
                    if not uname:
                        continue
                    normalized_items = []
                    if isinstance(items, list):
                        for item in items:
                            if isinstance(item, dict):
                                normalized_items.append(_normalize_user_whatsapp_connection(uname, item))
                    normalized[uname] = normalized_items
            try:
                chat_db.set_setting("dashboard_user_whatsapp_connections", json.dumps(normalized, ensure_ascii=False))
            except Exception:
                pass
            return normalized

        def _get_effective_evolution_config_for_user_connection(connection):
            global_cfg = _load_internal_whatsapp_config()
            conn = connection or {}
            effective = {
                "providerBaseUrl": str((conn.get("providerBaseUrl") or global_cfg.get("providerBaseUrl") or "")).strip(),
                "apiKey": str((conn.get("apiKey") or global_cfg.get("apiKey") or "")).strip(),
                "instanceName": str(conn.get("instanceName") or "").strip(),
                "webhookUrl": str(global_cfg.get("userWebhookUrl") or "").strip(),
            }
            if not effective["webhookUrl"]:
                base_webhook = str(global_cfg.get("webhookUrl") or "").strip()
                if base_webhook.endswith("/whatsapp/webhook"):
                    effective["webhookUrl"] = base_webhook.replace("/whatsapp/webhook", "/user_whatsapp/webhook")
                else:
                    effective["webhookUrl"] = base_webhook
            return effective

        def _serialize_user_whatsapp_connection(connection, include_private=False):
            conn = dict(connection or {})
            out = {
                "id": str(conn.get("id") or ""),
                "username": str(conn.get("username") or ""),
                "provider": "evolution",
                "connectionLabel": str(conn.get("connectionLabel") or ""),
                "instanceName": str(conn.get("instanceName") or ""),
                "whatsappNumber": str(conn.get("whatsappNumber") or ""),
                "notes": str(conn.get("notes") or ""),
                "enabled": bool(conn.get("enabled", True)),
                "connectionStatus": str(conn.get("connectionStatus") or "not_connected"),
                "lastConnectedAt": str(conn.get("lastConnectedAt") or ""),
                "lastQrUpdatedAt": str(conn.get("lastQrUpdatedAt") or ""),
                "qrCodeDataUrl": str(conn.get("qrCodeDataUrl") or ""),
                "createdAt": str(conn.get("createdAt") or ""),
                "updatedAt": str(conn.get("updatedAt") or ""),
            }
            if include_private:
                out["providerBaseUrl"] = str(conn.get("providerBaseUrl") or "")
                out["apiKey"] = str(conn.get("apiKey") or "")
            return out

        def _count_open_chats_for_owner(owner_user_id):
            owner = str(owner_user_id or "").strip()
            summary = {
                "count": 0,
                "needs_help_count": 0,
                "unread_count": 0,
            }
            if not owner:
                return summary
            try:
                rows = chat_db.get_sales_leads_by_owner(owner) or []
                for row in rows:
                    if int((row or {}).get("is_deleted") or 0) == 1:
                        continue
                    summary["count"] += 1
                    try:
                        summary["needs_help_count"] += 1 if int((row or {}).get("needs_help") or 0) == 1 else 0
                    except Exception:
                        pass
                    try:
                        summary["unread_count"] += max(0, int((row or {}).get("unread_count") or 0))
                    except Exception:
                        pass
            except Exception:
                pass
            return summary

        def _derive_team_user_connection_status(items):
            if not items:
                return "no_numbers"
            connected = 0
            pending = 0
            error = 0
            enabled = 0
            for item in items:
                if bool((item or {}).get("enabled", True)):
                    enabled += 1
                status = str((item or {}).get("connectionStatus") or "").strip().lower()
                if status == "connected":
                    connected += 1
                elif status == "pending_qr":
                    pending += 1
                elif status == "error":
                    error += 1
            if connected > 0:
                return "connected"
            if pending > 0:
                return "pending_qr"
            if error > 0:
                return "error"
            if enabled > 0:
                return "not_connected"
            return "disabled"

        def _build_team_user_overview(user_meta, key_meta, connection_items):
            user_meta = user_meta or {}
            username = str(user_meta.get("username") or "").strip()
            serialized_connections = [_serialize_user_whatsapp_connection(item) for item in (connection_items or []) if isinstance(item, dict)]
            numbers = []
            for item in serialized_connections:
                number = str(item.get("whatsappNumber") or "").strip()
                if number and number not in numbers:
                    numbers.append(number)
            primary_number = ""
            for item in serialized_connections:
                if str(item.get("connectionLabel") or "").strip().lower() == "primary number":
                    primary_number = str(item.get("whatsappNumber") or "").strip()
                    if primary_number:
                        break
            if not primary_number and numbers:
                primary_number = numbers[0]
            connected_count = sum(1 for item in serialized_connections if str(item.get("connectionStatus") or "").strip().lower() == "connected")
            pending_count = sum(1 for item in serialized_connections if str(item.get("connectionStatus") or "").strip().lower() == "pending_qr")
            error_count = sum(1 for item in serialized_connections if str(item.get("connectionStatus") or "").strip().lower() == "error")
            return {
                "user": user_meta,
                "api_key_meta": _serialize_user_api_key(username, key_meta, include_full_key=False),
                "whatsapp": {
                    "status": _derive_team_user_connection_status(serialized_connections),
                    "total_numbers": len(serialized_connections),
                    "connected_numbers": connected_count,
                    "pending_numbers": pending_count,
                    "error_numbers": error_count,
                    "primary_number": primary_number,
                    "numbers": numbers,
                    "connections": serialized_connections,
                },
                "open_chats": _count_open_chats_for_owner(username),
            }

        def _find_user_whatsapp_connection(connections_map, username, connection_id=None, instance_name=None):
            items = list((connections_map or {}).get(str(username or "").strip()) or [])
            for idx, item in enumerate(items):
                if connection_id and str(item.get("id") or "").strip() == str(connection_id).strip():
                    return idx, item
                if instance_name and str(item.get("instanceName") or "").strip() == str(instance_name).strip():
                    return idx, item
            return -1, None

        def _refresh_user_whatsapp_connection(connection):
            conn = _normalize_user_whatsapp_connection((connection or {}).get("username"), connection)
            cfg = _get_effective_evolution_config_for_user_connection(conn)
            qr_data = str(conn.get("qrCodeDataUrl") or "").strip() or None
            instance_name = str(cfg.get("instanceName") or "").strip()
            if not instance_name:
                conn["connectionStatus"] = "not_connected"
                return conn
            try:
                status_code, payload = _evolution_request("GET", cfg, f"/instance/connectionState/{quote(instance_name)}", timeout=12)
                state = _extract_connection_state(payload)
                detected_whatsapp_number = _extract_connected_whatsapp_number(payload)
                if status_code >= 400:
                    conn["connectionStatus"] = "error"
                else:
                    conn["connectionStatus"] = _map_evolution_state_to_ui(state, qr_data)
                    if detected_whatsapp_number:
                        conn["whatsappNumber"] = detected_whatsapp_number
                    if conn["connectionStatus"] == "connected" and not str(conn.get("whatsappNumber") or "").strip():
                        instance_meta = _fetch_evolution_instance_metadata(cfg, instance_name)
                        detected_whatsapp_number = _extract_connected_whatsapp_number(instance_meta)
                        if detected_whatsapp_number:
                            conn["whatsappNumber"] = detected_whatsapp_number
                    if conn["connectionStatus"] == "connected":
                        conn["lastConnectedAt"] = _utc_iso_now()
                        conn["qrCodeDataUrl"] = ""
            except Exception as e:
                logging.warning(f"Failed to refresh user WhatsApp connection status: {e}")
                if not str(conn.get("connectionStatus") or "").strip():
                    conn["connectionStatus"] = "error"
            conn["updatedAt"] = _utc_iso_now()
            return conn

        def _request_user_whatsapp_qr(connection):
            conn = _normalize_user_whatsapp_connection((connection or {}).get("username"), connection)
            cfg = _get_effective_evolution_config_for_user_connection(conn)
            if not str(cfg.get("providerBaseUrl") or "").strip():
                raise Exception("Provider Base URL is missing")
            if not str(cfg.get("apiKey") or "").strip():
                raise Exception("Global Evolution API key is missing")
            create_status_code, create_payload_response = _upsert_internal_whatsapp_instance(cfg)
            status_code, payload = _evolution_request("GET", cfg, f"/instance/connect/{quote(cfg.get('instanceName') or '')}", timeout=25)
            qr_data = _extract_qr_data(payload)
            state = _extract_connection_state(payload)
            detected_whatsapp_number = _extract_connected_whatsapp_number(payload)
            conn["connectionStatus"] = _map_evolution_state_to_ui(state, qr_data)
            if detected_whatsapp_number:
                conn["whatsappNumber"] = detected_whatsapp_number
            if conn["connectionStatus"] == "connected" and not str(conn.get("whatsappNumber") or "").strip():
                instance_meta = _fetch_evolution_instance_metadata(cfg, str(cfg.get("instanceName") or "").strip())
                detected_whatsapp_number = _extract_connected_whatsapp_number(instance_meta)
                if detected_whatsapp_number:
                    conn["whatsappNumber"] = detected_whatsapp_number
            if qr_data:
                conn["qrCodeDataUrl"] = qr_data
                conn["lastQrUpdatedAt"] = _utc_iso_now()
            if conn["connectionStatus"] == "connected":
                conn["lastConnectedAt"] = _utc_iso_now()
                conn["qrCodeDataUrl"] = ""
            conn["updatedAt"] = _utc_iso_now()
            return status_code, payload, conn, create_status_code, create_payload_response

        def _normalize_base_url(url):
            return str(url or "").strip().rstrip("/")

        def _sanitize_url_field(value):
            raw = str(value or "").strip()
            if not raw:
                return ""
            raw = raw.strip("`").strip().strip('"').strip("'").strip()
            return raw

        def _evolution_headers(cfg):
            api_key = str((cfg or {}).get("apiKey") or "").strip()
            if not api_key:
                raise Exception("Evolution API key is missing")
            return {
                "Content-Type": "application/json",
                "apikey": api_key,
            }

        def _extract_qr_data(data):
            try:
                if isinstance(data, dict):
                    for key in ("qrcode", "qrCode", "qr_code"):
                        nested = data.get(key)
                        if nested:
                            found = _extract_qr_data(nested)
                            if found:
                                return found
                    for key in ("base64", "qrBase64", "qr_base64"):
                        value = data.get(key)
                        if isinstance(value, str) and value.strip():
                            value = value.strip()
                            if value.startswith("data:image"):
                                return value
                            if len(value) > 100:
                                return f"data:image/png;base64,{value}"
                    for value in data.values():
                        found = _extract_qr_data(value)
                        if found:
                            return found
                elif isinstance(data, list):
                    for item in data:
                        found = _extract_qr_data(item)
                        if found:
                            return found
            except Exception:
                return None
            return None

        def _extract_connection_state(data):
            try:
                if isinstance(data, dict):
                    instance = data.get("instance")
                    if isinstance(instance, dict):
                        state = instance.get("state") or instance.get("status")
                        if state is not None:
                            return str(state)
                    state = data.get("state") or data.get("status")
                    if state is not None and not isinstance(state, (dict, list)):
                        return str(state)
                    for value in data.values():
                        found = _extract_connection_state(value)
                        if found:
                            return found
                elif isinstance(data, list):
                    for item in data:
                        found = _extract_connection_state(item)
                        if found:
                            return found
            except Exception:
                return None
            return None

        def _extract_connected_whatsapp_number(data):
            def _clean_number(value):
                raw = str(value or "").strip()
                if not raw:
                    return ""
                raw = raw.split("@", 1)[0].split(":", 1)[0].strip()
                digits = re.sub(r"\D", "", raw)
                return digits if len(digits) >= 7 else ""

            try:
                if isinstance(data, dict):
                    instance = data.get("instance")
                    if isinstance(instance, dict):
                        found = _extract_connected_whatsapp_number(instance)
                        if found:
                            return found
                    for key in ("number", "phoneNumber", "ownerJid", "wuid", "jid", "remoteJid", "id"):
                        found = _clean_number(data.get(key))
                        if found:
                            return found
                    for value in data.values():
                        found = _extract_connected_whatsapp_number(value)
                        if found:
                            return found
                elif isinstance(data, list):
                    for item in data:
                        found = _extract_connected_whatsapp_number(item)
                        if found:
                            return found
            except Exception:
                return ""
            return ""

        def _map_evolution_state_to_ui(state, qr_data_url=None):
            raw = str(state or "").strip().lower()
            if raw in ("open", "connected"):
                return "connected"
            if qr_data_url or raw in ("connecting", "qr", "qrcode", "pairing"):
                return "pending_qr"
            if raw in ("close", "closed", "disconnected", "logout", "not_connected", ""):
                return "not_connected"
            return "error"

        def _payload_text(data):
            try:
                if isinstance(data, dict):
                    return json.dumps(data, ensure_ascii=False)
                if isinstance(data, list):
                    return json.dumps(data, ensure_ascii=False)
            except Exception:
                pass
            return str(data or "")

        def _is_ok_or_existing_instance_response(status_code, payload):
            if int(status_code or 0) < 400:
                return True
            text = _payload_text(payload).lower()
            return (
                "already exists" in text
                or "instance already exists" in text
                or "already in use" in text
                or "name already in use" in text
            )

        def _evolution_request(method, cfg, path, json_body=None, timeout=40):
            base_url = _normalize_base_url((cfg or {}).get("providerBaseUrl"))
            if not base_url:
                raise Exception("Evolution API base URL is missing")
            url = f"{base_url}{path if str(path).startswith('/') else '/' + str(path)}"
            
            max_retries = 3
            attempt = 0
            while attempt < max_retries:
                try:
                    response = requests.request(
                        method=method.upper(),
                        url=url,
                        headers=_evolution_headers(cfg),
                        json=json_body,
                        timeout=timeout,
                    )
                    try:
                        payload = response.json()
                    except Exception:
                        payload = {"raw_text": response.text}
                    return response.status_code, payload
                except requests.exceptions.ReadTimeout as e:
                    attempt += 1
                    logging.warning(f"Evolution API Read timeout on attempt {attempt}/{max_retries} for {url}")
                    if attempt >= max_retries:
                        raise e
                    time.sleep(2)
                except requests.exceptions.RequestException as e:
                    attempt += 1
                    logging.warning(f"Evolution API RequestException on attempt {attempt}/{max_retries} for {url}: {e}")
                    if attempt >= max_retries:
                        raise e
                    time.sleep(2)

        def _fetch_evolution_instance_metadata(cfg, instance_name):
            name = str(instance_name or "").strip()
            if not name:
                return None
            query = urlencode({"instanceName": name})
            status_code, payload = _evolution_request("GET", cfg, f"/instance/fetchInstances?{query}", timeout=15)
            if int(status_code or 0) >= 400:
                return None
            if isinstance(payload, list):
                for item in payload:
                    if str((item or {}).get("name") or (item or {}).get("instanceName") or "").strip() == name:
                        return item
                return payload[0] if payload else None
            if isinstance(payload, dict):
                return payload
            return None

        def _extract_evolution_message_text(data):
            try:
                if isinstance(data, dict):
                    # Check for audio message (Evolution API format)
                    audio_message = data.get("audioMessage")
                    if isinstance(audio_message, dict):
                        import json
                        try:
                            # Instead of using the raw E2E encrypted URL, we pass the whole data object
                            # to be sent to getBase64FromMediaMessage endpoint
                            return f"__AUDIO_EVOLUTION_MSG__:{json.dumps(data, ensure_ascii=False)}"
                        except Exception as e:
                            logging.error(f"Error handling internal audio message: {e}")
                            return "[Audio Message: Failed to process]"

                    conversation = data.get("conversation")
                    if isinstance(conversation, str) and conversation.strip():
                        return conversation.strip()
                    ext_text = data.get("extendedTextMessage") or data.get("extendedText")
                    if isinstance(ext_text, dict):
                        text = ext_text.get("text")
                        if isinstance(text, str) and text.strip():
                            return text.strip()
                    for key in ("text", "caption", "body", "message"):
                        value = data.get(key)
                        if isinstance(value, str) and value.strip():
                            return value.strip()
                    for value in data.values():
                        found = _extract_evolution_message_text(value)
                        if found:
                            return found
                elif isinstance(data, list):
                    for item in data:
                        found = _extract_evolution_message_text(item)
                        if found:
                            return found
            except Exception:
                return ""
            return ""

        def _extract_evolution_remote_jid(data):
            try:
                if isinstance(data, dict):
                    key_obj = data.get("key")
                    if isinstance(key_obj, dict):
                        remote_jid = key_obj.get("remoteJid") or key_obj.get("participant")
                        if isinstance(remote_jid, str) and remote_jid.strip():
                            return remote_jid.strip()
                    for key in ("remoteJid", "jid", "participant", "sender"):
                        value = data.get(key)
                        if isinstance(value, str) and value.strip():
                            return value.strip()
                    for value in data.values():
                        found = _extract_evolution_remote_jid(value)
                        if found:
                            return found
                elif isinstance(data, list):
                    for item in data:
                        found = _extract_evolution_remote_jid(item)
                        if found:
                            return found
            except Exception:
                return ""
            return ""

        def _extract_evolution_message_id(data):
            try:
                if isinstance(data, dict):
                    key_obj = data.get("key")
                    if isinstance(key_obj, dict):
                        msg_id = key_obj.get("id")
                        if isinstance(msg_id, str) and msg_id.strip():
                            return msg_id.strip()
                    for key in ("id", "messageId"):
                        value = data.get(key)
                        if isinstance(value, str) and value.strip():
                            return value.strip()
                    for value in data.values():
                        found = _extract_evolution_message_id(value)
                        if found:
                            return found
                elif isinstance(data, list):
                    for item in data:
                        found = _extract_evolution_message_id(item)
                        if found:
                            return found
            except Exception:
                return ""
            return ""

        def _extract_evolution_from_me(data):
            try:
                if isinstance(data, dict):
                    key_obj = data.get("key")
                    if isinstance(key_obj, dict) and "fromMe" in key_obj:
                        return bool(key_obj.get("fromMe"))
                    if "fromMe" in data:
                        return bool(data.get("fromMe"))
                    for value in data.values():
                        nested = _extract_evolution_from_me(value)
                        if nested is not None:
                            return nested
                elif isinstance(data, list):
                    for item in data:
                        nested = _extract_evolution_from_me(item)
                        if nested is not None:
                            return nested
            except Exception:
                return None
            return None

        def _send_internal_whatsapp_text(text, recipient_phone, cfg=None):
            message_text = str(text or "").strip()
            to_phone = re.sub(r"\D", "", str(recipient_phone or ""))
            if not message_text or not to_phone:
                return False, "missing_text_or_phone"
            cfg = dict(cfg or _load_internal_whatsapp_config())
            if not str(cfg.get("instanceName") or "").strip():
                return False, "missing_instance_name"
            try:
                #region debug-point internal-worker-timeout.send_text_start
                _dbg_report(
                    "internal.send_text.start",
                    to_phone=to_phone,
                    text_preview=message_text[:200],
                    instance_name=str(cfg.get("instanceName") or "").strip(),
                    provider_base_url=str(cfg.get("providerBaseUrl") or "").strip(),
                )
                #endregion
                if bool(cfg.get("useInternalEvolutionService", True)):
                    _ensure_embedded_evolution_service_running()
                path = f"/message/sendText/{quote(str(cfg.get('instanceName') or '').strip())}"
                status_code, payload = _evolution_request(
                    "POST",
                    cfg,
                    path,
                    json_body={
                        "number": to_phone,
                        "text": message_text,
                    },
                    timeout=20,
                )
                #region debug-point internal-worker-timeout.send_text_result
                _dbg_report(
                    "internal.send_text.result",
                    to_phone=to_phone,
                    status_code=int(status_code or 0),
                    ok=bool(int(status_code or 0) < 400),
                    payload_preview=_payload_text(payload)[:600],
                )
                #endregion
                if int(status_code or 0) >= 400:
                    return False, _payload_text(payload)
                return True, payload
            except Exception as e:
                #region debug-point internal-worker-timeout.send_text_exception
                _dbg_report(
                    "internal.send_text.exception",
                    to_phone=to_phone,
                    error_type=type(e).__name__,
                    error=str(e),
                )
                #endregion
                logging.error(f"Failed to send internal WhatsApp text to {to_phone}: {e}", exc_info=True)
                return False, str(e)

        def _truncate_internal_button_text(value, max_len=20):
            text = " ".join(str(value or "").split()).strip()
            if not text:
                return ""
            if len(text) <= max_len:
                return text
            if max_len <= 3:
                return text[:max_len]
            return text[: max_len - 3].rstrip() + "..."

        def _send_internal_whatsapp_buttons(title, recipient_phone, buttons, description="", footer="", cfg=None):
            to_phone = re.sub(r"\D", "", str(recipient_phone or ""))
            title = str(title or "").strip()
            description = str(description or "").strip()
            footer = str(footer or "").strip()
            if not to_phone:
                return False, "missing_phone"
            cfg = dict(cfg or _load_internal_whatsapp_config())
            if not str(cfg.get("instanceName") or "").strip():
                return False, "missing_instance_name"

            safe_buttons = []
            for idx, item in enumerate(list(buttons or [])[:3], start=1):
                if not isinstance(item, dict):
                    continue
                button_type = str(item.get("type") or "reply").strip().lower()
                display_text = _truncate_internal_button_text(item.get("displayText") or item.get("title") or f"Option {idx}")
                if button_type == "url":
                    url = str(item.get("url") or "").strip()
                    if not url:
                        continue
                    safe_buttons.append({
                        "type": "url",
                        "displayText": display_text or "Open Link",
                        "url": url,
                    })
                    continue
                if button_type == "call":
                    phone_number = re.sub(r"\D", "", str(item.get("phoneNumber") or ""))
                    if not phone_number:
                        continue
                    safe_buttons.append({
                        "type": "call",
                        "displayText": display_text or "Call",
                        "phoneNumber": phone_number,
                    })
                    continue

                button_id = str(item.get("id") or display_text or f"option_{idx}").strip()
                button_id = re.sub(r"[^A-Za-z0-9_.:-]+", "_", button_id)[:64] or f"option_{idx}"
                safe_buttons.append({
                    "type": "reply",
                    "displayText": display_text or f"Option {idx}",
                    "id": button_id,
                })

            if not safe_buttons:
                return False, "missing_buttons"

            try:
                if bool(cfg.get("useInternalEvolutionService", True)):
                    _ensure_embedded_evolution_service_running()
                path = f"/message/sendButtons/{quote(str(cfg.get('instanceName') or '').strip())}"
                # #region debug-point A:send-buttons-request
                exec("import json as _dj, urllib.request as _ur; _p='.dbg/whatsapp-buttons-fallback.env'; _u='http://127.0.0.1:7777/event'; _s='whatsapp-buttons-fallback';\ntry:\n _c=open(_p,'r',encoding='utf-8').read(); _u=next((l.split('=',1)[1].strip() for l in _c.split('\\n') if l.startswith('DEBUG_SERVER_URL=')),_u); _s=next((l.split('=',1)[1].strip() for l in _c.split('\\n') if l.startswith('DEBUG_SESSION_ID=')),_s); _ur.urlopen(_ur.Request(_u, data=_dj.dumps({'sessionId':_s,'runId':'pre','hypothesisId':'A','location':'ai_agent.py:_send_internal_whatsapp_buttons:before_request','msg':'[DEBUG] About to call sendButtons','data':{'instanceName':str(cfg.get('instanceName') or ''),'path':path,'buttonCount':len(safe_buttons),'buttonTypes':[str((b or {}).get('type') or '') for b in safe_buttons],'buttonIds':[str((b or {}).get('id') or '') for b in safe_buttons],'phoneSuffix':to_phone[-4:]},'ts':__import__('time').time_ns()//1000000}).encode(), headers={'Content-Type':'application/json'}), timeout=2).read()\nexcept Exception:\n pass")
                # #endregion
                status_code, payload = _evolution_request(
                    "POST",
                    cfg,
                    path,
                    json_body={
                        "number": to_phone,
                        "title": title or "FTS Internal Assistant",
                        "description": description,
                        "footer": footer,
                        "buttons": safe_buttons,
                    },
                    timeout=20,
                )
                # #region debug-point B:send-buttons-response
                exec("import json as _dj, urllib.request as _ur; _p='.dbg/whatsapp-buttons-fallback.env'; _u='http://127.0.0.1:7777/event'; _s='whatsapp-buttons-fallback';\ntry:\n _c=open(_p,'r',encoding='utf-8').read(); _u=next((l.split('=',1)[1].strip() for l in _c.split('\\n') if l.startswith('DEBUG_SERVER_URL=')),_u); _s=next((l.split('=',1)[1].strip() for l in _c.split('\\n') if l.startswith('DEBUG_SESSION_ID=')),_s); _pt=str(_payload_text(payload) or ''); _ur.urlopen(_ur.Request(_u, data=_dj.dumps({'sessionId':_s,'runId':'pre','hypothesisId':'B','location':'ai_agent.py:_send_internal_whatsapp_buttons:after_request','msg':'[DEBUG] sendButtons returned response','data':{'statusCode':int(status_code or 0),'payloadPreview':_pt[:800],'ok':int(status_code or 0) < 400},'ts':__import__('time').time_ns()//1000000}).encode(), headers={'Content-Type':'application/json'}), timeout=2).read()\nexcept Exception:\n pass")
                # #endregion
                if int(status_code or 0) >= 400:
                    return False, _payload_text(payload)
                return True, payload
            except Exception as e:
                # #region debug-point E:send-buttons-exception
                exec("import json as _dj, urllib.request as _ur; _p='.dbg/whatsapp-buttons-fallback.env'; _u='http://127.0.0.1:7777/event'; _s='whatsapp-buttons-fallback';\ntry:\n _c=open(_p,'r',encoding='utf-8').read(); _u=next((l.split('=',1)[1].strip() for l in _c.split('\\n') if l.startswith('DEBUG_SERVER_URL=')),_u); _s=next((l.split('=',1)[1].strip() for l in _c.split('\\n') if l.startswith('DEBUG_SESSION_ID=')),_s); _ur.urlopen(_ur.Request(_u, data=_dj.dumps({'sessionId':_s,'runId':'pre','hypothesisId':'E','location':'ai_agent.py:_send_internal_whatsapp_buttons:exception','msg':'[DEBUG] sendButtons raised exception','data':{'error':str(e)},'ts':__import__('time').time_ns()//1000000}).encode(), headers={'Content-Type':'application/json'}), timeout=2).read()\nexcept Exception:\n pass")
                # #endregion
                logging.error(f"Failed to send internal WhatsApp buttons to {to_phone}: {e}", exc_info=True)
                return False, str(e)

        def _send_internal_whatsapp_response(response_payload, recipient_phone, cfg=None):
            if isinstance(response_payload, dict):
                buttons = list(response_payload.get("buttons") or [])
                prelude_text = str(response_payload.get("prelude_text") or "").strip()
                title_text = str(response_payload.get("title") or "").strip()
                description_text = str(response_payload.get("description") or "").strip()
                footer_text = str(response_payload.get("footer") or "").strip()
                fallback_text = str(
                    response_payload.get("fallback_text")
                    or response_payload.get("description")
                    or response_payload.get("title")
                    or ""
                ).strip()
                text_parts = []
                if prelude_text:
                    text_parts.append(prelude_text)
                elif fallback_text:
                    text_parts.append(fallback_text)
                else:
                    base_lines = []
                    if title_text:
                        base_lines.append(title_text)
                    if description_text and description_text != title_text:
                        base_lines.append(description_text)
                    if footer_text and footer_text not in base_lines:
                        base_lines.append(footer_text)
                    if base_lines:
                        text_parts.append("\n".join(base_lines))

                option_lines = []
                for item in buttons:
                    if not isinstance(item, dict):
                        continue
                    button_type = str(item.get("type") or "reply").strip().lower()
                    display_text = " ".join(str(item.get("displayText") or item.get("title") or "").split()).strip()
                    button_id = str(item.get("id") or "").strip()
                    if button_type == "reply":
                        if display_text and button_id and button_id.lower() != display_text.lower():
                            option_lines.append(f"- {display_text}: اكتب {button_id}")
                        elif display_text:
                            option_lines.append(f"- {display_text}")
                        elif button_id:
                            option_lines.append(f"- {button_id}")
                        continue
                    if button_type == "url":
                        url = str(item.get("url") or "").strip()
                        if display_text and url:
                            option_lines.append(f"- {display_text}: {url}")
                        elif url:
                            option_lines.append(f"- {url}")
                        continue
                    if button_type == "call":
                        phone_number = re.sub(r"\D", "", str(item.get("phoneNumber") or ""))
                        if display_text and phone_number:
                            option_lines.append(f"- {display_text}: +{phone_number}")
                        elif phone_number:
                            option_lines.append(f"- +{phone_number}")
                        continue
                    if display_text and button_id and button_id.lower() != display_text.lower():
                        option_lines.append(f"- {display_text}: اكتب {button_id}")
                    elif display_text:
                        option_lines.append(f"- {display_text}")
                    elif button_id:
                        option_lines.append(f"- {button_id}")

                if option_lines:
                    text_parts.append("\n".join(option_lines))
                elif fallback_text and fallback_text not in text_parts:
                    text_parts.append(fallback_text)

                final_text = "\n\n".join([part for part in text_parts if str(part or "").strip()]).strip()
                if not final_text:
                    return False, "empty_response_payload"
                return _send_internal_whatsapp_text(final_text, recipient_phone, cfg=cfg)
            return _send_internal_whatsapp_text(response_payload, recipient_phone, cfg=cfg)

        def _normalize_lookup_term(term):
            raw = str(term or "").strip()
            digits = re.sub(r"\D", "", raw)
            if digits:
                return digits
            return raw.strip()

        def _run_pi_cli(prompt, session_id="internal-assistant", messages=None, timeout=300):
            import subprocess
            import shutil

            prompt = str(prompt or "").strip()
            if not prompt:
                return {"status": "error", "message": "Prompt is required", "output": "", "error_output": ""}

            env = os.environ.copy()
            try:
                config_path = os.path.join(SCRIPT_DIR, get_data_path(get_data_path('config.json')))
                with open(config_path, 'r', encoding='utf-8') as f:
                    config_data = json.load(f)
                ai_providers = config_data.get('ai', {}).get('providers', {})
                openai_key = ai_providers.get('openai', {}).get('api_key')
                if openai_key:
                    env['OPENAI_API_KEY'] = openai_key
                deepseek_key = ai_providers.get('deepseek', {}).get('api_key')
                if deepseek_key:
                    env['DEEPSEEK_API_KEY'] = deepseek_key
            except Exception as e:
                logging.warning(f"Failed to load API keys for PI helper: {e}")

            session_dir = os.path.join(SCRIPT_DIR, "pi_sessions")
            os.makedirs(session_dir, exist_ok=True)
            safe_session_id = re.sub(r'[^A-Za-z0-9._-]', '_', str(session_id or "internal-assistant"))
            session_file = os.path.join(session_dir, f"{safe_session_id}.jsonl")

            pi_executable = shutil.which("pi.cmd") or shutil.which("pi")
            if not pi_executable:
                return {
                    "status": "error",
                    "message": "PI CLI executable was not found in PATH. Expected pi.cmd or pi.",
                    "output": "",
                    "error_output": "",
                }

            provider = "deepseek"
            model = "deepseek-chat"
            full_prompt = prompt
            if messages and isinstance(messages, list) and len(messages) > 1:
                context_parts = []
                for msg in messages[:-1]:
                    role = msg.get("role", "user")
                    content = msg.get("content", "")
                    if role == "user":
                        context_parts.append(f"User: {content}")
                    elif role in ("ai", "assistant"):
                        context_parts.append(f"Assistant: {content}")
                if context_parts:
                    full_prompt = (
                        "[Conversation Context]\n"
                        + "\n".join(context_parts)
                        + f"\n\n[Current Message]\nUser: {prompt}"
                    )

            if os.path.exists(session_file):
                full_prompt = f"{prompt}\n\n[System Note: Read the user's message carefully and preserve context.]"

            instructions_path = os.path.join(SCRIPT_DIR, "PI_AGENT_INSTRUCTIONS.md")
            pi_command = [pi_executable, "--mode", "json", "--provider", provider, "--model", model]
            if os.path.exists(instructions_path):
                pi_command.extend(["--append-system-prompt", instructions_path])
            
            # Write prompt to temp file to avoid Windows command line length limits
            temp_prompt_file = os.path.join(session_dir, f"{safe_session_id}_prompt.txt")
            with open(temp_prompt_file, "w", encoding="utf-8") as f:
                f.write(full_prompt)

            pi_command.extend([
                "--session", session_file, 
                "-p", 
                f"@{temp_prompt_file}",
                "Please read the attached file and execute the request exactly as instructed."
            ])

            try:
                process = subprocess.Popen(
                    pi_command,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    shell=False,
                    cwd=SCRIPT_DIR,
                    env=env,
                    encoding='utf-8',
                    errors='replace'
                )
                stdout_text, stderr_text = process.communicate(timeout=timeout)
            except subprocess.TimeoutExpired:
                try:
                    process.kill()
                except Exception:
                    pass
                return {"status": "error", "message": "PI command timed out", "output": "", "error_output": ""}
            except Exception as e:
                return {"status": "error", "message": str(e), "output": "", "error_output": ""}
            finally:
                # Cleanup temp prompt file
                try:
                    if os.path.exists(temp_prompt_file):
                        os.remove(temp_prompt_file)
                except Exception:
                    pass

            final_answer = ""
            error_message = ""
            if stdout_text:
                for line in stdout_text.split('\n'):
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        event = json.loads(line)
                        if event.get("type") in ["message_end", "turn_end", "agent_end"]:
                            msg_data = event.get("message", {}) or {}
                            if "errorMessage" in msg_data:
                                error_message = msg_data["errorMessage"]
                            if "messages" in event:
                                for msg in event["messages"]:
                                    if "errorMessage" in msg:
                                        error_message = msg["errorMessage"]
                        if event.get("type") == "agent_end" and "messages" in event:
                            messages_arr = event["messages"]
                            if messages_arr:
                                last_msg = messages_arr[-1]
                                if last_msg.get("role") == "assistant" and "content" in last_msg:
                                    for content_block in last_msg["content"]:
                                        if content_block.get("type") == "text":
                                            final_answer += content_block.get("text", "")
                    except Exception:
                        continue

            if not final_answer:
                if error_message:
                    final_answer = error_message
                elif stdout_text and not stdout_text.startswith('{'):
                    final_answer = stdout_text.strip()
                elif stderr_text:
                    final_answer = stderr_text.strip()

            return {
                "status": "success" if final_answer else "error",
                "message": error_message or "",
                "output": str(final_answer or "").strip(),
                "error_output": str(stderr_text or "").strip(),
            }

        def _normalize_internal_intent_text(text):
            txt = " ".join(str(text or "").strip().lower().split())
            replacements = {
                "عاوز": "اريد",
                "عايز": "اريد",
                "عايزك": "اريد منك",
                "عاوزك": "اريد منك",
                "محتاج": "اريد",
                "محتاجة": "اريد",
                "ايه": "ما",
                "إيه": "ما",
                "ايه الخطوة": "ما الخطوة",
                "ازاي": "كيف",
                "إزاي": "كيف",
                "ليه": "لماذا",
                "لـيه": "لماذا",
                "قولي": "اخبرني",
                "قلّي": "اخبرني",
                "فهمني": "اشرح لي",
                "وريني": "اعرض لي",
                "هاتلي": "اعرض لي",
                "هات": "اعرض",
                "بعت": "ارسل",
                "ابعت": "ارسل",
                "ابعتلي": "ارسل لي",
                "ابعتلى": "ارسل لي",
                "ابعتله": "ارسل له",
                "شوف": "افحص",
                "بص": "افحص",
                "عاوز افهم": "اريد شرح",
                "عايز افهم": "اريد شرح",
                "مش فاهم": "احتاج شرح",
            }
            for src, dst in replacements.items():
                txt = txt.replace(src, dst)
            return txt

        def _is_explicit_pi_request(text):
            txt = _normalize_internal_intent_text(text)
            markers = [
                "pi:",
                "pi ",
                "with pi",
                "using pi",
                "ب pi",
                "بـ pi",
                "شغل pi",
                "شغّل pi",
                "استدعي pi",
                "استدعاء pi",
                "حلل ب pi",
                "حللها ب pi",
                "pi حلل",
                "pi analyze",
            ]
            return any(marker in txt for marker in markers)

        def _should_delegate_internal_to_pi(intent, text, has_booking_context=False, actor=None):
            decision = _resolve_internal_intent_policy(
                intent,
                actor=actor or {},
                text=text,
                has_booking_context=has_booking_context,
            )
            return str(decision.get("executor") or "").strip().lower() == "pi"

