        def _internal_intent_policy_matrix():
            cfg = _internal_assistant_config()
            policy = dict(cfg.get("policy") or {})
            matrix = policy.get("intent_matrix") or {}
            if not isinstance(matrix, dict):
                matrix = {}
            defaults = {
                "booking_summary": {"executor": "local", "approval_required": False},
                "problems_diagnostics": {"executor": "local", "approval_required": False},
                "draft_reply": {"executor": "hybrid", "approval_required": False},
                "next_step": {"executor": "hybrid", "approval_required": False},
                "set_needshelp": {"executor": "local", "approval_required": False},
                "general_qa": {"executor": "hybrid", "approval_required": False},
                "send_customer_message": {"executor": "approval", "approval_required": True},
                "update_airtable": {"executor": "approval", "approval_required": True},
                "transfer_chat": {"executor": "approval", "approval_required": True},
                "create_invoice": {"executor": "approval", "approval_required": True},
                "add_watcher": {"executor": "pi", "approval_required": False},
            }
            merged = {}
            for key, value in defaults.items():
                item = dict(value)
                override = matrix.get(key)
                if isinstance(override, dict):
                    item.update(override)
                merged[key] = item
            return merged

        def _resolve_internal_intent_policy(intent, actor=None, text=None, has_booking_context=False):
            actor = actor or {}
            matrix = _internal_intent_policy_matrix()
            decision = dict(matrix.get(intent) or {"executor": "local", "approval_required": False})
            executor = str(decision.get("executor") or "local").strip().lower()
            approval_required = bool(decision.get("approval_required"))

            txt = _normalize_internal_intent_text(text)
            explicit_pi_request = _is_explicit_pi_request(text)
            complex_terms = [
                "analyze", "analysis", "compare", "why", "root cause", "workflow", "process", "plan", "strategy",
                "build", "design", "improve", "investigate", "report", "policy", "explain deeply", "operational brain",
                "حلل", "تحليل", "قارن", "ليه", "لماذا", "سبب", "خطة", "استراتيجية", "ورك فلو", "workflow",
                "عملية", "بروسيس", "صمم", "ابني", "طور", "حسن", "تقرير", "سياسة", "اشرح بالتفصيل",
                "اشرح", "اشرح لي", "افهم", "اريد شرح", "احتاج شرح", "فهمني", "وضح", "وضحلي", "وضح لي",
                "كيف", "ما الخطوة", "ما الأفضل", "افضل حل", "أفضل حل", "ايه الافضل", "ما السبب", "اشمعنى"
            ]
            if explicit_pi_request and executor in {"hybrid", "local"}:
                executor = "pi"
            if executor == "hybrid":
                if any(term in txt for term in complex_terms):
                    executor = "pi"
                elif intent == "general_qa" and len(txt) >= 80:
                    executor = "pi"
                elif has_booking_context and intent in ("draft_reply", "next_step") and len(txt) >= 30:
                    executor = "pi"
                else:
                    executor = "local"

            return {
                "intent": intent,
                "executor": executor,
                "approval_required": approval_required,
                "actor_role": str(actor.get("role") or "").strip().lower(),
            }

        def _match_internal_actor_by_phone(phone_digits):
            target = re.sub(r"\D", "", str(phone_digits or ""))
            if not target:
                return None
            try:
                users_list = _load_dashboard_users_list()
                if isinstance(users_list, list):
                    for user_obj in users_list:
                        if not isinstance(user_obj, dict):
                            continue
                        candidate = re.sub(r"\D", "", str(user_obj.get("toolPhone") or user_obj.get("phone") or ""))
                        if candidate and candidate == target:
                            username = str(user_obj.get("username") or "").strip()
                            return {
                                "name": str(user_obj.get("name") or username or target).strip(),
                                "role": str(user_obj.get("role") or "Agent").strip().lower(),
                                "phone": candidate,
                                "username": username,
                                "allowed_locations": list(user_obj.get("allowedLocations") or ["NeedHelp"]),
                                "allowIntents": [str(x).strip() for x in (user_obj.get("allowIntents") or []) if str(x).strip()][:40],
                            }
            except Exception:
                pass
            assistant_cfg = _internal_assistant_config()
            for actor in assistant_cfg.get("adminUsers") or []:
                actor_phone = re.sub(r"\D", "", str((actor or {}).get("phone") or ""))
                if actor_phone and actor_phone == target:
                    return {
                        "name": str((actor or {}).get("name") or "Admin Manager"),
                        "role": str((actor or {}).get("role") or "admin_manager"),
                        "phone": actor_phone,
                        "username": str((actor or {}).get("username") or ""),
                        "allowed_locations": list((actor or {}).get("allowed_locations") or ["All"]),
                        "allowIntents": [],
                    }
            return None

        def _search_customer_context_by_term(term):
            search_term = str(term or "").strip()
            if not search_term:
                return {"matches": [], "query": ""}

            import requests
            from airtable_fields import TABLE_NAME, FieldIds, ID_TO_READABLE_NAME

            query_term = search_term
            normalized_digits = re.sub(r"\D", "", search_term)
            term_lower = search_term.lower()

            def _formula_string(value):
                return "'" + str(value or "").replace("\\", "\\\\").replace("'", "\\'") + "'"

            def _formula_field(field_id):
                return "{" + str(ID_TO_READABLE_NAME.get(field_id, field_id)) + "}"

            booking_field = _formula_field(FieldIds.BOOKING_NR)
            email_field = _formula_field(FieldIds.CUSTOMER_EMAIL)
            personal_email_field = _formula_field(FieldIds.CUSTOMER_PERSONAL_EMAIL)
            phone_field = _formula_field(FieldIds.CUSTOMER_PHONE)
            name_field = _formula_field(FieldIds.CUSTOMER_NAME)
            headers = {"Authorization": f"Bearer {self.config['airtable']['api_key']}"}
            normalized_phone_formula = (
                f"SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE({phone_field}, ' ', ''), '-', ''), '+', ''), '(', ''), ')', '')"
            )

            booking_candidates = []
            try:
                booking_candidates = [str(code or "").strip() for code, _confidence in self.extract_booking_numbers_regex(search_term) if str(code or "").strip()]
            except Exception:
                booking_candidates = []
            if search_term and not self._is_placeholder_booking_number(search_term) and re.fullmatch(r"[A-Za-z0-9-]{5,20}", search_term):
                if search_term not in booking_candidates:
                    booking_candidates.insert(0, search_term)

            def _records_to_matches(records):
                out = []
                for rec in records:
                    fields = rec.get("fields", {}) or {}
                    booking_nr = self.get_field_value(fields, FieldIds.BOOKING_NR) or ""
                    name = self.get_field_value(fields, FieldIds.CUSTOMER_NAME) or "Unknown Customer"
                    email = self.get_field_value(fields, FieldIds.CUSTOMER_EMAIL) or self.get_field_value(fields, FieldIds.CUSTOMER_PERSONAL_EMAIL) or ""
                    phone = self.get_field_value(fields, FieldIds.CUSTOMER_PHONE) or ""
                    location = self.get_field_value(fields, FieldIds.FROM_LOC) or "Unknown"
                    out.append(
                        {
                            "record_id": rec.get("id"),
                            "booking_number": booking_nr,
                            "customer_name": name,
                            "email": email,
                            "phone": phone,
                            "location": location,
                        }
                    )
                return out

            email_candidates = []
            phone_candidates = []
            try:
                email_candidates = [str(x or "").strip().lower() for x in self.extract_emails_regex(search_term) if str(x or "").strip()]
            except Exception:
                email_candidates = []
            try:
                phone_candidates = [str(x or "").strip() for x in self.extract_phones_regex(search_term) if str(x or "").strip()]
            except Exception:
                phone_candidates = []

            for candidate in booking_candidates[:3]:
                candidate_lower = str(candidate).strip().lower()
                if not candidate_lower:
                    continue
                exact_booking_formula = f"LOWER(TRIM({booking_field}))={_formula_string(candidate_lower)}"
                exact_response = requests.get(
                    f"https://api.airtable.com/v0/{self.config['airtable']['base_id']}/{TABLE_NAME}",
                    headers=headers,
                    params={"filterByFormula": exact_booking_formula, "maxRecords": 5},
                    timeout=15,
                )
                exact_response.raise_for_status()
                exact_records = exact_response.json().get("records", []) or []
                if exact_records:
                    return {"matches": _records_to_matches(exact_records), "query": candidate}

            for candidate_email in email_candidates[:3]:
                if not candidate_email:
                    continue
                exact_email_formula = (
                    f"OR(LOWER(TRIM({email_field}))={_formula_string(candidate_email)},"
                    f"LOWER(TRIM({personal_email_field}))={_formula_string(candidate_email)})"
                )
                email_response = requests.get(
                    f"https://api.airtable.com/v0/{self.config['airtable']['base_id']}/{TABLE_NAME}",
                    headers=headers,
                    params={"filterByFormula": exact_email_formula, "maxRecords": 5},
                    timeout=15,
                )
                email_response.raise_for_status()
                email_records = email_response.json().get("records", []) or []
                if email_records:
                    return {"matches": _records_to_matches(email_records), "query": candidate_email}

            for candidate_phone in phone_candidates[:3]:
                normalized_phone = re.sub(r"\D", "", candidate_phone)
                if not normalized_phone:
                    continue
                exact_phone_formula = f"FIND({_formula_string(normalized_phone)}, {normalized_phone_formula})"
                phone_response = requests.get(
                    f"https://api.airtable.com/v0/{self.config['airtable']['base_id']}/{TABLE_NAME}",
                    headers=headers,
                    params={"filterByFormula": exact_phone_formula, "maxRecords": 5},
                    timeout=15,
                )
                phone_response.raise_for_status()
                phone_records = phone_response.json().get("records", []) or []
                if phone_records:
                    return {"matches": _records_to_matches(phone_records), "query": candidate_phone}

            formula_parts = [
                f"LOWER(TRIM({booking_field}))={_formula_string(term_lower)}",
                f"LOWER(TRIM({email_field}))={_formula_string(term_lower)}",
                f"LOWER(TRIM({personal_email_field}))={_formula_string(term_lower)}",
                f"LOWER(TRIM({name_field}))={_formula_string(term_lower)}",
                f"FIND({_formula_string(search_term)}, {phone_field})",
            ]
            if normalized_digits:
                formula_parts.append(f"FIND({_formula_string(normalized_digits)}, {normalized_phone_formula})")

            formula = f"OR({','.join(formula_parts)})"
            response = requests.get(
                f"https://api.airtable.com/v0/{self.config['airtable']['base_id']}/{TABLE_NAME}",
                headers=headers,
                params={"filterByFormula": formula, "maxRecords": 5},
                timeout=15,
            )
            response.raise_for_status()
            records = response.json().get("records", []) or []
            return {"matches": _records_to_matches(records), "query": search_term}

