            try:
                import time as _time
                _t0 = _time.time()
                limit = request.args.get("limit")
                offset = request.args.get("offset")
                location = request.args.get("location")
                include_unknown = request.args.get("include_unknown")
                needs_help = request.args.get("needs_help")
                sales_only = request.args.get("sales")
                source = request.args.get("source")
                exclude_source = request.args.get("exclude_source")
                chat_id = request.args.get("chat_id")
                include_deleted = request.args.get("include_deleted")
                trash = request.args.get("trash")
                actor_id = request.args.get("actor_id")
                ad_id = request.args.get("ad_id")

                if location and str(location).strip().lower() in ["all", "any", "none"]:
                    location = None

                # Extract Religious Agent Constraints
                dedicated_whatsapp = None
                assigned_to = None
                if location == "Religious" and actor_id:
                    users_raw = chat_db.get_setting("dashboard_users")
                    if users_raw:
                        import json
                        try:
                            users = json.loads(users_raw)
                            for u in users:
                                if str(u.get('id')) == str(actor_id):
                                    if u.get('role') != 'Admin':
                                        assigned_to = [str(actor_id)]
                                        if u.get('username'):
                                            assigned_to.append(str(u.get('username')))
                                        dedicated_whatsapp = u.get('dedicatedWhatsApp')
                                    break
                        except Exception:
                            pass

                page = chat_db.get_conversations_page(
                    limit=limit,
                    offset=offset,
                    location=location,
                    include_unknown=include_unknown,
                    needs_help=needs_help,
                    sales_only=sales_only,
                    source=source,
                    exclude_source=exclude_source,
                    chat_id=chat_id,
                    include_deleted=include_deleted,
                    trash=trash,
                    assigned_to=assigned_to,
                    dedicated_whatsapp=dedicated_whatsapp,
                    ad_id=ad_id
                )
                items = page.get("items") or []
                pagination = {
                    "limit": page.get("limit"),
                    "offset": page.get("offset"),
                    "total": page.get("total"),
                    "has_more": (int(page.get("offset") or 0) + int(page.get("limit") or 0)) < int(page.get("total") or 0),
                }
                _dbg_post(
                    "api_get_chats",
                    {
                        "ms": int((_time.time() - _t0) * 1000),
                        "count": len(items) if isinstance(items, list) else None,
                        "limit": pagination.get("limit"),
                        "offset": pagination.get("offset"),
                        "total": pagination.get("total"),
                    },
                )
                return jsonify({"status": "success", "data": items, "pagination": pagination}), 200
            except Exception as e:
                logging.error(f"Error in /api/chats: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

