                res = chat_db.release_sales_lead(chat_id=chat_id, actor_user_id=str(actor_user_id), allow_any=allow_any)
                if res.get("ok"):
                    try:
                        chat_db.log_sales_activity(
                            chat_id=chat_id,
                            event_type="lead_released",
                            actor_user_id=str(actor_user_id),
                            actor_name=str(actor.get('name') or actor.get('username') or actor.get('user_name') or actor_user_id or ""),
                            meta={"by_admin": bool(allow_any)},
                        )
                    except Exception:
                        pass
                    try:
                        chat_db.upsert_sales_state(
                            chat_id=chat_id,
                            updates={
                                "assigned_sales_user": None,
                                "needs_ai_review": 1,
                            },
                        )
                    except Exception:
                        pass
                    return jsonify({"status": "success"}), 200
                return jsonify({"status": "error", "message": res.get("error")}), 403
