        @app.route('/api/sales/activity/list', methods=['POST', 'OPTIONS'])
        def api_sales_activity_list():
            if request.method == 'OPTIONS':
                return jsonify({"status": "success"}), 200
            try:
                data = request.json or {}
                chat_id = data.get('chat_id')
                actor = data.get('actor') or {}
                actor_role = str(actor.get('role') or "")
                if actor_role.lower() != "admin":
                    return jsonify({"status": "error", "message": "Forbidden"}), 403
                if not chat_id:
                    return jsonify({"status": "error", "message": "Missing chat_id"}), 400
                events = chat_db.get_sales_activity(chat_id=chat_id, limit=50)
                filtered = []
                for e in events:
                    try:
                        ev_actor_name = str(e.get("actor_name") or "")
                        ev_actor_user_id = str(e.get("actor_user_id") or "")
                        ev_meta = e.get("meta") or {}
                        ev_role = str(ev_meta.get("actor_role") or "")
                        if ev_role.lower() == "admin":
                            continue
                        if ev_actor_name.lower().startswith("admin") or ev_actor_user_id.lower().startswith("admin"):
                            continue
                        if "admin" in ev_actor_user_id.lower():
                            continue
                    except Exception:
                        pass
                    filtered.append(e)
                return jsonify({"status": "success", "data": filtered}), 200
            except Exception as e:
                logging.error(f"Error in /api/sales/activity/list: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

