        @app.route('/api/hr_audit/query', methods=['POST', 'OPTIONS'])
        def api_hr_audit_query():
            if request.method == 'OPTIONS':
                return jsonify({"status": "success"}), 200
            try:
                data = request.json or {}
                actor = data.get('actor') or {}
                actor_role = str(actor.get('role') or "")
                if actor_role.lower() != "admin":
                    return jsonify({"status": "error", "message": "Forbidden"}), 403
                
                actor_username = actor.get('username') or ""
                actor_allowed = []
                is_super_admin = False
                if actor_username:
                    val = chat_db.get_setting("dashboard_users")
                    if val:
                        import json
                        users = json.loads(val)
                        for u in users:
                            if u.get("username") == actor_username:
                                actor_allowed = u.get("allowedLocations") or []
                                if "All" in actor_allowed:
                                    is_super_admin = True
                                break

                actor_user_id = data.get('actor_user_id') or data.get('user_id') or None
                role_filter = data.get('role') or None
                start = data.get('from') or data.get('start') or None
                end = data.get('to') or data.get('end') or None
                sort = data.get('sort') or "desc"
                event_type = data.get('event_type') or data.get('event') or None
                q = data.get('q') or data.get('query') or None
                page = data.get('page') or 1
                page_size = data.get('page_size') or 50
                exclude_admin = data.get('exclude_admin')
                if exclude_admin is None:
                    exclude_admin = False
                else:
                    try:
                        exclude_admin = bool(int(exclude_admin))
                    except Exception:
                        exclude_admin = bool(exclude_admin)

                res = chat_db.query_hr_audit_activity(
                    actor_user_id=actor_user_id,
                    actor_role=role_filter,
                    start=start,
                    end=end,
                    sort=sort,
                    event_type=event_type,
                    q=q,
                    page=page,
                    page_size=page_size,
                    exclude_admin=bool(exclude_admin),
                )
                
                if not is_super_admin:
                    allowed_users = set()
                    if actor_username:
                        val = chat_db.get_setting("dashboard_users")
                        if val:
                            import json
                            users = json.loads(val)
                            for u in users:
                                if u.get("createdBy") == actor_username or u.get("username") == actor_username:
                                    allowed_users.add(u.get("username"))
                    
                    if "items" in res:
                        res["items"] = [item for item in res["items"] if item.get("actor_user_id") in allowed_users]
                        res["total"] = len(res["items"])

                return jsonify({"status": "success", "data": res}), 200
            except Exception as e:
                logging.error(f"Error in /api/hr_audit/query: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

