        _dashboard_perf_cache = {}
        _dashboard_perf_cache_lock = threading.Lock()
        _dashboard_perf_refreshing = set()
        _DASHBOARD_PERF_CACHE_FRESH_SECONDS = 60.0
        _DASHBOARD_PERF_CACHE_STALE_SECONDS = 15 * 60.0

        def _dashboard_perf_cache_key(target_user_id, range_key="today", all_employees=False):
            scope = "__all__" if all_employees else str(target_user_id or "")
            return f"{scope}::{str(range_key or 'today')}"

        def _dashboard_perf_clone_payload(payload):
            try:
                return json.loads(json.dumps(payload, ensure_ascii=False, default=str))
            except Exception:
                return payload

        def _dashboard_perf_cache_read(cache_key):
            now_ts = time.time()
            with _dashboard_perf_cache_lock:
                entry = _dashboard_perf_cache.get(cache_key)
                if not isinstance(entry, dict):
                    return None, False
                ts = float(entry.get("ts") or 0.0)
                payload = entry.get("payload")
                age = now_ts - ts
                if age > _DASHBOARD_PERF_CACHE_STALE_SECONDS:
                    _dashboard_perf_cache.pop(cache_key, None)
                    return None, False
                return _dashboard_perf_clone_payload(payload), age <= _DASHBOARD_PERF_CACHE_FRESH_SECONDS

        def _dashboard_perf_cache_write(cache_key, payload):
            with _dashboard_perf_cache_lock:
                _dashboard_perf_cache[cache_key] = {
                    "ts": time.time(),
                    "payload": _dashboard_perf_clone_payload(payload),
                }

        def _dashboard_perf_compute_payload(available_users, range_key="today", all_employees=False, target_user_id=None, target_user_name=None, include_available_users=False):
            if all_employees:
                payload = _dashboard_build_all_employees_payload(available_users, range_key=range_key)
                if include_available_users:
                    payload["available_users"] = available_users
                    payload["selected_user_id"] = "__all__"
                return payload

            payload = chat_db.compute_employee_dashboard_data(target_user_id, actor_name=target_user_name, range_key=range_key)
            if payload is None:
                return None

            payload = _dashboard_enrich_employee_payload(
                payload,
                include_ai_summary=True,
                include_samples=True,
                max_assessment_samples=None,
            )
            if include_available_users:
                payload["available_users"] = available_users
                payload["selected_user_id"] = str(target_user_id)
            return payload

        def _dashboard_perf_refresh_async(cache_key, available_users, range_key="today", all_employees=False, target_user_id=None, target_user_name=None):
            with _dashboard_perf_cache_lock:
                if cache_key in _dashboard_perf_refreshing:
                    return
                _dashboard_perf_refreshing.add(cache_key)

            def _worker():
                try:
                    payload = _dashboard_perf_compute_payload(
                        available_users=available_users,
                        range_key=range_key,
                        all_employees=all_employees,
                        target_user_id=target_user_id,
                        target_user_name=target_user_name,
                        include_available_users=False,
                    )
                    if payload is not None:
                        _dashboard_perf_cache_write(cache_key, payload)
                except Exception as refresh_exc:
                    logging.error(f"Dashboard cache refresh failed for {cache_key}: {refresh_exc}", exc_info=True)
                finally:
                    with _dashboard_perf_cache_lock:
                        _dashboard_perf_refreshing.discard(cache_key)

            threading.Thread(target=_worker, daemon=True, name=f"dashboard-cache-{hash(cache_key) & 0xffff}").start()

        @app.route('/api/dashboard/performance', methods=['POST', 'OPTIONS'])
        def api_dashboard_performance():
            if request.method == 'OPTIONS':
                return jsonify({"status": "success"}), 200
            try:
                data = request.json or {}
                actor = data.get('actor') or {}
                actor_user_id = actor.get('id') or actor.get('username') or actor.get('user_id')
                actor_name = actor.get('name') or actor.get('username') or actor_user_id
                actor_role = str(actor.get('role') or "")
                if not actor_user_id:
                    return jsonify({"status": "error", "message": "Missing actor"}), 400

                is_admin = actor_role.lower() == "admin"
                range_key = data.get('range_key') or "today"
                all_employees = bool(data.get('all_employees'))
                available_users = _dashboard_available_users()

                if all_employees:
                    if not is_admin:
                        return jsonify({"status": "error", "message": "Forbidden"}), 403
                    cache_key = _dashboard_perf_cache_key("__all__", range_key=range_key, all_employees=True)
                    payload, is_fresh = _dashboard_perf_cache_read(cache_key)
                    if payload is None:
                        payload = _dashboard_perf_compute_payload(
                            available_users=available_users,
                            range_key=range_key,
                            all_employees=True,
                            include_available_users=False,
                        )
                        _dashboard_perf_cache_write(cache_key, payload)
                    elif not is_fresh:
                        _dashboard_perf_refresh_async(
                            cache_key,
                            available_users=available_users,
                            range_key=range_key,
                            all_employees=True,
                        )
                    payload = _dashboard_perf_clone_payload(payload) or {}
                    payload["available_users"] = available_users
                    payload["selected_user_id"] = "__all__"
                    return jsonify({"status": "success", "data": payload}), 200

                target_user_id = data.get('target_user_id') or actor_user_id
                target_match = None
                for item in available_users:
                    if str(item.get("user_id") or "") == str(target_user_id):
                        target_match = item
                        break
                target_user_name = data.get('target_user_name') or (target_match.get("display_name") if isinstance(target_match, dict) else actor_name)
                if str(target_user_id) != str(actor_user_id) and not is_admin:
                    return jsonify({"status": "error", "message": "Forbidden"}), 403

                cache_key = _dashboard_perf_cache_key(target_user_id, range_key=range_key, all_employees=False)
                payload, is_fresh = _dashboard_perf_cache_read(cache_key)
                if payload is None:
                    payload = _dashboard_perf_compute_payload(
                        available_users=available_users,
                        range_key=range_key,
                        all_employees=False,
                        target_user_id=target_user_id,
                        target_user_name=target_user_name,
                        include_available_users=False,
                    )
                    if payload is None:
                        return jsonify({"status": "error", "message": "Unable to compute dashboard data"}), 500
                    _dashboard_perf_cache_write(cache_key, payload)
                elif not is_fresh:
                    _dashboard_perf_refresh_async(
                        cache_key,
                        available_users=available_users,
                        range_key=range_key,
                        all_employees=False,
                        target_user_id=target_user_id,
                        target_user_name=target_user_name,
                    )

                payload = _dashboard_perf_clone_payload(payload) or {}
                payload["available_users"] = available_users if is_admin else []
                payload["selected_user_id"] = str(target_user_id)

                return jsonify({"status": "success", "data": payload}), 200
            except Exception as e:
                logging.error(f"Error in /api/dashboard/performance: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

        _session_dashboard_cache = {}
        _session_dashboard_cache_lock = threading.Lock()
        _session_dashboard_refreshing = set()
        _SESSION_DASHBOARD_CACHE_FRESH_SECONDS = 60.0
        _SESSION_DASHBOARD_CACHE_STALE_SECONDS = 15 * 60.0

        def _session_dashboard_cache_key(scope, target_date, target_user_id):
            return f"{str(scope or 'employee')}::{str(target_date or '')}::{str(target_user_id or '')}"

        def _session_dashboard_cache_read(cache_key):
            now_ts = time.time()
            with _session_dashboard_cache_lock:
                entry = _session_dashboard_cache.get(cache_key)
                if not isinstance(entry, dict):
                    return None, False
                ts = float(entry.get("ts") or 0.0)
                payload = entry.get("payload")
                age = now_ts - ts
                if age > _SESSION_DASHBOARD_CACHE_STALE_SECONDS:
                    _session_dashboard_cache.pop(cache_key, None)
                    return None, False
                return _dashboard_perf_clone_payload(payload), age <= _SESSION_DASHBOARD_CACHE_FRESH_SECONDS

        def _session_dashboard_cache_write(cache_key, payload):
            with _session_dashboard_cache_lock:
                _session_dashboard_cache[cache_key] = {
                    "ts": time.time(),
                    "payload": _dashboard_perf_clone_payload(payload),
                }

        def _session_dashboard_compute_payload(available_users, actor_user_id, actor_name, actor_role, target_date=None, target_user_id=None, all_employees=False):
            is_admin = str(actor_role or "").lower() == "admin"
            if all_employees:
                if not is_admin:
                    return None
                payload = _session_dashboard_build_team_payload(available_users, target_date=target_date)
                payload["available_users"] = available_users
                payload["selected_user_id"] = "__all__"
                return payload

            resolved_user_id = str(target_user_id or actor_user_id or "").strip()
            if not resolved_user_id:
                return None
            if resolved_user_id != str(actor_user_id or "").strip() and not is_admin:
                return None
            matched_user = next((item for item in available_users if str(item.get("user_id") or "") == resolved_user_id), None)
            payload = chat_db.compute_employee_session_day_data(
                resolved_user_id,
                actor_name=str((matched_user or {}).get("display_name") or target_user_id or actor_name or resolved_user_id),
                target_date=target_date,
            )
            if payload is None:
                return None
            payload = _session_dashboard_enrich_payload(payload, include_samples=True, max_assessment_samples=36)
            payload["available_users"] = available_users if is_admin else []
            payload["selected_user_id"] = resolved_user_id
            return payload

        def _session_dashboard_refresh_async(cache_key, available_users, actor_user_id, actor_name, actor_role, target_date=None, target_user_id=None, all_employees=False):
            with _session_dashboard_cache_lock:
                if cache_key in _session_dashboard_refreshing:
                    return
                _session_dashboard_refreshing.add(cache_key)

            def _worker():
                try:
                    payload = _session_dashboard_compute_payload(
                        available_users=available_users,
                        actor_user_id=actor_user_id,
                        actor_name=actor_name,
                        actor_role=actor_role,
                        target_date=target_date,
                        target_user_id=target_user_id,
                        all_employees=all_employees,
                    )
                    if payload is not None:
                        _session_dashboard_cache_write(cache_key, payload)
                except Exception as refresh_exc:
                    logging.error(f"Session dashboard refresh failed for {cache_key}: {refresh_exc}", exc_info=True)
                finally:
                    with _session_dashboard_cache_lock:
                        _session_dashboard_refreshing.discard(cache_key)

            threading.Thread(target=_worker, daemon=True, name=f"session-dashboard-{hash(cache_key) & 0xffff}").start()

        @app.route('/api/dashboard/session-daily', methods=['POST', 'OPTIONS'])
        def api_dashboard_session_daily():
            if request.method == 'OPTIONS':
                return jsonify({"status": "success"}), 200
            try:
                data = request.json or {}
                actor = data.get('actor') or {}
                actor_user_id = actor.get('id') or actor.get('username') or actor.get('user_id')
                actor_name = actor.get('name') or actor.get('username') or actor_user_id
                actor_role = str(actor.get('role') or "")
                if not actor_user_id:
                    return jsonify({"status": "error", "message": "Missing actor"}), 400

                target_date = str(data.get('target_date') or "").strip()[:10] or str((chat_db._get_cairo_now()).date().isoformat())
                all_employees = bool(data.get('all_employees'))
                requested_user_id = data.get('target_user_id') or actor_user_id
                available_users = _dashboard_filter_users_for_actor(_dashboard_available_users(), actor)
                actor_allowed = [str(loc).strip() for loc in (actor.get('allowed_locations') or []) if str(loc).strip()]
                actor_teams = [loc for loc in actor_allowed if loc not in ("All", "NeedHelp", "Transport")]
                can_view_team = actor_role.lower() == "admin" and (str(actor.get('username') or actor_user_id).strip().lower() == "admin" or bool(actor_teams))
                allowed_user_ids = {
                    str(u.get("user_id") or "").strip()
                    for u in (available_users or [])
                    if isinstance(u, dict) and str(u.get("user_id") or "").strip()
                }
                allowed_user_ids.add(str(actor_user_id))

                if all_employees and not can_view_team:
                    return jsonify({"status": "error", "message": "Forbidden"}), 403
                if str(requested_user_id) != str(actor_user_id) and str(requested_user_id) not in allowed_user_ids:
                    return jsonify({"status": "error", "message": "Forbidden"}), 403

                cache_key = _session_dashboard_cache_key("__all__" if all_employees else requested_user_id, target_date, "team" if all_employees else "employee")
                payload, is_fresh = _session_dashboard_cache_read(cache_key)
                if payload is None:
                    payload = _session_dashboard_compute_payload(
                        available_users=available_users,
                        actor_user_id=actor_user_id,
                        actor_name=actor_name,
                        actor_role=actor_role,
                        target_date=target_date,
                        target_user_id=requested_user_id,
                        all_employees=all_employees,
                    )
                    if payload is None:
                        return jsonify({"status": "error", "message": "Unable to compute session dashboard data"}), 500
                    _session_dashboard_cache_write(cache_key, payload)
                elif not is_fresh:
                    _session_dashboard_refresh_async(
                        cache_key=cache_key,
                        available_users=available_users,
                        actor_user_id=actor_user_id,
                        actor_name=actor_name,
                        actor_role=actor_role,
                        target_date=target_date,
                        target_user_id=requested_user_id,
                        all_employees=all_employees,
                    )

                payload = _dashboard_perf_clone_payload(payload) or {}
                if all_employees:
                    payload["available_users"] = available_users
                    payload["selected_user_id"] = "__all__"
                else:
                    payload["available_users"] = available_users if can_view_team else []
                    payload["selected_user_id"] = str(requested_user_id)
                return jsonify({"status": "success", "data": payload}), 200
            except Exception as e:
                logging.error(f"Error in /api/dashboard/session-daily: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

