                if isinstance(email_agencies_in, list) and email_agencies_in:
                    email_agencies = [str(x or '').strip() for x in email_agencies_in if str(x or '').strip()]
                email_agencies_norm = {a.lower() for a in email_agencies if a}

                status_field = str(payload.get('status_field') or 'Status Photographer WhatsApp').strip() or 'Status Photographer WhatsApp'
                done_value = str(payload.get('done_value') or 'Done').strip() or 'Done'
                retry_value = str(payload.get('retry_value') or 'Try Again').strip() or 'Try Again'

                whatsapp_template_name = str(payload.get('whatsapp_template_name') or 'photographers__sent_link').strip() or 'photographers__sent_link'
                whatsapp_template_language = str(payload.get('whatsapp_template_language') or 'en').strip() or 'en'
                whatsapp_button_mode = str(payload.get('whatsapp_button_mode') or 'auto').strip().lower() or 'auto'

                email_subject = str(payload.get('email_subject') or '').strip() or None
                email_html = str(payload.get('email_html') or '').strip() or None

                max_records = 25
