        @app.route('/api/knowledge_base/documents', methods=['GET', 'OPTIONS'])
        def api_kb_documents():
            if request.method == 'OPTIONS':
                return jsonify({"status": "success"}), 200
            try:
                dept = request.args.get('department')
                actor_username = request.args.get('actor_username')
                
                # Check permissions if actor is provided
                if actor_username:
                    val = chat_db.get_setting("dashboard_users")
                    if val:
                        import json
                        users = json.loads(val)
                        is_super_admin = False
                        actor_allowed = []
                        for u in users:
                            if u.get("username") == actor_username:
                                actor_allowed = u.get("allowedLocations") or []
                                if "All" in actor_allowed and u.get("role") == "Admin":
                                    is_super_admin = True
                                break
                        
                        if not is_super_admin:
                            # Restrict department to only what they are allowed to see
                            if dept:
                                depts = [d.strip() for d in dept.split(',')]
                                allowed_depts = [d for d in depts if d in actor_allowed]
                                if not allowed_depts:
                                    return jsonify({"status": "error", "message": "Unauthorized department"}), 403
                                dept = ','.join(allowed_depts)
                            else:
                                dept = ','.join([d for d in actor_allowed if d != 'All' and d != 'NeedHelp'])
                                if not dept:
                                    return jsonify({"status": "error", "message": "Unauthorized"}), 403

                docs = self.kb.get_documents(dept)
                return jsonify({"status": "success", "data": docs})
            except Exception as e:
                return jsonify({"status": "error", "message": str(e)}), 500

        @app.route('/api/knowledge_base/upload', methods=['POST', 'OPTIONS'])
        def api_kb_upload():
            if request.method == 'OPTIONS':
                return jsonify({"status": "success"}), 200
            try:
                if 'file' not in request.files:
                    return jsonify({"status": "error", "message": "No file part"}), 400
                file = request.files['file']
                department = request.form.get('department', 'general')
                actor_username = request.form.get('actor_username')
                
                # Verify permissions
                if actor_username:
                    val = chat_db.get_setting("dashboard_users")
                    if val:
                        import json
                        users = json.loads(val)
                        is_super_admin = False
                        actor_allowed = []
                        actor_role = "Agent"
                        actor_name = actor_username
                        for u in users:
                            if u.get("username") == actor_username:
                                actor_allowed = u.get("allowedLocations") or []
                                actor_role = u.get("role") or "Agent"
                                actor_name = u.get("name") or actor_username
                                if "All" in actor_allowed and u.get("role") == "Admin":
                                    is_super_admin = True
                                break
                        
                        if not is_super_admin:
                            if department not in actor_allowed:
                                return jsonify({"status": "error", "message": "Unauthorized to upload to this department"}), 403
                        
                        # Log audit
                        chat_db.log_hr_audit_activity(
                            actor_user_id=actor_username,
                            actor_name=actor_name,
                            actor_role=actor_role,
                            event_type="kb.document.uploaded",
                            description=f"Uploaded KB document {file.filename} to {department}",
                            meta={"department": department, "filename": file.filename}
                        )

                if file.filename == '':
                    return jsonify({"status": "error", "message": "No selected file"}), 400
                
                import os
                import uuid
                
                # Keep original extension, but use a secure random name or ascii-safe name to prevent issues with Arabic filenames
                ext = os.path.splitext(file.filename)[1]
                # We use uuid to ensure the file saves correctly regardless of original language
                safe_name = f"{uuid.uuid4().hex}{ext}"
                file_path = os.path.join("uploads", "kb", safe_name)
                os.makedirs(os.path.dirname(file_path), exist_ok=True)
                file.save(file_path)
                
                res = self.kb.add_document(file_path, file.filename, department)
                if res["status"] == "success":
                    return jsonify(res)
                else:
                    return jsonify(res), 500
            except Exception as e:
                import traceback
                logging.error(f"Error in KB upload: {e}")
                logging.error(traceback.format_exc())
                return jsonify({"status": "error", "message": str(e)}), 500

