        @app.route('/api/knowledge_base/strict_rules/<rule_id>', methods=['GET', 'PUT', 'DELETE', 'OPTIONS'])
        def api_kb_strict_rule(rule_id):
            if request.method == 'OPTIONS':
                return jsonify({"status": "success"}), 200
            try:
                actor_username = request.args.get('actor_username') or (request.json.get('actor_username') if request.is_json else None)
                rule_info = agent.kb.get_strict_qa_rule(rule_id)
                if not rule_info:
                    return jsonify({"status": "error", "message": "Strict Q/A rule not found"}), 404

                if actor_username:
                    val = chat_db.get_setting("dashboard_users")
                    if val:
                        import json
                        users = json.loads(val)
                        is_super_admin = False
                        actor_allowed = []
                        actor_role = "Agent"
                        actor_name = actor_username
                        for u in users:
                            if u.get("username") == actor_username:
                                actor_allowed = u.get("allowedLocations") or []
                                actor_role = u.get("role") or "Agent"
                                actor_name = u.get("name") or actor_username
                                if "All" in actor_allowed and u.get("role") == "Admin":
                                    is_super_admin = True
                                break

                        if not is_super_admin and rule_info.get("department") not in actor_allowed:
                            return jsonify({"status": "error", "message": "Unauthorized access to this strict Q/A rule"}), 403

                if request.method == 'GET':
                    return jsonify({"status": "success", "data": rule_info})

                if request.method == 'PUT':
                    data = request.get_json(silent=True) or {}
                    new_question = data.get('question', rule_info.get('question'))
                    new_answer = data.get('answer', rule_info.get('answer'))
                    new_department = data.get('department', rule_info.get('department'))
                    new_match_type = data.get('match_type', rule_info.get('match_type'))
                    new_is_enabled = data.get('is_enabled', rule_info.get('is_enabled'))

                    if actor_username and not is_super_admin and new_department not in actor_allowed:
                        return jsonify({"status": "error", "message": "Unauthorized to move strict Q/A rule to this department"}), 403

                    success = agent.kb.update_strict_qa_rule(
                        rule_id,
                        question=new_question,
                        answer=new_answer,
                        department=new_department,
                        match_type=new_match_type,
                        is_enabled=new_is_enabled,
                    )
                    if success:
                        if actor_username:
                            chat_db.log_hr_audit_activity(
                                actor_user_id=actor_username,
                                actor_name=actor_name,
                                actor_role=actor_role,
                                event_type="kb.strict_rule.updated",
                                description=f"Updated strict Q/A rule in {new_department}",
                                meta={"department": new_department, "question": new_question, "match_type": new_match_type}
                            )
                        return jsonify({"status": "success"})
                    return jsonify({"status": "error", "message": "Failed to update strict Q/A rule"}), 500

                success = agent.kb.delete_strict_qa_rule(rule_id)
                if success:
                    if actor_username:
                        chat_db.log_hr_audit_activity(
                            actor_user_id=actor_username,
                            actor_name=actor_name,
                            actor_role=actor_role,
                            event_type="kb.strict_rule.deleted",
                            description=f"Deleted strict Q/A rule from {rule_info.get('department')}",
                            meta={"department": rule_info.get("department"), "question": rule_info.get("question")}
                        )
                    return jsonify({"status": "success"})
                return jsonify({"status": "error", "message": "Failed to delete strict Q/A rule"}), 500
            except Exception as e:
                import traceback
                logging.error(f"Error in strict Q/A rule item API: {e}")
                logging.error(traceback.format_exc())
                return jsonify({"status": "error", "message": str(e)}), 500

