        @app.route('/api/operations/create_record', methods=['POST', 'OPTIONS'])
        def api_create_operations_record():
            if request.method == 'OPTIONS':
                return _apply_api_cors_headers(jsonify({"status": "ok"})), 200
            try:
                data = request.json
                fields = data.get('fields')
                actor = data.get('actor') or {}
                table_name = data.get('table_name')
                
                if not fields:
                    return jsonify({"status": "error", "message": "Missing fields"}), 400
                    
                import requests
                from urllib.parse import quote
                from airtable_fields import TABLE_NAME
                
                religious_views = [
                    'حجاج حج مباشر', 'حجاج حج مباشر باقات', 'حجاج حج قرعة', 
                    'حجاج تحسين', 'حجاج بري', 'حجاج كوكتيل', 'إحصائيات البرامج', 'استفسارات جديدة'
                ]
                
                # Airtable views (Operation Today, etc.) are NOT table names — map to List.
                operation_views = {
                    'Booking_today', 'Booking_tomorrow', 'Booking_Weekly',
                    'Operation Today', 'Operation Tomorrow', 'Operation Weekly',
                    'All Booking', 'bassant_Khaled', 'nadeen_Hossam', 'ahmedsaad_sales'
                }
                
                is_religious = table_name in religious_views

                target_base_id = self.config['airtable'].get('religious_base_id') if is_religious else self.config['airtable']['base_id']
                
                if not table_name or str(table_name).strip() in operation_views:
                    target_table_name = TABLE_NAME
                else:
                    target_table_name = table_name
                
                if not target_table_name:
                    return jsonify({"status": "error", "message": "Missing table_name"}), 400

                require_agency = bool(data.get('require_agency')) or (not is_religious and target_table_name == TABLE_NAME)
                agency_val = str((fields or {}).get('Agency') or '').strip()
                if require_agency and not agency_val:
                    return jsonify({
                        "status": "error",
                        "message": "Agency is required. Select or type the agency before creating the record."
                    }), 400

                # Field ACL for FTS AI Operation (List / non-religious creates).
                if not is_religious and target_table_name == TABLE_NAME:
                    user_obj = self._load_dashboard_user_by_actor(actor)
                    if not self._ai_operation_can_create_record(user_obj, actor=actor):
                        return jsonify({
                            "status": "error",
                            "message": "You do not have permission to create bookings."
                        }), 403
                    fields, denied = self._filter_ai_operation_fields_by_acl(
                        fields, user_obj, action="create", actor=actor
                    )
                    if denied:
                        return jsonify({
                            "status": "error",
                            "message": f"No permission to set fields on create: {', '.join(denied[:8])}"
                        }), 403
                    if not fields:
                        return jsonify({"status": "error", "message": "Missing fields"}), 400

                url = f"https://api.airtable.com/v0/{target_base_id}/{quote(target_table_name)}"
                headers = {
                    "Authorization": f"Bearer {self.config['airtable']['api_key']}",
                    "Content-Type": "application/json"
                }
                
                payload = {
                    "records": [
                        {
                            "fields": fields
                        }
                    ],
                    "typecast": True
                }
                
                response = requests.post(url, headers=headers, json=payload, timeout=15)
                
                if response.status_code in [200, 201]:
                    res_data = response.json()
                    created_record = res_data.get('records', [{}])[0]
                    created_id = str((created_record or {}).get('id') or '').strip()
                    created_fields = (created_record or {}).get('fields') or fields or {}

                    # Sync into local mirror so FTS AI Operation shows the record immediately.
                    if created_id and not is_religious and getattr(self, "airtable_mirror", None):
                        try:
                            self.airtable_mirror.upsert_main_list_record(created_id, created_fields)
                        except Exception as mirror_err:
                            logging.warning(f"Created Airtable record {created_id} but mirror upsert failed: {mirror_err}")

                    return jsonify({
                        "status": "success", 
                        "message": "Record created successfully",
                        "record": created_record
                    })
                else:
                    return jsonify({"status": "error", "message": response.text}), response.status_code

            except Exception as e:
                import traceback
                logging.error(f"Error creating record: {traceback.format_exc()}")
                return jsonify({"status": "error", "message": str(e)}), 500

        @app.route('/api/operations/update_booking', methods=['POST'])
        def api_update_operations_booking():
            try:
                data = request.json
                record_id = data.get('record_id')
                fields = data.get('fields')
                actor = data.get('actor') or {}
                field_types = data.get('field_types') or {}
                
                if not record_id or not fields:
                    return jsonify({"status": "error", "message": "Missing record_id or fields"}), 400
                    
                import requests
                from urllib.parse import quote
                from airtable_fields import TABLE_NAME
                
                table_name = data.get('table_name')
                
                religious_views = [
                    'حجاج حج مباشر', 'حجاج حج مباشر باقات', 'حجاج حج قرعة', 
                    'حجاج تحسين', 'حجاج بري', 'حجاج كوكتيل', 'إحصائيات البرامج', 'استفسارات جديدة'
                ]
                
                is_religious = data.get('is_religious') if 'is_religious' in data else (table_name in religious_views)

                target_base_id = self.config['airtable'].get('religious_base_id') if is_religious else self.config['airtable']['base_id']
                
                # Try to get the dynamic table name for religious base if applicable
                target_table_name = TABLE_NAME
                if is_religious:
                    if data.get('table_name') and data.get('table_name') in religious_views:
                        target_table_name = data.get('table_name')
                    elif getattr(self, "airtable_mirror", None):
                        table_key = self.airtable_mirror._get_table_key_for_main_list(is_religious=True)
                        if table_key:
                            with self.airtable_mirror._connect() as conn:
                                c = conn.cursor()
                                c.execute("SELECT table_name FROM mirror_tables WHERE table_key=?", (table_key,))
                                row = c.fetchone()
                                if row:
                                    target_table_name = row["table_name"]

                # Field ACL for FTS AI Operation updates (non-religious List).
                typecast_allowed = True
                if not is_religious:
                    user_obj = self._load_dashboard_user_by_actor(actor)
                    fields, denied = self._filter_ai_operation_fields_by_acl(
                        fields, user_obj, action="edit", actor=actor
                    )
                    if denied:
                        return jsonify({
                            "status": "error",
                            "message": f"No permission to edit fields: {', '.join(denied[:8])}"
                        }), 403
                    if not fields:
                        return jsonify({"status": "error", "message": "Missing record_id or fields"}), 400
                    # Creating brand-new select options via typecast requires Create ACL.
                    for fk in list(fields.keys()):
                        if not self._ai_operation_field_allowed(user_obj, fk, action="create", actor=actor):
                            typecast_allowed = False
                            break
                else:
                    user_obj = None

                url = f"https://api.airtable.com/v0/{target_base_id}/{quote(target_table_name)}/{record_id}"
                headers = {
                    "Authorization": f"Bearer {self.config['airtable']['api_key']}",
                    "Content-Type": "application/json"
                }
                
                prev_fields = {}
                try:
                    prev_res = requests.get(url, headers={"Authorization": headers["Authorization"]}, timeout=15)
                    if prev_res.status_code == 200:
                        prev_fields = (prev_res.json() or {}).get("fields") or {}
                except Exception:
                    prev_fields = {}

                try:
                    from airtable_fields import ID_TO_READABLE_NAME
                    trimmed_to_exact = {}
                    for v in (ID_TO_READABLE_NAME or {}).values():
                        if isinstance(v, str):
                            trimmed_to_exact.setdefault(v.strip(), v)
                    fixed_fields = {}
                    original_name_by_exact = {}
                    for k, v in (fields or {}).items():
                        if isinstance(k, str):
                            trimmed = k.strip()
                            exact = trimmed_to_exact.get(trimmed, k)
                        else:
                            exact = k
                        fixed_fields[exact] = v
                        original_name_by_exact[exact] = k
                    fields = self._sanitize_booking_field_updates(fixed_fields)
                    if not fields:
                        return jsonify({"status": "error", "message": "No valid fields to update"}), 400
                except Exception:
                    original_name_by_exact = {k: k for k in (fields or {}).keys()}
                    fields = self._sanitize_booking_field_updates(fields or {})
                    if not fields:
                        return jsonify({"status": "error", "message": "No valid fields to update"}), 400

                payload = {"fields": fields}
                response = requests.patch(
                    url,
                    headers=headers,
                    params={"typecast": "true" if typecast_allowed else "false"},
                    json=payload,
                    timeout=15,
                )
                
                if response.status_code != 200:
                    logging.error(
                        "Failed to update Airtable record %s: %s | fields=%s",
                        record_id,
                        response.text,
                        {k: fields.get(k) for k in list(fields.keys())[:12]},
                    )
                    return jsonify({"status": "error", "message": f"Airtable update failed: {response.text}"}), 500

                # Bust select-options cache so newly typecast-created choices appear next fetch.
                try:
                    opt_cache = getattr(api_operations_select_field_options, "_cache", None)
                    if isinstance(opt_cache, dict):
                        for fk in list(fields.keys()):
                            name = str(fk or "").strip()
                            if not name:
                                continue
                            opt_cache.pop(name, None)
                            # Also drop case-insensitive aliases used as cache keys.
                            for ck in list(opt_cache.keys()):
                                if str(ck).strip().lower() == name.lower():
                                    opt_cache.pop(ck, None)
                except Exception:
                    pass

                updated_payload = None
                try:
                    updated_payload = response.json() or {}
                except Exception:
                    updated_payload = None
                try:
                    final_res = requests.get(url, headers={"Authorization": headers["Authorization"]}, timeout=15)
                    if final_res.status_code == 200:
                        updated_payload = final_res.json() or updated_payload
                except Exception:
                    pass
                try:
                    if getattr(self, "airtable_mirror", None) and updated_payload and isinstance(updated_payload, dict):
                        merged_fields = {}
                        try:
                            merged_fields.update(prev_fields or {})
                        except Exception:
                            merged_fields = {}
                        try:
                            merged_fields.update((updated_payload.get("fields") or {}) if isinstance(updated_payload.get("fields") or {}, dict) else {})
                        except Exception:
                            pass
                        if merged_fields:
                            tk = None
                            if is_religious and data.get('table_name'):
                                with self.airtable_mirror._connect() as conn:
                                    c = conn.cursor()
                                    c.execute("SELECT table_key FROM mirror_tables WHERE base_label='religious' AND table_name=?", (data.get('table_name'),))
                                    r = c.fetchone()
                                    if r: tk = r['table_key']
                            self.airtable_mirror.upsert_main_list_record(record_id, merged_fields, override_table_key=tk)
                except Exception:
                    pass
                    
                try:
                    import operations_audit
                    from datetime import datetime, timezone

                    def norm(v):
                        if v is None:
                            return None
                        if isinstance(v, list):
                            return [str(x) for x in v]
                        if isinstance(v, (str, int, float, bool)):
                            return v
                        return str(v)

                    def values_equal(a, b):
                        if isinstance(a, list) or isinstance(b, list):
                            aa = [] if a is None else (a if isinstance(a, list) else [str(a)])
                            bb = [] if b is None else (b if isinstance(b, list) else [str(b)])
                            return sorted([str(x) for x in aa]) == sorted([str(x) for x in bb])
                        return str(a or "") == str(b or "")

                    known_single_select = {'pickup time', 'Booking Status', 'Agency', 'des'}

                    def infer_type(field_name, old_v, new_v):
                        if field_name in field_types:
                            return str(field_types.get(field_name))
                        if isinstance(field_name, str) and field_name.strip() in field_types:
                            return str(field_types.get(field_name.strip()))
                        if isinstance(new_v, list) or isinstance(old_v, list):
                            return 'multi_select'
                        if field_name in known_single_select:
                            return 'single_select'
                        s = str(new_v or "")
                        if '\n' in s or len(s) > 120:
                            return 'long_text'
                        return 'text'

                    now_iso = datetime.now(timezone.utc).isoformat()
                    user_id = actor.get('id') or actor.get('user_id')
                    user_name = actor.get('name') or actor.get('username') or actor.get('user_name')

                    for k, new_v in (fields or {}).items():
                        old_v = prev_fields.get(k)
                        original_name = original_name_by_exact.get(k, k)
                        log_field_name = original_name.strip() if isinstance(original_name, str) else str(original_name)
                        old_n = norm(old_v)
                        new_n = norm(new_v)
                        if values_equal(old_n, new_n):
                            continue
                        operations_audit.log_change(
                            record_id=record_id,
                            field_name=log_field_name,
                            field_type=infer_type(log_field_name, old_n, new_n),
                            old_value=old_n,
                            new_value=new_n,
                            user_id=user_id,
                            user_name=user_name,
                            changed_at=now_iso
                        )
                except Exception as e:
                    logging.error(f"Failed to log booking field change: {e}", exc_info=True)

                return jsonify({"status": "success", "data": updated_payload or {}})
            except Exception as e:
                logging.error(f"Error in api_update_operations_booking: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

