        @app.route('/api/operations/linked_field_options', methods=['GET'])
        def api_operations_linked_field_options():
            try:
                field_name = request.args.get('field')
                if not field_name:
                    return jsonify({"status": "error", "message": "Missing field"}), 400

                cache = getattr(api_operations_linked_field_options, "_cache", {})
                api_operations_linked_field_options._cache = cache
                key = str(field_name).strip()
                if key in cache:
                    return jsonify({"status": "success", "data": cache[key]})

                import requests
                from urllib.parse import quote

                base_id = self.config['airtable']['base_id']
                api_key = self.config['airtable']['api_key']
                main_table_name = self.config['airtable']['tables']['main_list']

                meta_url = f"https://api.airtable.com/v0/meta/bases/{base_id}/tables"
                meta_headers = {"Authorization": f"Bearer {api_key}"}
                meta_res = requests.get(meta_url, headers=meta_headers, timeout=30)
                if meta_res.status_code != 200:
                    return jsonify({"status": "error", "message": f"Failed to read Airtable meta: {meta_res.text}"}), 500

                tables = (meta_res.json() or {}).get("tables") or []
                main_table = next((t for t in tables if t.get("name") == main_table_name), None)
                if not main_table:
                    return jsonify({"status": "error", "message": "Main table not found"}), 500

                target_field = None
                for f in (main_table.get("fields") or []):
                    if str(f.get("name") or "").strip() == key:
                        target_field = f
                        break
                if not target_field:
                    return jsonify({"status": "error", "message": f"Field not found in main table: {key}"}), 404

                if target_field.get("type") != "multipleRecordLinks":
                    return jsonify({"status": "error", "message": f"Field is not linked: {key}"}), 400

                opts = target_field.get("options") or {}
                linked_table_id = opts.get("linkedTableId")
                if not linked_table_id:
                    return jsonify({"status": "error", "message": f"linkedTableId missing for {key}"}), 500

                linked_table = next((t for t in tables if t.get("id") == linked_table_id), None)
                if not linked_table:
                    return jsonify({"status": "error", "message": f"Linked table not found for {key}"}), 500

                linked_fields = linked_table.get("fields") or []
                primary_field_id = linked_table.get("primaryFieldId")
                primary_field_name = None
                for lf in linked_fields:
                    if lf.get("id") == primary_field_id:
                        primary_field_name = lf.get("name")
                        break
                if not primary_field_name and linked_fields:
                    primary_field_name = linked_fields[0].get("name")

                phone_field_name = None
                for lf in linked_fields:
                    n = str(lf.get("name") or "")
                    if "phone" in n.lower():
                        phone_field_name = n
                        break

                options_out = []
                offset = None
                page_count = 0
                while page_count < 20:
                    page_count += 1
                    data_url = f"https://api.airtable.com/v0/{base_id}/{linked_table_id}"
                    params = ["pageSize=100"]
                    if offset:
                        params.append(f"offset={quote(offset)}")
                    if params:
                        data_url += "?" + "&".join(params)
                    r = requests.get(data_url, headers=meta_headers, timeout=30)
                    if r.status_code != 200:
                        return jsonify({"status": "error", "message": f"Failed to fetch linked table records: {r.text}"}), 500
                    payload = r.json() or {}
                    for rec in payload.get("records") or []:
                        rid = rec.get("id")
                        f = rec.get("fields") or {}
                        primary_val = f.get(primary_field_name) if primary_field_name else ""
                        phone_val = f.get(phone_field_name) if phone_field_name else ""
                        label = str(primary_val or "").strip()
                        phone_s = str(phone_val or "").strip()
                        if phone_s and phone_s not in label:
                            label = f"{label} • {phone_s}" if label else phone_s
                        if not label:
                            label = rid
                        options_out.append({"id": rid, "label": label})
                    offset = payload.get("offset")
                    if not offset:
                        break

                options_out.sort(key=lambda x: x.get("label", ""))
                out = {
                    "field": key,
                    "linked_table_id": linked_table_id,
                    "primary_field": primary_field_name,
                    "phone_field": phone_field_name,
                    "options": options_out
                }
                cache[key] = out
                return jsonify({"status": "success", "data": out})
            except Exception as e:
                logging.error(f"Error in api_operations_linked_field_options: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

        @app.route('/api/operations/attachments/upload', methods=['POST'])
        def api_operations_attachments_upload():
            try:
                record_id = request.form.get('record_id')
                field_name = request.form.get('field_name')
                actor_raw = request.form.get('actor')
                file = request.files.get('file')

                if not record_id or not field_name or not file:
                    return jsonify({"status": "error", "message": "Missing record_id, field_name, or file"}), 400

                allowed_attachment_fields = {
                    "Attachments",
                    "Tickets",
                    "Attachments Boarding",
                    "Attachments Operations",
                    "Attachments Chat",
                    "Photo invoice",
                }
                field_name_l = str(field_name or "").strip().lower()
                if (
                    str(field_name).strip() not in allowed_attachment_fields
                    and "attachment" not in field_name_l
                    and field_name_l not in ("tickets", "photo invoice")
                ):
                    return jsonify({
                        "status": "error",
                        "message": f"Unsupported attachment field: {str(field_name).strip()}"
                    }), 400

                try:
                    actor = json.loads(actor_raw) if actor_raw else {}
                except Exception:
                    actor = {}

                user_obj = self._load_dashboard_user_by_actor(actor)
                if not self._ai_operation_field_allowed(user_obj, str(field_name).strip(), action="edit", actor=actor):
                    return jsonify({
                        "status": "error",
                        "message": f"No permission to edit field: {str(field_name).strip()}"
                    }), 403

                try:
                    from airtable_fields import ID_TO_READABLE_NAME
                    trimmed_to_exact = {}
                    for v in (ID_TO_READABLE_NAME or {}).values():
                        if isinstance(v, str):
                            trimmed_to_exact.setdefault(v.strip(), v)
                    field_key = trimmed_to_exact.get(str(field_name).strip(), field_name)
                except Exception:
                    field_key = field_name

                filename = file.filename or 'file'
                mime_type = file.mimetype or ''
                r_type = 'raw' if mime_type == 'application/pdf' else 'auto'

                base = filename.rsplit('.', 1)[0] if '.' in filename else filename
                safe_id = re.sub(r'[^a-zA-Z0-9_-]', '_', str(base)).strip('_') or 'upload'

                res = cloudinary.uploader.upload(
                    file,
                    resource_type=r_type,
                    public_id=safe_id,
                    format='pdf' if mime_type == 'application/pdf' else None
                )
                uploaded_url = (res or {}).get('secure_url')
                if not uploaded_url:
                    return jsonify({"status": "error", "message": "Cloudinary upload failed"}), 500

                import requests
                from urllib.parse import quote
                from airtable_fields import TABLE_NAME

                base_id = self.config['airtable']['base_id']
                api_key = self.config['airtable']['api_key']
                url = f"https://api.airtable.com/v0/{base_id}/{quote(TABLE_NAME)}/{record_id}"
                headers = {
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json"
                }

                prev_fields = {}
                prev_res = requests.get(url, headers={"Authorization": headers["Authorization"]}, timeout=20)
                if prev_res.status_code == 200:
                    prev_fields = (prev_res.json() or {}).get("fields") or {}
                else:
                    return jsonify({"status": "error", "message": f"Failed to read record before update: {prev_res.text}"}), 500

                old_items = prev_fields.get(field_key) if isinstance(prev_fields, dict) else None
                old_items = old_items if isinstance(old_items, list) else []

                next_items = [x for x in old_items if isinstance(x, dict) and isinstance(x.get('url'), str)]
                next_items.append({"url": uploaded_url, "filename": filename})

                payload = {"fields": {field_key: next_items}, "typecast": True}
                patch_res = requests.patch(url, headers=headers, json=payload, timeout=30)
                if patch_res.status_code != 200:
                    logging.error(f"Failed to update attachments for record {record_id}: {patch_res.text}")
                    return jsonify({"status": "error", "message": f"Airtable update failed: {patch_res.text}"}), 500

                updated_fields = (patch_res.json() or {}).get("fields") or {}
                updated_value = updated_fields.get(field_key) if isinstance(updated_fields, dict) else None

                try:
                    import operations_audit
                    from datetime import datetime, timezone

                    def to_urls(v):
                        if not isinstance(v, list):
                            return []
                        out = []
                        for it in v:
                            if isinstance(it, dict) and isinstance(it.get('url'), str):
                                out.append(it.get('url'))
                        return out

                    now_iso = datetime.now(timezone.utc).isoformat()
                    user_id = actor.get('id') or actor.get('user_id')
                    user_name = actor.get('name') or actor.get('username') or actor.get('user_name')
                    operations_audit.log_change(
                        record_id=record_id,
                        field_name=str(field_name).strip(),
                        field_type="attachments",
                        old_value=to_urls(old_items),
                        new_value=to_urls(updated_value),
                        user_id=user_id,
                        user_name=user_name,
                        changed_at=now_iso
                    )
                except Exception as e:
                    logging.error(f"Failed to log attachments upload: {e}", exc_info=True)

                return jsonify({
                    "status": "success",
                    "data": {
                        "record_id": record_id,
                        "field_name": str(field_name).strip(),
                        "field_key": field_key,
                        "uploaded_url": uploaded_url,
                        "attachments": updated_value
                    }
                })
            except Exception as e:
                logging.error(f"Error in api_operations_attachments_upload: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

