        @app.route('/api/settings/<key>', methods=['GET', 'POST', 'OPTIONS'])
        def api_settings(key):
            if request.method == 'OPTIONS':
                return jsonify({"status": "ok"}), 200
            import chat_db
            try:
                PRIMARY_ADMIN_USERNAME = "admin"
                FULL_ACCESS_LOCATIONS = ["All", "NeedHelp", "Hurghada/Cairo", "Sharm", "Sales", "Guides", "Drivers", "Quality", "Religious"]

                def _normalize_username(value):
                    return str(value or "").strip().lower()

                def _is_primary_admin_record(user_obj):
                    if not isinstance(user_obj, dict):
                        return False
                    return _normalize_username(user_obj.get("username")) == PRIMARY_ADMIN_USERNAME and str(user_obj.get("role") or "").strip().lower() == "admin"

                def _get_managed_teams(user_obj):
                    if not isinstance(user_obj, dict):
                        return []
                    return [
                        str(loc).strip()
                        for loc in (user_obj.get("allowedLocations") or [])
                        if str(loc).strip() and str(loc).strip() not in ("All", "NeedHelp", "Transport")
                    ]

                def _sanitize_dashboard_user_entry(user_obj):
                    if not isinstance(user_obj, dict):
                        return None

                    username = str(user_obj.get("username") or "").strip()
                    role = str(user_obj.get("role") or "").strip() or "Agent"
                    allowed_locations = []
                    for loc in (user_obj.get("allowedLocations") or []):
                        loc_str = str(loc or "").strip()
                        if loc_str and loc_str not in allowed_locations:
                            allowed_locations.append(loc_str)

                    if _normalize_username(username) == PRIMARY_ADMIN_USERNAME and role == "Admin":
                        allowed_locations = [loc for loc in FULL_ACCESS_LOCATIONS]
                    else:
                        allowed_locations = [loc for loc in allowed_locations if loc != "All"]

                    shift_fields = self._sanitize_user_shift_fields(user_obj)
                    return {
                        "id": str(user_obj.get("id") or ""),
                        "username": username,
                        "name": str(user_obj.get("name") or username or ""),
                        "role": role,
                        "allowedLocations": allowed_locations,
                        "allowedTabs": user_obj.get("allowedTabs"),
                        "weeklySchedule": shift_fields.get("weeklySchedule"),
                        "workingDays": shift_fields.get("workingDays"),
                        "shiftStart": shift_fields.get("shiftStart"),
                        "shiftEnd": shift_fields.get("shiftEnd"),
                        "additionalShifts": shift_fields.get("additionalShifts"),
                        "dedicatedWhatsApp": user_obj.get("dedicatedWhatsApp"),
                        "toolPhone": re.sub(r"\D", "", str(user_obj.get("toolPhone") or "")),
                        "allowIntents": [
                            str(x).strip()
                            for x in (user_obj.get("allowIntents") or [])
                            if str(x).strip()
                        ][:40],
                        "allowSensitive": [
                            str(x).strip()
                            for x in (user_obj.get("allowSensitive") or [])
                            if str(x).strip()
                        ][:40],
                        "deniedInboxTools": [
                            str(x).strip().lower()
                            for x in (user_obj.get("deniedInboxTools") or [])
                            if str(x).strip().lower() in (
                                "ai_reply", "optimize", "wa_template", "fb_template", "attach", "voice"
                            )
                        ][:20],
                        "canManageChannels": bool(user_obj.get("canManageChannels") or False),
                        "createdBy": str(user_obj.get("createdBy") or ""),
                        "skipWhatsAppSetup": bool(user_obj.get("skipWhatsAppSetup") or False),
                        "aiOperationAcl": self._sanitize_ai_operation_acl(user_obj.get("aiOperationAcl")),
                        "religiousOperationAcl": self._sanitize_religious_operation_acl(user_obj.get("religiousOperationAcl")),
                        "allowedBaseIds": self._sanitize_allowed_base_ids(user_obj.get("allowedBaseIds")),
                    }

                def _has_team_overlap(user_obj, actor_teams):
                    user_teams = set(_get_managed_teams(user_obj))
                    return bool(user_teams.intersection(set(actor_teams or [])))

                if request.method == 'GET':
                    if str(key) == "dashboard_channel_settings":
                        return jsonify({"status": "success", "value": _get_channel_settings()})
                    val = chat_db.get_setting(key)
                    if str(key) == "dashboard_users":
                        try:
                            import json
                            users = []
                            if isinstance(val, str) and val.strip():
                                users = json.loads(val)
                            if isinstance(users, list) and users:
                                defaults_admin_phone = ""
                                try:
                                    users_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), get_data_path(get_data_path('users.json')))
                                    if os.path.exists(users_path):
                                        defaults = json.load(open(users_path, "r", encoding="utf-8")) or []
                                        if isinstance(defaults, list):
                                            for item in defaults:
                                                if not isinstance(item, dict):
                                                    continue
                                                if _normalize_username(item.get("username")) != PRIMARY_ADMIN_USERNAME:
                                                    continue
                                                defaults_admin_phone = re.sub(r"\D", "", str(item.get("toolPhone") or item.get("phone") or ""))
                                                break
                                except Exception:
                                    defaults_admin_phone = ""

                                hydrated = False
                                if defaults_admin_phone:
                                    for u in users:
                                        if not _is_primary_admin_record(u):
                                            continue
                                        existing_phone = re.sub(r"\D", "", str(u.get("toolPhone") or ""))
                                        if not existing_phone:
                                            u["toolPhone"] = defaults_admin_phone
                                            hydrated = True
                                        break
                                if hydrated:
                                    try:
                                        val = json.dumps(users, ensure_ascii=False)
                                        chat_db.set_setting("dashboard_users", val)
                                    except Exception:
                                        pass
                        except Exception:
                            pass
                        actor_username = request.args.get('actor_username')
                        if actor_username and val:
                            try:
                                import json
                                users = json.loads(val)
                                actor_allowed = []
                                actor_teams = []
                                is_super_admin = False
                                for u in users:
                                    if u.get("username") == actor_username:
                                        actor_allowed = u.get("allowedLocations") or []
                                        actor_teams = _get_managed_teams(u)
                                        if _is_primary_admin_record(u):
                                            is_super_admin = True
                                        break
                                
                                if not is_super_admin:
                                    filtered_users = []
                                    for u in users:
                                        if u.get("username") == actor_username:
                                            filtered_users.append(_sanitize_dashboard_user_entry(u))
                                            continue
                                        if str(u.get("role") or "").strip().lower() == "admin":
                                            continue
                                        if u.get("createdBy") == actor_username or _has_team_overlap(u, actor_teams):
                                            filtered_users.append(_sanitize_dashboard_user_entry(u))
                                    filtered_users = [u for u in filtered_users if isinstance(u, dict)]
                                    val = json.dumps(filtered_users)
                            except Exception as e:
                                logging.error(f"Error filtering dashboard_users: {e}")

                    return jsonify({"status": "success", "value": val})
                else:
                    data = request.json or {}
                    val = data.get('value')
                    actor = data.get('actor') or {}

                    actor_user_id = actor.get('id') or actor.get('user_id') or actor.get('username')
                    actor_name = actor.get('name') or actor.get('username') or actor.get('user_name') or actor_user_id or ""
                    actor_role = actor.get('role') or "Agent"

                    old_val_raw = None
                    if str(key) in ("dashboard_users", "dashboard_user_passwords"):
                        try:
                            old_val_raw = chat_db.get_setting(key)
                        except Exception:
                            old_val_raw = None

                    import json
                    def _parse_users(v):
                        if isinstance(v, str) and v.strip():
                            try:
                                v = json.loads(v)
                            except Exception:
                                v = None
                        if isinstance(v, list):
                            out = []
                            for u in v:
                                if isinstance(u, dict):
                                    out.append(
                                        {
                                            "id": str(u.get("id") or ""),
                                            "username": str(u.get("username") or ""),
                                            "name": str(u.get("name") or u.get("username") or ""),
                                            "role": str(u.get("role") or ""),
                                            "allowedLocations": [str(x) for x in (u.get("allowedLocations") or []) if str(x).strip()],
                                            "allowedTabs": u.get("allowedTabs"),
                                            "weeklySchedule": u.get("weeklySchedule"),
                                            "workingDays": u.get("workingDays"),
                                            "shiftStart": u.get("shiftStart"),
                                            "shiftEnd": u.get("shiftEnd"),
                                            "additionalShifts": u.get("additionalShifts"),
                                            "dedicatedWhatsApp": u.get("dedicatedWhatsApp"),
                                            "toolPhone": re.sub(r"\D", "", str(u.get("toolPhone") or "")),
                                            "allowIntents": [
                                                str(x).strip()
                                                for x in (u.get("allowIntents") or [])
                                                if str(x).strip()
                                            ][:40],
                                            "allowSensitive": [
                                                str(x).strip()
                                                for x in (u.get("allowSensitive") or [])
                                                if str(x).strip()
                                            ][:40],
                                            "deniedInboxTools": [
                                                str(x).strip().lower()
                                                for x in (u.get("deniedInboxTools") or [])
                                                if str(x).strip().lower() in (
                                                    "ai_reply", "optimize", "wa_template", "fb_template", "attach", "voice"
                                                )
                                            ][:20],
                                            "canManageChannels": bool(u.get("canManageChannels") or False),
                                            "createdBy": str(u.get("createdBy") or ""),
                                            "skipWhatsAppSetup": bool(u.get("skipWhatsAppSetup") or False),
                                            "aiOperationAcl": self._sanitize_ai_operation_acl(u.get("aiOperationAcl")),
                                            "religiousOperationAcl": self._sanitize_religious_operation_acl(u.get("religiousOperationAcl")),
                                            "allowedBaseIds": self._sanitize_allowed_base_ids(u.get("allowedBaseIds")),
                                        }
                                    )
                            return out
                        return []

                    if str(key) == "dashboard_users":
                        old_users = _parse_users(old_val_raw)
                        new_users = [u for u in (_sanitize_dashboard_user_entry(u) for u in _parse_users(val)) if isinstance(u, dict)]
                        
                        actor_allowed = []
                        actor_teams = []
                        is_super_admin = False
                        for u in old_users:
                            if u.get("username") == actor_user_id:
                                actor_allowed = u.get("allowedLocations") or []
                                actor_teams = _get_managed_teams(u)
                                if _is_primary_admin_record(u):
                                    is_super_admin = True
                                break
                        if not is_super_admin and _normalize_username(actor_user_id) == PRIMARY_ADMIN_USERNAME and str(actor_role or "").strip().lower() == "admin":
                            is_super_admin = True
                        
                        if not is_super_admin:
                            merged_users = []
                            allowed_to_modify = {
                                u.get("username")
                                for u in old_users
                                if u.get("createdBy") == actor_user_id
                                or (str(u.get("role") or "").strip().lower() != "admin" and _has_team_overlap(u, actor_teams))
                            }
                            
                            # Keep users that the actor CANNOT modify
                            for u in old_users:
                                if u.get("username") not in allowed_to_modify and u.get("username") != actor_user_id:
                                    merged_users.append(u)
                                elif u.get("username") == actor_user_id:
                                    # Use _sanitize_dashboard_user_entry to ensure we keep new fields if the actor updated themselves
                                    # Wait, we need to find the actor in new_users if they updated themselves
                                    actor_new = next((n for n in new_users if n.get("username") == actor_user_id), None)
                                    if actor_new:
                                        merged_users.append(actor_new)
                                    else:
                                        merged_users.append(_sanitize_dashboard_user_entry(u))
                            
                            # Add/update users the actor sent
                            for u in new_users:
                                if u.get("username") == actor_user_id:
                                    continue # Actor is already preserved
                                if str(u.get("role") or "").strip().lower() == "admin":
                                    existing_admin = next((x for x in old_users if x.get("username") == u.get("username") and str(x.get("role") or "").strip().lower() == "admin"), None)
                                    if existing_admin:
                                        continue
                                    u["role"] = "Agent"
                                if u.get("username") in allowed_to_modify or not any(x.get("username") == u.get("username") for x in old_users):
                                    u["createdBy"] = actor_user_id
                                    # Ensure they only assign locations they have access to
                                    u["allowedLocations"] = [loc for loc in u["allowedLocations"] if loc in actor_allowed]
                                    if str(u.get("role") or "").strip().lower() == "admin":
                                        u["allowedLocations"] = [loc for loc in u["allowedLocations"] if loc != "All"]
                                    merged_users.append(u)
                            val = json.dumps(merged_users)
                        else:
                            for u in new_users:
                                if _normalize_username(u.get("username")) != PRIMARY_ADMIN_USERNAME and str(u.get("role") or "").strip().lower() == "admin":
                                    u["allowedLocations"] = [loc for loc in (u.get("allowedLocations") or []) if loc != "All"]
                            val = json.dumps(new_users)

                    if str(key).startswith('notification_sound_prefs_'):
                        import notification_sound_validation
                        ok, parsed = notification_sound_validation.validate_notification_sound_prefs(val)
                        if not ok:
                            return jsonify({"status": "error", "message": str(parsed)}), 400
                        val = json.dumps(parsed)

                    if str(key).startswith('inbox_favorites_'):
                        try:
                            parsed_favs = val
                            if isinstance(parsed_favs, str) and parsed_favs.strip():
                                parsed_favs = json.loads(parsed_favs)
                            if not isinstance(parsed_favs, list):
                                return jsonify({"status": "error", "message": "inbox_favorites must be a list"}), 400
                            cleaned = []
                            seen = set()
                            for item in parsed_favs:
                                cid = str(item or "").strip()
                                if not cid or cid in seen:
                                    continue
                                seen.add(cid)
                                cleaned.append(cid)
                                if len(cleaned) >= 5000:
                                    break
                            val = json.dumps(cleaned, ensure_ascii=False)
                        except Exception as fav_err:
                            return jsonify({"status": "error", "message": f"invalid inbox_favorites: {fav_err}"}), 400

                    # Preserve Create-with-PI replies the client might overwrite while isLoading
                    if str(key).startswith("admin_pi_sessions_"):
                        try:
                            existing_sessions = chat_db.get_setting(key)
                            if existing_sessions:
                                val = _merge_admin_pi_sessions_preserve_ai(val, existing_sessions)
                        except Exception as pi_merge_err:
                            logging.warning(f"admin_pi_sessions preserve merge skipped: {pi_merge_err}")

                    _write_setting_value(key, val)
                    if str(key) == "dashboard_channel_settings":
                        try:
                            self._refresh_dynamic_email_services(force=True)
                        except Exception:
                            pass

                    try:
                        if actor_user_id and str(key) == "dashboard_users":
                            old_users = _parse_users(old_val_raw)
                            new_users = _parse_users(val)

                            old_map = {u["username"]: u for u in old_users if u.get("username")}
                            new_map = {u["username"]: u for u in new_users if u.get("username")}

                            added = [u for uname, u in new_map.items() if uname not in old_map]
                            removed = [u for uname, u in old_map.items() if uname not in new_map]
                            updated = []
                            for uname, nu in new_map.items():
                                ou = old_map.get(uname)
                                if not ou:
                                    continue
                                if (
                                    str(ou.get("name") or "") != str(nu.get("name") or "")
                                    or str(ou.get("role") or "") != str(nu.get("role") or "")
                                    or sorted(list(ou.get("allowedLocations") or [])) != sorted(list(nu.get("allowedLocations") or []))
                                ):
                                    updated.append(nu)

                            for u in added:
                                chat_db.log_hr_audit_activity(
                                    actor_user_id=str(actor_user_id),
                                    actor_name=str(actor_name or ""),
                                    actor_role=str(actor_role or ""),
                                    event_type="hr.user.added",
                                    description=f"Added dashboard user {u.get('username')}",
                                    meta={"target_user": u},
                                )
                            for u in updated:
                                chat_db.log_hr_audit_activity(
                                    actor_user_id=str(actor_user_id),
                                    actor_name=str(actor_name or ""),
                                    actor_role=str(actor_role or ""),
                                    event_type="hr.user.updated",
                                    description=f"Updated dashboard user {u.get('username')}",
                                    meta={"target_user": u},
                                )
                            for u in removed:
                                chat_db.log_hr_audit_activity(
                                    actor_user_id=str(actor_user_id),
                                    actor_name=str(actor_name or ""),
                                    actor_role=str(actor_role or ""),
                                    event_type="hr.user.removed",
                                    description=f"Removed dashboard user {u.get('username')}",
                                    meta={"target_user": u},
                                )
                                
                                # Unassign chats and reassign religious chats
                                removed_id = str(u.get('id') or u.get('username') or "")
                                if removed_id:
                                    try:
                                        conn = chat_db._get_db()
                                        conn.row_factory = chat_db.sqlite3.Row
                                        c = conn.cursor()
                                        c.execute("SELECT chat_id, location FROM conversations WHERE lead_owner_user_id = ?", (removed_id,))
                                        assigned_chats = c.fetchall()
                                        conn.close()
                                        
                                        for row in assigned_chats:
                                            chat_id = row['chat_id']
                                            loc = row['location']
                                            chat_db.release_sales_lead(chat_id, "admin", allow_any=True)
                                            # If Religious, run round-robin
                                            if loc == 'Religious':
                                                self.route_religious_message_to_agent(chat_id)
                                    except Exception as e:
                                        logging.error(f"Error reassigning chats for removed user {removed_id}: {e}")

                        if actor_user_id and str(key) == "dashboard_user_passwords":
                            def _parse_map(v):
                                if isinstance(v, str) and v.strip():
                                    try:
                                        v = json.loads(v)
                                    except Exception:
                                        v = None
                                if isinstance(v, dict):
                                    out = {}
                                    for k, vv in v.items():
                                        ks = str(k or "").strip()
                                        if not ks:
                                            continue
                                        out[ks] = str(vv or "")
                                    return out
                                return {}

                            old_map = _parse_map(old_val_raw)
                            new_map = _parse_map(val)
                            changed = []
                            for uname, pw in new_map.items():
                                if uname not in old_map:
                                    changed.append(uname)
                                elif str(old_map.get(uname) or "") != str(pw or ""):
                                    changed.append(uname)

                            for uname in sorted(set(changed)):
                                chat_db.log_hr_audit_activity(
                                    actor_user_id=str(actor_user_id),
                                    actor_name=str(actor_name or ""),
                                    actor_role=str(actor_role or ""),
                                    event_type="hr.user.password_set",
                                    description=f"Set/updated password for {uname}",
                                    meta={"target_username": uname},
                                )
                    except Exception as e:
                        logging.error(f"HR audit log (settings) failed: {e}", exc_info=True)

                    return jsonify({"status": "success"})
            except Exception as e:
                logging.error(f"Error in api_settings: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

