        @app.route('/api/internal_notifications/user_api_keys', methods=['GET'])
        def api_internal_notifications_user_api_keys():
            try:
                actor_username = str(request.args.get("actor_username") or request.args.get("username") or "").strip()
                actor_role = str(request.args.get("actor_role") or "").strip().lower()
                target_username = str(request.args.get("target_username") or actor_username or "").strip()
                if not actor_username:
                    return jsonify({"status": "error", "message": "actor_username is required"}), 400
                is_admin = actor_role == "admin"
                if target_username and not is_admin and target_username != actor_username:
                    return jsonify({"status": "error", "message": "Forbidden"}), 403

                users_list = _load_dashboard_users_list()
                keys_map = _load_dashboard_user_api_keys()
                by_username = {str(u.get("username") or "").strip(): u for u in users_list if str(u.get("username") or "").strip()}

                if target_username:
                    if target_username not in by_username:
                        return jsonify({"status": "error", "message": "User not found"}), 404
                    user_meta = by_username.get(target_username) or {}
                    key_meta = keys_map.get(target_username) or {}
                    include_full_key = is_admin or target_username == actor_username
                    return jsonify({
                        "status": "success",
                        "data": {
                            "user": user_meta,
                            "api_key_meta": _serialize_user_api_key(target_username, key_meta, include_full_key=include_full_key),
                        }
                    }), 200

                items = []
                for user_meta in users_list:
                    username = str(user_meta.get("username") or "").strip()
                    if not username:
                        continue
                    items.append(
                        {
                            "user": user_meta,
                            "api_key_meta": _serialize_user_api_key(username, keys_map.get(username) or {}, include_full_key=False),
                        }
                    )
                return jsonify({"status": "success", "data": items}), 200
            except Exception as e:
                logging.error(f"Error in /api/internal_notifications/user_api_keys: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

