        def api_internal_notifications_user_whatsapp_webhook():
            try:
                if request.method == 'GET':
                    return jsonify({"status": "success", "message": "ok"}), 200

                payload = request.get_json(silent=True) or {}
                
                # Safely extract instance name avoiding AttributeError if 'instance' or 'data' is a string
                instance_obj = payload.get("instance")
                instance_name_1 = instance_obj.get("instanceName") if isinstance(instance_obj, dict) else ""
                
                instance_name_2 = payload.get("instanceName") if isinstance(payload, dict) else ""
                
                data_obj = payload.get("data")
                data_instance_obj = data_obj.get("instance") if isinstance(data_obj, dict) else None
                instance_name_3 = data_instance_obj.get("instanceName") if isinstance(data_instance_obj, dict) else ""
                
                payload_instance = (
                    str(instance_name_1 or "")
                    or str(instance_name_2 or "")
                    or str(instance_name_3 or "")
                ).strip()
                if not payload_instance:
                    return jsonify({"status": "success", "message": "ignored_no_instance"}), 200

                connections_map = _load_dashboard_user_whatsapp_connections()
                qr_data = _extract_qr_data(payload)
                state = _extract_connection_state(payload)
                next_status = _map_evolution_state_to_ui(state, qr_data)
                changed = False
                for username, items in list(connections_map.items()):
                    updated_items = []
                    for item in items or []:
                        conn = dict(item or {})
                        if str(conn.get("instanceName") or "").strip() == payload_instance:
                            if qr_data:
                                conn["qrCodeDataUrl"] = qr_data
                                conn["lastQrUpdatedAt"] = _utc_iso_now()
                            if next_status:
                                conn["connectionStatus"] = next_status
                            if next_status == "connected":
                                conn["lastConnectedAt"] = _utc_iso_now()
                                conn["qrCodeDataUrl"] = ""
                            conn["updatedAt"] = _utc_iso_now()
                            changed = True
                        updated_items.append(conn)
                    connections_map[username] = updated_items
                if changed:
                    _save_dashboard_user_whatsapp_connections(connections_map)
                return jsonify({"status": "success"}), 200
            except Exception as e:
                logging.error(f"Error in /api/internal_notifications/user_whatsapp/webhook: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500

