        @app.route('/api/customers/search_and_add', methods=['POST'])
        def api_search_and_add_customer():
            try:
                data = request.json
                term = data.get('search_term', '').strip()
                if not term:
                    return jsonify({"status": "error", "message": "Search term is required"}), 400

                import re
                import requests
                import chat_db
                from airtable_fields import TABLE_NAME, FieldIds, ID_TO_READABLE_NAME

                phone_clean = re.sub(r'\D', '', term)
                term_lower = term.lower()

                def _formula_string(value):
                    return "'" + str(value or "").replace("\\", "\\\\").replace("'", "\\'") + "'"

                def _formula_field(field_id):
                    return "{" + str(ID_TO_READABLE_NAME.get(field_id, field_id)) + "}"

                booking_field = _formula_field(FieldIds.BOOKING_NR)
                email_field = _formula_field(FieldIds.CUSTOMER_EMAIL)
                personal_email_field = _formula_field(FieldIds.CUSTOMER_PERSONAL_EMAIL)
                phone_field = _formula_field(FieldIds.CUSTOMER_PHONE)
                name_field = _formula_field(FieldIds.CUSTOMER_NAME)
                normalized_phone_formula = (
                    f"SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE({phone_field}, ' ', ''), '-', ''), '+', ''), '(', ''), ')', '')"
                )

                formula_parts = []
                formula_parts.append(f"LOWER(TRIM({booking_field}))={_formula_string(term_lower)}")
                formula_parts.append(f"LOWER(TRIM({email_field}))={_formula_string(term_lower)}")
                formula_parts.append(f"LOWER(TRIM({personal_email_field}))={_formula_string(term_lower)}")
                formula_parts.append(f"LOWER(TRIM({name_field}))={_formula_string(term_lower)}")
                formula_parts.append(f"FIND({_formula_string(term)}, {phone_field})")
                if phone_clean:
                    formula_parts.append(f"FIND({_formula_string(phone_clean)}, {normalized_phone_formula})")

                formula = f"OR({','.join(formula_parts)})"
                headers = {"Authorization": f"Bearer {self.config['airtable']['api_key']}"}

                response = requests.get(
                    f"https://api.airtable.com/v0/{self.config['airtable']['base_id']}/{TABLE_NAME}",
                    headers=headers,
                    params={"filterByFormula": formula},
                    timeout=15
                )
                if response.status_code != 200:
                    logging.error(f"Airtable query failed: {response.text}")
                    return jsonify({"status": "error", "message": "Failed to query Airtable"}), 500
                    
                records = response.json().get('records', [])
                if not records:
                    return jsonify({"status": "error", "message": "No customer found with the provided details."}), 404
                    
                # Take the most recent booking if there are multiple
                records.sort(key=lambda x: x.get('createdTime', ''), reverse=True)
                record = records[0]
                fields = record.get('fields', {})
                
                booking_nr = self.get_field_value(fields, FieldIds.BOOKING_NR) or ''
                name = self.get_field_value(fields, FieldIds.CUSTOMER_NAME) or 'Unknown Customer'
                email = (
                    self.get_field_value(fields, FieldIds.CUSTOMER_EMAIL)
                    or self.get_field_value(fields, FieldIds.CUSTOMER_PERSONAL_EMAIL)
                    or ''
                )
                phone = self.get_field_value(fields, FieldIds.CUSTOMER_PHONE) or ''
                location = self.get_field_value(fields, FieldIds.FROM_LOC) or 'Unknown'
                
                if not email and not phone:
                    return jsonify({"status": "error", "message": "Customer found, but neither email nor phone is available to start a chat."}), 400
                    
                if phone:
                    source = "WhatsApp"
                    phone_match = re.search(r'\+?[\d\s-]+', phone)
                    if phone_match:
                        raw_phone = phone_match.group(0)
                        sender_identifier = re.sub(r'[^\d+]', '', raw_phone)
                    else:
                        sender_identifier = re.sub(r'[^\d+]', '', phone)
                else:
                    source = "Email"
                    email_match = re.search(r'[\w\.-]+@[\w\.-]+\.\w+', email)
                    sender_identifier = email_match.group(0) if email_match else email

                chat = None
                req_location = data.get('location')
                is_sales = (str(req_location).strip() == 'Sales')

                if source == "WhatsApp":
                    existing_whatsapp_chat = chat_db.find_whatsapp_conversation_by_phone(sender_identifier)
                    if existing_whatsapp_chat:
                        existing_record_id = str(existing_whatsapp_chat.get('airtable_record_id') or '').strip()
                        update_payload = {
                            "chat_id": existing_whatsapp_chat['chat_id'],
                            "contact_name": name,
                            "needs_help": 0,
                            "booking_number": booking_nr
                        }
                        if is_sales:
                            update_payload["sales_inbox"] = True
                            # Do not overwrite location with Airtable location if we are just adding to Sales,
                            # so it keeps its original location (e.g. Hurghada) but also appears in Sales.
                            # Or if we want to ensure it has the Airtable location:
                            update_payload["location"] = location
                        else:
                            update_payload["location"] = location

                        if not existing_record_id or existing_record_id == record['id']:
                            update_payload["airtable_record_id"] = record['id']
                        chat_db.update_conversation_info(**update_payload)
                        chat = existing_whatsapp_chat

                if chat is None:
                    chat = chat_db.get_or_create_conversation(
                        source=source,
                        sender_identifier=sender_identifier,
                        contact_name=name,
                        airtable_record_id=record['id'],
                        location=location
                    )
                    # Mark as read/no-help and persist booking number so it appears immediately in Inbox metadata.
                    update_payload2 = {"needs_help": 0, "booking_number": booking_nr}
                    if is_sales:
                        update_payload2["sales_inbox"] = True
                    chat_db.update_conversation_info(chat['chat_id'], **update_payload2)
                
                return jsonify({
                    "status": "success",
                    "data": {
                        "chat_id": chat['chat_id'],
                        "customer_name": name,
                        "booking_nr": booking_nr
                    }
                })
                
            except Exception as e:
                logging.error(f"Error in api_search_and_add_customer: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500


