        @app.route('/api/sales_performance/settings', methods=['GET', 'POST', 'OPTIONS'])
        def api_sales_performance_settings():
            if request.method == 'OPTIONS':
                response = jsonify({})
                response.headers.add("Access-Control-Allow-Origin", "*")
                response.headers.add("Access-Control-Allow-Headers", "Content-Type,Authorization")
                response.headers.add("Access-Control-Allow-Methods", "GET,PUT,POST,DELETE,OPTIONS")
                return response, 200
            
            try:
                # Use a local file to store settings simply, or we could use Airtable.
                # For this specific requirement (manual override of window), a local json is efficient and reliable.
                import os, json
                settings_file = os.path.join(os.path.dirname(__file__), 'sales_performance_settings.json')
                
                # Default logic: open between 1st and 7th
                from datetime import datetime
                import pytz
                cairo_tz = pytz.timezone('Africa/Cairo')
                now = datetime.now(cairo_tz)
                auto_is_open = 1 <= now.day <= 7
                
                if request.method == 'GET':
                    settings = {"manual_override": None}
                    if os.path.exists(settings_file):
                        with open(settings_file, 'r') as f:
                            settings = json.load(f)
                    
                    manual_override = settings.get("manual_override")
                    
                    is_open = auto_is_open
                    if manual_override == "open":
                        is_open = True
                    elif manual_override == "closed":
                        is_open = False
                        
                    response = jsonify({
                        "status": "success", 
                        "data": {
                            "is_open": is_open,
                            "auto_is_open": auto_is_open,
                            "manual_override": manual_override,
                            "current_day": now.day
                        }
                    })
                    response.headers.add("Access-Control-Allow-Origin", "*")
                    return response, 200
                    
                elif request.method == 'POST':
                    data = request.json or {}
                    override_val = data.get("manual_override") # "open", "closed", or None
                    
                    settings = {"manual_override": override_val}
                    with open(settings_file, 'w') as f:
                        json.dump(settings, f)
                        
                    response = jsonify({"status": "success", "message": "Settings updated"})
                    response.headers.add("Access-Control-Allow-Origin", "*")
                    return response, 200
                    
            except Exception as e:
                logging.error(f"Error in api_sales_performance_settings: {e}", exc_info=True)
                response = jsonify({"status": "error", "message": str(e)})
                response.headers.add("Access-Control-Allow-Origin", "*")
                return response, 500

