        def _start_file_watcher():
            """Background thread: watches ai_agent.py for changes and triggers restart."""
            _monitor_file = os.path.abspath(__file__)
            _last_mtime = os.path.getmtime(_monitor_file) if os.path.exists(_monitor_file) else 0
            while True:
                time.sleep(1.5)
                try:
                    if os.path.exists(_monitor_file):
                        current_mtime = os.path.getmtime(_monitor_file)
                        if current_mtime != _last_mtime:
                            _last_mtime = current_mtime
                            logging.info("♻️  File change detected! Auto-restarting in 1 second...")
                            time.sleep(1.0)
                            os._exit(3)
                except Exception:
                    pass

        threading.Thread(target=_start_file_watcher, daemon=True).start()
        logging.info("👀 File watcher active: auto-restart on ai_agent.py change.")
